/**
 * 99 Names of Allah (Asma ul Husna) Data
 * Standard list (Tirmidhi narration order), meanings in all 7 UI languages.
 * meanings.ar is a brief Arabic gloss of the name.
 *
 * Also: PROPHETS_25 — the 25 prophets named in the Quran (standard list).
 * Each `count` was computed from this repo's data/quran-tokens.json by
 * summing the name's token forms (incl. attached vocatives/prepositions,
 * e.g. يادم = "O Adam", وابرهيم = "and Ibrahim") and matches the
 * well-known published mention counts. `forms` lists those exact
 * normalized token spellings (Uthmani rasm, diacritics stripped) so the
 * app can find every occurrence at runtime. Where the bare spelling is
 * ambiguous (هود also = "Jews", صلح also = "righteous", يحيى also =
 * the verb "he lives"), the disambiguated verse list is stored in `refs`
 * instead. `ref` is the name's first occurrence (mushaf order).
 */

const NAMES_99 = [
  { n: 1, ar: "الرَّحْمَٰنُ", translit: "Ar-Raḥmān", meanings: { en: "The Most Merciful", bn: "পরম করুণাময়", fr: "Le Tout Miséricordieux", id: "Yang Maha Pengasih", ur: "نہایت مہربان", tr: "Çok Merhametli", ar: "واسع الرحمة" , zh: '至慈者', ja: '全ての慈悲ぶかき者', hi: 'बेहद मेहरबान', es: 'El Compasivo', ru: 'Милостивый', de: 'Der Allerbarmer', fa: 'بسیار بخشنده', ms: 'Yang Maha Pemurah'},
    explain: { en: "Ar-Rahman is the name that encompasses Allah's all-encompassing mercy extended to every creature in this world — believer and disbeliever alike. It is derived from rahmah (mercy) in the intensified form, signifying a mercy so vast it embraces all of creation without discrimination. Ibn al-Qayyim noted that Ar-Rahman is specific to Allah alone and cannot be applied to any created being. The Basmala begins with this name to remind us that every act begins under His boundless mercy (Quran 1:1; 59:22).", bn: "আর-রাহমান নামে আছে আল্লাহর সেই ব্যাপক রহমত, যা এই দুনিয়ায় প্রতিটি সৃষ্টির ওপর ছড়িয়ে আছে, মুমিন হোক বা কাফির। শব্দটি এসেছে রাহমাহ (রহমত) থেকে, তবে জোরালো রূপে। অর্থাৎ এমন বিশাল রহমত, যা কোনো ভেদাভেদ ছাড়াই গোটা সৃষ্টিকে ঘিরে রাখে। ইবনুল কাইয়িম বলেছেন, আর-রাহমান নামটি কেবল আল্লাহর; কোনো সৃষ্টিকে এ নামে ডাকা যায় না। বিসমিল্লাহ শুরু হয় এই নাম দিয়েই, যাতে আমাদের মনে থাকে: প্রতিটি কাজ শুরু হয় তাঁর অসীম রহমতের ছায়ায় (কুরআন ১:১; ৫৯:২২)।" },
    hadith: { en: "Allah has ninety-nine names, one hundred minus one. Whoever memorises (and acts upon) them will enter Paradise.", bn: "আল্লাহর নিরানব্বইটি নাম আছে, এক কম একশো। যে এগুলো মুখস্থ করবে (এবং সে অনুযায়ী আমল করবে), সে জান্নাতে যাবে।", src: "Sahih al-Bukhari 6410; Sahih Muslim 2677" },
    invoke: { en: "When seeking mercy and compassion in all matters, begin your du'a with 'Ya Rahman, Ya Rahim' — just as every surah (except al-Tawbah) opens with the Basmala. Call upon Him by this name especially when you feel hopeless or distressed.", bn: "যেকোনো ব্যাপারে রহমত ও দয়া চাইলে দু'আ শুরু করুন 'ইয়া রাহমান, ইয়া রাহিম' বলে, ঠিক যেমন সূরা তাওবা ছাড়া প্রতিটি সূরা শুরু হয় বিসমিল্লাহ দিয়ে। বিশেষ করে যখন মন হতাশ বা অস্থির লাগে, তখন এই নামে তাঁকে ডাকুন।" } ,
    quranicRefs: [
      { ref: "1:3", noteEn: "Paired with Ar-Rahim in al-Fatiha, framing all worship under boundless mercy.", noteBn: "আল-ফাতিহায় আর-রাহিমের সঙ্গে একত্রে এসেছে। গোটা ইবাদতই তাই অসীম রহমতের ছায়ায়।" },
      { ref: "20:5", noteEn: "Ar-Rahman settled (istawa) upon the Throne — anchoring transcendence with this name.", noteBn: "আর-রাহমান আরশের উপর ইস্তিওয়া করেছেন। সৃষ্টির ঊর্ধ্বে তাঁর অবস্থানের কথা এসেছে এই নামের সঙ্গেই।" },
      { ref: "55:1", noteEn: "Opens Surah Ar-Rahman, cataloguing divine blessings with the refrain 'Which of your Lord's favours will you deny?'", noteBn: "সূরা আর-রাহমানের শুরু। এরপর একের পর এক নিয়ামতের কথা, আর বারবার ফিরে আসে একই প্রশ্ন: 'তোমরা তোমাদের রবের কোন কোন নিয়ামত অস্বীকার করবে?'" },
      { ref: "19:45", noteEn: "Ibrahim warns his father that Ar-Rahman's punishment may befall him for following Shaytan.", noteBn: "ইব্রাহিম তাঁর পিতাকে সতর্ক করেন: শয়তানের পথে চললে আর-রাহমানের শাস্তি তাঁর ওপর নেমে আসতে পারে।" },
      { ref: "78:37", noteEn: "Lord of heavens and earth — none shall have power to speak before Ar-Rahman.", noteBn: "আকাশ-পৃথিবীর রব — আর-রাহমানের সামনে কেউ কথা বলার ক্ষমতা রাখবে না।" }
    ]},
  { n: 2, ar: "الرَّحِيمُ", translit: "Ar-Raḥīm", meanings: { en: "The Most Compassionate", bn: "পরম দয়ালু", fr: "Le Très Miséricordieux", id: "Yang Maha Penyayang", ur: "نہایت رحم والا", tr: "Çok Merhamet Eden", ar: "دائم الرحمة" , zh: '特慈者', ja: '最も慈悲ぶかき者', hi: 'निहायत रहम करने वाला', es: 'El Misericordioso', ru: 'Милосердный', de: 'Der Barmherzige', fa: 'بسیار مهربان', ms: 'Yang Maha Mengasihani'},
    explain: { en: "Ar-Rahim refers to Allah's special, enduring mercy directed specifically toward the believers on the Day of Judgement and in the Hereafter. While Ar-Rahman's mercy spans all creation in this world, Ar-Rahim's mercy is a targeted compassion reserved for those who believe and do good. The Prophet (peace be upon him) described Allah as 'more merciful to His servants than a mother to her child' (Bukhari 5999). Together, Ar-Rahman and Ar-Rahim convey the complete picture of divine mercy.", bn: "আর-রাহিম নামে আছে আল্লাহর সেই বিশেষ ও স্থায়ী রহমত, যা কিয়ামতের দিন ও আখিরাতে কেবল মুমিনদের জন্য। আর-রাহমানের রহমত এই দুনিয়ায় সব সৃষ্টির জন্য; আর-রাহিমের রহমত বিশেষভাবে তাদের জন্য রাখা, যারা ঈমান আনে ও নেক আমল করে। নবী ﷺ বলেছেন, মা তার সন্তানের প্রতি যতটা দয়ালু, আল্লাহ তাঁর বান্দাদের প্রতি তার চেয়েও বেশি দয়ালু (বুখারি ৫৯৯৯)। আর-রাহমান ও আর-রাহিম মিলে আল্লাহর রহমতের পূর্ণ ছবি ফুটে ওঠে।" } ,
    hadith: { en: "The Prophet ﷺ taught Abu Bakr to say in his prayer: 'O Allah, I have greatly wronged myself and none forgives sins but You, so forgive me, for indeed You are Al-Ghafur, Ar-Rahim (the Oft-Forgiving, the Most Merciful).'", bn: "নবী ﷺ আবু বকর (রাঃ)-কে নামাজে এই দু'আ শেখান: 'হে আল্লাহ, আমি নিজের উপর অনেক জুলুম করেছি, আর আপনি ছাড়া কেউ গুনাহ ক্ষমা করতে পারে না; সুতরাং আমাকে ক্ষমা করুন, কারণ নিশ্চয়ই আপনি আল-গাফুর, আর-রাহিম (অতি ক্ষমাশীল, পরম দয়ালু)।'", src: "Sahih al-Bukhari 834; Sahih Muslim 2705" },
    invoke: { en: "Call 'Ya Rahim' when repenting after a sin, seeking the special mercy Allah reserves for the believers. The Prophet ﷺ taught Abu Bakr to close his prayer asking forgiveness 'for You are Al-Ghafur, Ar-Rahim' — pair this Name with honest confession of your shortcomings in du'a.", bn: "গুনাহের পর তওবা করার সময় 'ইয়া রাহিম' বলে ডাকুন, আর চান সেই বিশেষ রহমত, যা আল্লাহ মুমিনদের জন্য রেখেছেন। নবী ﷺ আবু বকর (রাঃ)-কে শিখিয়েছিলেন নামাজের শেষে 'নিশ্চয়ই আপনি আল-গাফুর, আর-রাহিম' বলে ক্ষমা চাইতে। দু'আয় নিজের ত্রুটি অকপটে স্বীকার করুন, আর সঙ্গে এই নামে ডাকুন।" },
    quranicRefs: [
      { ref: "1:3", noteEn: "Paired with Ar-Rahman in al-Fatiha, completing the two dimensions of divine mercy.", noteBn: "আল-ফাতিহায় আর-রাহমানের সঙ্গে এসেছে; দুয়ে মিলে আল্লাহর রহমতের দুটি দিক পূর্ণ হয়।" },
      { ref: "2:163", noteEn: "Allah is One, Ar-Rahman Ar-Rahim — mercy is essential to divine unity.", noteBn: "আল্লাহ এক, তিনি আর-রাহমান, আর-রাহিম। রহমত তাঁর একত্বেরই অবিচ্ছেদ্য অংশ।" },
      { ref: "33:43", noteEn: "He sends blessings upon believers — He is Ar-Rahim toward the faithful.", noteBn: "তিনি মুমিনদের ওপর রহমত বর্ষণ করেন; ঈমানদারদের প্রতি তিনি আর-রাহিম।" },
      { ref: "48:14", noteEn: "Allah is Ghafur and Rahim — forgiveness and mercy affirmed after the pledge of allegiance.", noteBn: "আল্লাহ গাফুর ও রাহিম — বাইআতের পরে ক্ষমা ও রহমত নিশ্চিত।" },
      { ref: "59:10", noteEn: "Believers pray for their predecessors: 'Our Lord, You are Ra'uf and Rahim.'", noteBn: "মুমিনরা তাদের পূর্বসূরিদের জন্য দু'আ করে: 'হে আমাদের রব, আপনি রাউফ ও রাহিম।'" }
    ]},
  { n: 3, ar: "الْمَلِكُ", translit: "Al-Malik", meanings: { en: "The King", bn: "সর্বাধিপতি", fr: "Le Souverain", id: "Yang Maha Merajai", ur: "بادشاہ", tr: "Mülkün Sahibi", ar: "الملك الحق" , zh: '君王者', ja: '王、君主、究極なる真の王', hi: 'बादशाह', es: 'El Rey', ru: 'Царь', de: 'Der König', fa: 'فرمانروا', ms: 'Yang Maha Merajai'},
    explain: { en: "Al-Malik is the Absolute King whose sovereignty requires no subjects to confirm it and no territory to define it. Every earthly kingdom is borrowed and temporary; His kingdom is eternal and total. On the Day of Resurrection, Allah will declare: 'To whom does sovereignty belong today? To Allah, the One, the Subduer!' (Quran 40:16). Ibn al-Qayyim wrote that reflecting on this name strips the heart of servitude to anyone but Allah.", bn: "আল-মালিক হলেন পরম রাজা। তাঁর রাজত্বের জন্য কোনো প্রজার স্বীকৃতি লাগে না, কোনো ভূখণ্ডের সীমাও লাগে না। দুনিয়ার প্রতিটি রাজত্ব ধার করা ও ক্ষণস্থায়ী; তাঁর রাজত্ব চিরস্থায়ী ও পূর্ণ। কিয়ামতের দিন আল্লাহ ঘোষণা করবেন: 'আজ রাজত্ব কার? এক, মহাপরাক্রমশালী আল্লাহর!' (কুরআন ৪০:১৬)। ইবনুল কাইয়িম লিখেছেন, এই নাম নিয়ে ভাবলে অন্তর আল্লাহ ছাড়া আর কারও গোলামি থেকে মুক্ত হয়।" },
    hadith: { en: "The most vile of names in Allah's sight on the Day of Resurrection will be a man calling himself 'King of Kings' — for there is no king but Allah.", bn: "কিয়ামতের দিন আল্লাহর কাছে সবচেয়ে নিকৃষ্ট নাম হবে সেই লোকের, যে নিজেকে 'রাজাধিরাজ' বলে। কারণ আল্লাহ ছাড়া কোনো রাজা নেই।", src: "Sahih al-Bukhari 6205; Sahih Muslim 2143" } ,
    invoke: { en: "When worldly powers seem overwhelming or a door of need is shut, turn to the true King with the Quranic du'a 'Qul Allahumma Malika-l-Mulk' (3:26) — He gives dominion to whom He wills. Ask Al-Malik directly for what no earthly authority can grant.", bn: "দুনিয়ার ক্ষমতাধরদের যখন খুব প্রবল মনে হয়, কিংবা প্রয়োজনের কোনো দরজা বন্ধ হয়ে যায়, তখন প্রকৃত রাজার দিকে ফিরুন। কুরআনের দু'আ 'কুল আল্লাহুম্মা মালিকাল-মুলক' (৩:২৬) পড়ুন; তিনি যাকে চান রাজত্ব দেন। দুনিয়ার কোনো কর্তৃপক্ষ যা দিতে পারে না, তা সরাসরি আল-মালিকের কাছে চান।" },
    quranicRefs: [
      { ref: "20:114", noteEn: "fa-ta'ala Allahu-l-Maliku-l-Haqq — exalted is Allah, the True Sovereign.", noteBn: "ফাতাআলাল্লাহুল-মালিকুল-হাক্ক: মহিমান্বিত আল্লাহ, যিনি প্রকৃত অধিপতি।" },
      { ref: "23:116", noteEn: "fa-ta'ala Allahu-l-Maliku-l-Haqq — closes the surah reaffirming absolute sovereignty.", noteBn: "ফাতাআলাল্লাহুল-মালিকুল-হাক্ক: সূরার শেষে আবারও তাঁর নিরঙ্কুশ রাজত্বের ঘোষণা।" },
      { ref: "59:23", noteEn: "Listed in the cluster of divine names in Surah al-Hashr alongside Al-Quddus and As-Salam.", noteBn: "সূরা আল-হাশরে আল্লাহর নামের তালিকায় আল-কুদ্দুস ও আস-সালামের সঙ্গে এসেছে।" },
      { ref: "62:1", noteEn: "All in heavens and earth glorifies Allah, Al-Malik, Al-Quddus, Al-Aziz, Al-Hakim.", noteBn: "আকাশ ও পৃথিবীর সবকিছু আল্লাহর তাসবিহ করে, যিনি আল-মালিক, আল-কুদ্দুস, আল-আযিয, আল-হাকিম।" },
      { ref: "114:2", noteEn: "Maliki-n-nas — King of mankind — in Surah an-Nas, one of the two refuge surahs.", noteBn: "মালিকিন-নাস, মানুষের অধিপতি: সূরা আন-নাসে, আশ্রয় চাওয়ার দুই সূরার একটিতে।" }
    ]},
  { n: 4, ar: "الْقُدُّوسُ", translit: "Al-Quddūs", meanings: { en: "The Most Holy", bn: "মহাপবিত্র", fr: "Le Très Saint", id: "Yang Maha Suci", ur: "نہایت پاک", tr: "Çok Kutsal", ar: "المنزه عن النقائص" , zh: '至潔者', ja: '最も神聖なる者', hi: 'निहायत पाक', es: 'El Puro', ru: 'Пречистый', de: 'Der Heilige', fa: 'پاک و منزه', ms: 'Yang Maha Suci'},
    explain: { en: "Al-Quddus signifies that Allah is utterly free from every imperfection, deficiency, likeness to creation, and any attribute that does not befit His majesty. The angels glorify Him with this name in their constant tasbih (Quran 59:23). Al-Ghazali in al-Maqsad al-Asna explains that recognising Allah's absolute holiness is the foundation of true tawhid — for once you know He is unblemished, you realize all worship belongs to Him alone.", bn: "আল-কুদ্দুস মানে আল্লাহ সব ত্রুটি ও অপূর্ণতা থেকে সম্পূর্ণ মুক্ত। সৃষ্টির সঙ্গে তাঁর কোনো সাদৃশ্য নেই, তাঁর মহিমার অযোগ্য কোনো গুণও তাঁর নেই। ফেরেশতারা তাঁদের অবিরাম তাসবিহে এই নামেই তাঁর মহিমা ঘোষণা করেন (কুরআন ৫৯:২৩)। আল-গাজালী 'আল-মাকসাদ আল-আসনা' গ্রন্থে বলেছেন, আল্লাহর পরম পবিত্রতা চেনাই খাঁটি তাওহিদের ভিত্তি। কারণ যখন জানবেন তিনি সব দোষ থেকে মুক্ত, তখনই বুঝবেন, সব ইবাদত কেবল তাঁরই প্রাপ্য।" } ,
    hadith: { en: "In his bowing and prostration the Prophet ﷺ used to say: 'Subbuhun Quddusun, Rabbu-l-mala'ikati wa-r-ruh' (Perfect, Most Holy, Lord of the angels and the Spirit).", bn: "নবী ﷺ রুকু ও সিজদায় বলতেন: 'সুব্বুহুন কুদ্দুসুন, রাব্বুল মালাইকাতি ওয়ার-রুহ' (পূত-পবিত্র, মহাপবিত্র, ফেরেশতাগণ ও রূহের রব)।", src: "Sahih Muslim 487" },
    invoke: { en: "Glorify Him in ruku and sujud with 'Subbuhun Quddusun, Rabbu-l-mala'ikati war-ruh' as the Prophet ﷺ did. Call 'Ya Quddus' when seeking purification of your heart from sins, envy, and every spiritual blemish — the Most Holy alone can purify.", bn: "নবী ﷺ যেমন করতেন, রুকু-সিজদায় 'সুব্বুহুন কুদ্দুসুন রাব্বুল মালাইকাতি ওয়ার-রুহ' বলে তাঁর তাসবিহ করুন। গুনাহ, হিংসা ও অন্তরের সব কালিমা থেকে মন পবিত্র করতে চাইলে 'ইয়া কুদ্দুস' বলে ডাকুন। মহাপবিত্র আল্লাহ ছাড়া আর কেউ পবিত্র করতে পারেন না।" },
    quranicRefs: [
      { ref: "59:23", noteEn: "Named after Al-Malik — the angels glorify Al-Quddus perpetually.", noteBn: "আল-মালিকের ঠিক পরেই এই নাম; ফেরেশতারা অবিরাম আল-কুদ্দুসের তাসবিহ করেন।" },
      { ref: "62:1", noteEn: "All in heavens and earth glorifies Allah Al-Malik Al-Quddus — holiness as the basis of universal glorification.", noteBn: "আকাশ ও পৃথিবীর সবকিছু আল্লাহর তাসবিহ করে, যিনি আল-মালিক, আল-কুদ্দুস। গোটা সৃষ্টির তাসবিহের ভিত্তিই তাঁর পবিত্রতা।" }
    ]},
  { n: 5, ar: "السَّلَامُ", translit: "As-Salām", meanings: { en: "The Source of Peace", bn: "শান্তিদাতা", fr: "La Paix", id: "Yang Maha Sejahtera", ur: "سلامتی والا", tr: "Esenlik Veren", ar: "السالم من كل عيب" , zh: '安宁者，赐安宁者', ja: '平和と恩恵、平和と安らぎの源', hi: 'सलामती देने वाला', es: 'La Fuente de la paz', ru: 'Источник мира', de: 'Der Quell des Friedens', fa: 'سرچشمه‌ی سلامت', ms: 'Yang Maha Sejahtera'},
    explain: { en: "As-Salam means that Allah is Himself the embodiment of peace and the source of all peace and safety. He is free from all defects in His essence, attributes, and actions, and He grants peace (salam) to His servants in this life and in Paradise. The greeting 'Assalamu Alaikum' is derived from this name, and the Prophet (peace be upon him) would say 'Allahumma Anta-s-Salam' after each prayer, acknowledging that true peace flows only from Allah.", bn: "আস-সালাম মানে আল্লাহ নিজেই শান্তি, আর সব শান্তি ও নিরাপত্তার উৎসও তিনি। তাঁর সত্তা, গুণাবলি ও কাজে কোনো ত্রুটি নেই। দুনিয়ায় ও জান্নাতে তিনিই বান্দাদের শান্তি (সালাম) দেন। 'আসসালামু আলাইকুম' সালামটি এই নাম থেকেই এসেছে। নবী ﷺ প্রতি নামাজের পর বলতেন 'আল্লাহুম্মা আনতাস-সালাম', মেনে নিতেন যে সত্যিকারের শান্তি কেবল আল্লাহর কাছ থেকেই আসে।" },
    invoke: { en: "After each obligatory prayer, say 'Allahumma Anta-s-Salam wa minka-s-Salam, tabarakta ya Dhal-Jalali wal-Ikram' (O Allah, You are Peace and from You comes peace, blessed are You, O Lord of Majesty and Honor). This was the Prophet's own practice.", bn: "প্রতিটি ফরজ নামাজের পর পড়ুন: 'আল্লাহুম্মা আনতাস-সালাম ওয়া মিনকাস-সালাম, তাবারাকতা ইয়া যাল-জালালি ওয়াল-ইকরাম' (হে আল্লাহ, আপনিই শান্তি, আপনার কাছ থেকেই শান্তি আসে; আপনি বরকতময়, হে মহিমা ও সম্মানের অধিকারী)। নবী ﷺ নিজে এভাবেই পড়তেন।" } ,
    hadith: { en: "After each obligatory prayer the Prophet (peace be upon him) used to say: 'Allahumma Anta-s-Salam wa minka-s-Salam, tabarakta ya Dhal-Jalali wal-Ikram.'", bn: "প্রতিটি ফরজ নামাজের পর নবী ﷺ বলতেন: 'আল্লাহুম্মা আনতাস-সালামু ওয়া মিনকাস-সালামু, তাবারাকতা ইয়া যুল-জালালি ওয়াল-ইকরাম।'", src: "Sahih Muslim 591" },
    quranicRefs: [
      { ref: "59:23", noteEn: "Named in the cluster of divine names in Surah al-Hashr — peace as a divine attribute alongside security and guardianship.", noteBn: "সূরা আল-হাশরে আল্লাহর নামগুলোর মধ্যে এসেছে; নিরাপত্তা ও অভিভাবকত্বের পাশাপাশি শান্তিও তাঁর গুণ।" }
    ]},
  { n: 6, ar: "الْمُؤْمِنُ", translit: "Al-Mu'min", meanings: { en: "The Giver of Security", bn: "নিরাপত্তাদাতা", fr: "Le Rassurant", id: "Yang Maha Memberi Keamanan", ur: "امن دینے والا", tr: "Güven Veren", ar: "المؤمِّن لعباده" , zh: '保證者', ja: '安全を与える者', hi: 'अमन देने वाला', es: 'El Dador de seguridad', ru: 'Дарующий безопасность', de: 'Der Sicherheit Gewährende', fa: 'ایمنی‌بخش', ms: 'Yang Maha Memberi Keamanan'},
    explain: { en: "Al-Mu'min has two complementary dimensions: He is the One who grants faith (iman) to His servants, and He is the One who gives security and safety — granting safety from His own punishment to those who obey Him. Al-Ghazali notes that only a servant who truly trusts in Allah can experience the inner security (itminan) that flows from this name. The word 'iman' (faith) and 'amn' (safety) share the same Arabic root, showing that faith and security are inseparable.", bn: "আল-মুমিন নামের দুটি দিক, একটি অন্যটিকে পূর্ণ করে। তিনি বান্দাদের ঈমান দান করেন, আবার তিনিই নিরাপত্তা ও আশ্রয় দেন: যারা তাঁর আনুগত্য করে, তাদের তিনি নিজের শাস্তি থেকে নিরাপদ রাখেন। আল-গাজালী বলেছেন, যে বান্দা সত্যিই আল্লাহর ওপর ভরসা করে, কেবল সে-ই এই নাম থেকে আসা অন্তরের প্রশান্তি (ইতমিনান) অনুভব করে। আরবিতে 'ঈমান' ও 'আমন' (নিরাপত্তা) একই মূল থেকে এসেছে। অর্থাৎ ঈমান আর নিরাপত্তা আলাদা করা যায় না।" } ,
    invoke: { en: "In times of anxiety, insecurity, or fear for your faith, call 'Ya Mu'min' — the Giver of Security — asking Him to plant firm iman in your heart and shield you from what you dread. Ask Him for safety (amn) in this world and safety from His punishment in the next.", bn: "উদ্বেগে, অনিরাপত্তায়, কিংবা নিজের ঈমান নিয়ে ভয় হলে 'ইয়া মুমিন' বলে নিরাপত্তাদাতাকে ডাকুন। চান, তিনি যেন অন্তরে মজবুত ঈমান বসিয়ে দেন এবং যা নিয়ে আপনি ভয় পান তা থেকে আপনাকে রক্ষা করেন। দুনিয়ায় নিরাপত্তা (আমন) চান, আর আখিরাতে তাঁর শাস্তি থেকে নিরাপত্তা চান।" },
    quranicRefs: [
      { ref: "59:23", noteEn: "Named in Surah al-Hashr alongside As-Salam and Al-Muhaymin — security as a divine quality.", noteBn: "সূরা আল-হাশরে আস-সালাম ও আল-মুহায়মিনের সঙ্গে এসেছে; নিরাপত্তা দেওয়া আল্লাহর গুণ।" }
    ]},
  { n: 7, ar: "الْمُهَيْمِنُ", translit: "Al-Muhaymin", meanings: { en: "The Guardian", bn: "রক্ষক", fr: "Le Protecteur", id: "Yang Maha Memelihara", ur: "نگہبان", tr: "Gözetip Koruyan", ar: "الرقيب الحافظ" , zh: '守護者', ja: '守護者、管理者', hi: 'निगहबान', es: 'El Custodio', ru: 'Оберегающий', de: 'Der Wächter', fa: 'نگهبان و چیره بر همه', ms: 'Yang Maha Memelihara'},
    explain: { en: "Al-Muhaymin comes from the root haymana, meaning to oversee, guard, and preserve with complete awareness. Allah watches over every detail of creation — nothing escapes His vigilance. This name also appears in Quran 5:48 describing the Quran itself as a guardian over previous scriptures, indicating that total, attentive guardianship is a divine quality manifested through His revelation.", bn: "আল-মুহায়মিন এসেছে 'হায়মানা' মূল থেকে, যার অর্থ পূর্ণ সজাগ থেকে দেখাশোনা করা, পাহারা দেওয়া ও রক্ষা করা। সৃষ্টির প্রতিটি খুঁটিনাটির ওপর আল্লাহর নজর আছে; কিছুই তাঁর দৃষ্টি এড়ায় না। কুরআনের ৫:৪৮ আয়াতেও শব্দটি এসেছে, যেখানে কুরআনকেই আগের কিতাবগুলোর রক্ষক বলা হয়েছে। এ থেকে বোঝা যায়, সজাগ ও পূর্ণ রক্ষণাবেক্ষণ আল্লাহর গুণ, যা তাঁর ওহির মধ্য দিয়েও প্রকাশ পায়।" } ,
    invoke: { en: "When you feel exposed to unseen dangers or fear for your family's safety, call upon Him as Ya Muhaymin, the Watchful Guardian who oversees every atom of creation. Entrust what you cannot protect to the One from whom nothing is hidden, and rest in the certainty that He is guarding it.", bn: "অদৃশ্য বিপদের আশঙ্কায় বা পরিবারের নিরাপত্তা নিয়ে ভয় পেলে 'ইয়া মুহায়মিন' বলে তাঁকে ডাকুন। তিনি সজাগ রক্ষক, সৃষ্টির প্রতিটি অণুর খবর রাখেন। যা আপনি নিজে রক্ষা করতে পারেন না, তা সঁপে দিন তাঁর হাতে, যাঁর কাছে কিছুই গোপন নয়। তারপর নিশ্চিন্ত থাকুন, তিনিই তা পাহারা দিচ্ছেন।" } ,
    quranicRefs: [
      { ref: "59:23", noteEn: "Named in Surah al-Hashr — the Overseer who watches and guards all creation.", noteBn: "সূরা আল-হাশরে এসেছে: তিনি সেই তত্ত্বাবধায়ক, যিনি গোটা সৃষ্টির ওপর নজর রাখেন ও রক্ষা করেন।" }
    ]},
  { n: 8, ar: "الْعَزِيزُ", translit: "Al-ʿAzīz", meanings: { en: "The Almighty", bn: "মহাপরাক্রমশালী", fr: "Le Tout Puissant", id: "Yang Maha Perkasa", ur: "سب پر غالب", tr: "Mutlak Güç Sahibi", ar: "الغالب الذي لا يُقهر" , zh: '勝利者、大能者', ja: '全能者', hi: 'सब पर ग़ालिब', es: 'El Poderoso', ru: 'Могущественный', de: 'Der Allmächtige', fa: 'شکست‌ناپذیر', ms: 'Yang Maha Perkasa'},
    explain: { en: "Al-'Aziz denotes that Allah is invincible, unconquerable, and utterly without equal. The root 'azza carries three meanings that are all applicable: rare and precious (nothing like Him exists), mighty and strong (no one can overpower Him), and the one who overcomes others without being overcome. Ibn al-Qayyim noted that al-'Aziz is often paired with al-Hakim in the Quran to show that Allah's power is always accompanied by wisdom — He is not arbitrary in His might.", bn: "আল-আযিয মানে আল্লাহ অজেয়, কেউ তাঁকে পরাস্ত করতে পারে না, আর তাঁর সমকক্ষ কেউ নেই। মূল শব্দ 'আযযা'-র তিনটি অর্থ আছে, আর তিনটিই তাঁর বেলায় খাটে: দুর্লভ ও মূল্যবান (তাঁর মতো কিছু নেই), শক্তিশালী ও প্রবল (কেউ তাঁকে হারাতে পারে না), আর যিনি সবাইকে পরাভূত করেন কিন্তু নিজে পরাভূত হন না। ইবনুল কাইয়িম বলেছেন, কুরআনে আল-আযিয প্রায়ই আল-হাকিমের সঙ্গে আসে। এতে বোঝা যায়, আল্লাহর শক্তির সঙ্গে সবসময় প্রজ্ঞা থাকে; তাঁর ক্ষমতা খেয়ালখুশির নয়।" } ,
    hadith: { en: "The Prophet ﷺ would say: 'O Allah, I seek refuge in Your might ('izzah) — none has the right to be worshipped but You — that You should let me go astray. You are the Ever-Living who never dies, while jinn and men die.'", bn: "নবী ﷺ বলতেন: 'হে আল্লাহ, আমি আপনার ইজ্জতের আশ্রয় চাই, আপনি ছাড়া কোনো ইলাহ নেই, যেন আপনি আমাকে পথভ্রষ্ট না করেন। আপনি চিরঞ্জীব, আপনার মৃত্যু নেই; আর জিন ও মানুষ মারা যায়।'", src: "Sahih al-Bukhari 7383; Sahih Muslim 2717" },
    invoke: { en: "When you feel weak, defeated, or humiliated, seek honor from Al-'Aziz alone — all might belongs to Him (Quran 35:10). Follow the Prophet's practice of seeking refuge in Allah's 'izzah: 'O Allah, I seek refuge in Your might — there is no god but You — that You let me go astray.'", bn: "দুর্বল, পরাজিত বা অপমানিত মনে হলে সম্মান চান কেবল আল-আযিযের কাছে; সব ইজ্জত তাঁরই (কুরআন ৩৫:১০)। নবী ﷺ যেভাবে আল্লাহর ইজ্জতের আশ্রয় নিতেন, আপনিও সেভাবে বলুন: 'হে আল্লাহ, আমি আপনার ইজ্জতের আশ্রয় চাই, আপনি ছাড়া কোনো ইলাহ নেই, যেন আপনি আমাকে পথভ্রষ্ট না করেন।'" },
    quranicRefs: [
      { ref: "2:129", noteEn: "Ibrahim's prayer: 'Send a messenger from themselves... You are Al-Aziz, Al-Hakim.'", noteBn: "ইব্রাহিমের দু'আ: 'তাদের মধ্য থেকে একজন রাসূল পাঠান... নিশ্চয়ই আপনি আল-আযিয, আল-হাকিম।'" },
      { ref: "26:9", noteEn: "Inna Rabbaka la-Huwa-l-Aziz-ur-Rahim — Your Lord is Al-Aziz, the Merciful, closing the Moses narrative.", noteBn: "ইন্না রাব্বাকা লা-হুওয়াল-আযিযুর-রাহিম: নিশ্চয়ই তোমার রব আল-আযিয, পরম দয়ালু। মূসার কাহিনী শেষ হয় এই কথায়।" },
      { ref: "59:23", noteEn: "Listed among the divine names in Surah al-Hashr alongside Al-Jabbar and Al-Mutakabbir.", noteBn: "সূরা আল-হাশরে আল-জাব্বার ও আল-মুতাকাব্বিরের সঙ্গে আল্লাহর নামের তালিকায় এসেছে।" },
      { ref: "59:24", noteEn: "Al-Aziz Al-Hakim — concludes the creation-names sequence, affirming might paired with wisdom.", noteBn: "আল-আযিয আল-হাকিম: সৃষ্টির নামগুলোর ধারা শেষ হয় এই দুই নামে, শক্তি আর তার সঙ্গে প্রজ্ঞা।" }
    ]},
  { n: 9, ar: "الْجَبَّارُ", translit: "Al-Jabbār", meanings: { en: "The Compeller", bn: "মহাপ্রতাপশালী", fr: "Le Contraignant", id: "Yang Maha Gagah", ur: "زبردست", tr: "Dilediğini Yaptıran", ar: "الذي يجبر الخلق" , zh: '超越者', ja: '力強き者', hi: 'ज़बरदस्त', es: 'El Irresistible', ru: 'Всесильный', de: 'Der Bezwinger', fa: 'چیره و جبران‌کننده', ms: 'Yang Maha Gagah'},
    explain: { en: "Al-Jabbar has a dual meaning that is both majestic and merciful. First, it means the One who compels and cannot be resisted — His will is carried out irresistibly. Second, from the same root (jabara), it means the One who repairs what is broken, restores the broken-hearted, and sets the fractured bone (jabr). Al-Ghazali writes that this name should inspire awe without despair: yes, He is irresistible in power, but He also mends broken spirits.", bn: "আল-জাব্বার নামের দুটি অর্থ, একটিতে প্রতাপ, অন্যটিতে দয়া। প্রথমত, তিনি এমন প্রবল যে কেউ তাঁকে ঠেকাতে পারে না; তাঁর ইচ্ছা কার্যকর হবেই। দ্বিতীয়ত, একই মূল (জাবারা) থেকে এর অর্থ: যিনি ভাঙা জিনিস জোড়া দেন, ভাঙা মন সারিয়ে তোলেন, ভাঙা হাড় জোড়া লাগান (জাবর)। আল-গাজালী লিখেছেন, এই নাম মনে ভয় জাগাবে, কিন্তু হতাশা নয়। তাঁর শক্তি অপ্রতিরোধ্য ঠিকই, আবার তিনিই ভাঙা হৃদয় জোড়া দেন।" } ,
    hadith: { en: "In the night prayer the Prophet ﷺ would say in his bowing: 'Subhana dhi-l-jabaruti wa-l-malakuti wa-l-kibriya'i wa-l-'azamah' (Glory to the Owner of absolute power, dominion, grandeur and majesty).", bn: "নবী ﷺ রাতের নামাজে রুকুতে বলতেন: 'সুবহানা যিল-জাবারুতি ওয়াল-মালাকুতি ওয়াল-কিবরিয়াই ওয়াল-আযামাহ' (পরাক্রম, রাজত্ব, মহত্ত্ব ও শ্রেষ্ঠত্বের অধিকারীর পবিত্রতা)।", src: "Sunan Abi Dawud 873; Sunan an-Nasa'i 1049" },
    invoke: { en: "When your heart is broken by loss or hardship, call upon Ya Jabbar — the One who mends what is shattered just as He sets a broken bone. Ask Him to repair your grief, restore what feels lost, and console the spirit that no created thing can console.", bn: "ক্ষতি বা কষ্টে মন ভেঙে গেলে 'ইয়া জাব্বার' বলে ডাকুন। ভাঙা হাড় যেমন তিনি জোড়া লাগান, তেমনি ভাঙা মনও জোড়া দেন। তাঁর কাছে চান: তিনি যেন আপনার শোক সারিয়ে দেন, যা হারিয়ে গেছে মনে হয় তা ফিরিয়ে দেন, আর এমন সান্ত্বনা দেন, যা কোনো সৃষ্টি দিতে পারে না।" } ,
    quranicRefs: [
      { ref: "59:23", noteEn: "Named in Surah al-Hashr — the Compeller whose will none can resist, yet who also mends the broken.", noteBn: "সূরা আল-হাশরে এসেছে: তাঁর ইচ্ছা কেউ ঠেকাতে পারে না, আবার তিনিই ভাঙাকে জোড়া দেন।" }
    ]},
  { n: 10, ar: "الْمُتَكَبِّرُ", translit: "Al-Mutakabbir", meanings: { en: "The Supreme", bn: "মহাগৌরবান্বিত", fr: "Le Superbe", id: "Yang Maha Megah", ur: "بڑائی والا", tr: "Büyüklükte Eşsiz", ar: "المتعالي عن السوء" , zh: '廣博者', ja: '強大なる者', hi: 'बड़ाई वाला', es: 'El Supremo', ru: 'Превосходящий', de: 'Der Überragende', fa: 'صاحب کبریا', ms: 'Yang Maha Megah'},
    explain: { en: "Al-Mutakabbir is the One who rightfully manifests supreme greatness, because He truly possesses it — unlike human arrogance which is a false claim. In Quran 59:23 this name appears after al-Jabbar, reminding us that divine pride (kibr) is not a flaw but the truthful assertion of His transcendence over all imperfection. The Prophet (peace be upon him) warned that no one who has an atom's weight of kibr (pride) in their heart will enter Paradise — meaning this attribute belongs to Allah alone.", bn: "আল-মুতাকাব্বির হলেন তিনি, যিনি ন্যায্যভাবেই নিজের সর্বোচ্চ মহত্ত্ব প্রকাশ করেন, কারণ সেই মহত্ত্ব সত্যিই তাঁর আছে। মানুষের অহংকার মিথ্যা দাবি, তাঁরটা সত্য। কুরআনের ৫৯:২৩ আয়াতে নামটি এসেছে আল-জাব্বারের পরে। এতে মনে করিয়ে দেওয়া হয়, আল্লাহর কিবর কোনো দোষ নয়; এ হলো সব অপূর্ণতার ঊর্ধ্বে থাকার সত্য ঘোষণা। নবী ﷺ সতর্ক করেছেন, যার অন্তরে অণু পরিমাণ অহংকার (কিবর) আছে, সে জান্নাতে যাবে না। অর্থাৎ এই গুণ কেবল আল্লাহর।" } ,
    hadith: { en: "Allah ﷻ says: 'Pride (al-kibriya') is My cloak and greatness (al-'azamah) is My lower garment; whoever contends with Me over either of them, I shall cast into the Fire.'", bn: "আল্লাহ ﷻ বলেন: 'অহংকার (আল-কিবরিয়া) আমার চাদর, আর মহত্ত্ব (আল-আযামাহ) আমার ইজার। এ দুটির যেকোনোটি নিয়ে যে আমার সঙ্গে টানাটানি করবে, আমি তাকে জাহান্নামে নিক্ষেপ করব।'", src: "Sahih Muslim 2620" },
    invoke: { en: "Invoke Al-Mutakabbir by emptying your own heart of pride — greatness is His garment alone, and whoever competes with Him in it is destroyed. When you notice arrogance rising in yourself, say 'Ya Mutakabbir' and ask Him to grant you humility before Him and His servants.", bn: "নিজের অন্তর অহংকার থেকে খালি করেই আল-মুতাকাব্বিরকে ডাকুন। মহত্ত্ব কেবল তাঁরই চাদর; এ নিয়ে যে তাঁর সঙ্গে পাল্লা দেয়, সে ধ্বংস হয়। নিজের মধ্যে অহংকার মাথা তুলছে টের পেলে 'ইয়া মুতাকাব্বির' বলুন, আর তাঁর কাছে চান, তাঁর সামনে ও তাঁর বান্দাদের সামনে যেন বিনয়ী থাকতে পারেন।" },
    quranicRefs: [
      { ref: "59:23", noteEn: "Named after Al-Jabbar in Surah al-Hashr — divine greatness as truthful assertion of transcendence.", noteBn: "সূরা আল-হাশরে আল-জাব্বারের পরে এসেছে। আল্লাহর মহত্ত্ব মানে সব অপূর্ণতার ঊর্ধ্বে থাকার সত্য ঘোষণা।" }
    ]},
  { n: 11, ar: "الْخَالِقُ", translit: "Al-Khāliq", meanings: { en: "The Creator", bn: "সৃষ্টিকর্তা", fr: "Le Créateur", id: "Yang Maha Pencipta", ur: "پیدا کرنے والا", tr: "Yaratan", ar: "الموجِد من العدم" , zh: '創造者', ja: '創造者', hi: 'पैदा करने वाला', es: 'El Creador', ru: 'Творец', de: 'Der Schöpfer', fa: 'آفریننده', ms: 'Yang Maha Pencipta'},
    explain: { en: "Al-Khaliq refers to Allah's act of bringing things into existence from absolute nothingness — creation ex nihilo. This is qualitatively distinct from human 'creation' which always works with pre-existing material. In Quran 59:24, all three creative names — al-Khaliq, al-Bari', al-Musawwir — appear together, showing the complete arc of creation: from divine will (al-Khaliq), to bringing into being (al-Bari'), to giving each thing its unique form (al-Musawwir).", bn: "আল-খালিক মানে আল্লাহ একেবারে শূন্য থেকে কোনো কিছুকে অস্তিত্বে আনেন। মানুষের 'সৃষ্টি' এর থেকে মূলত আলাদা, কারণ মানুষকে সবসময় আগে থেকে থাকা উপকরণ নিয়েই কাজ করতে হয়। কুরআনের ৫৯:২৪ আয়াতে সৃষ্টির তিনটি নাম একসঙ্গে এসেছে: আল-খালিক, আল-বারি, আল-মুসাওয়ির। এতে সৃষ্টির পুরো ধারাটা ধরা পড়ে: আল্লাহর ইচ্ছা (আল-খালিক), অস্তিত্বে আনা (আল-বারি), আর প্রতিটি জিনিসকে তার নিজস্ব রূপ দেওয়া (আল-মুসাওয়ির)।" },
    hadith: { en: "Allah, the Blessed and Exalted, said: 'Who is more unjust than one who tries to create like My creation? Let him create a grain of corn or a grain of wheat or a barleycorn.'", bn: "বরকতময় ও মহান আল্লাহ বলেন: 'তার চেয়ে বড় জালিম আর কে, যে আমার সৃষ্টির মতো সৃষ্টি করতে চায়? পারলে সে একটা ভুট্টার দানা, একটা গমের দানা বা একটা যবের দানা সৃষ্টি করে দেখাক।'", src: "Sahih al-Bukhari 5953" } ,
    invoke: { en: "When beginning any new venture, ask Al-Khaliq — who creates from nothing — to create ease, provision, and a way out for you. Reflecting on His creation in the sky, the earth, and your own self is itself a way of knowing and invoking this Name (Quran 3:191).", bn: "নতুন কোনো কাজ শুরুর সময় আল-খালিকের কাছে চান, যিনি শূন্য থেকে সৃষ্টি করেন: তিনি যেন আপনার জন্য সহজতা, রিজিক আর বের হওয়ার পথ তৈরি করে দেন। আকাশ, পৃথিবী আর নিজের সত্তায় তাঁর সৃষ্টি নিয়ে চিন্তা করাও এই নামকে চেনার ও এই নামে ডাকার একটি পথ (কুরআন ৩:১৯১)।" },
    quranicRefs: [
      { ref: "6:102", noteEn: "Dhalikal-llahu Rabbukum la ilaha illa Huwa Khaliqu kulli shay' — Creator of all things, there is none but Him.", noteBn: "যালিকুমুল্লাহু রাব্বুকুম লা ইলাহা ইল্লা হুওয়া খালিকু কুল্লি শায় — সব কিছুর স্রষ্টা, তিনি ছাড়া কেউ নেই।" },
      { ref: "13:16", noteEn: "Qul Allahu Khaliqu kulli shay' — Say: Allah is Creator of all things; He is Al-Wahid, Al-Qahhar.", noteBn: "কুল আল্লাহু খালিকু কুল্লি শায় — বলো: আল্লাহ সব কিছুর স্রষ্টা; তিনি আল-ওয়াহিদ, আল-কাহহার।" },
      { ref: "39:62", noteEn: "Allahu Khaliqu kulli shay' wa Huwa ala kulli shay'in Wakil — Creator and Trustee of all.", noteBn: "আল্লাহু খালিকু কুল্লি শায় ওয়া হুওয়া আলা কুল্লি শায়িন ওয়াকিল — সব কিছুর স্রষ্টা ও তত্ত্বাবধায়ক।" },
      { ref: "59:24", noteEn: "All three creation names — Al-Khaliq, Al-Bari, Al-Musawwir — appear together in this verse.", noteBn: "সৃষ্টির তিনটি নাম, আল-খালিক, আল-বারি ও আল-মুসাওয়ির, এই আয়াতে একসঙ্গে এসেছে।" }
    ]},
  { n: 12, ar: "الْبَارِئُ", translit: "Al-Bāri'", meanings: { en: "The Originator", bn: "উদ্ভাবক", fr: "Le Producteur", id: "Yang Maha Mengadakan", ur: "وجود بخشنے والا", tr: "Kusursuz Yaratan", ar: "الخالق بلا مثال" , zh: '從虛無中創造者', ja: '正当なる者', hi: 'वजूद देने वाला', es: 'El Originador', ru: 'Создатель', de: 'Der Hervorbringer', fa: 'هستی‌بخش', ms: 'Yang Maha Mengadakan'},
    explain: { en: "Al-Bari' is the One who separates and distinguishes each created thing from every other, bringing each into specific, individual existence with no confusion or overlap. The root bara'a means to distinguish and separate. While al-Khaliq emphasises the act of creating, al-Bari' emphasises the individuation of creation — that Allah gave every created thing its own distinct being. Al-Ghazali writes that this name points to Allah's absolute freedom from any model or prototype in His creation.", bn: "আল-বারি হলেন তিনি, যিনি প্রতিটি সৃষ্টিকে অন্য সবকিছু থেকে আলাদা করে নিজস্ব স্বতন্ত্র অস্তিত্ব দেন; কোথাও কোনো গোলমাল বা একটার সঙ্গে আরেকটা মিশে যাওয়া নেই। মূল শব্দ 'বারাআ'-র অর্থ আলাদা করা, পার্থক্য করা। আল-খালিক নামে জোর সৃষ্টি করার ওপর, আর আল-বারি নামে জোর প্রতিটি সৃষ্টির স্বাতন্ত্র্যের ওপর: আল্লাহ প্রতিটি জিনিসকে তার নিজস্ব আলাদা সত্তা দিয়েছেন। আল-গাজালী লিখেছেন, এই নাম বলে দেয়, সৃষ্টি করতে আল্লাহর কোনো আদর্শ বা নমুনার দরকার পড়ে না; তিনি এ থেকে সম্পূর্ণ মুক্ত।" } ,
    invoke: { en: "Turn in repentance to your Originator as Musa's people were commanded: 'fa-tubu ila Bari'ikum' — repent to your Bari' (Quran 2:54). Call 'Ya Bari'' when asking for sound health and rightly-ordered affairs, for He originated you free of defect.", bn: "মূসার কওমকে যেমন আদেশ দেওয়া হয়েছিল, 'ফাতুবু ইলা বারিইকুম' (তোমাদের স্রষ্টার কাছে তওবা করো), তেমনি আপনিও আপনার উদ্ভাবকের কাছে তওবা করুন (কুরআন ২:৫৪)। সুস্থ শরীর আর গোছানো জীবনের জন্য 'ইয়া বারি' বলে ডাকুন, কারণ তিনিই আপনাকে ত্রুটিহীন করে সৃষ্টি করেছেন।" },
    quranicRefs: [
      { ref: "59:24", noteEn: "Named alongside Al-Khaliq and Al-Musawwir in the triad of creation: conceiving, originating, fashioning.", noteBn: "সৃষ্টির তিন নামের একটি, আল-খালিক ও আল-মুসাওয়িরের সঙ্গে: পরিকল্পনা, অস্তিত্বদান ও আকৃতিদান।" }
    ]},
  { n: 13, ar: "الْمُصَوِّرُ", translit: "Al-Muṣawwir", meanings: { en: "The Fashioner", bn: "আকৃতিদানকারী", fr: "Le Formateur", id: "Yang Maha Membentuk", ur: "صورت گر", tr: "Şekil Veren", ar: "المصوِّر للخلق" , zh: '塑形者', ja: '形作りし者', hi: 'सूरत बनाने वाला', es: 'El Formador', ru: 'Дающий облик', de: 'Der Gestalter', fa: 'صورتگر', ms: 'Yang Maha Membentuk Rupa'},
    explain: { en: "Al-Musawwir is the Divine Fashioner who gives each created being its unique form, shape, colour, and appearance. The Quran (3:6) states: 'He it is who forms you in the womb however He wills.' No two faces are alike, no two fingerprints identical — this is the signature of Al-Musawwir. Ibn al-Qayyim marvelled that Allah fashions billions of humans from the same basic materials yet gives each an incomparable form, demonstrating limitless creative artistry.", bn: "আল-মুসাওয়ির হলেন সেই মহান রূপকার, যিনি প্রতিটি সৃষ্টিকে তার অনন্য রূপ, আকার, রং ও চেহারা দেন। কুরআন (৩:৬) বলছে: 'তিনিই মাতৃগর্ভে যেভাবে ইচ্ছা তোমাদের আকৃতি দেন।' কোনো দুটি মুখ এক রকম নয়, কোনো দুটি আঙুলের ছাপ অভিন্ন নয়; এ আল-মুসাওয়িরেরই স্বাক্ষর। ইবনুল কাইয়িম অবাক হয়ে বলেছেন, একই মৌলিক উপাদান থেকে আল্লাহ শত কোটি মানুষ গড়েন, অথচ প্রত্যেককে দেন অতুলনীয় এক রূপ। তাঁর সৃষ্টিশিল্পের কোনো সীমা নেই।" } ,
    hadith: { en: "Allah says: 'And who is more unjust than one who goes about creating like My creation? Let them create a little grain, or let them create a barley-corn.'", bn: "আল্লাহ বলেন: 'তার চেয়ে বড় জালিম আর কে, যে আমার সৃষ্টির মতো সৃষ্টি করতে যায়? তারা একটা ছোট্ট দানা সৃষ্টি করুক, কিংবা একটা যবের দানা!'", src: "Sahih al-Bukhari 5953; Sahih Muslim 2111" },
    invoke: { en: "Thank Al-Musawwir for the form He gave you and pray as the Prophet ﷺ did: 'O Allah, as You have made my form good, make my character good.' Expectant parents may ask the Fashioner, who shapes every child in the womb as He wills (3:6), for righteous and sound offspring.", bn: "আল-মুসাওয়ির আপনাকে যে রূপ দিয়েছেন, তার জন্য শুকরিয়া আদায় করুন, আর নবী ﷺ-এর মতো দু'আ করুন: 'হে আল্লাহ, আপনি যেমন আমার চেহারা সুন্দর করেছেন, তেমনি আমার চরিত্রও সুন্দর করে দিন।' যাঁরা সন্তানের অপেক্ষায় আছেন, তাঁরা নেক ও সুস্থ সন্তানের জন্য সেই রূপদাতার কাছে চাইতে পারেন, যিনি মাতৃগর্ভে প্রতিটি শিশুকে নিজের ইচ্ছামতো আকৃতি দেন (৩:৬)।" },
    quranicRefs: [
      { ref: "3:6", noteEn: "Huwa-lladhi yusawwirukum fi-l-arham kayfa yasha — He fashions you in the womb however He wills.", noteBn: "হুওয়াল্লাযি ইউসাওয়িরুকুম ফিল-আরহামি কায়ফা ইয়াশা — তিনি গর্ভে যেভাবে চান রূপ দেন।" },
      { ref: "59:24", noteEn: "Al-Musawwir appears with Al-Khaliq and Al-Bari — the fashioner completing the arc of creation.", noteBn: "আল-মুসাওয়ির এসেছে আল-খালিক ও আল-বারির সঙ্গে; রূপ দেওয়ার মধ্য দিয়েই সৃষ্টির ধারা পূর্ণ হয়।" }
    ]},
  { n: 14, ar: "الْغَفَّارُ", translit: "Al-Ghaffār", meanings: { en: "The Ever-Forgiving", bn: "মহাক্ষমাশীল", fr: "Le Grand Pardonneur", id: "Yang Maha Pengampun", ur: "بہت بخشنے والا", tr: "Çok Bağışlayan", ar: "كثير المغفرة" , zh: '至恕者', ja: '許し', hi: 'बहुत बख़्शने वाला', es: 'Aquel que perdona sin cesar', ru: 'Всепрощающий', de: 'Der immer wieder Vergebende', fa: 'بسیار آمرزنده', ms: 'Yang Sentiasa Mengampuni'},
    explain: { en: "Al-Ghaffar, in the intensified form (fa''al), means the One who forgives again and again without limit — not once or twice but continuously, no matter how many times a servant returns in repentance. The root ghafara means to cover and conceal, so Allah covers sins and erases them from the record. The Prophet (peace be upon him) encouraged saying 'Astaghfirullah' 100 times daily, trusting in this name. Al-Ghazali distinguished Al-Ghaffar (habitual, repeated forgiveness) from Al-Ghafur (total forgiveness of a single sin).", bn: "আল-গাফফার শব্দটি জোরালো রূপে (ফাআল) এসেছে। অর্থ: যিনি বারবার, সীমাহীনভাবে ক্ষমা করেন। একবার-দুবার নয়, অবিরাম; বান্দা যতবারই তওবা করে ফিরে আসুক। মূল শব্দ 'গাফারা'-র অর্থ ঢেকে দেওয়া ও গোপন রাখা। তাই আল্লাহ গুনাহ ঢেকে দেন এবং আমলনামা থেকে মুছে ফেলেন। নবী ﷺ এই নামের ওপর ভরসা রেখে প্রতিদিন ১০০ বার 'আস্তাগফিরুল্লাহ' বলতে উৎসাহ দিতেন। আল-গাজালী আল-গাফফার (অভ্যাসগত, বারবার ক্ষমা) আর আল-গাফুরের (একটি গুনাহের পূর্ণ ক্ষমা) মধ্যে পার্থক্য করেছেন।" },
    hadith: { en: "By Allah, I seek forgiveness from Allah and turn to Him in repentance more than seventy times a day.", bn: "আল্লাহর কসম, আমি প্রতিদিন আল্লাহর কাছে সত্তরেরও বেশিবার ক্ষমা প্রার্থনা করি এবং তওবা করি।", src: "Sahih al-Bukhari 6307" },
    invoke: { en: "Repeat 'Astaghfirullah al-Ghaffar' (I seek forgiveness from Allah, the Ever-Forgiving) when overwhelmed by guilt. The Quran (71:10-12) teaches that istighfar by this name brings rain, wealth, children, gardens, and rivers — forgiveness opens all doors.", bn: "গুনাহের বোঝায় মন ভারী হয়ে গেলে বারবার বলুন 'আস্তাগফিরুল্লাহ আল-গাফফার' (আমি মহাক্ষমাশীল আল্লাহর কাছে ক্ষমা চাই)। কুরআন (৭১:১০-১২) শেখায়, এই নামে ইস্তিগফার করলে বৃষ্টি, সম্পদ, সন্তান, বাগান আর নদী আসে। ক্ষমাই সব দরজা খুলে দেয়।" } ,
    quranicRefs: [
      { ref: "20:82", noteEn: "wa inni la-Ghaffar-un li-man taba — I am Al-Ghaffar for whoever repents, believes and does good.", noteBn: "ওয়া ইন্নি লা-গাফফারুন লিমান তাবা: যে তওবা করে, ঈমান আনে ও নেক আমল করে, আমি তার জন্য আল-গাফফার।" },
      { ref: "38:66", noteEn: "Rabb-us-samawati wal-ard... Al-Aziz-ul-Ghaffar — Lord of all creation, Almighty and Ever-Forgiving.", noteBn: "রাব্বুস-সামাওয়াতি ওয়াল-আরদ... আল-আযিযুল-গাফফার — সমস্ত সৃষ্টির রব, মহাশক্তিমান ও চির-ক্ষমাশীল।" },
      { ref: "39:5", noteEn: "Al-Aziz-ul-Ghaffar — might and forgiveness paired; divine power never overrides mercy.", noteBn: "আল-আযিযুল-গাফফার: শক্তি ও ক্ষমা একসঙ্গে। আল্লাহর শক্তি কখনো তাঁর রহমতকে ছাপিয়ে যায় না।" },
      { ref: "40:42", noteEn: "The believer in Pharaoh's court: I call you to Al-Ghaffar who can forgive all your sins.", noteBn: "ফেরাউনের দরবারের সেই মুমিন: আমি তোমাদের ডাকছি আল-গাফফারের দিকে, যিনি তোমাদের সব গুনাহ মাফ করতে পারেন।" },
      { ref: "71:10", noteEn: "Nuh tells his people: Your Lord has been Al-Ghaffar — seek His forgiveness and He will send rain.", noteBn: "নূহ তাঁর কওমকে বলেন: তোমাদের রব আল-গাফফার। তাঁর কাছে ক্ষমা চাও, তিনি বৃষ্টি পাঠাবেন।" }
    ]},
  { n: 15, ar: "الْقَهَّارُ", translit: "Al-Qahhār", meanings: { en: "The Subduer", bn: "মহাপরাক্রান্ত", fr: "Le Dominateur", id: "Yang Maha Menundukkan", ur: "سب پر قابو والا", tr: "Her Şeye Galip", ar: "القاهر فوق عباده" , zh: '征服者', ja: '全てを従える支配者', hi: 'सब पर क़ाबू रखने वाला', es: 'El Dominador', ru: 'Покоряющий', de: 'Der Allbezwingende', fa: 'چیره بر همه چیز', ms: 'Yang Maha Menundukkan'},
    explain: { en: "Al-Qahhar is the One who subdues and overpowers everything in existence — no will can resist Him, no plan can succeed against Him, no power can challenge Him. The Quran pairs this name with al-Wahid (the One) in Quran 13:16 and 14:48, showing that His oneness and His all-conquering power are inseparable. For the believer, recognising Allah as al-Qahhar brings liberation: if only Allah has ultimate power, then fearing anyone or anything other than Him is misplaced.", bn: "আল-কাহহার হলেন তিনি, যিনি অস্তিত্বের সবকিছুকে দমন করেন, সবকিছুর ওপর প্রবল। কোনো ইচ্ছা তাঁকে ঠেকাতে পারে না, তাঁর বিরুদ্ধে কোনো পরিকল্পনা সফল হয় না, কোনো শক্তি তাঁর মোকাবিলা করতে পারে না। কুরআনের ১৩:১৬ ও ১৪:৪৮ আয়াতে এই নাম এসেছে আল-ওয়াহিদের (এক) সঙ্গে। অর্থাৎ তাঁর একত্ব আর তাঁর সর্বজয়ী শক্তি আলাদা করা যায় না। মুমিনের জন্য আল্লাহকে আল-কাহহার বলে চেনা মানে মুক্তি: চূড়ান্ত ক্ষমতা যদি কেবল আল্লাহর হয়, তবে তাঁকে ছাড়া আর কাউকে বা কিছুকে ভয় করার কোনো মানে নেই।" } ,
    hadith: { en: "When the Prophet ﷺ woke during the night he would say: 'La ilaha illallahu-l-Wahidu-l-Qahhar — there is no god but Allah, the One, the Subduer, Lord of the heavens and the earth and all between them, the Almighty, the Ever-Forgiving.'", bn: "নবী ﷺ রাতে ঘুম থেকে জেগে বলতেন: 'লা ইলাহা ইল্লাল্লাহুল-ওয়াহিদুল-কাহহার — আল্লাহ ছাড়া কোনো ইলাহ নেই, তিনি এক, মহাপরাক্রান্ত দমনকারী, আসমান-জমিন ও এর মাঝের সবকিছুর রব, মহাপরাক্রমশালী, অতি ক্ষমাশীল।'", src: "Sunan an-Nasa'i (al-Sunan al-Kubra); Ibn Hibban — graded sahih" },
    invoke: { en: "When your nafs, a habit, or a tyrant seems unconquerable, call on Al-Qahhar — nothing withstands His subduing power. Say the Prophet's night dhikr 'La ilaha illallahu-l-Wahidu-l-Qahhar' and ask Him to subdue your desires and the whispers of Shaytan.", bn: "নফস, কোনো অভ্যাস বা কোনো জালিমকে যখন অজেয় মনে হয়, তখন আল-কাহহারকে ডাকুন; তাঁর দমনের শক্তির সামনে কিছুই টেকে না। নবী ﷺ-এর রাতের জিকির 'লা ইলাহা ইল্লাল্লাহুল-ওয়াহিদুল-কাহহার' পড়ুন, আর তাঁর কাছে চান, তিনি যেন আপনার কুপ্রবৃত্তি আর শয়তানের কুমন্ত্রণা দমন করে দেন।" },
    quranicRefs: [
      { ref: "12:39", noteEn: "Yusuf in prison: Are many lords better, or Allah Al-Wahid Al-Qahhar — the One, the Subduer?", noteBn: "কারাগারে ইউসুফ: ভিন্ন ভিন্ন অনেক রব ভালো, নাকি আল্লাহ, যিনি আল-ওয়াহিদ আল-কাহহার, এক ও মহাপরাক্রান্ত?" },
      { ref: "13:16", noteEn: "Allah is Creator of all and He is Al-Wahid Al-Qahhar — oneness and supremacy inseparable.", noteBn: "আল্লাহ সবকিছুর স্রষ্টা, তিনি আল-ওয়াহিদ, আল-কাহহার। তাঁর একত্ব আর সর্বময় কর্তৃত্ব অবিচ্ছেদ্য।" },
      { ref: "14:48", noteEn: "On the Day the earth is replaced, all stand before Allah Al-Wahid Al-Qahhar.", noteBn: "যেদিন এই পৃথিবী বদলে অন্য পৃথিবী হবে, সেদিন সবাই আল্লাহ আল-ওয়াহিদ আল-কাহহারের সামনে হাজির হবে।" },
      { ref: "38:65", noteEn: "No deity except Allah Al-Wahid Al-Qahhar — the cornerstone declaration of tawhid.", noteBn: "আল্লাহ আল-ওয়াহিদ আল-কাহহার ছাড়া কোনো ইলাহ নেই: তাওহিদের মূল ঘোষণা।" },
      { ref: "39:4", noteEn: "Subhana-hu Huwa-llahu-l-Wahid-ul-Qahhar — Glory be to Him, He is Allah, the One, the Subduer.", noteBn: "সুবহানাহু হুওয়াল্লাহুল-ওয়াহিদুল-কাহহার — মহিমাময় তিনি, আল্লাহ, আল-ওয়াহিদ, আল-কাহহার।" },
      { ref: "40:16", noteEn: "al-mulku-l-yawm lillahi-l-Wahid-il-Qahhar — sovereignty today belongs to Allah, the One, the Subduer.", noteBn: "আল-মুলকুল-ইয়াওমা লিল্লাহিল-ওয়াহিদিল-কাহহার: আজ রাজত্ব আল্লাহর, যিনি এক, মহাপরাক্রান্ত।" }
    ]},
  { n: 16, ar: "الْوَهَّابُ", translit: "Al-Wahhāb", meanings: { en: "The Bestower", bn: "মহাদাতা", fr: "Le Donateur", id: "Yang Maha Pemberi Karunia", ur: "بہت عطا کرنے والا", tr: "Karşılıksız Veren", ar: "كثير العطاء" , zh: '賜福者', ja: '授ける者', hi: 'बहुत अता करने वाला', es: 'El Dadivoso', ru: 'Дарующий', de: 'Der Schenkende', fa: 'بخشاینده‌ی بی‌دریغ', ms: 'Yang Maha Pemberi'},
    explain: { en: "Al-Wahhab is the One who gives freely, abundantly, and continuously without any expectation of return, benefit, or reciprocity. The root wahaba means to give as a pure gift. Every blessing a person possesses — life, intellect, health, family, faith — is a gift from Al-Wahhab. The Prophet Sulayman (Solomon) prayed: 'My Lord, forgive me and grant me a kingdom that shall not belong to anyone after me; You are the Bestower' (Quran 38:35). Ibn al-Qayyim noted that contemplating this name heals the disease of feeling entitled.", bn: "আল-ওয়াহহাব হলেন তিনি, যিনি কোনো প্রতিদান, লাভ বা বিনিময়ের আশা ছাড়াই অকাতরে, অবিরাম দান করেন। মূল শব্দ 'ওয়াহাবা'-র অর্থ খাঁটি উপহার হিসেবে দেওয়া। মানুষের যত নিয়ামত আছে, জীবন, বুদ্ধি, সুস্থতা, পরিবার, ঈমান, সবই আল-ওয়াহহাবের দান। নবী সুলায়মান (আঃ) দু'আ করেছিলেন: 'হে আমার রব, আমাকে ক্ষমা করুন এবং আমাকে এমন রাজত্ব দান করুন, যা আমার পরে আর কারও হবে না; নিশ্চয়ই আপনি মহাদাতা' (কুরআন ৩৮:৩৫)। ইবনুল কাইয়িম বলেছেন, এই নাম নিয়ে ভাবলে 'এ তো আমার পাওনা' মনের এই রোগ সেরে যায়।" },
    invoke: { en: "When you need a specific gift — a child, a spouse, knowledge, or guidance — call upon 'Ya Wahhab' as Sulayman (as) did. Recite: 'Rabbi hab li min ladunka rahma' (My Lord, grant me from Yourself a mercy — Quran 18:10). This is the du'a of those who feel their hands are empty.", bn: "যখন নির্দিষ্ট কোনো দান দরকার, সন্তান, জীবনসঙ্গী, জ্ঞান বা হেদায়েত, তখন সুলায়মান (আঃ)-এর মতো 'ইয়া ওয়াহহাব' বলে ডাকুন। পড়ুন: 'রাব্বি হাব লি মিন লাদুনকা রাহমা' (হে আমার রব, আপনার পক্ষ থেকে আমাকে রহমত দান করুন; কুরআন ১৮:১০)। যাদের মনে হয় হাত একেবারে খালি, এ তাদের দু'আ।" } ,
    quranicRefs: [
      { ref: "3:8", noteEn: "Prayer: grant us from Yourself (wa-hab lana) mercy — You are Al-Wahhab.", noteBn: "দু'আ: আপনার পক্ষ থেকে আমাদের রহমত দান করুন (ওয়া-হাব লানা); নিশ্চয়ই আপনি আল-ওয়াহহাব।" },
      { ref: "38:9", noteEn: "Do they possess the treasuries of Al-Aziz Al-Wahhab's mercy?", noteBn: "তাদের কাছে কি আল-আযিয আল-ওয়াহহাবের রহমতের ভাণ্ডার আছে?" },
      { ref: "38:35", noteEn: "Sulayman's prayer: grant me (hab li) a kingdom none will have after me — invoking Al-Wahhab.", noteBn: "সুলায়মানের দু'আ: আমাকে এমন রাজত্ব দান করুন (হাব লি), যা আমার পরে আর কারও হবে না। এখানে তিনি আল-ওয়াহহাবকেই ডাকছেন।" }
    ]},
  { n: 17, ar: "الرَّزَّاقُ", translit: "Ar-Razzāq", meanings: { en: "The Provider", bn: "রিযিকদাতা", fr: "Le Pourvoyeur", id: "Yang Maha Pemberi Rezeki", ur: "رزق دینے والا", tr: "Rızık Veren", ar: "المتكفل بالرزق" , zh: '供給者', ja: '常に与える者', hi: 'रोज़ी देने वाला', es: 'El Proveedor', ru: 'Наделяющий уделом', de: 'Der Versorger', fa: 'روزی‌دهنده', ms: 'Yang Maha Pemberi Rezeki'},
    explain: { en: "Ar-Razzaq is the One who continuously provides all creation with everything they need — food, drink, sustenance, livelihood, and every resource, both material and spiritual. The Quran states: 'Indeed, Allah is the All-Provider, Owner of Power, the Firm' (51:58). No creature will die until it has received its full portion of rizq (provision) — this is a divine guarantee. Al-Ghazali emphasises that no intermediary between us and Ar-Razzaq can withhold or delay what He has decreed for us.", bn: "আর-রাজ্জাক হলেন তিনি, যিনি গোটা সৃষ্টিকে অবিরাম তাদের প্রয়োজনের সবকিছু দেন: খাবার, পানীয়, জীবিকা, আর বস্তুগত ও আত্মিক প্রতিটি উপকরণ। কুরআন বলছে: 'নিশ্চয়ই আল্লাহই রিজিকদাতা, প্রবল শক্তির অধিকারী, সুদৃঢ়' (৫১:৫৮)। পূর্ণ রিজিক না পাওয়া পর্যন্ত কোনো প্রাণী মারা যাবে না; এ আল্লাহর দেওয়া নিশ্চয়তা। আল-গাজালী জোর দিয়ে বলেছেন, আমাদের আর আর-রাজ্জাকের মাঝখানে এমন কোনো মাধ্যম নেই, যে তাঁর নির্ধারিত রিজিক আটকে রাখতে বা দেরি করাতে পারে।" },
    hadith: { en: "The Holy Spirit (Jibril) breathed into my soul: No soul shall die until it has received its full provision, so seek it by lawful means.", bn: "রুহুল কুদুস (জিব্রাইল) আমার অন্তরে এ কথা ঢেলে দিয়েছেন: কোনো প্রাণ তার পূর্ণ রিজিক না পাওয়া পর্যন্ত মারা যাবে না। তাই হালাল পথে তা খোঁজো।", src: "Sahih Ibn Hibban; al-Mustadrak (authentic)" },
    invoke: { en: "For rizq (provision) and relief from financial worry, repeat 'Ya Razzaq' frequently. Also recite Quran 51:58 and the morning du'a: 'Allahumma inni as'aluka rizqan halalan tayyiban wasi'an' (O Allah, I ask You for lawful, good, and abundant provision).", bn: "রিজিকের জন্য আর টাকাপয়সার দুশ্চিন্তা থেকে মুক্তির জন্য বারবার 'ইয়া রাজ্জাক' বলুন। কুরআনের ৫১:৫৮ আয়াতও পড়ুন, আর সকালের এই দু'আ: 'আল্লাহুম্মা ইন্নি আস'আলুকা রিজকান হালালান তাইয়িবান ওয়াসিআন' (হে আল্লাহ, আমি আপনার কাছে হালাল, পবিত্র ও প্রশস্ত রিজিক চাই)।" } ,
    quranicRefs: [
      { ref: "11:6", noteEn: "No creature on earth but its provision (rizq) is upon Allah — the foundational promise of Ar-Razzaq.", noteBn: "পৃথিবীতে এমন কোনো প্রাণী নেই, যার রিজিকের দায়িত্ব আল্লাহর ওপর নয়। আর-রাজ্জাকের এটাই মূল প্রতিশ্রুতি।" },
      { ref: "51:58", noteEn: "Inna-llaha Huwa-r-Razzaq Dhu-l-Quwwati-l-Matin — the only verse naming Ar-Razzaq explicitly.", noteBn: "ইন্নাল্লাহা হুওয়ার-রাজ্জাকু যুল-কুওয়্যাতিল-মাতিন: এই একটি আয়াতেই আর-রাজ্জাক নামটি সরাসরি এসেছে।" }
    ]},
  { n: 18, ar: "الْفَتَّاحُ", translit: "Al-Fattāḥ", meanings: { en: "The Opener", bn: "মহাবিজয়দানকারী", fr: "Celui qui ouvre", id: "Yang Maha Pembuka", ur: "کھولنے والا", tr: "Kapıları Açan", ar: "الحاكم الفاتح" , zh: '開啟者', ja: '開く者、勝利を与える者', hi: 'खोलने वाला', es: 'El que abre', ru: 'Открывающий', de: 'Der Öffnende', fa: 'گشاینده', ms: 'Yang Maha Pembuka'},
    explain: { en: "Al-Fattah is the One who opens all locked doors — literal and metaphorical. He opens the door of mercy when all human options are exhausted, the door of knowledge when minds are confused, the door of provision when pathways seem closed, and the door of victory (fath) when believers are oppressed. Surah al-Fath (48) begins with Allah's promise of manifest victory (fath). Ibn al-Qayyim wrote that calling on this name is essential for anyone whose path seems blocked.", bn: "আল-ফাত্তাহ হলেন তিনি, যিনি সব বন্ধ দরজা খুলে দেন, চোখে দেখা দরজাও, জীবনের অদৃশ্য দরজাও। মানুষের সব উপায় যখন ফুরিয়ে যায়, তিনি খোলেন রহমতের দরজা। মন যখন দিশেহারা, খোলেন জ্ঞানের দরজা। পথ যখন বন্ধ মনে হয়, খোলেন রিজিকের দরজা। আর মুমিনরা যখন নির্যাতিত, খোলেন বিজয়ের (ফাতহ) দরজা। সূরা আল-ফাতহ (৪৮) শুরুই হয়েছে সুস্পষ্ট বিজয়ের প্রতিশ্রুতি দিয়ে। ইবনুল কাইয়িম লিখেছেন, যার পথ আটকে গেছে মনে হয়, তার জন্য এই নামে ডাকা অপরিহার্য।" },
    invoke: { en: "When you face an obstacle that seems impossible — a closed career path, a blocked marriage, a stalled project — say 'Ya Fattah, iftah lana' (O Opener, open for us). Recite Quran 35:2: 'Whatever Allah grants to people of mercy — none can withhold it.'", bn: "কোনো বাধা যখন অসম্ভব মনে হয়, যেমন চাকরির পথ বন্ধ, বিয়ে আটকে আছে, কোনো কাজ থমকে গেছে, তখন বলুন 'ইয়া ফাত্তাহ, ইফতাহ লানা' (হে উন্মোচনকারী, আমাদের জন্য খুলে দিন)। কুরআনের ৩৫:২ আয়াত পড়ুন: 'আল্লাহ মানুষের জন্য যে রহমত খুলে দেন, কেউ তা আটকাতে পারে না।'" } ,
    hadith: { en: "Whoever says when leaving his home: 'Bismillahi tawakkaltu ala-llah wa la hawla wa la quwwata illa billah' — it is said to him: you are guided, sufficed, and protected.", bn: "যে ঘর থেকে বের হওয়ার সময় বলে: 'বিসমিল্লাহি তাওয়াক্কালতু আলাল্লাহি ওয়া লা হাওলা ওয়ালা কুওয়াতা ইল্লা বিল্লাহ', তাকে বলা হয়: তুমি হেদায়েত পেলে, তোমার জন্য যথেষ্ট হলো, তুমি রক্ষা পেলে।", src: "Sunan Abu Dawud 5095; Sunan al-Tirmidhi 3426 (Hasan Sahih)" },
    quranicRefs: [
      { ref: "34:26", noteEn: "Our Lord will bring us together then judge (yaftahu) between us in truth — Al-Fattah as the divine arbitrator.", noteBn: "আমাদের রব আমাদের একত্র করবেন, তারপর আমাদের মধ্যে ন্যায্যভাবে ফয়সালা (ইয়াফতাহু) করবেন। আল-ফাত্তাহ তাই চূড়ান্ত মীমাংসাকারীও।" },
      { ref: "35:2", noteEn: "Whatever Allah opens (yaftah) of mercy for people, none can withhold it — Al-Fattah's mercy is unstoppable.", noteBn: "আল্লাহ মানুষের জন্য যে রহমত খুলে দেন (ইয়াফতাহ), কেউ তা আটকাতে পারে না। আল-ফাত্তাহর রহমত অপ্রতিরোধ্য।" }
    ]},
  { n: 19, ar: "الْعَلِيمُ", translit: "Al-ʿAlīm", meanings: { en: "The All-Knowing", bn: "সর্বজ্ঞ", fr: "L'Omniscient", id: "Yang Maha Mengetahui", ur: "سب کچھ جاننے والا", tr: "Her Şeyi Bilen", ar: "المحيط علمه بكل شيء" , zh: '全知者', ja: '全てを知る者', hi: 'सब कुछ जानने वाला', es: 'El Omnisciente', ru: 'Всезнающий', de: 'Der Allwissende', fa: 'دانا', ms: 'Yang Maha Mengetahui'},
    explain: { en: "Al-'Alim encompasses all knowledge — past, present, and future; seen and unseen; what has happened and what will never happen but if it had, how it would have unfolded. The Quran (31:34) states that only Allah knows what is in the wombs and what soul earns tomorrow. This name appears over 140 times in the Quran, often paired with al-Hakim (All-Wise), showing that Allah's knowledge always leads to wise, purposeful action. For the believer, this name is a source of comfort: Allah knows your situation better than you do.", bn: "আল-আলিম সব জ্ঞানের অধিকারী: অতীত, বর্তমান ও ভবিষ্যৎ; দৃশ্য ও অদৃশ্য; যা ঘটেছে, আর যা কখনো ঘটবে না, তবে ঘটলে কেমন করে ঘটত, তাও। কুরআন (৩১:৩৪) বলছে, গর্ভে কী আছে আর কোন প্রাণ আগামীকাল কী অর্জন করবে, তা কেবল আল্লাহই জানেন। কুরআনে এই নাম ১৪০ বারেরও বেশি এসেছে, প্রায়ই আল-হাকিমের (প্রজ্ঞাময়) সঙ্গে। এতে বোঝা যায়, আল্লাহর জ্ঞান সবসময় প্রজ্ঞাপূর্ণ, উদ্দেশ্যপূর্ণ কাজে রূপ নেয়। মুমিনের জন্য এই নাম সান্ত্বনার উৎস: আপনার অবস্থা আপনার চেয়ে আল্লাহ বেশি জানেন।" } ,
    hadith: { en: "The Prophet ﷺ taught the istikharah: 'O Allah, I seek Your guidance by Your knowledge, for You know and I know not, and You are the Knower of all that is unseen (Anta 'Allamu-l-ghuyub).'", bn: "নবী ﷺ ইস্তিখারার দু'আ শেখান: 'হে আল্লাহ, আমি আপনার জ্ঞানের মাধ্যমে কল্যাণ প্রার্থনা করি, কারণ আপনি জানেন, আমি জানি না; আর আপনিই গায়েবের সর্বজ্ঞ (আন্তা আল্লামুল-গুয়ুব)।'", src: "Sahih al-Bukhari 1162" },
    invoke: { en: "When facing a decision whose outcome you cannot see, turn to Ya 'Alim, the All-Knowing, and pray the Istikharah, asking Him who knows all to choose what is best for you. When seeking beneficial knowledge, begin with 'Rabbi zidni ilma' (My Lord, increase me in knowledge).", bn: "এমন কোনো সিদ্ধান্তের সামনে দাঁড়ালে, যার পরিণতি আপনি দেখতে পাচ্ছেন না, 'ইয়া আলিম' বলে সর্বজ্ঞ আল্লাহর দিকে ফিরুন এবং ইস্তিখারা করুন। যিনি সব জানেন, তাঁকেই বলুন আপনার জন্য যা উত্তম তা বেছে দিতে। উপকারী জ্ঞান চাইলে শুরু করুন 'রাব্বি যিদনি ইলমা' (হে আমার রব, আমার জ্ঞান বাড়িয়ে দিন) দিয়ে।" } ,
    quranicRefs: [
      { ref: "2:29", noteEn: "He created all on earth then turned to heaven... and He is Alim of all things — cosmic scope of His knowledge.", noteBn: "পৃথিবীর সবকিছু সৃষ্টি করে তিনি আকাশের দিকে মনোনিবেশ করলেন... আর তিনি সবকিছু সম্পর্কে আলিম। তাঁর জ্ঞান গোটা বিশ্বজগৎ জুড়ে।" },
      { ref: "2:115", noteEn: "Inna-llaha Wasi'un Alim — wherever you turn, there is Allah's face; He is All-Encompassing and All-Knowing.", noteBn: "ইন্নাল্লাহা ওয়াসিউন আলিম: তোমরা যেদিকেই ফেরো, সেদিকেই আল্লাহর চেহারা; তিনি সর্বব্যাপী, সর্বজ্ঞ।" },
      { ref: "6:13", noteEn: "To Him belongs all that dwells in night and day; He is As-Sami, Al-Alim — hearing and knowledge unified.", noteBn: "রাত ও দিনে যা কিছু অবস্থান করে, সব তাঁরই; তিনি আস-সামি, আল-আলিম। শোনা আর জানা তাঁর মধ্যে একসঙ্গে।" },
      { ref: "22:59", noteEn: "He will admit them to an entrance they will be pleased with; Allah is Alim and Halim.", noteBn: "তিনি তাদের এমন জায়গায় প্রবেশ করাবেন, যাতে তারা খুশি হবে; আল্লাহ আলিম ও হালিম।" },
      { ref: "49:16", noteEn: "Inna-llaha Alim-un bi-ma fi-s-samawati wa ma fi-l-ard — Allah is Alim of all in the heavens and earth.", noteBn: "ইন্নাল্লাহা আলিমুন বিমা ফিস-সামাওয়াতি ওয়ামা ফিল-আরদ — আল্লাহ আকাশ-পৃথিবীর সব জানেন।" }
    ]},
  { n: 20, ar: "الْقَابِضُ", translit: "Al-Qābiḍ", meanings: { en: "The Withholder", bn: "সংকোচনকারী", fr: "Celui qui rétracte", id: "Yang Maha Menyempitkan", ur: "تنگی دینے والا", tr: "Daraltan", ar: "القابض للأرزاق" , zh: '遏止者、整頓者', ja: '制止する者', hi: 'रोक लेने वाला', es: 'El que retiene', ru: 'Удерживающий', de: 'Der Zurückhaltende', fa: 'تنگ‌گیرنده', ms: 'Yang Maha Menyempitkan'},
    explain: { en: "Al-Qabid is the One who withholds, constricts, and takes back — provision, life, opportunity — always according to divine wisdom, not arbitrariness. This name always appears paired with al-Basit (the Expander) in the Quran and Sunnah, reminding us that constriction is not permanent and is part of the same divine hand that expands. Times of tightness are a divine test and an invitation to turn back to Allah.", bn: "আল-কাবিদ হলেন তিনি, যিনি আটকে রাখেন, সংকুচিত করেন, ফিরিয়ে নেন: রিজিক, জীবন, সুযোগ। সবই করেন প্রজ্ঞা দিয়ে, খেয়ালখুশিতে নয়। কুরআন ও সুন্নাহয় এই নাম সবসময় আল-বাসিতের (প্রশস্তকারী) সঙ্গে জোড়া বেঁধে আসে। এতে মনে করিয়ে দেওয়া হয়, সংকীর্ণতা চিরস্থায়ী নয়; যে হাত সংকুচিত করে, সেই হাতই প্রশস্ত করে। টানাটানির দিনগুলো আল্লাহর পরীক্ষা, আর তাঁর দিকে ফিরে আসার ডাক।" } ,
    hadith: { en: "People said: 'O Messenger of Allah, prices have risen, so fix prices for us.' He ﷺ replied: 'Indeed Allah is the Price-Maker, Al-Qabid (the Withholder), Al-Basit (the Extender), Ar-Razzaq (the Provider), and I hope to meet Allah with none of you holding a claim against me for any injustice in blood or wealth.'", bn: "লোকেরা বলল: 'হে আল্লাহর রাসূল, দ্রব্যমূল্য বেড়ে গেছে, আমাদের জন্য দাম নির্ধারণ করে দিন।' তিনি ﷺ বললেন: 'নিশ্চয়ই আল্লাহই মূল্য-নির্ধারক, আল-কাবিদ (সংকোচনকারী), আল-বাসিত (সম্প্রসারণকারী), আর-রাজ্জাক (রিজিকদাতা); আমি আশা করি এমন অবস্থায় আল্লাহর সাথে সাক্ষাৎ করব যে, রক্ত বা সম্পদের কোনো জুলুমের দাবি তোমাদের কারো আমার উপর থাকবে না।'", src: "Sunan Abi Dawud 3451; Jami' at-Tirmidhi 1314 — sahih" },
    invoke: { en: "When provision, health, or your heart feels constricted, know the withholding comes from Al-Qabid's wisdom, not neglect. Respond with patience and istighfar, and ask Him to exchange the tightness for expansion — for He alone holds back and releases.", bn: "রিজিক, স্বাস্থ্য বা মন যখন সংকুচিত মনে হয়, জেনে রাখুন, এই আটকে রাখা আল-কাবিদের প্রজ্ঞা থেকে, অবহেলা থেকে নয়। ধৈর্য আর ইস্তিগফার দিয়ে সাড়া দিন, আর তাঁর কাছে চান, তিনি যেন সংকীর্ণতাকে প্রশস্ততায় বদলে দেন। ধরে রাখা আর ছেড়ে দেওয়া কেবল তাঁরই হাতে।" },
    quranicRefs: [
      { ref: "2:245", noteEn: "Allahu yaqbidu wa yabsutu — Allah withholds and expands; Al-Qabid paired with Al-Basit in divine economy.", noteBn: "আল্লাহু ইয়াকবিদু ওয়া ইয়াবসুতু: আল্লাহই সংকুচিত করেন, আল্লাহই প্রশস্ত করেন। রিজিক বণ্টনে আল-কাবিদ আর আল-বাসিত একসঙ্গে।" }
    ]},
  { n: 21, ar: "الْبَاسِطُ", translit: "Al-Bāsiṭ", meanings: { en: "The Expander", bn: "সম্প্রসারণকারী", fr: "Celui qui étend", id: "Yang Maha Melapangkan", ur: "کشادگی دینے والا", tr: "Genişleten", ar: "الباسط للأرزاق" , zh: '寬宏者、慷慨者', ja: '広げる者、惜しみなく与える者', hi: 'कुशादगी देने वाला', es: 'El que extiende', ru: 'Расширяющий', de: 'Der Ausbreitende', fa: 'گشایش‌دهنده', ms: 'Yang Maha Melapangkan'},
    explain: { en: "Al-Basit is the One who expands provision, hearts, chests, and possibilities. The famous du'a 'Allahumma inni as'aluka sadr wasit' (O Allah, I ask You for an expanded chest) draws on this attribute. The Prophet (peace be upon him) said: 'No one who sets prices can do so — only Allah constricts and expands' (Abu Dawud 3450), establishing that Al-Qabid and Al-Basit alone control economic realities.", bn: "আল-বাসিত হলেন তিনি, যিনি রিজিক, মন, বুক আর সম্ভাবনা প্রশস্ত করেন। প্রসিদ্ধ দু'আ 'আল্লাহুম্মা ইন্নি আস'আলুকা সাদরান ওয়াসিআন' (হে আল্লাহ, আমি আপনার কাছে প্রশস্ত বুক চাই) এই গুণকে ঘিরেই। নবী ﷺ বলেছেন: 'দাম বেঁধে দেওয়ার ক্ষমতা কারও নেই; কেবল আল্লাহই সংকুচিত ও প্রশস্ত করেন' (আবু দাউদ ৩৪৫০)। অর্থাৎ বাজার ও অর্থনীতির আসল নিয়ন্ত্রণ কেবল আল-কাবিদ ও আল-বাসিতের হাতে।" } ,
    hadith: { en: "When asked to fix market prices, the Prophet ﷺ said: 'Indeed Allah is the Price-Maker, Al-Qabid (the Withholder), Al-Basit (the Extender), Ar-Razzaq (the Provider)' — affirming that constriction and expansion of provision are in Allah's hand alone.", bn: "বাজারদর বেঁধে দিতে বলা হলে নবী ﷺ বললেন: 'নিশ্চয়ই আল্লাহই মূল্য নির্ধারণকারী, আল-কাবিদ (সংকোচনকারী), আল-বাসিত (সম্প্রসারণকারী), আর-রাজ্জাক (রিজিকদাতা)।' অর্থাৎ রিজিক কমানো-বাড়ানো কেবল আল্লাহর হাতে।", src: "Sunan Abi Dawud 3451; Jami' at-Tirmidhi 1314 — sahih" },
    invoke: { en: "Ask Al-Basit to expand your provision, knowledge, and chest — as Musa prayed, 'My Lord, expand for me my chest' (20:25). Give charity generously, for Allah stretches out His Hand by night and by day to accept the repentance and giving of His servants.", bn: "আল-বাসিতের কাছে চান, তিনি যেন আপনার রিজিক, জ্ঞান ও বুক প্রশস্ত করে দেন, যেমন মূসা দু'আ করেছিলেন: 'হে আমার রব, আমার বুক প্রশস্ত করে দিন' (২০:২৫)। খোলা হাতে দান করুন। আল্লাহ দিন-রাত তাঁর হাত প্রসারিত রাখেন, বান্দার তওবা আর দান কবুল করার জন্য।" },
    quranicRefs: [
      { ref: "2:245", noteEn: "Allahu yaqbidu wa yabsutu — Al-Basit expands provision, hearts and possibilities alongside Al-Qabid.", noteBn: "আল্লাহু ইয়াকবিদু ওয়া ইয়াবসুতু: আল-কাবিদের পাশাপাশি আল-বাসিত রিজিক, মন ও সম্ভাবনা প্রশস্ত করেন।" }
    ]},
  { n: 22, ar: "الْخَافِضُ", translit: "Al-Khāfiḍ", meanings: { en: "The Abaser", bn: "অবনতকারী", fr: "Celui qui abaisse", id: "Yang Maha Merendahkan", ur: "پست کرنے والا", tr: "Alçaltan", ar: "الخافض للجبابرة" , zh: '貶謫者', ja: '低める者', hi: 'पस्त करने वाला', es: 'El que rebaja', ru: 'Принижающий', de: 'Der Erniedrigende', fa: 'پست‌کننده', ms: 'Yang Maha Merendahkan'},
    explain: { en: "Al-Khafid is the One who lowers the arrogant and oppressive — the tyrants, the proud, those who transgress. This name appears paired with Ar-Rafi' (the Exalter), forming a perfect divine justice: those who humble themselves are raised, and those who raise themselves in arrogance are brought low. The Quran (56:3) uses this name to describe Allah's action on the Day of Resurrection, when all social orders are overturned.", bn: "আল-খাফিদ হলেন তিনি, যিনি অহংকারী ও জালিমদের নিচে নামিয়ে আনেন: স্বৈরাচারী, দাম্ভিক, সীমালঙ্ঘনকারী সবাইকে। এই নাম আসে আর-রাফি'র (উন্নতকারী) সঙ্গে জোড়া বেঁধে, আর দুয়ে মিলে পূর্ণ ন্যায়বিচার: যে বিনয়ী হয়, আল্লাহ তাকে উঁচু করেন; যে অহংকারে নিজেকে উঁচু করে, তিনি তাকে নামিয়ে দেন। কুরআন (৫৬:৩) কিয়ামতের দিন আল্লাহর এই কাজের কথা বলেছে, যেদিন সমাজের সব উঁচু-নিচু উল্টে যাবে।" } ,
    hadith: { en: "The Prophet ﷺ said: 'Indeed Allah raises some peoples by this Book (the Quran) and lowers others by it.'", bn: "নবী ﷺ বলেছেন: 'নিশ্চয়ই আল্লাহ এই কিতাবের (কুরআনের) মাধ্যমে কিছু জাতিকে উন্নীত করেন এবং এরই মাধ্যমে অন্যদের অবনমিত করেন।'", src: "Sahih Muslim 817" },
    invoke: { en: "Pray that Al-Khafid abases oppression and falsehood wherever they rise, and seek refuge in Him from being among those He lowers. Humble yourself willingly before Him in sujud — the one who bows low for Allah is never truly abased.", bn: "দু'আ করুন, জুলুম আর মিথ্যা যেখানেই মাথা তোলে, আল-খাফিদ যেন সেখানেই তা নামিয়ে দেন। আর তিনি যাদের নিচু করেন, তাদের দলে পড়া থেকে তাঁর আশ্রয় চান। সিজদায় নিজে থেকে তাঁর সামনে নত হোন। আল্লাহর জন্য যে মাথা নোয়ায়, সে কখনো সত্যিকারের অপমানিত হয় না।" },
    quranicRefs: [
      { ref: "56:3", noteEn: "khafidatun rafi'ah — lowering some and raising others; divine justice overturning human hierarchies.", noteBn: "খাফিদাতুন রাফিআহ: কাউকে নামাবে, কাউকে ওঠাবে। মানুষের গড়া উঁচু-নিচুর ভেদ উল্টে দেয় আল্লাহর ন্যায়বিচার।" }
    ]},
  { n: 23, ar: "الرَّافِعُ", translit: "Ar-Rāfiʿ", meanings: { en: "The Exalter", bn: "উন্নতকারী", fr: "Celui qui élève", id: "Yang Maha Meninggikan", ur: "بلند کرنے والا", tr: "Yücelten", ar: "الرافع لأوليائه" , zh: '擢昇者', ja: '高尚なる者', hi: 'बुलंद करने वाला', es: 'El que eleva', ru: 'Возвышающий', de: 'Der Erhöhende', fa: 'بالابرنده', ms: 'Yang Maha Meninggikan'},
    explain: { en: "Ar-Rafi' is the One who elevates and raises in status — in this world and the next. He raises ranks in paradise, raises the righteous over the wicked, and raises the humble believer over the arrogant disbeliever. The Quran (58:11) says: 'Allah will raise those who have believed among you and those who were given knowledge, by degrees.' This name assures believers that the right path — of patience, sincerity, and worship — leads to elevation.", bn: "আর-রাফি হলেন তিনি, যিনি মর্যাদায় উঁচু করেন, দুনিয়াতেও, আখিরাতেও। তিনি জান্নাতে মর্যাদার স্তর বাড়ান, নেককারকে বদকারের ওপরে তোলেন, বিনয়ী মুমিনকে অহংকারী কাফিরের ওপরে মর্যাদা দেন। কুরআন (৫৮:১১) বলছে: 'তোমাদের মধ্যে যারা ঈমান এনেছে এবং যাদের জ্ঞান দেওয়া হয়েছে, আল্লাহ তাদের মর্যাদায় বহু স্তর উঁচু করবেন।' এই নাম মুমিনকে আশ্বাস দেয়: ধৈর্য, ইখলাস আর ইবাদতের সঠিক পথই উঁচু মর্যাদায় পৌঁছে দেয়।" } ,
    hadith: { en: "The Prophet ﷺ said: 'Charity does not decrease wealth; Allah adds honor to a servant who pardons; and no one humbles himself for the sake of Allah but Allah raises him.'", bn: "নবী ﷺ বলেছেন: 'সদকা সম্পদ কমায় না; ক্ষমাকারী বান্দার সম্মান আল্লাহ বাড়িয়ে দেন; আর আল্লাহর জন্য যে বিনয়ী হয়, আল্লাহ তাকে অবশ্যই উঁচু করেন।'", src: "Sahih Muslim 2588" },
    invoke: { en: "Ask Ar-Rafi' to raise your rank in both worlds — He elevates 'those who believe and those given knowledge by degrees' (58:11). Pursue knowledge with humility, for the Prophet ﷺ said no one humbles himself for the sake of Allah but Allah raises him.", bn: "দুই জাহানে মর্যাদা বৃদ্ধির জন্য আর-রাফির কাছে দু'আ করুন। তিনি 'ঈমানদার ও জ্ঞানপ্রাপ্তদের মর্যাদায় বহু স্তর উঁচু করেন' (৫৮:১১)। বিনয়ের সঙ্গে জ্ঞান অর্জন করুন, কারণ নবী ﷺ বলেছেন, আল্লাহর জন্য যে বিনয়ী হয়, আল্লাহ তাকে উঁচু করেন।" },
    quranicRefs: [
      { ref: "6:165", noteEn: "He raised some above others in rank to test you — divine elevation as trial and responsibility.", noteBn: "তোমাদের পরীক্ষা করার জন্য তিনি কাউকে কারও ওপর মর্যাদায় উঁচু করেছেন। মর্যাদা তাই পরীক্ষা, দায়িত্বও।" },
      { ref: "43:32", noteEn: "We raised some above others in rank so that some may take others into service — divine distribution of roles.", noteBn: "আমি কাউকে কারও ওপর মর্যাদায় উঁচু করেছি, যাতে একে অন্যের কাছ থেকে কাজ নিতে পারে। কার কী ভূমিকা, তা আল্লাহই ভাগ করে দেন।" },
      { ref: "56:3", noteEn: "khafidatun rafi'ah — the paired action of lowering and raising on the Day of Judgement.", noteBn: "খাফিদাতুন রাফিআহ: কিয়ামতের দিন একই সঙ্গে নামানো আর ওঠানো।" },
      { ref: "58:11", noteEn: "yarfa'i-llahu-lladhina amanu... darajat — Allah raises believers and those given knowledge in rank.", noteBn: "ইয়ারফাইল্লাহুল্লাযিনা আমানু... দারাজাত — আল্লাহ ঈমানদার ও জ্ঞানপ্রাপ্তদের মর্যাদায় উন্নীত করেন।" }
    ]},
  { n: 24, ar: "الْمُعِزُّ", translit: "Al-Muʿizz", meanings: { en: "The Giver of Honor", bn: "সম্মানদাতা", fr: "Celui qui honore", id: "Yang Maha Memuliakan", ur: "عزت دینے والا", tr: "İzzet Veren", ar: "المعطي العزة" , zh: '賜榮者', ja: '栄誉を与える者', hi: 'इज़्ज़त देने वाला', es: 'El que honra', ru: 'Дарующий честь', de: 'Der Ehre Verleihende', fa: 'عزت‌بخش', ms: 'Yang Maha Memuliakan'},
    explain: { en: "Al-Mu'izz is the One who grants true honour and dignity ('izzah) to whomever He wills. The Quran (3:26) says: 'You honour whom You will and You humble whom You will.' Real honour comes only from Allah — no degree, wealth, or lineage grants it permanently. The Prophet (peace be upon him) taught that whoever seeks honour through arrogance will be humiliated, but whoever seeks it through obedience to Allah will be truly honoured.", bn: "আল-মুইয্য হলেন তিনি, যিনি যাকে চান তাকে প্রকৃত সম্মান ও মর্যাদা (ইয্যাহ) দান করেন। কুরআন (৩:২৬) বলছে: 'আপনি যাকে চান সম্মান দেন, যাকে চান অপমানিত করেন।' আসল সম্মান আসে কেবল আল্লাহর কাছ থেকে; কোনো ডিগ্রি, সম্পদ বা বংশ তা স্থায়ীভাবে দিতে পারে না। নবী ﷺ শিখিয়েছেন, যে অহংকার দিয়ে সম্মান খোঁজে, সে অপমানিত হয়; আর যে আল্লাহর আনুগত্যের মধ্য দিয়ে সম্মান খোঁজে, সে-ই সত্যিকারের সম্মান পায়।" } ,
    invoke: { en: "Seek honor from Al-Mu'izz through obedience, not through people's approval — 'whoever desires honor, to Allah belongs all honor' (35:10). Call 'Ya Mu'izz' asking for a dignity founded on iman that no one can strip away.", bn: "সম্মান চান আল-মুইয্যের কাছে, আনুগত্যের পথে; মানুষের বাহবার পথে নয়। 'যে সম্মান চায়, (সে জেনে রাখুক) সব সম্মান আল্লাহরই' (৩৫:১০)। 'ইয়া মুইয্য' বলে এমন মর্যাদা চান, যার ভিত ঈমান, আর যা কেউ কেড়ে নিতে পারে না।" },
    quranicRefs: [
      { ref: "3:26", noteEn: "tu'izzu man tasha' — You honour whom You will; true honour comes from Allah alone, not worldly rank.", noteBn: "তুইয্যু মান তাশা — আপনি যাকে চান সম্মানিত করেন; প্রকৃত সম্মান কেবল আল্লাহর কাছ থেকে।" }
    ]},
  { n: 25, ar: "الْمُذِلُّ", translit: "Al-Mudhill", meanings: { en: "The Humiliator", bn: "অপদস্থকারী", fr: "Celui qui humilie", id: "Yang Maha Menghinakan", ur: "ذلت دینے والا", tr: "Zillete Düşüren", ar: "المذل لأعدائه" , zh: '施恥者', ja: '不名誉を与える者', hi: 'ज़िल्लत देने वाला', es: 'El que humilla', ru: 'Унижающий', de: 'Der Demütigende', fa: 'خوارکننده', ms: 'Yang Maha Menghinakan'},
    explain: { en: "Al-Mudhil is the One who humiliates and degrades — specifically those who resist and transgress against His command, and those who seek honour through paths other than obedience to Him. This is not a vindictive attribute but a manifestation of perfect divine justice. Al-Ghazali notes that understanding this name should motivate the believer to flee from disobedience, since all paths that are not aligned with Allah's guidance lead ultimately to degradation.", bn: "আল-মুযিল হলেন তিনি, যিনি অপমানিত ও অবনত করেন: বিশেষ করে তাদের, যারা তাঁর আদেশের বিরুদ্ধে দাঁড়ায় ও সীমালঙ্ঘন করে, আর যারা তাঁর আনুগত্য বাদ দিয়ে অন্য পথে সম্মান খোঁজে। এ কোনো প্রতিশোধপরায়ণ গুণ নয়, বরং আল্লাহর নিখুঁত ন্যায়বিচারের প্রকাশ। আল-গাজালী বলেছেন, এই নাম বুঝলে মুমিন নাফরমানি থেকে পালাতে চাইবে, কারণ আল্লাহর হেদায়েতের বাইরের প্রতিটি পথ শেষ পর্যন্ত লাঞ্ছনায় গিয়ে ঠেকে।" } ,
    invoke: { en: "Seek refuge in Allah from the disgrace of sin and from being humbled on the Day the wrongdoers are humiliated. Al-Mudhill abases only with justice — so never purchase status through disobedience, for that trade ends in the very humiliation you fear.", bn: "গুনাহের লাঞ্ছনা থেকে, আর যেদিন জালিমরা অপমানিত হবে সেদিনের অপমান থেকে আল্লাহর আশ্রয় চান। আল-মুযিল কেবল ন্যায়ের সঙ্গেই অপদস্থ করেন। তাই নাফরমানির বিনিময়ে কখনো মর্যাদা কিনবেন না; সেই কেনাবেচার শেষ ঠিকানা সেই লাঞ্ছনাই, যাকে আপনি ভয় পান।" },
    quranicRefs: [
      { ref: "3:26", noteEn: "wa tudhillu man tasha' — You humble whom You will; paired with tu'izzu, honour and humiliation are Allah's alone.", noteBn: "ওয়া তুযিল্লু মান তাশা: আপনি যাকে চান অপমানিত করেন। 'তুইয্যু'-র সঙ্গে জোড়া বেঁধে এসেছে; সম্মান আর অপমান দুটোই কেবল আল্লাহর হাতে।" }
    ]},
  { n: 26, ar: "السَّمِيعُ", translit: "As-Samīʿ", meanings: { en: "The All-Hearing", bn: "সর্বশ্রোতা", fr: "L'Audient", id: "Yang Maha Mendengar", ur: "سب کچھ سننے والا", tr: "Her Şeyi İşiten", ar: "السامع لكل شيء" , zh: '全聽者', ja: '全て聞こえし者', hi: 'सब कुछ सुनने वाला', es: 'El que todo lo oye', ru: 'Всеслышащий', de: 'Der Allhörende', fa: 'شنوا', ms: 'Yang Maha Mendengar'},
    explain: { en: "As-Sami' means Allah hears everything — every whisper, every silent du'a, every thought not yet uttered aloud, in every language, simultaneously, without limit or distraction. Hajar ('Alayhassalam), alone in the desert with her infant Ismail, ran between Safa and Marwa calling out — and Allah heard, and the spring of Zamzam burst forth. The believer who knows As-Sami' is never truly alone: every prayer, even unspoken, reaches Allah perfectly.", bn: "আস-সামি মানে আল্লাহ সবকিছু শোনেন: প্রতিটি ফিসফিসানি, প্রতিটি নীরব দু'আ, মুখে না আনা প্রতিটি ভাবনা, সব ভাষায়, একই সঙ্গে, কোনো সীমা বা অমনোযোগ ছাড়াই। হাজার (আঃ) শিশু ইসমাইলকে নিয়ে মরুভূমিতে একা, সাফা আর মারওয়ার মাঝে ডাকতে ডাকতে দৌড়াচ্ছিলেন। আল্লাহ শুনলেন, আর জমজমের ঝর্ণা ফুটে বেরোল। যে মুমিন আস-সামিকে চেনে, সে কখনো সত্যিই একা নয়: প্রতিটি দু'আ, মুখে না বললেও, আল্লাহর কাছে পুরোপুরি পৌঁছে যায়।" },
    hadith: { en: "Aisha (may Allah be pleased with her) said: 'Praise be to Allah Whose hearing encompasses all voices! The woman who disputed (about her husband) complained to the Messenger of Allah ﷺ, and I could not hear part of what she said — yet Allah heard her and revealed: Allah has heard the words of she who disputes with you concerning her husband (58:1).'", bn: "আয়িশা (রাঃ) বলেন: 'সব প্রশংসা সেই আল্লাহর, যাঁর শ্রবণ সব আওয়াজকে ঘিরে আছে! (স্বামীর ব্যাপারে) বাদানুবাদকারী সেই নারী রাসূলুল্লাহ ﷺ-এর কাছে অভিযোগ করছিলেন, আর আমি তার কথার কিছু অংশ শুনতেই পাচ্ছিলাম না। অথচ আল্লাহ শুনলেন এবং নাজিল করলেন: আল্লাহ শুনেছেন সেই নারীর কথা, যে তার স্বামীর বিষয়ে তোমার সঙ্গে বাদানুবাদ করছে (৫৮:১)।'", src: "Sunan Ibn Majah 188 (Sahih); cf. Quran 58:1" } ,
    invoke: { en: "When no one hears your complaint or you weep alone, call upon Ya Sami' — He hears the faintest whisper and the silent prayer of the heart. Speak to Him freely in any language, certain that the All-Hearing never misses a single word or sigh.", bn: "আপনার অভিযোগ যখন কেউ শোনে না, কিংবা একা একা কাঁদেন, তখন 'ইয়া সামি' বলে ডাকুন। তিনি ক্ষীণতম ফিসফিসানি আর মনের নীরব দু'আও শোনেন। যেকোনো ভাষায় মন খুলে তাঁর সঙ্গে কথা বলুন। নিশ্চিত থাকুন, সর্বশ্রোতার কাছে একটি শব্দ, একটি দীর্ঘশ্বাসও হারিয়ে যায় না।" } ,
    quranicRefs: [
      { ref: "2:127", noteEn: "Ibrahim and Ismail raise the Kaaba foundations: Inna-ka Anta-s-Sami-ul-Alim — You are As-Sami, Al-Alim.", noteBn: "ইব্রাহিম ও ইসমাইল কাবার ভিত্তি তুলছেন: ইন্নাকা আনতাস-সামিউল-আলিম, নিশ্চয়ই আপনি আস-সামি, আল-আলিম।" },
      { ref: "2:137", noteEn: "Wa Huwa-s-Sami-ul-Alim — affirmed after the command to follow Ibrahim's path.", noteBn: "ওয়া হুওয়াস-সামিউল-আলিম: ইব্রাহিমের পথ অনুসরণের আদেশের পর এই ঘোষণা।" },
      { ref: "4:148", noteEn: "Wa kana-llahu Sami'an Alima — As-Sami and Al-Alim in the context of speaking out against injustice.", noteBn: "ওয়া কানাল্লাহু সামিআন আলিমা — অন্যায়ের বিরুদ্ধে কথা বলার প্রসঙ্গে আস-সামি ও আল-আলিম।" },
      { ref: "8:17", noteEn: "Wa-llahu Sami'un Alim — after the Battle of Badr, affirming Allah heard the believers' prayers.", noteBn: "ওয়াল্লাহু সামিউন আলিম: বদরের যুদ্ধের পর এই ঘোষণা, আল্লাহ মুমিনদের দু'আ শুনেছেন।" },
      { ref: "49:1", noteEn: "Inna-llaha Sami'un Alim — commanding believers not to presume before Allah and His Messenger.", noteBn: "ইন্নাল্লাহা সামিউন আলিম: মুমিনদের আদেশ দেওয়া হয়েছে, আল্লাহ ও তাঁর রাসূলের আগে আগ বাড়িয়ে কিছু না করতে।" }
    ]},
  { n: 27, ar: "الْبَصِيرُ", translit: "Al-Baṣīr", meanings: { en: "The All-Seeing", bn: "সর্বদ্রষ্টা", fr: "Le Clairvoyant", id: "Yang Maha Melihat", ur: "سب کچھ دیکھنے والا", tr: "Her Şeyi Gören", ar: "المبصر لكل شيء" , zh: '全視者', ja: '全てを見し者', hi: 'सब कुछ देखने वाला', es: 'El que todo lo ve', ru: 'Всевидящий', de: 'Der Allsehende', fa: 'بینا', ms: 'Yang Maha Melihat'},
    explain: { en: "Al-Basir sees everything — the tiniest ant on a black stone in a moonless night, the movement of atoms, and the innermost secrets of hearts. As-Sami' and Al-Basir appear together in a dozen verses of the Quran (e.g. 4:58, 17:1, 22:61, 42:11), showing that Allah's comprehensive awareness encompasses both auditory and visual reality. For the servant of Allah, this name functions as a conscience: every action, even in the deepest privacy, is witnessed by the All-Seeing.", bn: "আল-বাসির সবকিছু দেখেন: চাঁদহীন রাতে কালো পাথরের ওপর সবচেয়ে ছোট্ট পিঁপড়াটিও, পরমাণুর নড়াচড়াও, অন্তরের গভীরতম গোপন কথাও। কুরআনের প্রায় বারোটি আয়াতে আস-সামি ও আল-বাসির একসঙ্গে এসেছে (যেমন ৪:৫৮, ১৭:১, ২২:৬১, ৪২:১১)। অর্থাৎ আল্লাহর জ্ঞান শোনা ও দেখা, দুই জগৎই ঘিরে আছে। আল্লাহর বান্দার কাছে এই নাম বিবেকের কাজ করে: একেবারে নিভৃতে করা প্রতিটি কাজও সর্বদ্রষ্টা দেখছেন।" } ,
    invoke: { en: "When you are wronged in secret or your sincere efforts go unnoticed by people, find comfort in Ya Basir — the All-Seeing witnesses every hidden good deed and every injustice. Let this name inspire ihsan: worship Allah as though you see Him, for though you see Him not, He surely sees you.", bn: "গোপনে আপনার ওপর জুলুম হলে, কিংবা আপনার আন্তরিক চেষ্টা মানুষের চোখে না পড়লে, 'ইয়া বাসির' নামে সান্ত্বনা খুঁজুন। সর্বদ্রষ্টা প্রতিটি গোপন নেক কাজ আর প্রতিটি অবিচার দেখছেন। এই নাম আপনাকে ইহসানের দিকে টানুক: এমনভাবে আল্লাহর ইবাদত করুন, যেন আপনি তাঁকে দেখছেন; আপনি তাঁকে না দেখলেও তিনি তো আপনাকে দেখছেন।" } ,
    hadith: { en: "The Prophet ﷺ said to the companions raising their voices in dhikr: 'Be gentle with yourselves; you are not calling upon one who is deaf or absent — you are calling upon One who is All-Hearing, All-Seeing, and Near.'", bn: "উচ্চস্বরে যিকিরকারী সাহাবিদের নবী ﷺ বললেন: 'নিজেদের প্রতি সদয় হও; তোমরা কোনো বধির বা অনুপস্থিত সত্তাকে ডাকছ না — তোমরা ডাকছ এমন সত্তাকে যিনি সর্বশ্রোতা, সর্বদ্রষ্টা ও নিকটবর্তী।'", src: "Sahih al-Bukhari 7386; Sahih Muslim 2704" },
    quranicRefs: [
      { ref: "4:58", noteEn: "Inna-llaha kana Sami'an Basira — As-Sami and Al-Basir paired when commanding just governance.", noteBn: "ইন্নাল্লাহা কানা সামিআন বাসিরা: ন্যায়ের সঙ্গে শাসন করার আদেশে আস-সামি ও আল-বাসির একসঙ্গে।" },
      { ref: "17:1", noteEn: "Surana-lladhi asra... Inna-hu Huwa-s-Sami-ul-Basir — the Night Journey verse; Al-Basir witnessed it all.", noteBn: "সুবহানাল্লাযি আসরা... ইন্নাহু হুওয়াস-সামিউল-বাসির: ইসরার (রাতের সফর) আয়াত; আল-বাসির সবকিছু দেখেছেন।" },
      { ref: "22:61", noteEn: "Inna-llaha Sami'un Basir — affirmed in the cycle of night and day; awareness spans all time.", noteBn: "ইন্নাল্লাহা সামিউন বাসির: রাত-দিনের আবর্তনের প্রসঙ্গে এই ঘোষণা; তাঁর জ্ঞান সব সময়কে ঘিরে।" },
      { ref: "40:20", noteEn: "Inna-llaha Huwa-s-Sami-ul-Basir — the ultimate witness, unlike false gods that neither hear nor see.", noteBn: "ইন্নাল্লাহা হুওয়াস-সামিউল-বাসির: তিনিই চূড়ান্ত সাক্ষী, সেই মিথ্যা উপাস্যদের মতো নন, যারা শোনেও না, দেখেও না।" },
      { ref: "42:11", noteEn: "Wa Huwa-s-Sami-ul-Basir — in the verse of divine incomparability: nothing is like Him yet He hears and sees all.", noteBn: "ওয়া হুওয়াস-সামিউল-বাসির: আল্লাহর অতুলনীয়তার আয়াতে। তাঁর মতো কিছুই নেই, অথচ তিনি সব শোনেন, সব দেখেন।" }
    ]},
  { n: 28, ar: "الْحَكَمُ", translit: "Al-Ḥakam", meanings: { en: "The Judge", bn: "মহাবিচারক", fr: "L'Arbitre", id: "Yang Maha Menetapkan Hukum", ur: "فیصلہ کرنے والا", tr: "Hükmeden", ar: "الحاكم العدل" , zh: '仲裁者', ja: '審判、調停者', hi: 'फ़ैसला करने वाला', es: 'El Juez', ru: 'Судья', de: 'Der Richter', fa: 'داور', ms: 'Yang Maha Menghakimi'},
    explain: { en: "Al-Hakam is the ultimate Judge whose rulings are final, perfect, and just. Unlike human courts which can be wrong, delayed, or bribed, Al-Hakam's judgement is infallible. The Prophet (peace be upon him) forbade giving the name 'Hakam' to people, explaining 'The Judge is Allah' (Abu Dawud 4955). Every injustice in this world will be addressed at the final court of Al-Hakam — a fact that should comfort the oppressed and warn the oppressor.", bn: "আল-হাকাম হলেন চূড়ান্ত বিচারক; তাঁর রায় চূড়ান্ত, নিখুঁত ও ন্যায্য। মানুষের আদালত ভুল করতে পারে, দেরি করতে পারে, ঘুষে বিকিয়ে যেতে পারে; আল-হাকামের বিচারে কোনো ভুল নেই। নবী ﷺ মানুষের নাম 'হাকাম' রাখতে নিষেধ করেছেন, বলেছেন: 'বিচারক তো আল্লাহ' (আবু দাউদ ৪৯৫৫)। এই দুনিয়ার প্রতিটি অবিচারের বিচার হবে আল-হাকামের চূড়ান্ত আদালতে। এ কথা মজলুমের জন্য সান্ত্বনা, জালিমের জন্য সতর্কবার্তা।" } ,
    hadith: { en: "The Prophet ﷺ said to Abu Shurayh, who was known by the kunya Abu al-Hakam: 'Indeed Allah — He is Al-Hakam, and to Him belongs all judgment.'", bn: "আবু শুরাইহ, যাঁর উপনাম ছিল আবুল-হাকাম, তাঁকে নবী ﷺ বললেন: 'নিশ্চয়ই আল্লাহই আল-হাকাম, আর হুকুম (চূড়ান্ত বিচার-ফয়সালা) তাঁরই।'", src: "Sunan Abi Dawud 4955; Sunan an-Nasa'i 5387 — sahih" },
    invoke: { en: "When wronged in a dispute no court can settle, say 'Ya Hakam' and refer the verdict to the Judge who never errs. Being content with His rulings in the Shariah is itself part of honouring this Name in daily life.", bn: "কোনো বিবাদে অন্যায়ের শিকার হলে, যা কোনো আদালত মেটাতে পারে না, 'ইয়া হাকাম' বলুন এবং রায়ের ভার দিন সেই বিচারকের হাতে, যিনি কখনো ভুল করেন না। শরিয়তে তাঁর বিধানে খুশি থাকাও দৈনন্দিন জীবনে এই নামকে সম্মান করারই অংশ।" },
    quranicRefs: [
      { ref: "6:114", noteEn: "A-fa-ghayra-llahi abtaghi hakaman — Shall I seek other than Allah as Al-Hakam? He revealed the Book in truth.", noteBn: "আফাগায়রাল্লাহি আবতাগি হাকামান: আমি কি আল্লাহ ছাড়া অন্য কাউকে হাকাম (বিচারক) হিসেবে খুঁজব? তিনিই তো সত্যসহ কিতাব নাজিল করেছেন।" },
      { ref: "12:40", noteEn: "In al-hukmu illa lillah — judgement belongs only to Allah; Yusuf affirms tawhid to his prison companions.", noteBn: "ইনিল-হুকমু ইল্লা লিল্লাহ: ফয়সালার অধিকার কেবল আল্লাহর; কারাসঙ্গীদের কাছে ইউসুফের তাওহিদের ঘোষণা।" },
      { ref: "95:8", noteEn: "A-laysa-llahu bi-ahkami-l-Hakimin — Is not Allah the Most Just of all judges? A rhetorical affirmation.", noteBn: "আলায়সাল্লাহু বিআহকামিল-হাকিমিন: আল্লাহ কি সব বিচারকের মধ্যে সবচেয়ে ন্যায়বান নন? প্রশ্নের ভঙ্গিতে দৃঢ় ঘোষণা।" }
    ]},
  { n: 29, ar: "الْعَدْلُ", translit: "Al-ʿAdl", meanings: { en: "The Just", bn: "ন্যায়বিচারক", fr: "Le Juste", id: "Yang Maha Adil", ur: "عادل", tr: "Mutlak Adil", ar: "العادل في حكمه" , zh: '正義者', ja: '絶対的に正しきもの', hi: 'इंसाफ़ करने वाला', es: 'El Justo', ru: 'Справедливый', de: 'Der Gerechte', fa: 'دادگر', ms: 'Yang Maha Adil'},
    explain: { en: "Al-'Adl is absolute justice — not approximation, not compromise, not cultural interpretation. Every decree of Allah is perfectly just, even when human minds cannot comprehend its justice. Ibn al-Qayyim writes extensively in Shifa' al-'Alil that understanding divine justice requires recognising that Allah's wisdom (hikmah) is the axis around which His justice revolves. The believer who trusts in Al-'Adl finds peace even in painful decrees, knowing they are never arbitrary.", bn: "আল-আদল মানে পরম ন্যায়বিচার: আনুমানিক নয়, আপসের নয়, সংস্কৃতিভেদে বদলে যাওয়া ব্যাখ্যাও নয়। আল্লাহর প্রতিটি ফয়সালা পুরোপুরি ন্যায্য, মানুষের মন তার ন্যায্যতা বুঝতে না পারলেও। ইবনুল কাইয়িম 'শিফাউল আলিল' গ্রন্থে বিস্তারিত লিখেছেন: আল্লাহর ন্যায়বিচার বুঝতে হলে জানতে হবে, তাঁর প্রজ্ঞাই (হিকমাহ) সেই কেন্দ্র, যাকে ঘিরে তাঁর ন্যায়বিচার আবর্তিত হয়। যে মুমিন আল-আদলের ওপর ভরসা রাখে, কষ্টের ফয়সালাতেও সে শান্তি পায়, কারণ সে জানে এর কোনোটিই খেয়ালখুশির নয়।" },
    hadith: { en: "O My servants, I have forbidden injustice for Myself and have made it forbidden amongst you, so do not oppress one another.", bn: "হে আমার বান্দারা, আমি নিজের ওপর জুলুম হারাম করেছি, আর তোমাদের মধ্যেও তা হারাম করেছি। কাজেই তোমরা একে অপরের ওপর জুলুম কোরো না।", src: "Sahih Muslim 2577 (Hadith Qudsi)" } ,
    invoke: { en: "When you suffer or witness injustice, find rest in Al-'Adl — every account will be settled perfectly on the Day of Judgement. Ask Him to make you just in word and deed, even against yourself, for the just will stand upon pulpits of light near Him.", bn: "অবিচারের শিকার হলে বা অবিচার দেখলে আল-আদলের কাছে প্রশান্তি খুঁজুন; কিয়ামতের দিন প্রতিটি হিসাব নিখুঁতভাবে মেটানো হবে। তাঁর কাছে তাওফিক চান, যেন কথায় ও কাজে ন্যায়পরায়ণ থাকতে পারেন, নিজের বিরুদ্ধে গেলেও। কারণ ন্যায়পরায়ণরা তাঁর কাছে নূরের মিম্বরে থাকবে।" },
    quranicRefs: [
      { ref: "4:40", noteEn: "Inna-llaha la yazlimu mithqala dharratin — Allah does not wrong anyone an atom's weight; the foundation of divine justice.", noteBn: "ইন্নাল্লাহা লা ইয়াযলিমু মিছকালা যার্রাতিন: আল্লাহ কারও প্রতি অণু পরিমাণও জুলুম করেন না। আল্লাহর ন্যায়বিচারের ভিত্তি এটাই।" },
      { ref: "6:115", noteEn: "Wa tammat kalimatu Rabbika sidqan wa adlan — Your Lord's word is complete in truth and justice.", noteBn: "ওয়া তাম্মাত কালিমাতু রাব্বিকা সিদকান ওয়া আদলান: তোমার রবের বাণী সত্য ও ন্যায়ে পরিপূর্ণ।" },
      { ref: "16:90", noteEn: "Inna-llaha ya'muru bil-adl wal-ihsan — Allah commands justice and excellence; He embodies what He commands.", noteBn: "ইন্নাল্লাহা ইয়ামুরু বিল-আদলি ওয়াল-ইহসান: আল্লাহ ন্যায় ও ইহসানের আদেশ দেন; যা আদেশ করেন, তিনি নিজেই তার পূর্ণ রূপ।" }
    ]},
  { n: 30, ar: "اللَّطِيفُ", translit: "Al-Laṭīf", meanings: { en: "The Subtle One", bn: "সূক্ষ্মদর্শী", fr: "Le Doux", id: "Yang Maha Lembut", ur: "باریک بین مہربان", tr: "Lütufkâr", ar: "اللطيف بعباده" , zh: '微妙者', ja: '小さな親切', hi: 'बारीकबीं, मेहरबान', es: 'El Sutil', ru: 'Проницательный', de: 'Der Feinfühlige', fa: 'لطیف و باریک‌بین', ms: 'Yang Maha Halus'},
    explain: { en: "Al-Latif is one of the most profound names, combining two meanings: the One who perceives the most subtle and minute details of everything, and the One who is gentle, kind, and gracious in His dealings — reaching His servants through pathways so subtle they may not even notice. Quran 6:103 states: 'No vision can grasp Him, but His grasp is over all vision; He is Al-Latif, the All-Aware.' Al-Ghazali wrote that this name describes Allah reaching into the depths of every situation with a touch so delicate it transforms without disturbing.", bn: "আল-লাতিফ সবচেয়ে গভীর নামগুলোর একটি; এতে দুটি অর্থ একসঙ্গে। তিনি সবকিছুর সূক্ষ্মতম খুঁটিনাটিও জানেন, আবার বান্দার সঙ্গে আচরণে তিনি কোমল, দয়ালু ও অনুগ্রহশীল। বান্দার কাছে তাঁর অনুগ্রহ পৌঁছায় এমন সূক্ষ্ম পথে, যা হয়তো বান্দা টেরও পায় না। কুরআন ৬:১০৩ বলছে: 'দৃষ্টি তাঁকে আয়ত্ত করতে পারে না, অথচ তিনি সব দৃষ্টিকে আয়ত্ত করেন; তিনি আল-লাতিফ, আল-খাবির।' আল-গাজালী লিখেছেন, এই নাম বোঝায়, আল্লাহ প্রতিটি পরিস্থিতির গভীরে এমন কোমল স্পর্শে পৌঁছান, যা কিছু না নাড়িয়েই সব বদলে দেয়।" },
    invoke: { en: "When facing a complex situation that seems to have no good solution, call upon 'Ya Latif' repeatedly. Recite Quran 12:100 where Prophet Yusuf (as) says 'Inna Rabbi Latifun lima yasha' — my Lord is subtle in fulfilling what He wills. His help often arrives through unexpected, gentle pathways.", bn: "জটিল কোনো পরিস্থিতিতে যখন কোনো ভালো সমাধান চোখে পড়ে না, বারবার 'ইয়া লাতিফ' বলুন। কুরআনের ১২:১০০ আয়াত পড়ুন, যেখানে নবী ইউসুফ (আঃ) বলেন: 'ইন্না রাব্বি লাতিফুন লিমা ইয়াশা', আমার রব যা চান তা সূক্ষ্ম কৌশলে বাস্তবায়ন করেন। তাঁর সাহায্য প্রায়ই আসে অপ্রত্যাশিত, কোমল পথে।" } ,
    quranicRefs: [
      { ref: "6:103", noteEn: "La tudrikuhu-l-absaru wa Huwa-l-Latif-ul-Khabir — vision cannot grasp Him; He is Al-Latif and Al-Khabir.", noteBn: "লা তুদরিকুহুল-আবসারু ওয়া হুওয়াল-লাতিফুল-খাবির: দৃষ্টি তাঁকে আয়ত্ত করতে পারে না; তিনি আল-লাতিফ, আল-খাবির।" },
      { ref: "12:100", noteEn: "Inna Rabbi Latifun lima yasha — My Lord is Latif in fulfilling what He wills; Yusuf's gratitude after years of trial.", noteBn: "ইন্না রাব্বি লাতিফুন লিমা ইয়াশা: আমার রব যা চান, তা পূরণে তিনি লাতিফ। বহু বছরের পরীক্ষার পর ইউসুফের শুকরিয়া।" },
      { ref: "22:63", noteEn: "Inna-llaha Latifun Khabir — declared when Allah sends rain and revives dead earth with green.", noteBn: "ইন্নাল্লাহা লাতিফুন খাবির: আল্লাহ বৃষ্টি পাঠিয়ে মৃত মাটিকে সবুজ করে তোলেন, সেই প্রসঙ্গে এই ঘোষণা।" },
      { ref: "31:16", noteEn: "Inna-llaha Latifun Khabir — even a mustard seed's deed hidden in rock will be brought forth by Al-Latif.", noteBn: "ইন্নাল্লাহা লাতিফুন খাবির: পাথরের ভেতরে লুকানো সরিষার দানা পরিমাণ আমলও আল-লাতিফ বের করে আনবেন।" },
      { ref: "42:19", noteEn: "Allahu Latifun bi-ibadihi yarzuqu man yasha — Allah is Latif toward His servants, providing for whom He wills.", noteBn: "আল্লাহু লাতিফুন বিইবাদিহি ইয়ারযুকু মান ইয়াশা — আল্লাহ তাঁর বান্দাদের প্রতি লাতিফ, যাকে চান রিজিক দেন।" }
    ]},
  { n: 31, ar: "الْخَبِيرُ", translit: "Al-Khabīr", meanings: { en: "The All-Aware", bn: "সর্ববিষয়ে অবহিত", fr: "Le Bien-Informé", id: "Yang Maha Mengenal", ur: "خبردار", tr: "Her Şeyden Haberdar", ar: "العليم ببواطن الأمور" , zh: '全知者', ja: '全てを認知せし者', hi: 'पूरी ख़बर रखने वाला', es: 'El Bien Informado', ru: 'Ведающий', de: 'Der Allkundige', fa: 'آگاه', ms: 'Yang Maha Mendalam Pengetahuan-Nya'},
    explain: { en: "Al-Khabir is the One who possesses profound inner knowledge (khibra) — not just surface awareness but the deep insider knowledge of hidden realities, motivations, and ultimate consequences. Al-'Alim knows what things are; Al-Khabir knows the inner nature and hidden states of things. Quran 31:16 tells Luqman's son: 'O my son, if a deed should be the weight of a mustard seed, and should be within a rock or in the heavens or in the earth, Allah will bring it forth. Indeed, Allah is Subtle and Acquainted (Khabir).'", bn: "আল-খাবির হলেন তিনি, যাঁর আছে গভীর অন্তর্জ্ঞান (খিবরা)। কেবল বাইরের খবর নয়, ভেতরের গোপন বাস্তবতা, মনের উদ্দেশ্য আর শেষ পরিণতিরও পূর্ণ জ্ঞান। আল-আলিম জানেন কোন জিনিস কী; আল-খাবির জানেন জিনিসের ভেতরের স্বরূপ আর গোপন অবস্থা। কুরআন ৩১:১৬-তে লুকমান তাঁর ছেলেকে বলেন: 'হে আমার প্রিয় পুত্র, কোনো আমল যদি সরিষার দানা পরিমাণও হয়, আর তা থাকে কোনো পাথরের ভেতরে, কিংবা আকাশে বা পৃথিবীতে, আল্লাহ তা বের করে আনবেন। নিশ্চয়ই আল্লাহ সূক্ষ্মদর্শী, সর্ববিষয়ে অবহিত (খাবির)।'" } ,
    invoke: { en: "When matters are tangled and their inner truth is hidden from you, call upon Ya Khabir, the One aware of every hidden reality and secret motive. Ask Him to guide you through what you cannot perceive, trusting that He is fully acquainted with how all affairs will end.", bn: "বিষয়গুলো যখন জট পাকিয়ে যায়, আর তার ভেতরের সত্য আপনার কাছে অজানা থাকে, তখন 'ইয়া খাবির' বলে ডাকুন। তিনি প্রতিটি গোপন বাস্তবতা আর মনের গোপন উদ্দেশ্য জানেন। যা আপনি বুঝতে পারছেন না, তার ভেতর দিয়ে পথ দেখাতে তাঁর কাছে চান। ভরসা রাখুন, সব কাজ শেষে কোথায় গিয়ে দাঁড়াবে, তা তিনি পুরোপুরি জানেন।" } ,
    quranicRefs: [
      { ref: "6:18", noteEn: "Wa Huwa-l-Qahiru fawqa ibadihi wa Huwa-l-Hakim-ul-Khabir — He is supreme over His servants; Al-Hakim, Al-Khabir.", noteBn: "ওয়া হুওয়াল-কাহিরু ফাওকা ইবাদিহি ওয়া হুওয়াল-হাকিমুল-খাবির: তিনি তাঁর বান্দাদের ওপর পরাক্রমশালী; তিনি আল-হাকিম, আল-খাবির।" },
      { ref: "11:1", noteEn: "The Quran is from Hakim and Khabir — wisdom and inner knowledge are the twin sources of revelation.", noteBn: "কুরআন এসেছে হাকিম ও খাবিরের কাছ থেকে। ওহির উৎস দুটি গুণ: প্রজ্ঞা আর গভীর অন্তর্জ্ঞান।" },
      { ref: "17:30", noteEn: "Inna-hu kana bi-ibadihi Khabiran Basira — He is Khabir and Basir regarding His servants; He knows provision's wisdom.", noteBn: "ইন্নাহু কানা বিইবাদিহি খাবিরান বাসিরা: তিনি তাঁর বান্দাদের ব্যাপারে খাবির ও বাসির। কাকে কতটা রিজিক দিতে হয়, তার হিকমত তিনিই জানেন।" },
      { ref: "49:13", noteEn: "Inna-llaha Alimun Khabir — the most honoured is the most God-fearing; Al-Khabir verifies inner reality.", noteBn: "ইন্নাল্লাহা আলিমুন খাবির: তোমাদের মধ্যে সবচেয়ে সম্মানিত সে, যে সবচেয়ে বেশি তাকওয়াবান। ভেতরের আসল অবস্থা যাচাই করেন আল-খাবির।" }
    ]},
  { n: 32, ar: "الْحَلِيمُ", translit: "Al-Ḥalīm", meanings: { en: "The Forbearing", bn: "মহাসহনশীল", fr: "Le Longanime", id: "Yang Maha Penyantun", ur: "بردبار", tr: "Çok Hoşgörülü", ar: "الذي لا يعجل بالعقوبة" , zh: '克制者、寬大者', ja: '寛容なる者', hi: 'बुर्दबार', es: 'El Clemente', ru: 'Выдержанный', de: 'Der Nachsichtige', fa: 'بردبار', ms: 'Yang Maha Penyantun'},
    explain: { en: "Al-Halim is the One who withholds immediate punishment despite being fully capable of it, giving servants time to repent and reform. This is not weakness but the highest form of strength — restraining power out of wisdom and mercy. Every day that passes without divine punishment of sins is a manifestation of Al-Halim. Ibn al-Qayyim writes that Al-Halim's forbearance should motivate genuine repentance, not complacency, because punishment is not cancelled but deferred.", bn: "আল-হালিম হলেন তিনি, যিনি পুরো ক্ষমতা থাকা সত্ত্বেও সঙ্গে সঙ্গে শাস্তি দেন না, বান্দাকে তওবা ও সংশোধনের সময় দেন। এ দুর্বলতা নয়, শক্তির সর্বোচ্চ রূপ: প্রজ্ঞা আর রহমতের কারণে নিজের ক্ষমতা সংযত রাখা। গুনাহের শাস্তি ছাড়াই যে প্রতিটি দিন কেটে যায়, তা আল-হালিমেরই প্রকাশ। ইবনুল কাইয়িম লিখেছেন, আল-হালিমের সহনশীলতা যেন মানুষকে খাঁটি তওবার দিকে টানে, নিশ্চিন্ত গাফিলতির দিকে নয়। কারণ শাস্তি বাতিল হয়নি, শুধু পিছিয়ে দেওয়া হয়েছে।" } ,
    hadith: { en: "At times of distress the Prophet ﷺ would say: 'La ilaha illa Allahu-l-'Azimu-l-Halim (there is no god but Allah, the Magnificent, the Forbearing), la ilaha illa Allahu Rabbu-l-'arshi-l-'azim.'", bn: "বিপদের সময় নবী ﷺ বলতেন: 'লা ইলাহা ইল্লাল্লাহুল-আযিমুল-হালিম (মহান ও সহনশীল আল্লাহ ছাড়া কোনো ইলাহ নেই), লা ইলাহা ইল্লাল্লাহু রাব্বুল-আরশিল-আযিম।'", src: "Sahih al-Bukhari 6346; Sahih Muslim 2730" },
    invoke: { en: "When anger rises or you are tempted to retaliate, call upon Ya Halim and ask for a share of His forbearance — He delays punishment and does not hasten to requite those who disobey. Seek His gentle restraint so you may forgive others as He forbears with you every day.", bn: "রাগ যখন মাথায় চড়ে, বা প্রতিশোধ নিতে মন চায়, তখন 'ইয়া হালিম' বলে ডাকুন এবং তাঁর সহনশীলতার কিছু অংশ চান। তিনি শাস্তি পিছিয়ে দেন, নাফরমানদের প্রতিফল দিতে তাড়াহুড়া করেন না। তাঁর কাছে এমন কোমল সংযম চান, যাতে আপনিও অন্যদের ক্ষমা করতে পারেন, যেমন তিনি প্রতিদিন আপনার প্রতি সহনশীল থাকেন।" } ,
    quranicRefs: [
      { ref: "2:225", noteEn: "Wa-llahu Ghafurun Halim — Allah is Ghafur and Halim regarding unintentional oaths; forbearance covers honest mistakes.", noteBn: "ওয়াল্লাহু গাফুরুন হালিম: অনিচ্ছাকৃত কসমের ব্যাপারে আল্লাহ গাফুর ও হালিম। সরল মনে করা ভুল তাঁর সহনশীলতায় ঢাকা পড়ে।" },
      { ref: "2:235", noteEn: "Wa-lamu anna-llaha Ghafurun Halim — know that Allah is Ghafur and Halim; forbearance gives time for correction.", noteBn: "ওয়াআলামু আন্নাল্লাহা গাফুরুন হালিম: জেনে রাখো, আল্লাহ গাফুর ও হালিম। তাঁর সহনশীলতা শুধরে নেওয়ার সময় দেয়।" },
      { ref: "3:155", noteEn: "Inna-llaha Ghafurun Halim — after the setback at Uhud, reassuring that flight was forgiven by Al-Halim.", noteBn: "ইন্নাল্লাহা গাফুরুন হালিম: উহুদের বিপর্যয়ের পর আশ্বাস, রণাঙ্গন ছেড়ে পালানোর অপরাধ আল-হালিম ক্ষমা করেছেন।" },
      { ref: "4:12", noteEn: "Wa-llahu Alimun Halim — knowledge and forbearance paired in inheritance laws, showing compassion for human complexity.", noteBn: "ওয়াল্লাহু আলিমুন হালিম: মীরাসের বিধানে জ্ঞান ও সহনশীলতা একসঙ্গে; মানুষের জটিল অবস্থার প্রতি সহমর্মিতা।" },
      { ref: "22:59", noteEn: "La Aliman Halima — He will admit martyrs with good reward; He is Al-Alim and Al-Halim.", noteBn: "লা আলিমান হালিমা: তিনি শহীদদের উত্তম প্রতিদানসহ প্রবেশ করাবেন; তিনি আল-আলিম, আল-হালিম।" }
    ]},
  { n: 33, ar: "الْعَظِيمُ", translit: "Al-ʿAẓīm", meanings: { en: "The Magnificent", bn: "মহান", fr: "Le Magnifique", id: "Yang Maha Agung", ur: "عظمت والا", tr: "Pek Yüce", ar: "العظيم في كل شيء" , zh: '絕崇者', ja: '壮大なる者、無限なる者', hi: 'अज़मत वाला', es: 'El Inmenso', ru: 'Великий', de: 'Der Allgewaltige', fa: 'باعظمت', ms: 'Yang Maha Agung'},
    explain: { en: "Al-'Azim denotes a greatness so vast that all of creation together is less than a speck before it. The Prophet (peace be upon him) taught 'Subhana Rabbiya al-'Azim' in ruku' (bowing) in prayer, instructing that this specific moment of physical humility should be accompanied by this specific acknowledgment of divine greatness. Ayat al-Kursi (2:255) concludes with 'Wa Huwa al-'Aliyy al-'Azim' — tying boundless knowledge to infinite greatness.", bn: "আল-আযিম এমন মহত্ত্ব, যার সামনে গোটা সৃষ্টি মিলেও একটা কণার চেয়েও তুচ্ছ। নবী ﷺ নামাজের রুকুতে 'সুবহানা রাব্বিয়াল-আযিম' বলতে শিখিয়েছেন। অর্থাৎ শরীর যখন বিনয়ে ঝুঁকে আছে, ঠিক সেই মুহূর্তে আল্লাহর মহত্ত্বের এই স্বীকৃতি। আয়াতুল কুরসি (২:২৫৫) শেষ হয় 'ওয়া হুওয়াল-আলিয়্যুল-আযিম' দিয়ে, যেখানে সীমাহীন জ্ঞানের সঙ্গে অসীম মহত্ত্ব জুড়ে দেওয়া হয়েছে।" },
    hadith: { en: "Two words are light on the tongue, heavy in the balance, and beloved to the Most Merciful: Subhan-Allahi wa bi-hamdihi, Subhan-Allahi al-'Azim.", bn: "দুটি কথা জিহ্বায় হালকা, মিজানে ভারী এবং রহমানের কাছে প্রিয়: সুবহানাল্লাহি ওয়া বিহামদিহি, সুবহানাল্লাহিল-আযিম।", src: "Sahih al-Bukhari 6682; Sahih Muslim 2694" } ,
    invoke: { en: "Magnify Him in every ruku with 'Subhana Rabbiya-l-'Azim', and in distress say the Prophet's du'a: 'La ilaha illallahu-l-'Azimu-l-Halim.' When your problems appear enormous, recite Ayat al-Kursi and remember that He is greater than everything you fear.", bn: "প্রতিটি রুকুতে 'সুবহানা রাব্বিয়াল-আজিম' বলে তাঁর মহিমা ঘোষণা করুন, আর বিপদে নবী ﷺ-এর দু'আ পড়ুন: 'লা ইলাহা ইল্লাল্লাহুল-আজিমুল-হালিম।' সমস্যা বিশাল মনে হলে আয়াতুল কুরসি পড়ুন এবং মনে রাখুন — আপনি যা ভয় করেন তিনি তার সবকিছুর চেয়ে মহান।" },
    quranicRefs: [
      { ref: "2:255", noteEn: "Wa Huwa-l-Aliyy-ul-Azim — the Throne Verse closes with Al-Azim after the fullest description of divine attributes.", noteBn: "ওয়া হুওয়াল-আলিয়্যুল-আযিম: আল্লাহর গুণাবলির সবচেয়ে পূর্ণ বর্ণনার পর আয়াতুল কুরসি শেষ হয় আল-আযিম নামে।" },
      { ref: "42:4", noteEn: "Wa Huwa-l-Aliyy-ul-Azim — all in heavens and earth belongs to Him; He is Most High, Most Great.", noteBn: "ওয়া হুওয়াল-আলিয়্যুল-আযিম — আকাশ-পৃথিবীর সব তাঁর; তিনি সর্বোচ্চ, সর্বমহান।" },
      { ref: "56:74", noteEn: "fa-sabbih bi-smi Rabbika-l-Azim — glorify your Lord Al-Azim; the prescribed tasbih of ruku in prayer.", noteBn: "ফাসাব্বিহ বিসমি রাব্বিকাল-আযিম — তোমার মহান রব আল-আযিমের নামে তাসবিহ পড়ো; নামাজে রুকুর নির্ধারিত তাসবিহ এ থেকেই।" },
      { ref: "56:96", noteEn: "fa-sabbih bi-smi Rabbika-l-Azim — repeated at surah's end, bookending the eschatological account.", noteBn: "ফাসাব্বিহ বিসমি রাব্বিকাল-আযিম — সূরার শেষে কথাটি আবার এসেছে; আখিরাতের পুরো বর্ণনাকে দুই দিক থেকে এই তাসবিহই ঘিরে রেখেছে।" }
    ]},
  { n: 34, ar: "الْغَفُورُ", translit: "Al-Ghafūr", meanings: { en: "The All-Forgiving", bn: "ক্ষমাপরায়ণ", fr: "Le Pardonneur", id: "Yang Maha Pengampun", ur: "بخشنے والا", tr: "Bağışlayıcı", ar: "الساتر للذنوب" , zh: '永恕者', ja: '全てを受け入れしもの', hi: 'बख़्शने वाला', es: 'El Perdonador', ru: 'Прощающий', de: 'Der Allvergebende', fa: 'آمرزنده', ms: 'Yang Maha Pengampun'},
    explain: { en: "Al-Ghafur describes the totality of Allah's forgiveness — sins are not just overlooked but truly erased, covered, and removed as if they never happened. The difference from Al-Ghaffar is one of intensity: Al-Ghaffar is habitual, repeated forgiveness; Al-Ghafur is comprehensive, all-covering forgiveness. Quran 39:53 is the strongest promise: 'Say, O My servants who have transgressed against themselves, do not despair of the mercy of Allah. Indeed, Allah forgives all sins.' This was revealed as a universal invitation, not limited to any category of sin.", bn: "আল-গাফুর নামে আল্লাহর ক্ষমার পূর্ণতা ফুটে ওঠে। তিনি গুনাহ শুধু এড়িয়ে যান না, সত্যিই মুছে দেন, ঢেকে দেন, এমনভাবে সরিয়ে দেন যেন তা কখনো ঘটেইনি। আল-গাফফারের সাথে পার্থক্যটা মাত্রার: আল-গাফফার বারবার, অভ্যাসের মতো ক্ষমা করেন; আল-গাফুরের ক্ষমা সবকিছু ঢেকে নেয়, কিছুই বাদ রাখে না। কুরআনের সবচেয়ে জোরালো প্রতিশ্রুতি ৩৯:৫৩-এ: 'বলো, হে আমার বান্দারা, যারা নিজেদের প্রতি সীমালঙ্ঘন করেছ, আল্লাহর রহমত থেকে নিরাশ হয়ো না। নিশ্চয়ই আল্লাহ সব গুনাহ মাফ করে দেন।' এ আয়াত নাজিল হয়েছে সবার জন্য খোলা দাওয়াত হিসেবে, কোনো বিশেষ ধরনের গুনাহে তা সীমাবদ্ধ নয়।" },
    hadith: { en: "If you were to commit sin until your sins reached the heaven, then you were to ask Allah for forgiveness, He would forgive you.", bn: "তুমি যদি এত গুনাহ করো যে তা আকাশ পর্যন্ত পৌঁছে যায়, তারপর আল্লাহর কাছে ক্ষমা চাও, তিনি তোমাকে ক্ষমা করে দেবেন।", src: "Sunan ibn Majah 4248; al-Tirmidhi 3540 (Hasan)" } ,
    invoke: { en: "When burdened by a grave sin you fear is unforgivable, call upon Ya Ghafur — He forgives all sins completely and never lets a repentant servant despair of His mercy. Recite 'Astaghfirullah al-Ghafur ar-Rahim' with a sincere heart, for He loves to pardon.", bn: "কোনো বড় গুনাহের ভার বুকে চেপে বসলে, আর ভয় হলে যে এ গুনাহ বুঝি মাফ হবে না, তখন 'ইয়া গাফুর' বলে ডাকুন। তিনি সব গুনাহ পুরোপুরি মাফ করেন, তওবাকারী কোনো বান্দাকে তাঁর রহমত থেকে নিরাশ হতে দেন না। খাঁটি মনে পড়ুন 'আস্তাগফিরুল্লাহ আল-গাফুর আর-রাহিম', কারণ ক্ষমা করতে তিনি ভালোবাসেন।" } ,
    quranicRefs: [
      { ref: "2:173", noteEn: "Inna-llaha Ghafurun Rahim — paired with Ar-Rahim in rulings on necessity; mercy governs the law.", noteBn: "ইন্নাল্লাহা গাফুরুন রাহিম — নিরুপায় অবস্থার বিধানে আর-রাহিমের সাথে এসেছে; বিধানের ওপরেও রহমতই কর্তৃত্ব করে।" },
      { ref: "35:28", noteEn: "Inna-llaha Azizun Ghafur — might and forgiveness together; power does not preclude mercy.", noteBn: "ইন্নাল্লাহা আযিযুন গাফুর — শক্তি ও ক্ষমা একসাথে; শক্তি রহমতকে বাধা দেয় না।" },
      { ref: "39:53", noteEn: "Inna-llaha yaghfiru-dh-dhunuba jami'a — Allah forgives ALL sins; the broadest forgiveness promise in the Quran.", noteBn: "ইন্নাল্লাহা ইয়াগফিরুয-যুনুবা জামিআ — আল্লাহ সব গুনাহ মাফ করেন; কুরআনে ক্ষমার সবচেয়ে ব্যাপক প্রতিশ্রুতি।" },
      { ref: "64:14", noteEn: "wa-in ta'fu wa-tasfahhu wa-taghfiru fa-inna-llaha Ghafurun Rahim — if you pardon, Allah is Ghafur and Rahim.", noteBn: "ওয়াইন তাআফু ওয়াতাসফাহু ওয়াতাগফিরু ফাইন্নাল্লাহা গাফুরুন রাহিম — তোমরা মাফ করে দিলে জেনো, আল্লাহও গাফুর ও রাহিম।" }
    ]},
  { n: 35, ar: "الشَّكُورُ", translit: "Ash-Shakūr", meanings: { en: "The Appreciative", bn: "গুণগ্রাহী", fr: "Le Reconnaissant", id: "Yang Maha Mensyukuri", ur: "قدر دان", tr: "Şükre Karşılık Veren", ar: "المجازي على القليل بالكثير" , zh: '受謝者', ja: '感謝される者', hi: 'क़द्रदान', es: 'El Agradecido', ru: 'Признательный', de: 'Der stets zu Dank Bereite', fa: 'قدرشناس', ms: 'Yang Maha Menghargai'},
    explain: { en: "Ash-Shakur is a remarkable name: Allah is the One who is deeply appreciative of even the smallest good deed and rewards it with a return far exceeding what was offered. A human cannot truly 'give' Allah anything — yet He acknowledges and rewards every atom of sincerity. The Quran (35:30) says He 'rewards them fully and increases them of His bounty.' Al-Ghazali writes that knowing this name transforms worship: even a tiny sincere deed is not wasted before Allah.", bn: "আশ-শাকুর এক অসাধারণ নাম। ছোট থেকে ছোট ভালো কাজেরও আল্লাহ গভীর কদর করেন, আর বান্দা যা দিয়েছে তার চেয়ে বহুগুণ বেশি প্রতিদান দেন। মানুষ সত্যিকার অর্থে আল্লাহকে কিছুই 'দিতে' পারে না, তবু অণু পরিমাণ ইখলাসেরও তিনি মূল্য দেন, প্রতিদান দেন। কুরআন (৩৫:৩০) বলছে, তিনি 'তাদের প্রতিদান পুরোপুরি দেবেন এবং নিজ অনুগ্রহে আরও বাড়িয়ে দেবেন।' আল-গাজালী লিখেছেন, এই নাম চিনলে ইবাদতের চেহারাই বদলে যায়: খাঁটি নিয়তের ছোট্ট আমলও আল্লাহর কাছে বৃথা যায় না।" } ,
    invoke: { en: "No deed is too small for Ash-Shakur — He multiplies the sincere mustard-seed of good. Do good consistently and pray as Sulayman did: 'My Lord, enable me to be grateful for Your favour' (27:19), and praise Him after every meal knowing He appreciates it.", bn: "আশ-শাকুরের কাছে কোনো আমলই ছোট নয়। খাঁটি নিয়তে করা সরিষার দানা পরিমাণ নেকিও তিনি বহুগুণ বাড়িয়ে দেন। নিয়মিত নেক আমল করুন, আর সুলাইমানের মতো দু'আ করুন: 'হে আমার রব, আপনার নিয়ামতের শোকর আদায়ের সামর্থ্য দিন' (২৭:১৯)। প্রতিবার খাওয়ার পর তাঁর প্রশংসা করুন; জেনে রাখুন, তিনি এর কদর করেন।" },
    quranicRefs: [
      { ref: "35:30", noteEn: "Inna-hu Ghafurun Shakur — Forgiving and Appreciative; Allah appreciates even the deeds He forgave.", noteBn: "ইন্নাহু গাফুরুন শাকুর — ক্ষমাশীল ও গুণগ্রাহী; আল্লাহ যে আমলগুলো মাফ করেছেন, সেগুলোরও কদর করেন।" },
      { ref: "35:34", noteEn: "Inna Rabbana la-Ghafurun Shakur — the people of Paradise praise their Lord who is Ghafur and Shakur.", noteBn: "ইন্না রাব্বানা লা-গাফুরুন শাকুর — জান্নাতবাসীরা তাদের রবের প্রশংসা করে বলবে, তিনি গাফুর ও শাকুর।" },
      { ref: "42:23", noteEn: "Inna-llaha Ghafurun Shakur — Allah rewards good deeds and appreciates even the smallest sincere act.", noteBn: "ইন্নাল্লাহা গাফুরুন শাকুর — আল্লাহ নেক আমলের প্রতিদান দেন, খাঁটি নিয়তের ছোট্ট কাজেরও কদর করেন।" },
      { ref: "64:17", noteEn: "Wa-llahu Shakurun Halim — Allah is Ash-Shakur and Al-Halim; He rewards charity with appreciation and patience.", noteBn: "ওয়াল্লাহু শাকুরুন হালিম — আল্লাহ আশ-শাকুর ও আল-হালিম; দান-সদকার প্রতিদান তিনি দেন কদর ও ধৈর্যের সাথে।" }
    ]},
  { n: 36, ar: "الْعَلِيُّ", translit: "Al-ʿAliyy", meanings: { en: "The Most High", bn: "সর্বোচ্চ", fr: "Le Très-Haut", id: "Yang Maha Tinggi", ur: "سب سے بلند", tr: "Pek Yüksek", ar: "العالي فوق خلقه" , zh: '崇高者', ja: '高貴で崇高なる者', hi: 'सबसे बुलंद', es: 'El Altísimo', ru: 'Возвышенный', de: 'Der Erhabene', fa: 'والا', ms: 'Yang Maha Tinggi'},
    explain: { en: "Al-'Aliyy is supremely high in essence, attributes, and status — not physically 'above' in a spatial sense, but ontologically transcendent over all creation. Ayat al-Kursi ends with 'al-'Aliyy al-'Azim' (2:255), connecting this name with supreme greatness. Ibn al-Qayyim distinguishes three types of 'uluww (highness): highness in essence ('uluww al-dhat), highness in attributes ('uluww al-sifat), and highness in power and domination ('uluww al-qahr) — Allah possesses all three absolutely.", bn: "আল-আলিয়্যু সত্তায়, গুণে ও মর্যাদায় সবার ঊর্ধ্বে; সমস্ত সৃষ্টির ওপরে তিনি, কোনো কিছুর সাথে তাঁর তুলনা চলে না। আয়াতুল কুরসি শেষ হয়েছে 'আল-আলিয়্যুল আযিম' দিয়ে (২:২৫৫); ফলে এই নাম মিলে গেছে পরম মহত্ত্বের সাথে। ইবনুল কাইয়িম উলুউ বা উচ্চতাকে তিন ভাগে দেখিয়েছেন: সত্তার উচ্চতা (উলুউ আয-যাত), গুণের উচ্চতা (উলুউ আস-সিফাত), আর ক্ষমতা ও আধিপত্যের উচ্চতা (উলুউ আল-কাহর)। আল্লাহর মধ্যে তিনটিই আছে পরিপূর্ণভাবে।" } ,
    hadith: { en: "The Prophet ﷺ asked Ubayy ibn Ka'b which verse of Allah's Book is greatest; he answered: Ayat al-Kursi — the verse that ends 'and He is Al-'Aliyy, Al-'Azim.' The Prophet ﷺ approved: 'May knowledge delight you, Abu-l-Mundhir!'", bn: "নবী ﷺ উবাই ইবনে কা'ব (রাঃ)-কে জিজ্ঞেস করলেন, আল্লাহর কিতাবের সবচেয়ে মহান আয়াত কোনটি। তিনি বললেন: আয়াতুল কুরসি, যার শেষে আছে 'তিনিই আল-আলিয়্যু, আল-আজিম'। নবী ﷺ খুশি হয়ে বললেন: 'হে আবুল মুনযির, তোমার জন্য জ্ঞান মোবারক হোক!'", src: "Sahih Muslim 810" },
    invoke: { en: "Glorify the Most High in every sujud with 'Subhana Rabbiya-l-A'la' — physically at your lowest while praising the Highest. When difficulties tower over you, say 'la hawla wa la quwwata illa billahi-l-'Aliyyi-l-'Azim' — there is no power except by the Most High, the Magnificent.", bn: "প্রতিটি সিজদায় 'সুবহানা রাব্বিয়াল-আ'লা' বলে সর্বোচ্চ রবের পবিত্রতা ঘোষণা করুন। দেহ তখন সবচেয়ে নিচুতে, আর মুখে সবচেয়ে উঁচু সত্তার প্রশংসা। বিপদ যখন পাহাড়ের মতো মাথার ওপর চেপে বসে, বলুন: 'লা হাওলা ওয়া লা কুওয়াতা ইল্লা বিল্লাহিল-আলিয়্যিল-আজিম', অর্থাৎ সর্বোচ্চ, মহান আল্লাহ ছাড়া কোনো শক্তি নেই।" },
    quranicRefs: [
      { ref: "2:255", noteEn: "Wa Huwa-l-Aliyy-ul-Azim — the Throne Verse's closing pair: supreme in transcendence and greatness.", noteBn: "ওয়া হুওয়াল-আলিয়্যুল-আযিম — আয়াতুল কুরসির শেষের দুই নাম: তিনি সবার ঊর্ধ্বে, সবচেয়ে মহান।" },
      { ref: "4:34", noteEn: "Inna-llaha kana Aliyyan Kabira — Allah is Al-Aliyy, Al-Kabir, in the context of authority and family relations.", noteBn: "ইন্নাল্লাহা কানা আলিয়্যান কাবিরা — কর্তৃত্ব ও পারিবারিক সম্পর্কের আয়াতে আল্লাহ নিজেকে আল-আলিয়্যু ও আল-কাবির বলেছেন।" },
      { ref: "22:62", noteEn: "Dhalika bi-anna-llaha Huwa-l-Haqq... wa anna-llaha Huwa-l-Aliyy-ul-Kabir — truth and highness affirmed together.", noteBn: "যালিকা বিআন্নাল্লাহা হুওয়াল-হাক্ক... ওয়া আন্নাল্লাহা হুওয়াল-আলিয়্যুল-কাবির — সত্য ও উচ্চতা একসাথে।" },
      { ref: "31:30", noteEn: "Wa anna-llaha Huwa-l-Aliyy-ul-Kabir — Al-Haqq, Al-Aliyy, Al-Kabir together; falsehood is vain beside His highness.", noteBn: "ওয়া আন্নাল্লাহা হুওয়াল-আলিয়্যুল-কাবির — আল-হাক্ক, আল-আলিয়্যু, আল-কাবির একসাথে; তাঁর উচ্চতার পাশে মিথ্যা অসার।" },
      { ref: "42:4", noteEn: "Wa Huwa-l-Aliyy-ul-Azim — all creation belongs to Him; He is Most High and Most Great above His creation.", noteBn: "ওয়া হুওয়াল-আলিয়্যুল-আযিম — সমস্ত সৃষ্টি তাঁর; তিনি সৃষ্টির উপরে সর্বোচ্চ ও সর্বমহান।" }
    ]},
  { n: 37, ar: "الْكَبِيرُ", translit: "Al-Kabīr", meanings: { en: "The Most Great", bn: "সুমহান", fr: "Le Très Grand", id: "Yang Maha Besar", ur: "سب سے بڑا", tr: "Pek Büyük", ar: "الكبير المتعال" , zh: '偉大者', ja: '偉大なる者', hi: 'सबसे बड़ा', es: 'El Grande', ru: 'Величайший', de: 'Der Große', fa: 'بزرگ', ms: 'Yang Maha Besar'},
    explain: { en: "Al-Kabir describes a greatness inherent in Allah's being — not greatness measured against something else, but self-subsisting divine magnificence. The Quran (13:9) pairs Al-Kabir with Al-Muta'al: 'the Most Great, the Most High.' Human greatness is relative and borrowed; Allah's greatness is absolute and self-originating. Recognising Al-Kabir helps the servant calibrate all other greatness: every king, nation, and star is infinitesimally small before Al-Kabir.", bn: "আল-কাবির নামে সেই মহত্ত্বের কথা, যা আল্লাহর সত্তার মধ্যেই আছে। অন্য কিছুর সাথে মেপে এ মহত্ত্ব নয়; এ তাঁর নিজস্ব, কারও ওপর নির্ভরশীল নয়। কুরআন (১৩:৯) আল-কাবিরের সাথে আল-মুতাআলকে জুড়ে বলেছে: 'মহান, সর্বোচ্চ।' মানুষের বড়ত্ব আপেক্ষিক, ধার করা; আল্লাহর মহত্ত্ব পরম, কারও কাছ থেকে পাওয়া নয়। আল-কাবিরকে চিনলে বান্দা অন্য সব বড়ত্বের সঠিক মাপ বুঝতে পারে: প্রতিটি রাজা, জাতি আর নক্ষত্র আল-কাবিরের সামনে অতি তুচ্ছ।" } ,
    invoke: { en: "Declare His greatness with takbir — in the adhan, in every movement of salah, and on the days of Eid. When any fear or task seems too big, answer it with 'Allahu Akbar': Allah is greater. Ask Al-Kabir to remove love of status and self-importance from your heart.", bn: "তাকবির দিয়ে তাঁর বড়ত্ব ঘোষণা করুন: আজানে, নামাজের প্রতিটি ওঠাবসায়, ঈদের দিনগুলোতে। কোনো ভয় বা কাজ খুব বড় মনে হলে জবাব দিন 'আল্লাহু আকবার' বলে: আল্লাহ তার চেয়েও বড়। আল-কাবিরের কাছে চান, তিনি যেন অন্তর থেকে পদমর্যাদার মোহ আর নিজেকে বড় ভাবার রোগ দূর করে দেন।" },
    quranicRefs: [
      { ref: "13:9", noteEn: "Alim-ul-ghaybi wal-shahada Al-Kabir-ul-Muta'al — Knower of the unseen and seen, Most Great, Most Exalted.", noteBn: "আলিমুল-গায়বি ওয়াশ-শাহাদাতিল-কাবিরুল-মুতাআল — অদৃশ্য ও দৃশ্যের জ্ঞানী, মহান, সর্বোচ্চ।" },
      { ref: "22:62", noteEn: "Wa anna-llaha Huwa-l-Aliyy-ul-Kabir — Allah is Most High and Most Great; all worshipped besides Him is falsehood.", noteBn: "ওয়া আন্নাল্লাহা হুওয়াল-আলিয়্যুল-কাবির — আল্লাহ সর্বোচ্চ ও মহান; তাঁকে ছাড়া আর যার ইবাদত করা হয়, সবই বাতিল।" },
      { ref: "31:30", noteEn: "Wa anna-llaha Huwa-l-Aliyy-ul-Kabir — divine truth versus falsehood; Al-Kabir affirms absolute greatness.", noteBn: "ওয়া আন্নাল্লাহা হুওয়াল-আলিয়্যুল-কাবির — আল্লাহর সত্য আর বাতিলের মুখোমুখি অবস্থান; আল-কাবির নাম তাঁর পরম মহত্ত্ব ঘোষণা করে।" },
      { ref: "34:23", noteEn: "Inna-llaha Huwa-l-Aliyy-ul-Kabir — intercession avails only with His permission; His greatness is ultimate.", noteBn: "ইন্নাল্লাহা হুওয়াল-আলিয়্যুল-কাবির — তাঁর অনুমতি ছাড়া কোনো সুপারিশ কাজে আসে না; তাঁর মহত্ত্বই চূড়ান্ত।" },
      { ref: "40:12", noteEn: "Dhalika bi-anna-llaha Huwa-l-Aliyy-ul-Kabir — the final verdict on the Day of Judgement affirms His supreme greatness.", noteBn: "যালিকা বিআন্নাল্লাহা হুওয়াল-আলিয়্যুল-কাবির — কিয়ামতের দিনের চূড়ান্ত রায়ে তাঁর সর্বোচ্চ মহত্ত্বই প্রকাশ পায়।" }
    ]},
  { n: 38, ar: "الْحَفِيظُ", translit: "Al-Ḥafīẓ", meanings: { en: "The Preserver", bn: "মহারক্ষক", fr: "Le Gardien", id: "Yang Maha Menjaga", ur: "حفاظت کرنے والا", tr: "Koruyup Gözeten", ar: "الحافظ لكل شيء" , zh: '保護者', ja: '管理せし者', hi: 'हिफ़ाज़त करने वाला', es: 'El Preservador', ru: 'Хранитель', de: 'Der Behüter', fa: 'نگه‌دارنده', ms: 'Yang Maha Menjaga'},
    explain: { en: "Al-Hafiz preserves everything — the Quran from corruption, the universe from disintegration, the righteous from ruin, and the deeds of every person for the reckoning. The Quran (86:4) states: 'There is no soul but that it has over it a protector.' Prophet Ya'qub (Jacob, peace be upon him) entrusted his sons to 'Khayru-l-Hafizin' (the Best of Preservers, Quran 12:64) when sending them to Egypt. Knowing this name builds reliance on Allah's protection above all human precautions.", bn: "আল-হাফিজ সবকিছু হেফাজত করেন: কুরআনকে বিকৃতি থেকে, মহাবিশ্বকে ভেঙে পড়া থেকে, নেককারদের ধ্বংস থেকে; আর প্রত্যেক মানুষের আমল তিনি হিসাবের দিনের জন্য সংরক্ষিত রাখেন। কুরআন (৮৬:৪) বলছে: 'এমন কোনো প্রাণ নেই, যার ওপর একজন রক্ষক নেই।' ইয়াকুব (আঃ) ছেলেদের মিসরে পাঠানোর সময় তাদের সঁপে দিয়েছিলেন 'খাইরুল হাফিজিন', অর্থাৎ সর্বোত্তম রক্ষাকারীর হাতে (কুরআন ১২:৬৪)। এই নাম জানা থাকলে মানুষের সব সতর্কতার চেয়ে আল্লাহর হেফাজতের ওপর ভরসা বাড়ে।" } ,
    invoke: { en: "When traveling, sleeping, or fearing for those you love, call upon Ya Hafiz to guard you from every harm seen and unseen. Recite Ayat al-Kursi and the morning and evening adhkar, entrusting your body, faith, and family to the One who never neglects what He preserves.", bn: "সফরে, ঘুমানোর আগে, কিংবা প্রিয়জনদের নিয়ে ভয় হলে 'ইয়া হাফিজ' বলে ডাকুন, যেন তিনি দৃশ্য-অদৃশ্য সব ক্ষতি থেকে আপনাকে রক্ষা করেন। আয়াতুল কুরসি আর সকাল-সন্ধ্যার জিকিরগুলো পড়ুন। নিজের শরীর, ঈমান ও পরিবারকে সঁপে দিন তাঁর হাতে, যিনি নিজের হেফাজতের কিছুই কখনো অবহেলা করেন না।" } ,
    hadith: { en: "The Prophet ﷺ said to Ibn Abbas: 'Be mindful of Allah and He will guard you; be mindful of Allah and you will find Him before you.'", bn: "নবী ﷺ ইবনে আব্বাস (রাঃ)-কে বললেন: 'আল্লাহর (বিধানের) হেফাজত করো, আল্লাহ তোমার হেফাজত করবেন; আল্লাহর হেফাজত করো, তাঁকে তোমার সামনে পাবে।'", src: "Jami' at-Tirmidhi 2516 — hasan sahih" },
    quranicRefs: [
      { ref: "11:57", noteEn: "Inna Rabbi ala kulli shay'in Hafiz — My Lord is Preserver over all things; Hud's declaration of divine guardianship.", noteBn: "ইন্না রাব্বি আলা কুল্লি শায়িন হাফিজ — আমার রব সবকিছুর হাফিজ; আল্লাহর অভিভাবকত্ব নিয়ে হুদের ঘোষণা।" },
      { ref: "12:64", noteEn: "fa-Allahu Khayru Hafizin — Allah is the Best of Preservers; Ya'qub entrusts his sons to Al-Hafiz.", noteBn: "ফাল্লাহু খায়রুন হাফিজান — আল্লাহই সর্বোত্তম হাফিজ; ইয়াকুব নিজের ছেলেদের আল-হাফিজের হাতে সঁপে দেন।" },
      { ref: "34:21", noteEn: "Wa Rabbuka ala kulli shay'in Hafiz — Your Lord is Preserver of all; affirmed regarding Shaytan's limited power.", noteBn: "ওয়া রাব্বুকা আলা কুল্লি শায়িন হাফিজ — তোমার রব সবকিছুর হাফিজ; শয়তানের ক্ষমতা যে সীমিত, সেই প্রসঙ্গে বলা।" },
      { ref: "86:4", noteEn: "In kullu nafsin lamma alayha hafizun — over every soul there is a Preserver; divine guardianship is universal.", noteBn: "ইন কুল্লু নাফসিন লাম্মা আলায়হা হাফিজুন — প্রত্যেক প্রাণের ওপর একজন রক্ষক আছেন; আল্লাহর হেফাজত সবার জন্য।" }
    ]},
  { n: 39, ar: "الْمُقِيتُ", translit: "Al-Muqīt", meanings: { en: "The Sustainer", bn: "আহারদাতা", fr: "Le Nourricier", id: "Yang Maha Pemberi Kecukupan", ur: "روزی پہنچانے والا", tr: "Azık Veren", ar: "المتكفل بالأقوات" , zh: '給養者', ja: '栄養を与えし者', hi: 'रोज़ी पहुँचाने वाला', es: 'El que nutre', ru: 'Питающий', de: 'Der Ernährende', fa: 'روزی‌رسان', ms: 'Yang Maha Pemberi Kecukupan'},
    explain: { en: "Al-Muqit means the One who provides the specific sustenance (qut) each creature needs — physical food for the body, spiritual nourishment for the soul, knowledge for the intellect. The root qawt refers to the minimum necessary sustenance, suggesting Allah provides precisely what each being needs. Al-Ghazali notes that Al-Muqit is more specific than Ar-Razzaq: while Ar-Razzaq is the general Provider, Al-Muqit is the precise Sustainer who tailors each provision.", bn: "আল-মুকিত তিনি, যিনি প্রতিটি সৃষ্টিকে তার প্রয়োজনের নির্দিষ্ট রিজিক (কুত) দেন: শরীরের জন্য খাবার, আত্মার জন্য রুহানি খোরাক, বুদ্ধির জন্য জ্ঞান। মূল শব্দ কাওত মানে বেঁচে থাকার জন্য ন্যূনতম যতটুকু দরকার; অর্থাৎ আল্লাহ প্রত্যেককে ঠিক ততটুকুই দেন, যতটুকু তার প্রয়োজন। আল-গাজালী বলেছেন, আল-মুকিত নামটি আর-রাজ্জাকের চেয়ে বেশি নির্দিষ্ট। আর-রাজ্জাক সাধারণভাবে রিজিকদাতা; আল-মুকিত প্রত্যেকের রিজিক মেপে মেপে তার মাপমতো ঠিক করে দেন।" } ,
    invoke: { en: "When you worry about food, strength, or the means to endure a hardship, call upon Ya Muqit — He apportions the nourishment of every creature and gives each what sustains its body and soul. Ask Him for both physical provision and the inner strength to persevere.", bn: "খাবার, শক্তি, কিংবা কষ্ট সামলানোর সামর্থ্য নিয়ে দুশ্চিন্তা হলে 'ইয়া মুকিত' বলে ডাকুন। প্রতিটি সৃষ্টির খোরাক তিনিই ভাগ করে দেন, প্রত্যেককে দেন দেহ ও মনের রসদ। তাঁর কাছে শরীরের রিজিকও চান, টিকে থাকার ভেতরের শক্তিও চান।" } ,
    quranicRefs: [
      { ref: "4:85", noteEn: "Wa kana-llahu ala kulli shay'in Muqita — Allah is Muqit over all things; the only explicit Quranic mention.", noteBn: "ওয়া কানাল্লাহু আলা কুল্লি শায়িন মুকিতান — আল্লাহ সব কিছুর মুকিত; কুরআনে একমাত্র সরাসরি উল্লেখ।" }
    ]},
  { n: 40, ar: "الْحَسِيبُ", translit: "Al-Ḥasīb", meanings: { en: "The Reckoner", bn: "হিসাব গ্রহণকারী", fr: "Celui qui compte", id: "Yang Maha Membuat Perhitungan", ur: "حساب لینے والا", tr: "Hesaba Çeken", ar: "الكافي المحاسِب" , zh: '計算者', ja: '計算する者', hi: 'हिसाब लेने वाला', es: 'El que toma cuentas', ru: 'Ведущий счёт', de: 'Der Abrechnende', fa: 'حسابرس', ms: 'Yang Maha Membuat Perhitungan'},
    explain: { en: "Al-Hasib has two connected meanings: the Reckoner who takes the most precise account of all deeds on the Day of Judgement, and the Sufficient One who suffices His servants and fulfills all their needs. Quran 4:6 says 'and Allah is sufficient as a Reckoner.' The believer who says 'hasbiyallah' (Allah is sufficient for me) is invoking Al-Hasib: the One whose account is perfect and whose sufficiency is complete.", bn: "আল-হাসিব নামের দুটি অর্থ, একটির সাথে আরেকটি জড়িত। তিনি সেই হিসাবগ্রহণকারী, যিনি কিয়ামতের দিন সব আমলের নিখুঁত হিসাব নেবেন; আবার তিনিই বান্দাদের জন্য যথেষ্ট, তাদের সব প্রয়োজন পূরণ করেন। কুরআন ৪:৬ বলছে: 'হিসাব নেওয়ার জন্য আল্লাহই যথেষ্ট।' মুমিন যখন বলে 'হাসবিয়াল্লাহ' (আল্লাহই আমার জন্য যথেষ্ট), তখন সে আল-হাসিবকেই ডাকে: যাঁর হিসাব নিখুঁত, যিনি একাই যথেষ্ট।" },
    invoke: { en: "When overwhelmed by worry — about enemies, finances, or the future — say 'Hasbiyallahu la ilaha illa Huwa, 'alayhi tawakkaltu wa Huwa Rabb al-'Arsh al-'Azim' (Quran 9:129). This was the du'a of the Prophet (peace be upon him) in his most difficult moments.", bn: "শত্রু, টাকা-পয়সা বা ভবিষ্যৎ নিয়ে দুশ্চিন্তা যখন চেপে ধরে, বলুন: 'হাসবিয়াল্লাহু লা ইলাহা ইল্লা হুওয়া, আলায়হি তাওয়াক্কালতু ওয়া হুওয়া রাব্বুল আরশিল আযিম' (কুরআন ৯:১২৯)। সবচেয়ে কঠিন মুহূর্তগুলোতে নবী ﷺ এই দু'আ করতেন।" } ,
    hadith: { en: "Ibn Abbas said: 'Hasbunallahu wa ni'mal-Wakil (Allah is sufficient for us, and He is the best Disposer of affairs)' — Ibrahim said it when he was cast into the fire, and Muhammad ﷺ said it when it was said: 'The people have gathered against you, so fear them.'", bn: "ইবনে আব্বাস (রাঃ) বলেন: 'হাসবুনাল্লাহু ওয়া নি'মাল-ওয়াকিল (আল্লাহই আমাদের জন্য যথেষ্ট, আর তিনি কতই না উত্তম কর্মবিধায়ক)।' আগুনে নিক্ষিপ্ত হওয়ার সময় ইব্রাহিম (আঃ) এ কথা বলেছিলেন। আর মুহাম্মাদ ﷺ বলেছিলেন তখন, যখন লোকেরা বলল: 'মানুষ তোমাদের বিরুদ্ধে জড়ো হয়েছে, তাদের ভয় করো।'", src: "Sahih al-Bukhari 4563" },
    quranicRefs: [
      { ref: "4:6", noteEn: "Wa kafa billahi Hasiba — Allah suffices as Reckoner for the distribution of orphans' wealth.", noteBn: "ওয়া কাফা বিল্লাহি হাসিবা — এতিমদের সম্পদ বুঝিয়ে দেওয়ার সময় হিসাব নেওয়ার জন্য আল্লাহই যথেষ্ট।" },
      { ref: "4:86", noteEn: "Inna-llaha kana ala kulli shay'in Hasiba — Allah is Hasib over all things; even responding to a greeting is accounted.", noteBn: "ইন্নাল্লাহা কানা আলা কুল্লি শায়িন হাসিবান — আল্লাহ সবকিছুর হাসিব; সালামের জবাবও তাঁর হিসাবে ধরা থাকে।" },
      { ref: "17:14", noteEn: "Iqra kitabaka kafa bi-nafsika-l-yawm alayka Hasiba — read your record; you suffice today as Hasib against yourself.", noteBn: "ইকরা কিতাবাকা কাফা বিনাফসিকাল-ইয়াওমা আলায়কা হাসিবা — তোমার আমলনামা পড়ো; আজ নিজের হিসাব নেওয়ার জন্য তুমি নিজেই যথেষ্ট।" },
      { ref: "33:39", noteEn: "Wa kafa billahi Hasiba — those who convey Allah's messages need fear only Him as the ultimate Hasib.", noteBn: "ওয়া কাফা বিল্লাহি হাসিবা — যাঁরা আল্লাহর বাণী পৌঁছে দেন, তাঁদের ভয় করার কেউ নেই আল্লাহ ছাড়া; চূড়ান্ত হিসাবগ্রহণকারী তিনিই।" }
    ]},
  { n: 41, ar: "الْجَلِيلُ", translit: "Al-Jalīl", meanings: { en: "The Majestic", bn: "মহামহিমান্বিত", fr: "Le Majestueux", id: "Yang Maha Luhur", ur: "بزرگی والا", tr: "Ululuk Sahibi", ar: "ذو الجلال والعظمة" , zh: '至尊者', ja: '雄大なる者', hi: 'जलाल वाला', es: 'El Majestuoso', ru: 'Величественный', de: 'Der Majestätische', fa: 'شکوهمند', ms: 'Yang Maha Luhur'},
    explain: { en: "Al-Jalil describes divine majesty — the combination of supreme power, absolute transcendence, and infinite grandeur that inspires profound awe and reverence. It differs from Al-Kabir (greatness of size) and Al-'Azim (greatness of magnitude): Al-Jalil is the majesty that overwhelms the heart. The Quran ends Surah ar-Rahman (55:27) with 'Dhul-Jalali wal-Ikram' — Lord of Majesty and Honour — as a summarising title for all the blessings enumerated. True jalal (majesty) is Allah's alone.", bn: "আল-জালিল নামে আল্লাহর মহিমার কথা: সর্বোচ্চ ক্ষমতা, সবকিছুর ঊর্ধ্বে থাকা আর অসীম মহত্ত্ব মিলে সেই মহিমা, যা অন্তরে গভীর ভয় ও সম্ভ্রম জাগায়। আল-কাবির (আকারের বড়ত্ব) আর আল-আযিম (বিশালতার বড়ত্ব) থেকে এটি আলাদা: আল-জালিল সেই মহিমা, যা হৃদয়কে অভিভূত করে দেয়। কুরআনে সূরা আর-রাহমান (৫৫:২৭) শেষ হয়েছে 'যুল-জালালি ওয়াল-ইকরাম' কথাটি দিয়ে, অর্থাৎ মহিমা ও সম্মানের অধিকারী; সূরায় গোনা সব নিয়ামতের সারকথা এই উপাধি। প্রকৃত জালাল (মহিমা) কেবল আল্লাহরই।" } ,
    invoke: { en: "Approach Al-Jalil with awe (haybah) in your worship — stand in prayer conscious of His majesty. Persist in saying 'Ya Dhal-Jalali wal-Ikram' in your du'as as the Prophet ﷺ instructed, letting reverence for His grandeur deepen your khushu'.", bn: "ইবাদতে ভীতিমিশ্রিত সম্ভ্রম (হাইবাহ) নিয়ে আল-জালিলের সামনে দাঁড়ান; নামাজে দাঁড়ান তাঁর মহিমার কথা মনে রেখে। নবী ﷺ যেমন শিখিয়েছেন, দু'আয় বারবার বলুন 'ইয়া যাল-জালালি ওয়াল-ইকরাম'। তাঁর মহিমার প্রতি সম্ভ্রম আপনার খুশুকে আরও গভীর করুক।" },
    quranicRefs: [
      { ref: "55:27", noteEn: "Wa yabqa Wajhu Rabbika Dhu-l-Jalali wal-Ikram — the Face of your Lord, Owner of Jalal and Ikram, will remain.", noteBn: "ওয়া ইয়াবকা ওয়াজহু রাব্বিকা যুল-জালালি ওয়াল-ইকরাম — মহিমা ও সম্মানের অধিকারী তোমার রবের চেহারাই শুধু বাকি থাকবে।" },
      { ref: "55:78", noteEn: "Tabaraka-smu Rabbika Dhi-l-Jalali wal-Ikram — blessed is the name of your Lord, Owner of Jalal; closes Surah ar-Rahman.", noteBn: "তাবারাকাসমু রাব্বিকা যিল-জালালি ওয়াল-ইকরাম — মহিমার অধিকারী তোমার রবের নাম বরকতময়; এ আয়াতেই সূরা আর-রাহমান শেষ।" }
    ]},
  { n: 42, ar: "الْكَرِيمُ", translit: "Al-Karīm", meanings: { en: "The Generous", bn: "মহানুভব", fr: "Le Généreux", id: "Yang Maha Pemurah", ur: "کرم کرنے والا", tr: "Cömert", ar: "الجواد المعطي" , zh: '慷慨者', ja: '寛大なる者', hi: 'करम करने वाला', es: 'El Generoso', ru: 'Щедрый', de: 'Der Edelmütige', fa: 'کریم', ms: 'Yang Maha Dermawan'},
    explain: { en: "Al-Karim is generosity without limit, without condition, and without any expectation of return. Human generosity diminishes the giver; Allah's generosity increases Him in nothing but gives His servants everything. The Quran (82:6) addresses mankind: 'O mankind, what has deceived you concerning your Lord, Al-Karim?' — the very generosity that surrounds you should lead to gratitude, not ingratitude. Al-Ghazali writes that Al-Karim gives even before being asked, gives more than what is asked, and never mentions the gift afterwards.", bn: "আল-কারিম মানে এমন দানশীলতা, যার সীমা নেই, শর্ত নেই, বিনিময়ের কোনো আশাও নেই। মানুষ দান করলে তার নিজের ভাণ্ডার কমে; আল্লাহ দান করে নিজে কিছুই পান না, অথচ বান্দাদের দেন সবকিছু। কুরআন (৮২:৬) মানুষকে ডেকে বলছে: 'হে মানুষ, কিসে তোমাকে তোমার রব আল-কারিম সম্পর্কে ধোঁকায় ফেলল?' চারপাশে ছড়িয়ে থাকা এই দানই তো মানুষকে কৃতজ্ঞ করার কথা, অকৃতজ্ঞ নয়। আল-গাজালী লিখেছেন, আল-কারিম চাওয়ার আগেই দেন, যা চাওয়া হয় তার চেয়ে বেশি দেন, আর দেওয়ার পর সে কথা তুলে কখনো খোঁটা দেন না।" } ,
    hadith: { en: "The Prophet ﷺ said: 'Indeed your Lord is Modest and Most Generous (Hayyiyyun Karim); He is shy, when a man raises his hands to Him, to turn them back empty and disappointed.'", bn: "নবী ﷺ বলেন: 'নিশ্চয়ই তোমাদের রব লজ্জাশীল ও মহাদানশীল (হাইয়িয়্যুন কারিম); বান্দা যখন তাঁর দিকে হাত তোলে, তখন সেই হাত খালি ও নিরাশ ফিরিয়ে দিতে তিনি লজ্জাবোধ করেন।'", src: "Sunan Abi Dawud 1488; Jami' at-Tirmidhi 3556" },
    invoke: { en: "When your needs feel too great or too many to ask, call upon Ya Karim — His generosity never diminishes and He is not wearied by repeated requests. Ask boldly and often, for the Most Generous is displeased when His servant does not ask of Him.", bn: "প্রয়োজন এত বড় বা এত বেশি মনে হয় যে চাইতেও সংকোচ লাগে? তখন 'ইয়া কারিম' বলে ডাকুন। তাঁর দান কখনো কমে না, বারবার চাইলেও তিনি ক্লান্ত হন না। সাহস করে বারবার চান, কারণ বান্দা না চাইলে বরং মহাদাতা অসন্তুষ্ট হন।" } ,
    quranicRefs: [
      { ref: "27:40", noteEn: "Inna Rabbi Ghani-yun Karim — My Lord is Self-Sufficient and Al-Karim; Sulayman's gratitude for the brought throne.", noteBn: "ইন্না রাব্বি গানিয়্যুন কারিম — আমার রব অমুখাপেক্ষী, আল-কারিম; সিংহাসন এনে হাজির করা হলে সুলায়মানের শোকর।" },
      { ref: "82:6", noteEn: "Ya ayyuha-l-insanu ma gharraka bi-Rabbika-l-Karim — what deceived you about your Lord, Al-Karim?", noteBn: "ইয়া আয়্যুহাল-ইনসানু মা গার্রাকা বিরাব্বিকাল-কারিম — কিসে তোমাকে তোমার রব আল-কারিম সম্পর্কে ধোঁকায় ফেলল?" }
    ]},
  { n: 43, ar: "الرَّقِيبُ", translit: "Ar-Raqīb", meanings: { en: "The Watchful", bn: "সদা পর্যবেক্ষক", fr: "Le Vigilant", id: "Yang Maha Mengawasi", ur: "نگران", tr: "Gözetleyen", ar: "المطّلع على كل شيء" , zh: '鑒察者', ja: '用心深きもの', hi: 'निगरानी करने वाला', es: 'El Vigilante', ru: 'Наблюдающий', de: 'Der Wachsame', fa: 'مراقب', ms: 'Yang Maha Mengawasi'},
    explain: { en: "Ar-Raqib is the Watcher who never sleeps, never blinks, and never turns away — every action, thought, and intention is under His constant surveillance. Quran 4:1 ends with 'Indeed Allah is ever Watchful (Raqiban) over you,' and Quran 5:117 records Jesus (Isa, peace be upon him) saying 'You were the Watcher over them' to Allah. Al-Ghazali writes that internalising this name produces authentic muraqabah (spiritual watchfulness) — the highest station of worship.", bn: "আর-রাকিব সেই পর্যবেক্ষক, যিনি কখনো ঘুমান না, পলক ফেলেন না, মুখ ফিরিয়েও নেন না। প্রতিটি কাজ, চিন্তা ও নিয়ত সারাক্ষণ তাঁর নজরে। কুরআন ৪:১ শেষ হয়েছে এই কথায়: 'নিশ্চয়ই আল্লাহ তোমাদের ওপর সদা দৃষ্টি রাখেন (রাকিবান)।' আর ৫:১১৭-এ ঈসা (আঃ) আল্লাহকে বলছেন: 'আপনিই ছিলেন তাদের ওপর পর্যবেক্ষক।' আল-গাজালী লিখেছেন, এই নাম অন্তরে গেঁথে গেলে জন্ম নেয় খাঁটি মুরাকাবা, অর্থাৎ সারাক্ষণ আল্লাহর নজরে থাকার অনুভূতি; এটাই ইবাদতের সর্বোচ্চ স্তর।" },
    hadith: { en: "Worship Allah as though you see Him, and if you do not see Him, know that He sees you.", bn: "এমনভাবে আল্লাহর ইবাদত করো, যেন তুমি তাঁকে দেখছ; আর তুমি তাঁকে না দেখলেও জেনে রাখো, তিনি তোমাকে দেখছেন।", src: "Sahih al-Bukhari 50; Sahih Muslim 8 (Hadith Jibril)" } ,
    invoke: { en: "When alone and tempted toward sin, remember Ya Raqib watches over you constantly, and let this awareness guard your private conduct. Call upon Him to make you of those ever-conscious that Allah observes them, so your solitude becomes as upright as your public life.", bn: "একা থাকার সময় গুনাহের টান এলে মনে করুন, আর-রাকিব সারাক্ষণ আপনাকে দেখছেন; এই অনুভূতিই আপনার গোপন জীবনকে পাহারা দিক। 'ইয়া রাকিব' বলে তাঁর কাছে চান, তিনি যেন আপনাকে তাদের দলে রাখেন, যারা সব সময় মনে রাখে যে আল্লাহ তাদের দেখছেন। তাহলে আপনার নির্জন জীবনও প্রকাশ্য জীবনের মতোই সৎ হবে।" } ,
    quranicRefs: [
      { ref: "4:1", noteEn: "Inna-llaha kana alaykum Raqiba — Allah has been Watchful over you; affirmed in the verse on family rights.", noteBn: "ইন্নাল্লাহা কানা আলায়কুম রাকিবা — আল্লাহ তোমাদের ওপর রাকিব; পরিবারের হক নিয়ে আয়াতে এ ঘোষণা।" },
      { ref: "5:117", noteEn: "Isa says: kunta Anta-r-Raqib alayhim — You were the Watcher over them after my departure.", noteBn: "ঈসা বলেন: কুনতা আনতার-রাকিবা আলায়হিম — আমার প্রস্থানের পরে আপনি তাদের উপর রাকিব ছিলেন।" },
      { ref: "33:52", noteEn: "Wa kana-llahu ala kulli shay'in Raqiba — Allah is Watchful over all things; affirmed for proper conduct.", noteBn: "ওয়া কানাল্লাহু আলা কুল্লি শায়িন রাকিবান — আল্লাহ সবকিছুর ওপর রাকিব; সঠিক আচরণের নির্দেশ প্রসঙ্গে।" }
    ]},
  { n: 44, ar: "الْمُجِيبُ", translit: "Al-Mujīb", meanings: { en: "The Responsive", bn: "দুআ কবুলকারী", fr: "Celui qui exauce", id: "Yang Maha Mengabulkan", ur: "دعا قبول کرنے والا", tr: "Duaları Kabul Eden", ar: "المجيب للدعاء" , zh: '答覆者', ja: '信頼できる者', hi: 'दुआ क़बूल करने वाला', es: 'El que responde', ru: 'Отвечающий', de: 'Der Erhörende', fa: 'اجابت‌کننده', ms: 'Yang Maha Memperkenankan'},
    explain: { en: "Al-Mujib is the Responder who always answers — though not always in the manner or timing we expect. The Quran (2:186) says: 'And when My servants ask you concerning Me, I am indeed near. I respond to the call of the caller when he calls on Me.' The Prophet (peace be upon him) guaranteed: either the du'a is granted as asked, or equivalent harm is averted, or a reward is stored for the Hereafter. Al-Mujib never ignores a sincere call.", bn: "আল-মুজিব সেই সাড়াদানকারী, যিনি সবসময় সাড়া দেন, যদিও সবসময় আমাদের প্রত্যাশিত ধরনে বা সময়ে নয়। কুরআন (২:১৮৬) বলছে: 'আমার বান্দারা যখন তোমাকে আমার সম্পর্কে জিজ্ঞেস করে, আমি তো কাছেই। আহ্বানকারী যখন আমাকে ডাকে, আমি তার ডাকে সাড়া দিই।' নবী ﷺ নিশ্চয়তা দিয়েছেন: আল্লাহ হয় চাওয়া জিনিসটাই দেন, নয়তো সমপরিমাণ কোনো বিপদ সরিয়ে দেন, নয়তো আখিরাতের জন্য প্রতিদান জমা রাখেন। খাঁটি মনের কোনো ডাক আল-মুজিব কখনো উপেক্ষা করেন না।" },
    invoke: { en: "Before making any du'a, address Allah as 'Ya Mujib' to strengthen your trust. The du'a of the Prophet Yunus (as) from the whale's belly — 'La ilaha illa Anta, Subhanaka, inni kuntu min al-zalimin' (21:87) — was answered because Al-Mujib heard it. Persist: the door is never closed.", bn: "যেকোনো দু'আর শুরুতে 'ইয়া মুজিব' বলে আল্লাহকে ডাকুন; এতে ভরসা মজবুত হয়। মাছের পেট থেকে নবী ইউনুস (আ.)-এর দু'আ, 'লা ইলাহা ইল্লা আনতা, সুবহানাকা, ইন্নি কুনতু মিনাজ-জালিমিন' (২১:৮৭), কবুল হয়েছিল, কারণ আল-মুজিব তা শুনেছিলেন। লেগে থাকুন; এ দরজা কখনো বন্ধ হয় না।" } ,
    hadith: { en: "Allah the Exalted says: 'I am as My servant expects Me to be, and I am with him when he calls upon Me.'", bn: "আল্লাহ তাআলা বলেন: 'আমি আমার বান্দার ধারণা অনুযায়ী (তার সাথে আচরণ করি) এবং সে যখন আমাকে ডাকে আমি তার সাথে থাকি।'", src: "Sahih al-Bukhari 7405; Sahih Muslim 2675 (Hadith Qudsi)" },
    quranicRefs: [
      { ref: "2:186", noteEn: "Ujib-u da'wata-d-da'i idha da'ani — I respond to the call of the caller when he calls Me; the definitive promise of Al-Mujib.", noteBn: "উজিবু দাওয়াতাদ-দাই ইযা দাআনি — আহ্বানকারী ডাকলে আমি সাড়া দিই; আল-মুজিবের চূড়ান্ত প্রতিশ্রুতি।" },
      { ref: "11:61", noteEn: "Inna Rabbi Qarib-un Mujib — My Lord is Near and Responsive; Salih's affirmation when inviting his people.", noteBn: "ইন্না রাব্বি কারিবুন মুজিব — আমার রব কাছেই আছেন, ডাকে সাড়া দেন; নিজের কওমকে দাওয়াত দিতে গিয়ে সালিহের ঘোষণা।" }
    ]},
  { n: 45, ar: "الْوَاسِعُ", translit: "Al-Wāsiʿ", meanings: { en: "The All-Encompassing", bn: "সর্বব্যাপী", fr: "L'Ample", id: "Yang Maha Luas", ur: "وسعت والا", tr: "İlmi ve Rahmeti Geniş", ar: "الواسع الغني" , zh: '宽恩者', ja: '広大なる者、すべてを包み込みしもの', hi: 'वुसअत वाला', es: 'El que todo lo abarca', ru: 'Объемлющий', de: 'Der Allumfassende', fa: 'فراگیر', ms: 'Yang Maha Luas'},
    explain: { en: "Al-Wasi' describes Allah's all-encompassing nature — His knowledge, mercy, generosity, and power have no boundary or limit. The Quran (2:115) says: 'Wherever you turn, there is the face of Allah; Indeed, Allah is All-Encompassing and All-Knowing.' No matter where a person turns in prayer, supplication, or need, they cannot be outside the sphere of Al-Wasi'. His mercy encloses and exceeds the cosmos itself.", bn: "আল-ওয়াসি নামে আল্লাহর সর্বব্যাপী সত্তার কথা: তাঁর জ্ঞান, রহমত, দান আর ক্ষমতার কোনো সীমা-পরিসীমা নেই। কুরআন (২:১১৫) বলছে: 'তোমরা যেদিকেই মুখ ফেরাও, সেদিকেই আল্লাহর চেহারা; নিশ্চয়ই আল্লাহ সর্বব্যাপী, সর্বজ্ঞ।' নামাজে, দু'আয় বা প্রয়োজনে মানুষ যেদিকেই ফিরুক, আল-ওয়াসির পরিধির বাইরে যেতে পারে না। তাঁর রহমত গোটা বিশ্বজগৎকে ঘিরে আছে, তাকেও ছাড়িয়ে গেছে।" } ,
    invoke: { en: "When your provision feels tight or you fear Allah's mercy cannot reach your situation, call upon Ya Wasi' — His mercy, knowledge, and bounty encompass all things without limit. Ask from His vast treasures, for what you seek can never exhaust the All-Encompassing.", bn: "রিজিকে টানাটানি মনে হলে, কিংবা ভয় হলে যে আল্লাহর রহমত বুঝি আপনার অবস্থা পর্যন্ত পৌঁছাবে না, 'ইয়া ওয়াসি' বলে ডাকুন। তাঁর রহমত, জ্ঞান ও অনুগ্রহ সীমাহীনভাবে সবকিছু ঘিরে আছে। তাঁর অফুরন্ত ভাণ্ডার থেকে চান; আপনি যত চান, তাতে সর্বব্যাপী আল্লাহর ভাণ্ডার কখনো ফুরাবে না।" } ,
    quranicRefs: [
      { ref: "2:115", noteEn: "Inna-llaha Wasi'un Alim — wherever you turn there is Allah's face; He is All-Encompassing and All-Knowing.", noteBn: "ইন্নাল্লাহা ওয়াসিউন আলিম — যেদিকেই মুখ ফেরাও, সেদিকেই আল্লাহর চেহারা; তিনি সর্বব্যাপী, সর্বজ্ঞ।" },
      { ref: "2:261", noteEn: "Wa-llahu Wasi'un Alim — after charity multiplied 700-fold; Al-Wasi's encompassing generosity.", noteBn: "ওয়াল্লাহু ওয়াসিউন আলিম — দান ৭০০ গুণ বাড়িয়ে দেওয়ার কথার পরেই এসেছে; আল-ওয়াসির অফুরন্ত দানশীলতা।" },
      { ref: "2:268", noteEn: "Wa-llahu Wasi'un Alim — Shaytan promises poverty, Allah promises forgiveness; His encompassing mercy surpasses fear.", noteBn: "ওয়াল্লাহু ওয়াসিউন আলিম — শয়তান অভাবের ভয় দেখায়, আল্লাহ ক্ষমার ওয়াদা দেন; তাঁর অফুরন্ত রহমত সেই ভয়কে ছাপিয়ে যায়।" },
      { ref: "3:73", noteEn: "Wa-llahu Wasi'un Alim — guidance and Allah's bounty are for whom He wills; His knowledge is encompassing.", noteBn: "ওয়াল্লাহু ওয়াসিউন আলিম — হেদায়েত ও অনুগ্রহ যাকে চান তার জন্য; তাঁর জ্ঞান সর্বব্যাপী।" },
      { ref: "5:54", noteEn: "Wa-llahu Wasi'un Alim — when He replaces the unfaithful with those He loves; divine encompassment chooses the sincere.", noteBn: "ওয়াল্লাহু ওয়াসিউন আলিম — যারা বিশ্বস্ত থাকে না, তাদের জায়গায় আল্লাহ আনেন এমন লোক, যাদের তিনি ভালোবাসেন; তাঁর অসীম পরিধি থেকে তিনি বেছে নেন খাঁটি বান্দাদের।" }
    ]},
  { n: 46, ar: "الْحَكِيمُ", translit: "Al-Ḥakīm", meanings: { en: "The All-Wise", bn: "মহাপ্রজ্ঞাময়", fr: "Le Sage", id: "Yang Maha Bijaksana", ur: "حکمت والا", tr: "Hikmet Sahibi", ar: "الحكيم في تدبيره" , zh: '睿智者', ja: '賢い者', hi: 'हिकमत वाला', es: 'El Sabio', ru: 'Мудрый', de: 'Der Allweise', fa: 'حکیم', ms: 'Yang Maha Bijaksana'},
    explain: { en: "Al-Hakim is the source of all wisdom (hikmah) — perfect knowledge perfectly applied. In the Quran, Al-Hakim is the second most frequently appearing name after Al-'Alim, often paired together: 'and Allah is All-Knowing, All-Wise.' This pairing shows that Allah's power of knowing (Al-'Alim) is always channeled through wisdom (Al-Hakim) — He does nothing arbitrary. Ibn al-Qayyim writes that accepting difficult divine decrees becomes easier when you trust that behind every decree is infinite wisdom.", bn: "আল-হাকিম সব প্রজ্ঞার (হিকমাহ) উৎস: নিখুঁত জ্ঞান, নিখুঁতভাবে প্রয়োগ করা। কুরআনে আল-আলিমের পরে সবচেয়ে বেশি এসেছে আল-হাকিম নাম, আর প্রায়ই দুটি একসাথে: 'আল্লাহ সর্বজ্ঞ, প্রজ্ঞাময়।' এই জোড়া দেখায়, আল্লাহর জ্ঞান (আল-আলিম) সবসময় কাজ করে প্রজ্ঞার (আল-হাকিম) পথ ধরে; তিনি খেয়ালখুশিমতো কিছুই করেন না। ইবনুল কাইয়িম লিখেছেন, আল্লাহর কোনো কঠিন ফয়সালা মেনে নেওয়া সহজ হয়ে যায়, যখন আপনি ভরসা রাখেন যে প্রতিটি ফয়সালার পেছনে আছে অসীম প্রজ্ঞা।" },
    hadith: { en: "He whom Allah wills good for, He gives him understanding (fiqh) of the religion.", bn: "আল্লাহ যার জন্য ভালো চান, তাকে দ্বীনের গভীর বোঝাপড়া (ফিকহ) দেন।", src: "Sahih al-Bukhari 71; Sahih Muslim 1037" } ,
    invoke: { en: "When a decree of Allah confuses or grieves you, call upon Ya Hakim and trust that His wisdom places everything perfectly, even when you cannot see the reason. Ask Him for wisdom (hikmah) in your own choices, for He grants it to whom He wills and it is abundant good.", bn: "আল্লাহর কোনো ফয়সালা বুঝে উঠতে না পারলে বা তাতে কষ্ট পেলে 'ইয়া হাকিম' বলে ডাকুন। ভরসা রাখুন, তাঁর প্রজ্ঞা সবকিছু ঠিক জায়গায় রাখে, কারণটা আপনি দেখতে না পেলেও। নিজের সিদ্ধান্তগুলোর জন্য তাঁর কাছে প্রজ্ঞা (হিকমাহ) চান; তিনি যাকে চান তাকেই তা দেন, আর তা প্রচুর কল্যাণ।" } ,
    quranicRefs: [
      { ref: "2:32", noteEn: "Inna-ka Anta-l-Alim-ul-Hakim — You are Al-Alim and Al-Hakim; the angels recognise these names as defining divine knowledge.", noteBn: "ইন্নাকা আনতাল-আলিমুল-হাকিম — আপনিই আল-আলিম, আল-হাকিম; ফেরেশতারা আল্লাহর জ্ঞানের পরিচয় দিতে এই দুই নামই বলেছেন।" },
      { ref: "3:62", noteEn: "Wa inna-llaha la-Huwa-l-Aziz-ul-Hakim — after the Isa narrative: power always paired with wisdom.", noteBn: "ওয়া ইন্নাল্লাহা লা-হুওয়াল-আযিযুল-হাকিম — ঈসার বর্ণনার পরে: শক্তি সর্বদা প্রজ্ঞার সাথে।" },
      { ref: "4:26", noteEn: "Wa-llahu Alimun Hakim — Allah wills to make guidance clear; He is Alim and Hakim in His legislation.", noteBn: "ওয়াল্লাহু আলিমুন হাকিম — আল্লাহ হেদায়েত স্পষ্ট করে দিতে চান; বিধান দেওয়ায় তিনি আলিম ও হাকিম।" },
      { ref: "45:37", noteEn: "Wa Huwa-l-Aziz-ul-Hakim — His majesty fills the heavens and earth; He is Al-Aziz and Al-Hakim.", noteBn: "ওয়া হুওয়াল-আযিযুল-হাকিম — আকাশ ও পৃথিবী জুড়ে তাঁরই মহিমা; তিনি আল-আযিয, আল-হাকিম।" },
      { ref: "46:2", noteEn: "Tanzil-ul-Kitab mina-llahi-l-Aziz-il-Hakim — the Quran is revealed from Allah, Al-Aziz and Al-Hakim; wisdom underlies every verse.", noteBn: "তানযিলুল-কিতাবি মিনাল্লাহিল-আযিযিল-হাকিম — এ কিতাব নাজিল হয়েছে আল-আযিয, আল-হাকিম আল্লাহর কাছ থেকে; প্রতিটি আয়াতের পেছনে প্রজ্ঞা।" }
    ]},
  { n: 47, ar: "الْوَدُودُ", translit: "Al-Wadūd", meanings: { en: "The Loving", bn: "প্রেমময়", fr: "L'Aimant", id: "Yang Maha Mengasihi", ur: "محبت کرنے والا", tr: "Çok Seven", ar: "المحب لعباده" , zh: '仁慈者', ja: '愛しき者', hi: 'मुहब्बत करने वाला', es: 'El Amoroso', ru: 'Любящий', de: 'Der Liebevolle', fa: 'دوستدار', ms: 'Yang Maha Pengasih'},
    explain: { en: "Al-Wadud is divine love (wudd) — an affectionate, warm, tender love that is not dependent on the worthiness of the beloved. While Ar-Rahman and Ar-Rahim describe mercy, Al-Wadud describes love. The Quran (11:90) calls Allah both 'Ghafur' and 'Wadud' — forgiving AND loving, together. Ibn al-Qayyim in Madarij al-Salikin writes at length about Allah's love for His servants, noting that Allah's love is active: He shows it through protection, guidance, and elevation of the beloved.", bn: "আল-ওয়াদুদ মানে আল্লাহর ভালোবাসা (উদ্দ): স্নেহভরা, উষ্ণ, কোমল ভালোবাসা, যা প্রিয়জন কতটা যোগ্য তার ওপর নির্ভর করে না। আর-রাহমান ও আর-রাহিম নামে রহমতের কথা, আল-ওয়াদুদ নামে ভালোবাসার। কুরআন (১১:৯০) আল্লাহকে একসাথে 'গাফুর' ও 'ওয়াদুদ' বলেছে: তিনি ক্ষমাও করেন, ভালোও বাসেন। ইবনুল কাইয়িম 'মাদারিজুস সালিকিন'-এ বান্দার প্রতি আল্লাহর ভালোবাসা নিয়ে বিস্তারিত লিখেছেন। তিনি দেখিয়েছেন, এ ভালোবাসা সক্রিয়: প্রিয় বান্দাকে হেফাজত করে, পথ দেখিয়ে, মর্যাদা বাড়িয়ে আল্লাহ তা প্রকাশ করেন।" },
    hadith: { en: "Allah says: 'My servant does not draw near to Me with anything more beloved to Me than the religious duties I have made obligatory. My servant continues to draw near to Me with supererogatory acts until I love him.'", bn: "আল্লাহ বলেন: 'আমার বান্দা আমার কাছে আমার ফরজ করা ইবাদত পালনের চেয়ে বেশি প্রিয় কোনো কিছু দিয়ে নিকটবর্তী হয় না। আমার বান্দা নফল ইবাদত দিয়ে আমার নিকটবর্তী হতে থাকে যতক্ষণ না আমি তাকে ভালোবাসি।'", src: "Sahih al-Bukhari 6502 (Hadith Qudsi)" } ,
    invoke: { en: "When you long to be loved by Allah or to soften a hardened heart, call upon Ya Wadud — He loves His obedient servants and plants love between believers. Ask Him to make you among those He loves and to fill your heart with love for Him and for what He loves.", bn: "আল্লাহর ভালোবাসা পেতে মন চাইলে, কিংবা শক্ত হয়ে যাওয়া অন্তর নরম করতে চাইলে 'ইয়া ওয়াদুদ' বলে ডাকুন। তিনি তাঁর অনুগত বান্দাদের ভালোবাসেন, মুমিনদের মধ্যে ভালোবাসা জন্মে দেন। তাঁর কাছে চান, তিনি যেন আপনাকে তাঁর প্রিয়জনদের মধ্যে রাখেন, আর আপনার অন্তর ভরে দেন তাঁর ভালোবাসায় এবং তিনি যা ভালোবাসেন তার ভালোবাসায়।" } ,
    quranicRefs: [
      { ref: "11:90", noteEn: "Inna Rabbi Rahimun Wadud — My Lord is Merciful and Loving; Shuayb declares divine love for those who repent.", noteBn: "ইন্না রাব্বি রাহিমুন ওয়াদুদ — আমার রব দয়ালু, প্রেমময়; তওবাকারীদের প্রতি আল্লাহর ভালোবাসার কথা শুয়াইবের মুখে।" },
      { ref: "85:14", noteEn: "Wa Huwa-l-Ghafur-ul-Wadud — He is the All-Forgiving and the Loving; forgiveness and love are inseparable divine qualities.", noteBn: "ওয়া হুওয়াল-গাফুরুল-ওয়াদুদ — তিনি গাফুর ও ওয়াদুদ; ক্ষমা ও ভালোবাসা অবিচ্ছেদ্য ঐশ্বরিক গুণ।" }
    ]},
  { n: 48, ar: "الْمَجِيدُ", translit: "Al-Majīd", meanings: { en: "The Glorious", bn: "মহাগৌরবময়", fr: "Le Glorieux", id: "Yang Maha Mulia", ur: "بزرگ شان والا", tr: "Şanı Yüce", ar: "العظيم الشأن" , zh: '榮耀者', ja: '全ての栄光ある者', hi: 'बुज़ुर्ग शान वाला', es: 'El Glorioso', ru: 'Славный', de: 'Der Ruhmvolle', fa: 'ارجمند', ms: 'Yang Maha Mulia'},
    explain: { en: "Al-Majid combines supreme majesty (jalal) with supreme generosity and honour (karam). The root majd means glory, honour, and nobility of character. The salutations on the Prophet (Ibrahim's prayer, Quran 11:73) address Allah as 'Hamid, Majid' — the Praiseworthy and Glorious. This combination appears in the closing of Salawat Ibrahim (the Abrahamic salutation) recited in every prayer: 'innaka Hamidun Majid' — You are the Praiseworthy, the Glorious.", bn: "আল-মাজিদ নামে সর্বোচ্চ মহিমা (জালাল) আর সর্বোচ্চ দানশীলতা ও সম্মান (কারাম) একসাথে মিলেছে। মূল শব্দ মাজদ মানে গৌরব, সম্মান ও চরিত্রের আভিজাত্য। কুরআন ১১:৭৩-এ, ইব্রাহিমের পরিবারের প্রসঙ্গে, আল্লাহকে বলা হয়েছে 'হামিদ, মাজিদ': প্রশংসিত, মহিমান্বিত। এই জোড়া নামই আসে দরুদে ইব্রাহিমির শেষে, যা প্রতি নামাজে পড়া হয়: 'ইন্নাকা হামিদুন মাজিদ', নিশ্চয়ই আপনি প্রশংসিত, মহিমান্বিত।" } ,
    hadith: { en: "In the salawat taught for every tashahhud, the Prophet ﷺ concluded: '...as You blessed the family of Ibrahim; indeed You are Hamidun Majid (Praiseworthy, Glorious).'", bn: "প্রতিটি তাশাহহুদের জন্য শেখানো দরুদে নবী ﷺ শেষ করেছেন: '...যেমন আপনি ইব্রাহিমের পরিবারকে বরকত দিয়েছেন; নিশ্চয়ই আপনি হামিদুন মাজিদ (পরম প্রশংসিত, মহিমান্বিত)।'", src: "Sahih al-Bukhari 3370; Sahih Muslim 406" },
    invoke: { en: "Praise Him as Hamid and Majid in the salawat of every tashahhud, exactly as the Prophet ﷺ taught. Call 'Ya Majid' when asking for a gift beyond your means — His glory means His generosity has no ceiling.", bn: "প্রতিটি তাশাহহুদের দরুদে তাঁকে হামিদ ও মাজিদ বলে প্রশংসা করুন, ঠিক যেমন নবী ﷺ শিখিয়েছেন। সামর্থ্যের বাইরের কিছু চাইলে 'ইয়া মাজিদ' বলে ডাকুন; তাঁর মহিমা মানেই তাঁর দানের কোনো সীমা নেই।" },
    quranicRefs: [
      { ref: "11:73", noteEn: "Inna-hu Hamidun Majid — declared by the angels at Ibrahim's home; glory and praise in divine announcement.", noteBn: "ইন্নাহু হামিদুন মাজিদ — ইব্রাহিমের গৃহে ফেরেশতাদের ঘোষণা; ঐশ্বরিক বার্তায় গৌরব ও প্রশংসা একসাথে।" },
      { ref: "85:15", noteEn: "Dhu-l-Arsh-il-Majid — Owner of the Glorious Throne; the Throne's glory reflects the Owner's majesty.", noteBn: "যুল-আরশিল-মাজিদ — মহিমান্বিত আরশের মালিক; আরশের গৌরবে ফুটে ওঠে তার মালিকের মহিমা।" }
    ]},
  { n: 49, ar: "الْبَاعِثُ", translit: "Al-Bāʿith", meanings: { en: "The Resurrector", bn: "পুনরুত্থানকারী", fr: "Celui qui ressuscite", id: "Yang Maha Membangkitkan", ur: "اٹھانے والا", tr: "Dirilten", ar: "الباعث بعد الموت" , zh: '亡人喚醒者', ja: '死をもたらす者', hi: 'मुर्दों को उठाने वाला', es: 'El que resucita', ru: 'Воскрешающий', de: 'Der Auferweckende', fa: 'برانگیزاننده', ms: 'Yang Maha Membangkitkan'},
    explain: { en: "Al-Ba'ith is the One who will resurrect all creation after death for the Day of Judgement — a central article of Islamic faith. The Quran (36:51-52) describes the moment: the trumpet will sound and people will rise from their graves saying 'Who has raised us from our sleeping place?' Al-Ba'ith also means the One who sends forth Prophets and Messengers as divine envoys. Both meanings point to divine initiative: Allah is the One who awakens — whether from physical death or spiritual heedlessness.", bn: "আল-বাইছ তিনি, যিনি মৃত্যুর পর কিয়ামতের দিনের জন্য সব সৃষ্টিকে আবার জীবিত করে ওঠাবেন; এ বিশ্বাস ইসলামি আকিদার কেন্দ্রীয় অংশ। কুরআন (৩৬:৫১-৫২) সেই মুহূর্তের ছবি এঁকেছে: শিঙায় ফুঁ দেওয়া হবে, মানুষ কবর থেকে উঠে বলবে, 'কে আমাদের ঘুমের জায়গা থেকে উঠিয়ে আনল?' আল-বাইছের আরেক অর্থ, যিনি নবী-রাসূলদের নিজের দূত হিসেবে পাঠান। দুই অর্থেই উদ্যোগ আল্লাহর: তিনিই জাগিয়ে তোলেন, তা দৈহিক মৃত্যু থেকে হোক বা অন্তরের গাফিলতি থেকে।" } ,
    hadith: { en: "On waking, the Prophet ﷺ would say: 'Praise be to Allah who brought us to life after He caused us to die, and to Him is the resurrection (an-nushur).'", bn: "ঘুম থেকে জেগে নবী ﷺ বলতেন: 'সমস্ত প্রশংসা আল্লাহর, যিনি আমাদের মৃত্যু দেওয়ার পর জীবিত করলেন, আর তাঁরই কাছে পুনরুত্থান (নুশুর)।'", src: "Sahih al-Bukhari 6312" },
    invoke: { en: "Begin each morning with 'Alhamdu lillahi-lladhi ahyana ba'da ma amatana wa ilayhi-n-nushur' — sleep and waking rehearse death and resurrection daily. After the adhan, ask Allah to raise (ib'ath) the Prophet ﷺ to the Praised Station, and ask Al-Ba'ith to revive your own heedless heart.", bn: "প্রতিটি সকাল শুরু করুন 'আলহামদু লিল্লাহিল্লাযি আহইয়ানা বা'দা মা আমাতানা ওয়া ইলাইহিন-নুশুর' দিয়ে। ঘুম আর জেগে ওঠা যেন প্রতিদিন মৃত্যু ও পুনরুত্থানের মহড়া। আজানের পর দু'আ করুন, আল্লাহ যেন নবী ﷺ-কে মাকামে মাহমুদে পৌঁছে দেন (ইব'আস); আর আল-বাইসের কাছে চান, তিনি যেন আপনার গাফেল অন্তরকে আবার জাগিয়ে তোলেন।" },
    quranicRefs: [
      { ref: "3:9", noteEn: "Inna-ka jami'u-n-nasi li-yawmin la rayba fih — You will gather all mankind for a Day of which there is no doubt.", noteBn: "ইন্নাকা জামিউন-নাসি লিইয়াওমিন লা রায়বা ফিহ — আপনি সব মানুষকে একত্র করবেন এমন এক দিনে, যার আগমনে কোনো সন্দেহ নেই।" },
      { ref: "22:7", noteEn: "Wa anna-s-Sa'ata atiyatun la rayba fiha wa anna-llaha yab'athu man fi-l-qubur — Allah will resurrect those in the graves.", noteBn: "ওয়া আন্নাস-সাআতা আতিয়াতুন লা রায়বা ফিহা ওয়া আন্নাল্লাহা ইয়াবআছু মান ফিল-কুবুর — কবরে যারা আছে, আল্লাহ তাদের আবার জীবিত করে ওঠাবেন।" },
      { ref: "6:36", noteEn: "Innama yastajib-u-lladhina yasma'un wa-l-mawta yab'athu-hum-u-llah — the dead Allah will resurrect; He is Al-Ba'ith.", noteBn: "ইন্নামা ইয়াস্তাজিবুল্লাযিনা ইয়াসমাউন ওয়াল-মাওতা ইয়াবআছুহুমুল্লাহ — মৃতদের আল্লাহ আবার জীবিত করে ওঠাবেন; তিনিই আল-বাইছ।" }
    ]},
  { n: 50, ar: "الشَّهِيدُ", translit: "Ash-Shahīd", meanings: { en: "The Witness", bn: "সর্বসাক্ষী", fr: "Le Témoin", id: "Yang Maha Menyaksikan", ur: "گواہ", tr: "Her Şeye Şahit", ar: "الشاهد على كل شيء" , zh: '見證者', ja: '立会人', hi: 'गवाह', es: 'El Testigo', ru: 'Свидетель', de: 'Der Zeuge', fa: 'گواه', ms: 'Yang Maha Menyaksikan'},
    explain: { en: "Ash-Shahid is the All-Witness who bears testimony to everything that has ever happened or been said, with the most complete and unbiased testimony imaginable. On the Day of Judgement, Allah will be the ultimate witness, and the record will be infallible. The Quran (10:61) says: 'And you are not engaged in any matter or recite any of the Quran, and you do not do any deed except that We are witness over you.' This name should make every Muslim mindful that their private actions are not private from Allah.", bn: "যা কিছু ঘটেছে বা বলা হয়েছে, আশ-শাহিদ তার সবকিছুর সাক্ষী। তাঁর সাক্ষ্যের চেয়ে পূর্ণ ও নিরপেক্ষ সাক্ষ্য কল্পনাও করা যায় না। কিয়ামতের দিন আল্লাহই হবেন চূড়ান্ত সাক্ষী, আর আমলনামায় কোনো ভুল থাকবে না। কুরআন (১০:৬১) বলছে: 'তুমি যে অবস্থাতেই থাকো, কুরআনের যা কিছুই তিলাওয়াত করো, আর তোমরা যে কাজই করো, আমি তখন তোমাদের ওপর সাক্ষী থাকি।' এই নাম প্রত্যেক মুসলিমকে মনে করিয়ে দেয়: মানুষের কাছে যা গোপন, আল্লাহর কাছে তা গোপন নয়।" } ,
    hadith: { en: "On the Farewell Pilgrimage, after asking the people whether he had conveyed the message and they affirmed, the Prophet ﷺ raised his finger and said thrice: 'O Allah, bear witness (Allahumma-shhad).'", bn: "বিদায় হজে নবী ﷺ লোকদের জিজ্ঞেস করলেন তিনি বার্তা পৌঁছে দিয়েছেন কিনা, তারা সম্মতি দিলে তিনি আঙুল তুলে তিনবার বললেন: 'হে আল্লাহ, আপনি সাক্ষী থাকুন (আল্লাহুম্মাশহাদ)।'", src: "Sahih Muslim 1218" },
    invoke: { en: "Live conscious that Ash-Shahid witnesses every deed, word, and intention — this awareness is the heart of ihsan. When slandered or misjudged, take comfort that the Witness knows the truth, and make Him your witness in solemn commitments as the Prophet ﷺ did at Arafah: 'Allahumma-shhad' (O Allah, bear witness).", bn: "এই চেতনা নিয়ে জীবন কাটান যে আশ-শাহিদ আপনার প্রতিটি কাজ, কথা ও নিয়তের সাক্ষী; এই সচেতনতাই ইহসানের মূল। অপবাদ বা ভুল বিচারের শিকার হলে এই ভেবে সান্ত্বনা নিন যে, সাক্ষী সত্যটা জানেন। আর গুরুত্বপূর্ণ অঙ্গীকারে তাঁকে সাক্ষী রাখুন, যেমন নবী ﷺ আরাফায় বলেছিলেন: 'আল্লাহুম্মাশহাদ' (হে আল্লাহ, সাক্ষী থাকুন)।" },
    quranicRefs: [
      { ref: "4:166", noteEn: "Wa-llahu Shahid-un anna-hu anzala ilayhi bi-'ilmihi — Allah is Shahid that He revealed it with His knowledge.", noteBn: "ওয়াল্লাহু শাহিদুন আন্নাহু আনযালা ইলায়হি বিইলমিহি — আল্লাহ সাক্ষী যে তিনি তাঁর জ্ঞানে এটি অবতীর্ণ করেছেন।" },
      { ref: "10:46", noteEn: "Thumma-llahu Shahid-un ala ma yaf'alun — then Allah is Ash-Shahid over all they do; He witnesses every deed.", noteBn: "ছুম্মাল্লাহু শাহিদুন আলা মা ইয়াফআলুন — তারপর আল্লাহ তারা যা করে তার সাক্ষী।" },
      { ref: "22:17", noteEn: "Inna-llaha ala kulli shay'in Shahid — Allah is Ash-Shahid over all things; He witnesses all religious communities.", noteBn: "ইন্নাল্লাহা আলা কুল্লি শায়িন শাহিদ — আল্লাহ সবকিছুর সাক্ষী; সব ধর্মের অনুসারীদের তিনি দেখছেন।" },
      { ref: "48:28", noteEn: "Wa kafa billahi Shahida — Allah suffices as Ash-Shahid to His messenger's mission and its truth.", noteBn: "ওয়া কাফা বিল্লাহি শাহিদান — তাঁর রাসূলের দাওয়াত ও তার সত্যতার সাক্ষী হিসেবে আল্লাহই যথেষ্ট।" }
    ]},
  { n: 51, ar: "الْحَقُّ", translit: "Al-Ḥaqq", meanings: { en: "The Truth", bn: "চিরসত্য", fr: "Le Vrai", id: "Yang Maha Benar", ur: "برحق", tr: "Gerçeğin Kendisi", ar: "الثابت الذي لا يزول" , zh: '真實者', ja: '真実', hi: 'हक़', es: 'La Verdad', ru: 'Истина', de: 'Die Wahrheit', fa: 'حق', ms: 'Yang Maha Benar'},
    explain: { en: "Al-Haqq is not merely truthful — He IS Truth itself. His existence is the only necessary and self-subsisting existence; everything else's existence is borrowed and contingent. The Quran (22:6) declares: 'That is because Allah is the Truth, and that what they call upon besides Him is falsehood.' Every truth in the cosmos — mathematical, moral, or physical — is a reflection of and derived from Al-Haqq. Falsehood (batil) has no independent existence; it is merely the absence or distortion of haqq.", bn: "আল-হাক্ক শুধু সত্যবাদী নন, তিনি নিজেই সত্য। একমাত্র তাঁর অস্তিত্বই অনিবার্য, নিজে নিজে প্রতিষ্ঠিত; বাকি সবকিছুর অস্তিত্ব ধার করা, অন্যের ওপর নির্ভরশীল। কুরআন (২২:৬) ঘোষণা করে: 'এটা এজন্য যে, আল্লাহই সত্য, আর তাঁকে ছাড়া তারা যাদের ডাকে, তা বাতিল।' বিশ্বজগতের প্রতিটি সত্য, তা গণিতের হোক, নৈতিকতার হোক বা প্রকৃতির, আল-হাক্ক থেকেই আসে, তাঁরই প্রতিফলন। বাতিলের (মিথ্যার) নিজস্ব কোনো অস্তিত্ব নেই; তা কেবল হক্কের অনুপস্থিতি বা বিকৃতি।" },
    hadith: { en: "The most truthful statement a poet ever said is the statement of Labid: 'Verily, everything except Allah is vain (batil).'", bn: "কোনো কবির মুখে উচ্চারিত সবচেয়ে সত্য কথা হলো লাবিদের এই কথা: 'জেনে রাখো, আল্লাহ ছাড়া সবকিছুই বাতিল (অসার)।'", src: "Sahih al-Bukhari 3841" } ,
    invoke: { en: "When surrounded by falsehood or doubt shakes your certainty, call upon Ya Haqq — He is the Real whose truth outlasts every illusion. Ask Him to anchor your heart in truth, to show you the true as true and the false as false, and to keep you firm upon it.", bn: "চারপাশে মিথ্যার ভিড়ে, কিংবা সন্দেহ যখন বিশ্বাসকে নাড়িয়ে দেয়, তখন 'ইয়া হাক্ক' বলে ডাকুন। তিনিই প্রকৃত সত্য; সব মরীচিকা মিলিয়ে যায়, তাঁর সত্য টিকে থাকে। তাঁর কাছে চান, তিনি যেন আপনার অন্তরকে সত্যের ওপর স্থির রাখেন, সত্যকে সত্য আর মিথ্যাকে মিথ্যা হিসেবে দেখান, আর তার ওপর আপনাকে অটল রাখেন।" } ,
    quranicRefs: [
      { ref: "6:62", noteEn: "Thummma ruddu ila-llahi Mawla-hum-ul-Haqq — they are returned to Allah, their Master, Al-Haqq.", noteBn: "ছুম্মা রুদ্দু ইলাল্লাহি মাওলাহুমুল-হাক্ক — তারপর তাদের ফিরিয়ে নেওয়া হবে আল্লাহর কাছে, যিনি তাদের প্রকৃত মাওলা, আল-হাক্ক।" },
      { ref: "18:44", noteEn: "Hunak-al-walayatu lillahi-l-Haqq — authority belongs to Allah, Al-Haqq; wealth and children avail nothing before truth.", noteBn: "হুনাকাল-ওয়ালায়াতু লিল্লাহিল-হাক্ক — সেখানে কর্তৃত্ব কেবল সত্য আল্লাহরই; সত্যের সামনে সম্পদ আর সন্তান কোনো কাজে আসে না।" },
      { ref: "22:6", noteEn: "Dhalika bi-anna-llaha Huwa-l-Haqq wa anna-hu yuhyi-l-mawta — Allah is Al-Haqq and He gives life to the dead.", noteBn: "যালিকা বিআন্নাল্লাহা হুওয়াল-হাক্ক ওয়া আন্নাহু ইউহয়িল-মাওতা — আল্লাহ আল-হাক্ক ও মৃতদের জীবন দেন।" },
      { ref: "22:62", noteEn: "Dhalika bi-anna-llaha Huwa-l-Haqq... Al-Aliyy-ul-Kabir — truth, highness and greatness affirmed together.", noteBn: "যালিকা বিআন্নাল্লাহা হুওয়াল-হাক্ক... আল-আলিয়্যুল-কাবির — সত্য, উচ্চতা ও মহত্ত্ব একসাথে।" },
      { ref: "31:30", noteEn: "Dhalika bi-anna-llaha Huwa-l-Haqq — Al-Haqq is why all falsehood is vain and all truth points to Him.", noteBn: "যালিকা বিআন্নাল্লাহা হুওয়াল-হাক্ক — আল্লাহ আল-হাক্ক বলেই সব মিথ্যা অসার, আর সব সত্য তাঁর দিকেই ইশারা করে।" }
    ]},
  { n: 52, ar: "الْوَكِيلُ", translit: "Al-Wakīl", meanings: { en: "The Trustee", bn: "কর্মবিধায়ক", fr: "Le Garant", id: "Yang Maha Mewakili", ur: "کارساز", tr: "Güvenilir Vekil", ar: "المتكفل بأمور عباده" , zh: '可信賴者', ja: '管理者、信頼できる者', hi: 'कारसाज़', es: 'Quien de todo Se encarga', ru: 'Попечитель', de: 'Der Sachwalter', fa: 'کارساز', ms: 'Pengurus segala urusan'},
    explain: { en: "Al-Wakil is the Trustee and Disposer of Affairs — the One to whom all matters can safely be entrusted, knowing they will be managed with perfect knowledge, power, and care. The formula 'hasbunallah wa ni'ma-l-wakil' (Allah is sufficient for us and what an excellent Trustee!) was said by Prophet Ibrahim (as) when thrown into fire and by Prophet Muhammad (peace be upon him) when told that enemies had gathered against him (Quran 3:173). In both cases, the result was divine protection.", bn: "আল-ওয়াকিল সেই অভিভাবক ও কর্মবিধায়ক, যাঁর হাতে নিশ্চিন্তে সব বিষয় সঁপে দেওয়া যায়; তিনি তা সামলাবেন পূর্ণ জ্ঞান, ক্ষমতা ও যত্নে। 'হাসবুনাল্লাহ ওয়া নি'মাল-ওয়াকিল' (আল্লাহই আমাদের জন্য যথেষ্ট, আর তিনি কতই না উত্তম কর্মবিধায়ক) কথাটি ইব্রাহিম (আ.) বলেছিলেন আগুনে নিক্ষিপ্ত হওয়ার সময়, আর নবী মুহাম্মাদ (সা.) বলেছিলেন যখন খবর এল যে শত্রুরা তাঁর বিরুদ্ধে জড়ো হয়েছে (কুরআন ৩:১৭৩)। দুই ক্ষেত্রেই ফল ছিল আল্লাহর হেফাজত।" },
    invoke: { en: "In moments of helplessness — when you have done all you can and the matter is beyond you — say 'Tawakkaltu 'ala Allah' (I place my trust in Allah) and 'hasbunallah wa ni'ma-l-wakil.' This is tawakkul: not passivity, but entrusting outcomes to Al-Wakil after exhausting your means.", bn: "অসহায় মুহূর্তে, যখন যা করার সব করেছেন আর বিষয়টি আপনার হাতের বাইরে চলে গেছে, বলুন 'তাওয়াক্কালতু আলাল্লাহ' (আমি আল্লাহর ওপর ভরসা করলাম) এবং 'হাসবুনাল্লাহ ওয়া নি'মাল-ওয়াকিল'। এটাই তাওয়াক্কুল: হাত গুটিয়ে বসে থাকা নয়, বরং সব উপায় কাজে লাগানোর পর ফলাফল আল-ওয়াকিলের হাতে ছেড়ে দেওয়া।" } ,
    hadith: { en: "'Hasbunallahu wa ni'ma-l-Wakil' (Allah is sufficient for us, and what an excellent Trustee) — Ibrahim said it when cast into the fire, and Muhammad ﷺ said it when told the enemy had gathered against him.", bn: "'হাসবুনাল্লাহু ওয়া নি'মাল-ওয়াকিল' (আল্লাহই আমাদের জন্য যথেষ্ট, আর কতই না উত্তম কর্মবিধায়ক) — ইব্রাহিম (আঃ) আগুনে নিক্ষিপ্ত হওয়ার সময় এটি বলেছিলেন, আর মুহাম্মদ ﷺ শত্রুরা একত্র হওয়ার সংবাদে এটি বলেছিলেন।", src: "Sahih al-Bukhari 4563" },
    quranicRefs: [
      { ref: "3:173", noteEn: "Hasbuna-llahu wa ni'ma-l-Wakil — Allah is sufficient and what an excellent Trustee; said when facing gathered enemies.", noteBn: "হাসবুনাল্লাহু ওয়া নিআমাল-ওয়াকিল — আল্লাহই যথেষ্ট, কতই না উত্তম ওয়াকিল; জড়ো হওয়া শত্রুর মুখে দাঁড়িয়ে মুমিনরা এ কথা বলেছিলেন।" },
      { ref: "4:81", noteEn: "Tawakkal ala-llahi wa kafa billahi Wakila — put trust in Allah; He suffices as Trustee, the command of complete reliance.", noteBn: "তাওয়াক্কাল আলাল্লাহি ওয়া কাফা বিল্লাহি ওয়াকিলা — আল্লাহর ওপর ভরসা করো, ওয়াকিল হিসেবে তিনিই যথেষ্ট; পূর্ণ ভরসার নির্দেশ।" },
      { ref: "6:102", noteEn: "La ilaha illa Huwa... fa-ubudu-hu wa Huwa ala kulli shay'in Wakil — no deity but Him; worship Him, He is Wakil over all.", noteBn: "লা ইলাহা ইল্লা হুওয়া... ফাউবুদুহু ওয়া হুওয়া আলা কুল্লি শায়িন ওয়াকিল — তিনি ছাড়া কোনো ইলাহ নেই; তাঁর ইবাদত করো, তিনিই সবকিছুর ওয়াকিল।" },
      { ref: "39:62", noteEn: "Allahu Khaliqu kulli shay' wa Huwa ala kulli shay'in Wakil — Creator and Trustee: the fullest statement of divine oversight.", noteBn: "আল্লাহু খালিকু কুল্লি শায় ওয়া হুওয়া আলা কুল্লি শায়িন ওয়াকিল — তিনি স্রষ্টা, তিনিই ওয়াকিল; সবকিছুর দেখভাল যে তাঁর হাতে, এর চেয়ে পূর্ণ ঘোষণা আর নেই।" },
      { ref: "73:9", noteEn: "Rabb-ul-mashriq wal-maghrib... fa-ttakhidh-hu Wakila — Lord of East and West; take Him as your Wakil.", noteBn: "রাব্বুল-মাশরিকি ওয়াল-মাগরিবি... ফাত্তাখিযহু ওয়াকিলা — তিনি পূর্ব-পশ্চিমের রব; তাঁকেই তোমার ওয়াকিল হিসেবে গ্রহণ করো।" }
    ]},
  { n: 53, ar: "الْقَوِيُّ", translit: "Al-Qawiyy", meanings: { en: "The All-Strong", bn: "মহাশক্তিধর", fr: "Le Fort", id: "Yang Maha Kuat", ur: "بڑی قوت والا", tr: "Pek Güçlü", ar: "صاحب القوة التامة" , zh: '至強者', ja: '強きもの', hi: 'बड़ी ताक़त वाला', es: 'El Fuerte', ru: 'Сильный', de: 'Der Allstarke', fa: 'نیرومند', ms: 'Yang Maha Kuat'},
    explain: { en: "Al-Qawiyy is the Absolutely Strong whose strength has no weakness, fatigue, diminishment, or limit. The Quran (22:74) says: 'Indeed, Allah is All-Strong, All-Powerful.' Every physical and spiritual strength in creation is derivative from Al-Qawiyy. Al-Ghazali notes that the believer who turns to Al-Qawiyy in weakness finds strength not through self-reliance but through divine empowerment — 'la hawla wa la quwwata illa billah' (there is no power or strength except through Allah).", bn: "আল-কাওয়িয়্যু পরম শক্তিমান; তাঁর শক্তিতে কোনো দুর্বলতা নেই, ক্লান্তি নেই, ক্ষয় নেই, সীমাও নেই। কুরআন (২২:৭৪) বলছে: 'নিশ্চয়ই আল্লাহ মহাশক্তিমান, পরাক্রমশালী।' সৃষ্টির মধ্যে দৈহিক বা আত্মিক যত শক্তি আছে, সবই আল-কাওয়িয়্যুর কাছ থেকে পাওয়া। আল-গাজালী বলেন, দুর্বল অবস্থায় যে মুমিন আল-কাওয়িয়্যুর দিকে ফেরে, সে শক্তি পায় নিজের ওপর ভর করে নয়, আল্লাহর দেওয়া শক্তিতে: 'লা হাওলা ওয়ালা কুওয়াতা ইল্লা বিল্লাহ' (আল্লাহর সাহায্য ছাড়া কোনো উপায় নেই, কোনো শক্তিও নেই)।" } ,
    invoke: { en: "When you feel weak, outnumbered, or unable to face a trial, call upon Ya Qawiyy — all strength belongs to Him and no power stands against His. Lean on His strength rather than your own, asking Him to carry you through what is beyond your capacity.", bn: "নিজেকে দুর্বল মনে হলে, প্রতিপক্ষ সংখ্যায় বেশি হলে, কিংবা কোনো পরীক্ষার সামনে দাঁড়ানোর শক্তি না পেলে 'ইয়া কাওয়িয়্যু' বলে ডাকুন। সব শক্তি তাঁরই, কোনো শক্তি তাঁর সামনে টিকতে পারে না। নিজের শক্তির বদলে তাঁর শক্তির ওপর ভর করুন; যা আপনার সাধ্যের বাইরে, তা পার করিয়ে দিতে তাঁর কাছে চান।" } ,
    quranicRefs: [
      { ref: "8:52", noteEn: "Wa anna-llaha Qawiyyun shadid-ul-iqab — Allah is Al-Qawiyy, severe in punishment for those who deny His messengers.", noteBn: "ওয়া আন্নাল্লাহা কাওয়িয়্যুন শাদিদুল-ইকাব — আল্লাহ আল-কাওয়িয়্যু, রাসূল অস্বীকারকারীদের শাস্তিতে কঠোর।" },
      { ref: "22:40", noteEn: "Inna-llaha la-Qawiyyun Aziz — Allah is Al-Qawiyy and Al-Aziz; divine strength defends places of worship.", noteBn: "ইন্নাল্লাহা লা-কাওয়িয়্যুন আযিয — আল্লাহ আল-কাওয়িয়্যু ও আল-আযিয; ঐশ্বরিক শক্তি ইবাদতের স্থান রক্ষা করে।" },
      { ref: "22:74", noteEn: "Inna-llaha Qawiyyun Aziz — those who belittle Allah have not measured Him rightly; He is immeasurably strong.", noteBn: "ইন্নাল্লাহা কাওয়িয়্যুন আযিয — যারা আল্লাহকে ছোট করে দেখে, তারা তাঁর যথাযথ মর্যাদা বোঝেনি; তাঁর শক্তি মাপার বাইরে।" },
      { ref: "42:19", noteEn: "Wa Huwa-l-Qawiyy-ul-Aziz — paired with Al-Latif; gentle provision combined with absolute strength.", noteBn: "ওয়া হুওয়াল-কাওয়িয়্যুল-আযিয — আল-লাতিফের সাথে জুটি; কোমল রিজিক ও পরম শক্তির সমন্বয়।" },
      { ref: "57:25", noteEn: "Inna-llaha Qawiyyun Aziz — in the context of sending iron and the balance; divine strength upholds justice.", noteBn: "ইন্নাল্লাহা কাওয়িয়্যুন আযিয — লোহা ও মিজান পাঠানোর প্রসঙ্গে; ঐশ্বরিক শক্তি ন্যায় বজায় রাখে।" }
    ]},
  { n: 54, ar: "الْمَتِينُ", translit: "Al-Matīn", meanings: { en: "The Firm", bn: "সুদৃঢ়", fr: "L'Inébranlable", id: "Yang Maha Kokoh", ur: "مضبوط", tr: "Sarsılmaz Güç Sahibi", ar: "الشديد القوي" , zh: '堅定者', ja: '堅固なる者、忠誠なる者', hi: 'मज़बूत', es: 'El Firme', ru: 'Крепкий', de: 'Der Feste', fa: 'استوار', ms: 'Yang Maha Teguh'},
    explain: { en: "Al-Matin describes divine firmness and solidity — strength that is not just powerful but absolutely stable, immovable, and consistent. The Quran (51:58) combines this name with Ar-Razzaq: 'Indeed, Allah is the Provider, Owner of Power (Quwwa), the Firm (Matin).' While Al-Qawiyy describes the intensity of divine strength, Al-Matin describes its unshakeable durability. Nothing can shift Allah's plan, exhaust His strength, or destabilise His decrees.", bn: "আল-মাতিন নামে আল্লাহর দৃঢ়তার কথা: এমন শক্তি, যা শুধু প্রবল নয়, পুরোপুরি স্থির, অটল, কখনো বদলায় না। কুরআন (৫১:৫৮) এই নামকে আর-রাজ্জাকের সাথে জুড়ে বলেছে: 'নিশ্চয়ই আল্লাহই রিজিকদাতা, শক্তির অধিকারী, সুদৃঢ়।' আল-কাওয়িয়্যু নামে তাঁর শক্তির প্রবলতা, আর আল-মাতিন নামে সেই শক্তির অটল স্থায়িত্ব। আল্লাহর পরিকল্পনা কেউ নড়াতে পারে না, তাঁর শক্তি ফুরায় না, তাঁর ফয়সালা টলানো যায় না।" } ,
    invoke: { en: "When your resolve wavers or your resources feel fragile, lean on Al-Matin — 'indeed Allah is the Provider, Possessor of firm strength' (51:58). Ask Him for thabat (steadfastness) in faith, for the rope He holds never frays.", bn: "সংকল্প টলে গেলে বা সামর্থ্য নাজুক মনে হলে আল-মাতিনের ওপর ভর করুন: 'নিশ্চয়ই আল্লাহই রিজিকদাতা, সুদৃঢ় শক্তির অধিকারী' (৫১:৫৮)। তাঁর কাছে ঈমানে সাবাত (অবিচলতা) চান; তিনি যে রশি ধরে রাখেন, তা কখনো ছেঁড়ে না।" },
    quranicRefs: [
      { ref: "51:58", noteEn: "Inna-llaha Huwa-r-Razzaq Dhu-l-Quwwati-l-Matin — the only verse naming Al-Matin; firmness is inseparable from provision.", noteBn: "ইন্নাল্লাহা হুওয়ার-রাজ্জাকু যুল-কুওয়্যাতিল-মাতিন — আল-মাতিন নামটি আছে শুধু এই আয়াতে; দৃঢ়তা আর রিজিক এখানে অবিচ্ছেদ্য।" }
    ]},
  { n: 55, ar: "الْوَلِيُّ", translit: "Al-Waliyy", meanings: { en: "The Protecting Friend", bn: "অভিভাবক", fr: "L'Allié", id: "Yang Maha Melindungi", ur: "دوست و مددگار", tr: "Dost ve Yardımcı", ar: "الناصر المتولي" , zh: '親切的朋友', ja: '自らを守ってくれる友', hi: 'हिमायती दोस्त', es: 'El Amigo protector', ru: 'Покровитель', de: 'Der Schutzherr', fa: 'دوست و یاور', ms: 'Yang Maha Melindungi'},
    explain: { en: "Al-Waliyy is the Protecting Friend and Guardian who takes charge of those who believe and guides them out of darkness into light (Quran 2:257). To have Allah as your Wali is the ultimate protection — no enemy can truly harm one who is under divine walayah (friendship/guardianship). The Quran (45:19) says: 'And Allah is the Wali of the believers.' Al-Ghazali distinguishes this from mere protection: Allah as Wali is actively engaged in nurturing and guiding His protected ones.", bn: "আল-ওয়ালিয়্যু সেই রক্ষাকারী বন্ধু ও অভিভাবক, যিনি ঈমানদারদের দায়িত্ব নেন এবং তাদের অন্ধকার থেকে আলোর দিকে বের করে আনেন (কুরআন ২:২৫৭)। আল্লাহ যার অভিভাবক, তার চেয়ে নিরাপদ আর কেউ নেই; আল্লাহর বেলায়াতের (বন্ধুত্ব ও অভিভাবকত্ব) ছায়ায় যে আছে, কোনো শত্রু সত্যিকার অর্থে তার ক্ষতি করতে পারে না। কুরআন (৪৫:১৯) বলছে: 'আর আল্লাহ মুমিনদের অভিভাবক।' আল-গাজালী একে নিছক রক্ষা করা থেকে আলাদা করে দেখিয়েছেন: অভিভাবক হিসেবে আল্লাহ নিজের আশ্রিতদের সক্রিয়ভাবে লালন করেন, পথ দেখান।" },
    invoke: { en: "When you feel alone, abandoned, or unprotected, call upon 'Ya Waliyy, Ya Nasir' (O Protecting Friend, O Helper). Recite Quran 2:286 in your du'a: 'Anta Mawlana fansurna 'ala-l-qawm il-kafirin' (You are our Protector, so help us against the disbelieving people).", bn: "নিজেকে একা, পরিত্যক্ত বা অরক্ষিত মনে হলে বলুন: 'ইয়া ওয়ালিয়্যু, ইয়া নাসির' (হে রক্ষাকারী বন্ধু, হে সাহায্যকারী)। দু'আয় কুরআন ২:২৮৬-এর এ অংশ পড়ুন: 'আনতা মাওলানা ফানসুরনা আলাল-কাওমিল-কাফিরিন' (আপনিই আমাদের অভিভাবক, তাই কাফির সম্প্রদায়ের বিরুদ্ধে আমাদের সাহায্য করুন)।" } ,
    hadith: { en: "The Prophet ﷺ would supplicate: 'O Allah, grant my soul its taqwa and purify it — You are the best to purify it; You are its Waliyy (Guardian-Friend) and its Mawla (Protector).'", bn: "নবী ﷺ দু'আ করতেন: 'হে আল্লাহ, আমার নফসকে তার তাকওয়া দান করুন এবং একে পরিশুদ্ধ করুন — আপনিই তার সর্বোত্তম পরিশুদ্ধকারী; আপনিই তার ওয়ালি ও মাওলা।'", src: "Sahih Muslim 2722" },
    quranicRefs: [
      { ref: "2:257", noteEn: "Allahu Waliyy-u-lladhina amanu yukhrijuhum mina-z-zulumati ila-n-nur — Allah brings believers from darkness to light.", noteBn: "আল্লাহু ওয়ালিয়্যুল্লাযিনা আমানু ইউখরিজুহুম মিনায-যুলুমাতি ইলান-নুর — আল্লাহ বিশ্বাসীদের অন্ধকার থেকে আলোতে আনেন।" },
      { ref: "3:68", noteEn: "Wa-llahu Waliyy-u-l-mu'minin — Allah is the Waliyy of the believers; His friendship is the truest protection.", noteBn: "ওয়াল্লাহু ওয়ালিয়্যুল-মুমিনিন — আল্লাহ বিশ্বাসীদের ওয়ালিয়্যু; তাঁর বন্ধুত্বই সত্যিকারের সুরক্ষা।" },
      { ref: "4:45", noteEn: "Wa-llahu akbar-u Waliyyan wa kafa billahi Nasira — Allah is the greatest Waliyy and sufficient as Helper.", noteBn: "ওয়াল্লাহু আকবারু ওয়ালিয়্যান ওয়া কাফা বিল্লাহি নাসিরা — আল্লাহ সর্বোচ্চ ওয়ালিয়্যু এবং সাহায্যকারী হিসেবে যথেষ্ট।" },
      { ref: "42:9", noteEn: "Fa-llahu Huwa-l-Waliyy — have they taken protectors besides Him? Allah alone is Al-Waliyy; no other walayah avails.", noteBn: "ফাল্লাহু হুওয়াল-ওয়ালিয়্যু — তারা কি তাঁকে ছাড়া অন্য অভিভাবক ধরেছে? আল্লাহই একমাত্র আল-ওয়ালিয়্যু; আর কারও অভিভাবকত্ব কাজে আসে না।" },
      { ref: "45:19", noteEn: "Wa-llahu Waliyy-u-l-muttaqin — Allah is Waliyy of the God-fearing; taqwa draws one into divine friendship.", noteBn: "ওয়াল্লাহু ওয়ালিয়্যুল-মুত্তাকিন — আল্লাহ মুত্তাকিদের ওয়ালিয়্যু; তাকওয়াই মানুষকে আল্লাহর বন্ধুত্বের কাছে নিয়ে যায়।" }
    ]},
  { n: 56, ar: "الْحَمِيدُ", translit: "Al-Ḥamīd", meanings: { en: "The Praiseworthy", bn: "সর্বপ্রশংসিত", fr: "Le Digne de louange", id: "Yang Maha Terpuji", ur: "تعریف کے لائق", tr: "Övgüye Lâyık", ar: "المستحق للحمد" , zh: '值得讚頌者', ja: '全ての称賛に値する', hi: 'तारीफ़ के लायक़', es: 'El Digno de alabanza', ru: 'Достохвальный', de: 'Der Lobenswürdige', fa: 'ستوده', ms: 'Yang Maha Terpuji'},
    explain: { en: "Al-Hamid is the One who is inherently and perfectly praiseworthy — not because He seeks praise, but because every one of His attributes and actions is objectively praise-worthy. The Quran opens with 'Alhamdulillah' — all praise belongs to Allah — establishing Al-Hamid as the primary context for all existence. Al-Ghazali writes that every 'hamd' (praise) in the universe ultimately belongs to Allah alone, because any praise of creation is ultimately praise of the Creator who made them excellent.", bn: "আল-হামিদ সত্তাগতভাবেই পরিপূর্ণ প্রশংসার যোগ্য। তিনি প্রশংসা চান বলে নয়; তাঁর প্রতিটি গুণ ও কাজ আসলেই প্রশংসার যোগ্য। কুরআন শুরু হয়েছে 'আলহামদুলিল্লাহ' দিয়ে, অর্থাৎ সব প্রশংসা আল্লাহর; গোটা অস্তিত্বের মূল প্রেক্ষাপট হিসেবে এভাবেই দাঁড়িয়ে আছে আল-হামিদ নামটি। আল-গাজালী লিখেছেন, বিশ্বজগতের সব হামদ (প্রশংসা) শেষ পর্যন্ত কেবল আল্লাহরই, কারণ কোনো সৃষ্টির প্রশংসা আসলে সেই স্রষ্টারই প্রশংসা, যিনি তাকে সুন্দর করে গড়েছেন।" } ,
    hadith: { en: "Allah is pleased with His servant who, upon eating food, praises Him (says Alhamdulillah), and upon drinking, praises Him.", bn: "আল্লাহ সেই বান্দার প্রতি সন্তুষ্ট হন যে খাবার খেয়ে আলহামদুলিল্লাহ বলে এবং পানীয় পান করেও আলহামদুলিল্লাহ বলে।", src: "Sahih Muslim 2734" },
    invoke: { en: "In moments of blessing or hardship alike, call upon Ya Hamid and fill your tongue with 'Alhamdulillah' — He is worthy of all praise in every state. Praising Him by this name increases your blessings and turns even trials into occasions of gratitude.", bn: "নিয়ামতের সময় হোক বা কষ্টের, 'ইয়া হামিদ' বলে ডাকুন, আর মুখে বারবার বলুন 'আলহামদুলিল্লাহ'; সব অবস্থায় সব প্রশংসা তাঁরই প্রাপ্য। এই নামে তাঁর প্রশংসা করলে নিয়ামত বাড়ে, আর পরীক্ষাও হয়ে ওঠে শোকরের উপলক্ষ।" } ,
    quranicRefs: [
      { ref: "2:267", noteEn: "Wa-llahu Ghani-yun Hamid — Allah is Self-Sufficient and Praiseworthy; He accepts only wholesome charity.", noteBn: "ওয়াল্লাহু গানিয়্যুন হামিদ — আল্লাহ অমুখাপেক্ষী ও হামিদ; তিনি কেবল পবিত্র, উত্তম দানই কবুল করেন।" },
      { ref: "14:8", noteEn: "Inna-llaha la-Ghani-yun Hamid — if all people were ungrateful, Allah is Self-Sufficient and Praiseworthy.", noteBn: "ইন্নাল্লাহা লা-গানিয়্যুন হামিদ — সবাই অকৃতজ্ঞ হলেও আল্লাহ স্বনির্ভর ও হামিদ।" },
      { ref: "22:64", noteEn: "Wa inna-llaha Huwa-l-Ghani-yul-Hamid — He owns all in heavens and earth; He is Al-Ghaniyy and Al-Hamid.", noteBn: "ওয়া ইন্নাল্লাহা হুওয়াল-গানিয়্যুল-হামিদ — আকাশ-পৃথিবীর সব তাঁর; তিনি আল-গানিয়্যু ও আল-হামিদ।" },
      { ref: "31:12", noteEn: "Fa-inna-llaha Ghani-yun Hamid — whoever is ungrateful, Allah is Self-Sufficient and Praiseworthy; gratitude benefits the giver.", noteBn: "ফাইন্নাল্লাহা গানিয়্যুন হামিদ — কেউ অকৃতজ্ঞ হলেও আল্লাহ গানিয়্যু ও হামিদ; শোকরের লাভ শোকরকারীরই।" },
      { ref: "41:42", noteEn: "Min Hakim-in Hamid — the Quran comes from One Wise and Praiseworthy; every word of the Book is from Al-Hamid.", noteBn: "মিন হাকিমিন হামিদ — কুরআন এসেছে প্রজ্ঞাময়, প্রশংসিত আল্লাহর কাছ থেকে; কিতাবের প্রতিটি শব্দ আল-হামিদের।" }
    ]},
  { n: 57, ar: "الْمُحْصِي", translit: "Al-Muḥṣī", meanings: { en: "The Enumerator", bn: "সর্বগণনাকারী", fr: "Celui qui dénombre", id: "Yang Maha Menghitung", ur: "شمار کرنے والا", tr: "Her Şeyi Sayan", ar: "المحصي لكل شيء" , zh: '清算者', ja: '答える者', hi: 'गिनती रखने वाला', es: 'El que todo lo cuenta', ru: 'Исчисляющий', de: 'Der alles Erfassende', fa: 'شمارنده', ms: 'Yang Maha Menghitung'},
    explain: { en: "Al-Muhsi is the One who has counted and catalogued every single thing — every grain of sand, every raindrop, every leaf, every breath taken, every word spoken, every heartbeat. Quran 36:12 says: 'We have counted everything in a clear register.' No number is too large, no quantity too small, no fleeting moment too brief. On the Day of Judgement, Al-Muhsi's account will be presented in full: the Quran (99:7-8) says an atom's weight of good or evil will be shown.", bn: "আল-মুহসি সবকিছু গুনে রেখেছেন, লিখে রেখেছেন: প্রতিটি বালুকণা, প্রতিটি বৃষ্টির ফোঁটা, প্রতিটি পাতা, প্রতিটি নিঃশ্বাস, মুখের প্রতিটি কথা, হৃদয়ের প্রতিটি স্পন্দন। কুরআন ৩৬:১২ বলছে: 'আমি সবকিছু এক সুস্পষ্ট কিতাবে গুনে রেখেছি।' কোনো সংখ্যা তাঁর কাছে বেশি বড় নয়, কোনো পরিমাণ বেশি ছোট নয়, কোনো মুহূর্ত বেশি ক্ষণিক নয়। কিয়ামতের দিন আল-মুহসির পুরো হিসাব সামনে আনা হবে; কুরআন (৯৯:৭-৮) বলছে, অণু পরিমাণ ভালো বা মন্দ কাজও সেদিন দেখানো হবে।" } ,
    invoke: { en: "No hidden good deed is lost with Al-Muhsi, who enumerates what oceans of ink could never record — so do good in secret with full confidence. Hold yourself to account (muhasabah) each night, before the Day your own record is read back to you.", bn: "আল-মুহসির কাছে কোনো গোপন নেক আমল হারিয়ে যায় না। সাগরের সব পানি কালি হলেও যা লিখে শেষ করা যেত না, তিনি তা-ও গুনে রাখেন। তাই পূর্ণ আস্থা নিয়ে গোপনে ভালো কাজ করুন। যেদিন আপনার আমলনামা পড়ে শোনানো হবে, তার আগেই প্রতি রাতে নিজের হিসাব (মুহাসাবা) নিন।" },
    quranicRefs: [
      { ref: "19:94", noteEn: "Laqad ahsa-hum wa adda-hum adda — He has counted them and numbered them with precision; Al-Muhsi's count is exact.", noteBn: "লাকাদ আহসাহুম ওয়া আদ্দাহুম আদ্দা — তিনি তাদের গুনে রেখেছেন, সঠিক সংখ্যায় হিসাব করে রেখেছেন; আল-মুহসির গণনা নির্ভুল।" },
      { ref: "36:12", noteEn: "Wa kulla shay'in ahsayna-hu fi Imam-in Mubin — We have enumerated everything in a clear register; the divine catalogue is complete.", noteBn: "ওয়া কুল্লা শায়িন আহসায়নাহু ফি ইমামিন মুবিন — আমি সবকিছু এক সুস্পষ্ট কিতাবে গুনে রেখেছি; আল্লাহর খাতায় কিছুই বাদ নেই।" }
    ]},
  { n: 58, ar: "الْمُبْدِئُ", translit: "Al-Mubdi'", meanings: { en: "The Initiator", bn: "সূচনাকারী", fr: "Celui qui commence", id: "Yang Maha Memulai", ur: "پہلی بار پیدا کرنے والا", tr: "İlkin Yaratan", ar: "المبدئ للخلق" , zh: '首創萬物者', ja: '創造主', hi: 'पहली बार पैदा करने वाला', es: 'El Iniciador', ru: 'Начинающий', de: 'Der Beginnende', fa: 'آغازگر آفرینش', ms: 'Yang Maha Memulakan'},
    explain: { en: "Al-Mubdi' is the One who initiates creation from absolute nothingness — the Originator who starts existence itself. This name appears paired with Al-Mu'id (the Restorer) in classical theology: just as He began creation, He will end and recreate it. Quran 85:13 says 'He originates (yubdi') and restores (yu'id).' Ibn al-Qayyim writes that reflecting on Al-Mubdi' counters the argument of those who deny resurrection: the One who initiated creation from nothing can certainly restore it.", bn: "আল-মুবদি সেই সত্তা, যিনি একেবারে শূন্য থেকে সৃষ্টির সূচনা করেন; অস্তিত্বের শুরুটাই তাঁর হাতে। আকিদার প্রাচীন গ্রন্থগুলোতে এই নাম আসে আল-মুইদের (পুনঃসৃষ্টিকারী) সাথে জোড়ায়: যেভাবে তিনি সৃষ্টি শুরু করেছেন, সেভাবেই তা শেষ করে আবার সৃষ্টি করবেন। কুরআন ৮৫:১৩ বলছে: 'তিনিই প্রথমবার সৃষ্টি করেন (ইউবদিউ), তিনিই আবার সৃষ্টি করেন (ইউইদ)।' ইবনুল কাইয়িম লিখেছেন, আল-মুবদি নিয়ে ভাবলে পুনরুত্থান অস্বীকারকারীদের যুক্তি খণ্ডন হয়ে যায়: যিনি শূন্য থেকে সৃষ্টি শুরু করেছেন, তিনি অবশ্যই তা আবার ফিরিয়ে আনতে পারেন।" } ,
    invoke: { en: "Ask Al-Mubdi' for fresh beginnings — a new chapter of repentance, work, or knowledge. The One who initiated you from nothing finds no new start difficult; entrust every first step to Him with bismillah.", bn: "আল-মুবদির কাছে নতুন সূচনা চান — তাওবা, কাজ বা জ্ঞানের নতুন অধ্যায়। যিনি আপনাকে শূন্য থেকে সূচনা করেছেন, তাঁর কাছে কোনো নতুন শুরুই কঠিন নয়; প্রতিটি প্রথম পদক্ষেপ 'বিসমিল্লাহ' বলে তাঁর হাতে সঁপে দিন।" },
    quranicRefs: [
      { ref: "10:34", noteEn: "Qul hal min shuraka'ikum man yabda'u-l-khalqa thumma yu'idu-hu, quli-llahu yabda'u-l-khalqa — Allah initiates creation.", noteBn: "কুল হাল মিন শুরাকাইকুম মান ইয়াবদাউল-খালকা ছুম্মা ইউইদুহু, কুলিল্লাহু ইয়াবদাউল-খালকা — আল্লাহ সৃষ্টির সূচনা করেন।" },
      { ref: "85:13", noteEn: "Inna-hu Huwa yubdi'u wa yu'id — He originates and He restores; the paired names Al-Mubdi and Al-Mu'id in one verse.", noteBn: "ইন্নাহু হুওয়া ইউবদিউ ওয়া ইউইদ — তিনিই সূচনা করেন, তিনিই আবার সৃষ্টি করেন; আল-মুবদি ও আল-মুইদ জোড়া নাম একই আয়াতে।" }
    ]},
  { n: 59, ar: "الْمُعِيدُ", translit: "Al-Muʿīd", meanings: { en: "The Restorer", bn: "পুনঃসৃষ্টিকারী", fr: "Celui qui redonne", id: "Yang Maha Mengembalikan", ur: "دوبارہ پیدا کرنے والا", tr: "Yeniden Dirilten", ar: "المعيد للخلق" , zh: '恢復福祉者', ja: '全てを還す者', hi: 'दोबारा पैदा करने वाला', es: 'El que restablece', ru: 'Возвращающий', de: 'Der Wiederherstellende', fa: 'بازگرداننده', ms: 'Yang Maha Mengembalikan'},
    explain: { en: "Al-Mu'id is the One who restores and recreates — primarily referring to the resurrection on the Day of Judgement. The Quran (10:34) challenges: 'Who originates creation and then repeats it?' Then answers: 'Allah.' To those who doubt resurrection, the Quran (36:78-79) replies that the One who created from bones the first time can restore them with even greater ease. Al-Mu'id also reassures that lost faith, broken hearts, and corrupted souls can be restored.", bn: "আল-মুইদ সেই সত্তা, যিনি ফিরিয়ে আনেন, আবার সৃষ্টি করেন; মূলত কিয়ামতের দিনের পুনরুত্থান বোঝাতেই এ নাম। কুরআন (১০:৩৪) চ্যালেঞ্জ ছুড়ে দেয়: 'কে সৃষ্টির সূচনা করে, তারপর আবার তা সৃষ্টি করে?' তারপর নিজেই জবাব দেয়: 'আল্লাহ।' যারা পুনরুত্থানে সন্দেহ করে, কুরআন (৩৬:৭৮-৭৯) তাদের বলে: যিনি প্রথমবার সৃষ্টি করেছেন, পচা হাড়কে আবার জীবিত করা তাঁর জন্য আরও সহজ। আল-মুইদ নামটি এই আশ্বাসও দেয় যে হারানো ঈমান, ভাঙা হৃদয় আর কলুষিত আত্মাও আবার ঠিক হতে পারে।" } ,
    invoke: { en: "When something good is lost — health, the sweetness of faith, a livelihood — ask Al-Mu'id to restore it, for He who will repeat all creation can easily return what left you. Remember too that your own return (ma'ad) is to Him, and prepare for it.", bn: "কোনো কল্যাণ হারিয়ে গেলে, যেমন স্বাস্থ্য, ঈমানের মিষ্টতা বা জীবিকা, আল-মুইদের কাছে তা ফিরিয়ে দেওয়ার দু'আ করুন। যিনি গোটা সৃষ্টিকে আবার সৃষ্টি করবেন, হারানো জিনিস ফেরানো তাঁর কাছে সহজ। আর মনে রাখুন, আপনার নিজের ফিরে যাওয়াও (মাআদ) তাঁরই কাছে; তার প্রস্তুতি নিন।" },
    quranicRefs: [
      { ref: "10:34", noteEn: "Thumma yu'idu-hu — then He restores it; Al-Mu'id is the inevitable answer to those who doubt resurrection.", noteBn: "ছুম্মা ইউইদুহু — তারপর তিনি আবার সৃষ্টি করেন; যারা পুনরুত্থানে সন্দেহ করে, তাদের অকাট্য জবাব আল-মুইদ নামেই।" },
      { ref: "85:13", noteEn: "Inna-hu Huwa yubdi'u wa yu'id — He originates and He restores; paired with Al-Mubdi in the same verse.", noteBn: "ইন্নাহু হুওয়া ইউবদিউ ওয়া ইউইদ — তিনিই সূচনা করেন, তিনিই আবার সৃষ্টি করেন; একই আয়াতে আল-মুবদির সাথে জোড়া।" }
    ]},
  { n: 60, ar: "الْمُحْيِي", translit: "Al-Muḥyī", meanings: { en: "The Giver of Life", bn: "জীবনদাতা", fr: "Celui qui fait vivre", id: "Yang Maha Menghidupkan", ur: "زندگی دینے والا", tr: "Hayat Veren", ar: "المحيي للخلق" , zh: '賜予生命者', ja: '生命を与える者', hi: 'ज़िंदगी देने वाला', es: 'El Dador de vida', ru: 'Дарующий жизнь', de: 'Der Leben Gebende', fa: 'زنده‌کننده', ms: 'Yang Maha Menghidupkan'},
    explain: { en: "Al-Muhyi is the Giver of Life in every sense — the One who breathed life into Adam from clay (Quran 15:29), who sends rain to revive dead land (Quran 30:50), and who will restore life to the dead on the Day of Resurrection (Quran 2:260). The Quran also uses ihya' (enlivening) metaphorically for spiritual life: a heart awakened by guidance is 'brought to life' by Al-Muhyi. Life — physical, ecological, and spiritual — has one single source.", bn: "আল-মুহয়ি সব অর্থেই জীবনদাতা। তিনি মাটির আদমে প্রাণ ফুঁকে দিয়েছেন (কুরআন ১৫:২৯), বৃষ্টি পাঠিয়ে মরা জমিকে জীবিত করেন (কুরআন ৩০:৫০), আর কিয়ামতের দিন মৃতদের আবার জীবন দেবেন (কুরআন ২:২৬০)। কুরআন ইহইয়া (জীবিত করা) শব্দটি আত্মিক জীবন বোঝাতেও ব্যবহার করে: হেদায়েতে জেগে ওঠা হৃদয়কে আল-মুহয়িই 'জীবিত' করেন। দেহের জীবন, প্রকৃতির জীবন, আত্মার জীবন, সবকিছুর উৎস একটাই।" } ,
    hadith: { en: "On waking the Prophet ﷺ would say: 'Al-hamdu lillahi-lladhi ahyana ba'da ma amatana wa ilayhi-n-nushur' (Praise be to Allah who gave us life after causing us to die, and to Him is the resurrection).", bn: "ঘুম থেকে জেগে নবী ﷺ বলতেন: 'আলহামদু লিল্লাহিল্লাযি আহইয়ানা বা'দা মা আমাতানা ওয়া ইলাইহিন-নুশুর' (সকল প্রশংসা সেই আল্লাহর, যিনি মৃত্যুর পর আমাদের জীবিত করলেন, আর তাঁরই দিকে পুনরুত্থান)।", src: "Sahih al-Bukhari 6312" },
    invoke: { en: "When your heart feels spiritually dead or you lose hope in renewal, call upon Ya Muhyi — He who revives the barren earth can revive your heart with faith. Ask Him to breathe life into your worship, your intentions, and every dead hope you have surrendered.", bn: "হৃদয়টা যখন মরা মনে হয়, কিংবা নতুন করে জেগে ওঠার আশা হারিয়ে ফেলেন, তখন 'ইয়া মুহয়ি' বলে ডাকুন। যিনি শুকনো জমিনকে জীবিত করেন, তিনি ঈমান দিয়ে আপনার হৃদয়কেও জীবিত করতে পারেন। তাঁর কাছে চান, তিনি যেন আপনার ইবাদতে, নিয়তে, আর যে আশাগুলো মরে গেছে বলে ছেড়ে দিয়েছেন সেগুলোতে আবার প্রাণ দেন।" } ,
    quranicRefs: [
      { ref: "2:258", noteEn: "Allah yuhyi wa yumit — Allah gives life and causes death; Ibrahim's argument to Namrud about Al-Muhyi.", noteBn: "আল্লাহু ইউহয়ি ওয়া ইউমিত — আল্লাহ জীবন দেন ও মৃত্যু ঘটান; নমরুদের বিরুদ্ধে ইব্রাহিমের যুক্তি।" },
      { ref: "30:50", noteEn: "fa-unzur ila athari rahmati-llah kayfa yuhyi-l-ard ba'da mawtiha — see how Allah revives the earth after its death.", noteBn: "ফাউনযুর ইলা আছারি রাহমাতিল্লাহ কায়ফা ইউহয়িল-আরদা বাআদা মাওতিহা — দেখো কীভাবে আল্লাহ মৃত্যুর পরে পৃথিবী পুনরুজ্জীবিত করেন।" },
      { ref: "41:39", noteEn: "Inna-lladhi ahyaha la-Muhyi-l-mawta — He who revived it is indeed Al-Muhyi of the dead; rain over dead earth proves resurrection.", noteBn: "ইন্নাল্লাযি আহয়াহা লা-মুহয়িল-মাওতা — যিনি তা পুনরুজ্জীবিত করেছেন তিনি মৃতদের আল-মুহয়ি; মৃত মাটিতে বৃষ্টি পুনরুত্থানের প্রমাণ।" }
    ]},
  { n: 61, ar: "الْمُمِيتُ", translit: "Al-Mumīt", meanings: { en: "The Bringer of Death", bn: "মৃত্যুদাতা", fr: "Celui qui fait mourir", id: "Yang Maha Mematikan", ur: "موت دینے والا", tr: "Öldüren", ar: "المميت للأحياء" , zh: '賜死者、毀滅者', ja: '死をもたらす者、破壊者', hi: 'मौत देने वाला', es: 'El que da la muerte', ru: 'Умерщвляющий', de: 'Der den Tod Bringende', fa: 'میراننده', ms: 'Yang Maha Mematikan'},
    explain: { en: "Al-Mumit is the One who causes death — not as a tragedy but as a transition, and not arbitrarily but at the precisely appointed time. The Quran (3:185) says: 'Every soul will taste death.' Death in Islamic theology is not the end but the gateway: Al-Mumit and Al-Muhyi work together to form the cycle of existence. Al-Ghazali writes that meditating on Al-Mumit purifies the heart of love for the world and attachments that lead to heedlessness.", bn: "আল-মুমিত মৃত্যু দেন। এ মৃত্যু কোনো বিপর্যয় নয়, এক জীবন থেকে আরেক জীবনে পারাপার; আর তা খেয়ালখুশিমতো নয়, ঠিক নির্ধারিত সময়ে। কুরআন (৩:১৮৫) বলছে: 'প্রত্যেক প্রাণীকে মৃত্যুর স্বাদ নিতে হবে।' ইসলামি আকিদায় মৃত্যু শেষ নয়, একটি দরজা; আল-মুমিত আর আল-মুহয়ি মিলেই অস্তিত্বের এই চক্র। আল-গাজালী লিখেছেন, আল-মুমিত নিয়ে ভাবলে অন্তর দুনিয়ার মোহ আর গাফিলতি ডেকে আনা আসক্তি থেকে পরিষ্কার হয়।" },
    hadith: { en: "Remember often the destroyer of pleasures — death.", bn: "আনন্দের ধ্বংসকারী মৃত্যুকে বারবার স্মরণ করো।", src: "Sunan ibn Majah 4258; Sunan al-Tirmidhi 2307 (Hasan)" } ,
    invoke: { en: "Remember Al-Mumit by remembering death often — the Prophet ﷺ commanded frequent remembrance of 'the destroyer of pleasures'. Say the evening dhikr 'bika nahya wa bika namut' (by You we live and by You we die), and let this Name loosen your grip on the dunya.", bn: "মৃত্যুকে বেশি বেশি স্মরণ করে আল-মুমিতকে স্মরণ করুন; নবী ﷺ 'স্বাদ বিনাশকারী' মৃত্যুকে বেশি বেশি স্মরণ করতে বলেছেন। সন্ধ্যার জিকির 'বিকা নাহইয়া ওয়া বিকা নামুত' (আপনারই হুকুমে আমরা বাঁচি, আপনারই হুকুমে মরি) পড়ুন, আর এই নাম দুনিয়াকে আঁকড়ে ধরা মুঠি আলগা করে দিক।" },
    quranicRefs: [
      { ref: "2:258", noteEn: "Allah yuhyi wa yumit — Allah gives life and causes death; the divine pair Al-Muhyi and Al-Mumit stated together.", noteBn: "আল্লাহু ইউহয়ি ওয়া ইউমিত — আল্লাহ জীবন দেন ও মৃত্যু ঘটান; আল-মুহয়ি ও আল-মুমিত একসাথে।" },
      { ref: "3:156", noteEn: "Wa-llahu yuhyi wa yumit — Allah gives life and causes death; those who fall in battle are in Allah's care.", noteBn: "ওয়াল্লাহু ইউহয়ি ওয়া ইউমিত — আল্লাহ জীবন দেন ও মৃত্যু ঘটান; যুদ্ধে যারা প্রাণ দেয়, তারাও আল্লাহর তত্ত্বাবধানে।" },
      { ref: "7:158", noteEn: "Wa Huwa yuhyi wa yumit — He gives life and causes death; the Prophet commands belief in Al-Muhyi Al-Mumit.", noteBn: "ওয়া হুওয়া ইউহয়ি ওয়া ইউমিত — তিনি জীবন দেন ও মৃত্যু ঘটান; নবী মানুষকে আল-মুহয়ি, আল-মুমিতের ওপর ঈমান আনতে বলেন।" }
    ]},
  { n: 62, ar: "الْحَيُّ", translit: "Al-Ḥayy", meanings: { en: "The Ever-Living", bn: "চিরঞ্জীব", fr: "Le Vivant", id: "Yang Maha Hidup", ur: "ہمیشہ زندہ", tr: "Diri Olan", ar: "الحي الذي لا يموت" , zh: '永生者', ja: '永久に生きる者', hi: 'हमेशा ज़िंदा', es: 'El Viviente', ru: 'Живой', de: 'Der ewig Lebendige', fa: 'زنده‌ی همیشگی', ms: 'Yang Tetap Hidup'},
    explain: { en: "Al-Hayy is the Ever-Living whose life is perfect, beginningless, endless, and uncaused — requiring nothing to sustain it. All life in creation is borrowed from Al-Hayy: every creature lives only because Al-Hayy wills it and sustains it. Ayat al-Kursi opens: 'Allah — there is no deity except Him, Al-Hayy, Al-Qayyum' (2:255), establishing this as the foundational statement of divine reality. Ibn al-Qayyim writes that Al-Hayy encompasses all attributes of perfection, because a dead being has no attributes.", bn: "আল-হাইয়্যু চিরঞ্জীব। তাঁর জীবন পরিপূর্ণ; এর শুরু নেই, শেষ নেই, কোনো কারণ থেকে আসেনি, টিকে থাকতে কিছুর দরকারও নেই। সৃষ্টির সব জীবন আল-হাইয়্যুর কাছ থেকে ধার করা; প্রতিটি প্রাণী বেঁচে আছে কেবল এজন্য যে আল-হাইয়্যু তা চান এবং টিকিয়ে রাখেন। আয়াতুল কুরসি শুরু হয়েছে এভাবে: 'আল্লাহ, তিনি ছাড়া কোনো ইলাহ নেই, তিনি আল-হাইয়্যু, আল-কাইয়্যুম' (২:২৫৫); আল্লাহর পরিচয়ের মূল ঘোষণা এটাই। ইবনুল কাইয়িম লিখেছেন, আল-হাইয়্যু নামের মধ্যে পূর্ণতার সব গুণ এসে যায়, কারণ যে মৃত, তার কোনো গুণই থাকে না।" },
    hadith: { en: "The Prophet (peace be upon him) used to say when distressed: 'Ya Hayyu Ya Qayyum, bi-rahmatika astaghith' — O Ever-Living, O Self-Sustaining, by Your mercy I seek help.", bn: "নবী (সা.) বিপদে পড়লে বলতেন: 'ইয়া হাইয়্যু ইয়া কাইয়্যুম, বিরাহমাতিকা আস্তাগিছ', অর্থাৎ হে চিরঞ্জীব, হে স্বয়ংপ্রতিষ্ঠিত, আপনার রহমতের উসিলায় আমি সাহায্য চাই।", src: "Sunan al-Tirmidhi 3524; al-Hakim (Sahih)" },
    invoke: { en: "In moments of deep distress or spiritual darkness, call upon 'Ya Hayyu Ya Qayyum, bi-rahmatika astaghith, wa aslih li sha'ni kullahu wa la takilni ila nafsi tarfata 'ayn' (O Ever-Living, O Sustainer, by Your mercy I seek help; set right all my affairs and do not entrust me to myself even for a blink). This was the Prophet's own du'a.", bn: "গভীর বিপদ বা আত্মিক অন্ধকারের মুহূর্তে ডাকুন: 'ইয়া হাইয়্যু ইয়া কাইয়্যুম, বিরাহমাতিকা আস্তাগিছ, ওয়া আসলিহ লি শানি কুল্লাহু ওয়ালা তাকিলনি ইলা নাফসি তারফাতা আইন' (হে চিরঞ্জীব, হে ধারক, আপনার রহমতের উসিলায় সাহায্য চাই; আমার সব বিষয় ঠিক করে দিন, আর চোখের পলক পরিমাণ সময়ের জন্যও আমাকে আমার নিজের হাতে ছেড়ে দেবেন না)। দু'আটি নবী (সা.)-এর নিজের।" } ,
    quranicRefs: [
      { ref: "2:255", noteEn: "Allahu la ilaha illa Huwa-l-Hayy-ul-Qayyum — Ayat al-Kursi opens with Al-Hayy; the Ever-Living who never sleeps.", noteBn: "আল্লাহু লা ইলাহা ইল্লা হুওয়াল-হাইয়্যুল-কাইয়্যুম — আয়াতুল কুরসির শুরুতেই আল-হাইয়্যু; সেই চিরঞ্জীব, যিনি কখনো ঘুমান না।" },
      { ref: "3:2", noteEn: "Allahu la ilaha illa Huwa-l-Hayy-ul-Qayyum — opens Surah Ali Imran, anchoring the revelation in divine life.", noteBn: "আল্লাহু লা ইলাহা ইল্লা হুওয়াল-হাইয়্যুল-কাইয়্যুম — সূরা আলি ইমরানের শুরু এই কথায়; ওহির ভিত্তি চিরঞ্জীব আল্লাহ।" },
      { ref: "20:111", noteEn: "Wa akhada-t-ul-wujuhu li-l-Hayy-il-Qayyum — faces bow before Al-Hayy Al-Qayyum on the Day of Resurrection.", noteBn: "ওয়া আখাদাতিল-উজুহু লিল-হাইয়্যিল-কাইয়্যুম — কিয়ামতের দিন সব চেহারা আল-হাইয়্যু আল-কাইয়্যুমের সামনে নত হবে।" },
      { ref: "25:58", noteEn: "Wa tawakkal ala-l-Hayy-illadhi la yamut — put trust in Al-Hayy who never dies; He alone is worthy of ultimate trust.", noteBn: "ওয়া তাওয়াক্কাল আলাল-হাইয়্যিল্লাযি লা ইয়ামুত — ভরসা করো সেই চিরঞ্জীবের ওপর, যিনি কখনো মরবেন না; চূড়ান্ত ভরসার যোগ্য কেবল তিনিই।" },
      { ref: "40:65", noteEn: "Huwa-l-Hayy la ilaha illa Huwa fa-d'u-hu mukhlisin — He is Al-Hayy, call upon Him with pure sincerity.", noteBn: "হুওয়াল-হাইয়্যু লা ইলাহা ইল্লা হুওয়া ফাদউহু মুখলিসিন — তিনি আল-হাইয়্যু; খাঁটি মনে, একনিষ্ঠভাবে তাঁকে ডাকো।" }
    ]},
  { n: 63, ar: "الْقَيُّومُ", translit: "Al-Qayyūm", meanings: { en: "The Sustainer of All", bn: "সর্বসত্তার ধারক", fr: "L'Immuable", id: "Yang Maha Berdiri Sendiri", ur: "سب کو قائم رکھنے والا", tr: "Her Şeyi Ayakta Tutan", ar: "القائم على كل شيء" , zh: '維持萬物者、自我擁有者', ja: 'すべてのものを自分で守るもの', hi: 'सबको क़ायम रखने वाला', es: 'El Sustentador', ru: 'Вседержитель', de: 'Der alles Erhaltende', fa: 'برپادارنده‌ی هستی', ms: 'Yang Kekal Mentadbir Sekalian Makhluk'},
    explain: { en: "Al-Qayyum is the Self-Subsisting Sustainer of all creation — the One who needs nothing to exist and without whom nothing else can exist. Every atom in the universe is sustained moment to moment by Al-Qayyum; if He were to withdraw His sustaining power for an instant, all creation would cease. Ibn al-Qayyim (whose very name is derived from this attribute) writes that Al-Qayyum is the name that all other divine names 'return to' as their foundation and the most comprehensive name after Allah Himself.", bn: "আল-কাইয়্যুম নিজে নিজে প্রতিষ্ঠিত, আর গোটা সৃষ্টির ধারক। টিকে থাকতে তাঁর কিছুই লাগে না, অথচ তাঁকে ছাড়া কোনো কিছুই টিকে থাকতে পারে না। মহাবিশ্বের প্রতিটি অণু মুহূর্তে মুহূর্তে আল-কাইয়্যুমের ধারণেই টিকে আছে; এক মুহূর্তের জন্যও তিনি সেই ধারণ সরিয়ে নিলে সব সৃষ্টি মিলিয়ে যেত। ইবনুল কাইয়িম (যাঁর নামটিও এই গুণ থেকে এসেছে) লিখেছেন, আল্লাহর অন্য সব নাম ভিত্তি হিসেবে আল-কাইয়্যুমের দিকেই 'ফিরে আসে'; 'আল্লাহ' নামের পরে এটিই সবচেয়ে ব্যাপক নাম।" } ,
    hadith: { en: "When something distressed him the Prophet ﷺ would say: 'Ya Hayyu Ya Qayyum, bi-rahmatika astaghith' (O Ever-Living, O Sustainer of all, by Your mercy I seek relief).", bn: "কোনো কিছু নবী ﷺ-কে চিন্তিত করলে তিনি বলতেন: 'ইয়া হাইয়ু ইয়া কাইয়ুম, বিরাহমাতিকা আস্তাগিস' (হে চিরঞ্জীব, হে সবকিছুর ধারক, আপনার রহমতের উসিলায় আমি সাহায্য চাই)।", src: "Jami' at-Tirmidhi 3524" },
    invoke: { en: "In times of deep distress, call upon 'Ya Hayyu Ya Qayyum, bi-rahmatika astaghith' (O Ever-Living, O Sustainer, by Your mercy I seek relief) — a du'a the Prophet ﷺ turned to in anguish. He upholds all existence, so entrust your collapsing affairs to the One who never tires.", bn: "গভীর দুশ্চিন্তার সময় পড়ুন 'ইয়া হাইয়ু ইয়া কাইয়ুম, বিরাহমাতিকা আস্তাগিস' (হে চিরঞ্জীব, হে সর্বসত্তার ধারক, আপনার রহমতের উসিলায় আমি সাহায্য চাই) — এই দু'আ নবী ﷺ কষ্টের সময় পড়তেন। তিনি সমস্ত অস্তিত্ব ধারণ করেন, তাই আপনার ভেঙে পড়া বিষয়গুলো সেই সত্তার হাতে সঁপে দিন যিনি কখনো ক্লান্ত হন না।" } ,
    quranicRefs: [
      { ref: "2:255", noteEn: "Allahu la ilaha illa Huwa-l-Hayy-ul-Qayyum — Ayat al-Kursi: Al-Qayyum sustains all creation without weariness.", noteBn: "আল্লাহু লা ইলাহা ইল্লা হুওয়াল-হাইয়্যুল-কাইয়্যুম — আয়াতুল কুরসি: আল-কাইয়্যুম ক্লান্তি ছাড়া সমস্ত সৃষ্টি টিকিয়ে রাখেন।" },
      { ref: "3:2", noteEn: "Allahu la ilaha illa Huwa-l-Hayy-ul-Qayyum — opens Surah Ali Imran; Al-Qayyum as the sustaining ground of all revelation.", noteBn: "আল্লাহু লা ইলাহা ইল্লা হুওয়াল-হাইয়্যুল-কাইয়্যুম — সূরা আলি ইমরানের শুরু; সব ওহির ধারক ও ভিত্তি আল-কাইয়্যুম।" },
      { ref: "20:111", noteEn: "Wa akhada-t-ul-wujuhu li-l-Hayy-il-Qayyum — faces bow before Al-Qayyum on the Day of Resurrection.", noteBn: "ওয়া আখাদাতিল-উজুহু লিল-হাইয়্যিল-কাইয়্যুম — কিয়ামতে মুখমণ্ডল আল-কাইয়্যুমের সামনে নত হবে।" }
    ]},
  { n: 64, ar: "الْوَاجِدُ", translit: "Al-Wājid", meanings: { en: "The Finder", bn: "সর্বপ্রাপক", fr: "Celui qui trouve", id: "Yang Maha Menemukan", ur: "پانے والا", tr: "Dilediğini Bulan", ar: "الغني الذي لا يفتقر" , zh: '搜查者', ja: '見つけし者', hi: 'पाने वाला', es: 'El que encuentra', ru: 'Находящий', de: 'Der Findende', fa: 'یابنده', ms: 'Yang Maha Menemui'},
    explain: { en: "Al-Wajid means the One who finds and the One who is never in want — the root wajada carries both meanings. He is never deprived of anything He wishes to find; His resources never run short. Al-Ghazali links this name to divine richness (ghina'): since Allah needs nothing and lacks nothing, His giving is truly from abundance. Reflecting on Al-Wajid reminds the servant that all scarcity is on the human side, never on Allah's side.", bn: "আল-ওয়াজিদ মানে যিনি খুঁজে পান, আবার যিনি কখনো অভাবে পড়েন না; মূল শব্দ ওয়াজাদার মধ্যে দুটি অর্থই আছে। যা তিনি পেতে চান, তা থেকে কখনো বঞ্চিত হন না; তাঁর ভাণ্ডার কখনো কমে না। আল-গাজালী এই নামকে আল্লাহর অমুখাপেক্ষিতার (গিনা) সাথে মিলিয়েছেন: আল্লাহর কোনো প্রয়োজন নেই, কোনো কিছুর ঘাটতিও নেই, তাই তাঁর দান সত্যিই প্রাচুর্য থেকে আসে। আল-ওয়াজিদ নিয়ে ভাবলে বান্দা বোঝে, সব অভাব মানুষের দিকে, আল্লাহর দিকে কখনো নয়।" } ,
    invoke: { en: "Al-Wajid lacks nothing He wills — whatever you need already exists with Him in full. Bring your needs, however impossible they seem, to the Finder who is never at a loss, pairing honest effort with tawakkul.", bn: "আল-ওয়াজিদ যা চান, তার কোনো কিছুরই অভাব তাঁর নেই; আপনার যা দরকার, সবই পুরোপুরি তাঁর কাছে আছে। প্রয়োজন যত অসম্ভবই মনে হোক, তা নিয়ে যান সেই সত্তার কাছে, যিনি কখনো দিশেহারা হন না। সৎ চেষ্টার সাথে তাওয়াক্কুল মিলিয়ে নিন।" },
    quranicRefs: [
      { ref: "93:6", noteEn: "Alam yajidka yatiman fa-awa — Did He not find you (from the root wajada) an orphan and shelter you? The One who finds is never in want.", noteBn: "আলাম ইয়াজিদকা ইয়াতিমান ফা-আওয়া — তিনি কি তোমাকে (ওয়াজাদা মূল থেকে) এতিম পাননি ও আশ্রয় দেননি? যিনি খুঁজে পান তিনি কখনো অভাবী নন।" },
      { ref: "93:7", noteEn: "Wa wajadaka dallan fa-hada — and He found you unaware and guided you; nothing He seeks eludes Him.", noteBn: "ওয়া ওয়াজাদাকা দাল্লান ফা-হাদা — এবং তিনি তোমাকে পথহারা পেয়ে পথ দেখিয়েছেন; তিনি যা খোঁজেন তা তাঁকে এড়ায় না।" },
      { ref: "35:15", noteEn: "Wa-llahu Huwa-l-Ghaniyy-ul-Hamid — Allah is Free of all need; the Finder never lacks what He wills.", noteBn: "ওয়াল্লাহু হুওয়াল-গানিয়্যুল-হামিদ — আল্লাহই অভাবমুক্ত; আল-ওয়াজিদ যা চান, তাতে তাঁর কখনো ঘাটতি পড়ে না।" },
      { ref: "47:38", noteEn: "Wa-llahu-l-Ghaniyy wa antumu-l-fuqara' — Allah is Free of need while you are the needy; scarcity is only on the human side.", noteBn: "ওয়াল্লাহুল-গানিয়্যু ওয়া আনতুমুল-ফুকারা — আল্লাহ অভাবমুক্ত আর তোমরা মুখাপেক্ষী; অভাব কেবল মানুষের দিকে।" }
    ]},
  { n: 65, ar: "الْمَاجِدُ", translit: "Al-Mājid", meanings: { en: "The Noble", bn: "মহিমান্বিত", fr: "Le Noble", id: "Yang Maha Mulia Sifatnya", ur: "بزرگی والا", tr: "Şerefi Yüce", ar: "الماجد الكريم" , zh: '卓越者', ja: '高貴なる者', hi: 'बुज़ुर्गी वाला', es: 'El Noble', ru: 'Благородный', de: 'Der Edle', fa: 'بزرگوار', ms: 'Yang Maha Mulia Sifat-Nya'},
    explain: { en: "Al-Majid describes nobility of character (majd) — the combination of generosity, honour, and magnificence. While Al-Majid (name 48) refers to external glory, Al-Majid here (as distinguished in classical scholarship) emphasises inner nobility of divine character. Allah's generosity is of the noblest kind: He gives to those who oppose Him, He delays punishment for those who deserve it, and He rewards beyond what is deserved.", bn: "আল-মাজিদ নামে আছে চরিত্রের মহত্ত্ব (মাজদ): উদারতা, সম্মান ও মহিমার মিলন। আল-মাজিদ (৪৮ নম্বর নাম) বোঝায় বাইরের মহিমা; আর এখানকার আল-মাজিদ, প্রাচীন আলেমরা যেভাবে দুটিকে আলাদা করেছেন, জোর দেয় আল্লাহর গুণের ভেতরের মহত্ত্বে। আল্লাহর উদারতা সবচেয়ে মহৎ ধরনের: যারা তাঁর বিরোধিতা করে, তিনি তাদেরও দেন; যারা শাস্তির যোগ্য, তাদের শাস্তিও পিছিয়ে দেন; আর প্রাপ্যের চেয়ে বেশি পুরস্কার দেন।" } ,
    invoke: { en: "Open your du'a by praising Al-Majid lavishly before presenting requests — the Prophet ﷺ taught that supplication begins with hamd and thana' (praise). Call on the Noble One expecting a reply worthy of His glory, not of your merit.", bn: "কিছু চাওয়ার আগে মন খুলে আল-মাজিদের প্রশংসা করে দু'আ শুরু করুন। নবী ﷺ শিখিয়েছেন, দু'আর শুরু হয় হামদ ও সানা (প্রশংসা) দিয়ে। মহান এই সত্তাকে ডাকুন এই আশা নিয়ে যে জবাব আসবে তাঁর মহিমা অনুযায়ী, আপনার যোগ্যতা অনুযায়ী নয়।" },
    quranicRefs: [
      { ref: "11:73", noteEn: "Innahu Hamidun Majid — Indeed He is Praiseworthy, Glorious (Majid); spoken of the household of Ibrahim.", noteBn: "ইন্নাহু হামিদুন মাজিদ — নিশ্চয়ই তিনি প্রশংসিত, মহিমান্বিত (মাজিদ)। কথাটি এসেছে ইবরাহিমের পরিবার প্রসঙ্গে।" },
      { ref: "85:15", noteEn: "Dhu-l-'Arshi-l-Majid — Lord of the Glorious Throne; His majd (nobility) is supreme.", noteBn: "যুল-আরশিল-মাজিদ — মহিমান্বিত আরশের অধিপতি; তাঁর মাজদ (মহত্ত্ব) সবার ঊর্ধ্বে।" },
      { ref: "85:21", noteEn: "Bal huwa Qur'anun Majid — rather it is a Glorious Quran, reflecting the majesty of its Author.", noteBn: "বাল হুওয়া কুরআনুন মাজিদ — বরং এটি মহিমান্বিত কুরআন; এতে ফুটে ওঠে যিনি এটি নাজিল করেছেন তাঁর মহিমা।" },
      { ref: "50:1", noteEn: "Qaf, wa-l-Qur'ani-l-Majid — by the Glorious Quran; the same attribute of majd.", noteBn: "কাফ, ওয়াল-কুরআনিল-মাজিদ — শপথ মহিমান্বিত কুরআনের; এখানেও সেই একই মাজদ গুণ।" }
    ]},
  { n: 66, ar: "الْوَاحِدُ", translit: "Al-Wāḥid", meanings: { en: "The One", bn: "একক", fr: "L'Unique", id: "Yang Maha Esa", ur: "یکتا", tr: "Tek Olan", ar: "الواحد بلا شريك" , zh: '獨一者', ja: '唯一無二の者', hi: 'एक', es: 'El Uno', ru: 'Единый', de: 'Der Eine', fa: 'یکتا', ms: 'Yang Maha Esa'},
    explain: { en: "Al-Wahid is the numerical One — there is only one God, no second, no partner, no assistant, no rival. The Quran (14:48) speaks of the Day when people will 'come before Allah, the One, Al-Qahhar.' This name is the foundation of tawhid (monotheism): acknowledging Al-Wahid is the first and fundamental obligation. Al-Ghazali notes that Al-Wahid guards against the subtle forms of shirk (associating partners with Allah) including making goals and fears subservient to anything other than Allah.", bn: "আল-ওয়াহিদ মানে সংখ্যায় এক। ইলাহ একজনই; তাঁর কোনো দ্বিতীয় নেই, শরিক নেই, সাহায্যকারী নেই, প্রতিদ্বন্দ্বী নেই। কুরআন (১৪:৪৮) সেই দিনের কথা বলে, যেদিন মানুষ 'আল্লাহ, আল-ওয়াহিদ, আল-কাহহারের সামনে উপস্থিত হবে।' এই নামই তাওহিদের ভিত্তি: আল-ওয়াহিদকে মেনে নেওয়াই প্রথম ও মৌলিক ফরজ। ইমাম গাজালী বলেন, আল-ওয়াহিদ নাম শিরকের (আল্লাহর সঙ্গে শরিক করা) সূক্ষ্ম রূপগুলো থেকে রক্ষা করে, যেমন নিজের লক্ষ্য ও ভয়কে আল্লাহ ছাড়া অন্য কিছুর অধীন করে ফেলা।" } ,
    hadith: { en: "When the Prophet ﷺ woke during the night he would say: 'La ilaha illallahu-l-Wahidu-l-Qahhar — there is no god but Allah, the One (Al-Wahid), the Subduer, Lord of the heavens and the earth and all between them.'", bn: "নবী ﷺ রাতে ঘুম থেকে জেগে বলতেন: 'লা ইলাহা ইল্লাল্লাহুল-ওয়াহিদুল-কাহহার — আল্লাহ ছাড়া কোনো ইলাহ নেই, তিনি এক (আল-ওয়াহিদ), মহাদমনকারী, আসমান-জমিন ও এর মাঝের সবকিছুর রব।'", src: "Sunan an-Nasa'i (al-Sunan al-Kubra); Ibn Hibban — graded sahih" },
    invoke: { en: "Direct every act of worship to Al-Wahid alone — du'a, sacrifice, hope, and fear admit no partner. When you stir at night, say as the Prophet ﷺ did: 'La ilaha illallahu-l-Wahidu-l-Qahhar', gathering your scattered heart upon the One.", bn: "প্রতিটি ইবাদত শুধু আল-ওয়াহিদের জন্য করুন। দু'আ, কুরবানি, আশা, ভয়, কোনোটিতেই কাউকে শরিক করা চলে না। রাতে ঘুম ভাঙলে নবী ﷺ-এর মতো বলুন: 'লা ইলাহা ইল্লাল্লাহুল-ওয়াহিদুল-কাহহার', আর বিক্ষিপ্ত মনকে এক আল্লাহর দিকে জড়ো করুন।" },
    quranicRefs: [
      { ref: "13:16", noteEn: "Allahu Khaliq-u kulli shay' wa Huwa-l-Wahid-ul-Qahhar — Creator of all and the One, the Subduer.", noteBn: "আল্লাহু খালিকু কুল্লি শায় ওয়া হুওয়াল-ওয়াহিদুল-কাহহার — সব কিছুর স্রষ্টা এবং আল-ওয়াহিদ, আল-কাহহার।" },
      { ref: "14:48", noteEn: "Wa barazu-llahi-l-Wahid-il-Qahhar — they stand before Allah Al-Wahid Al-Qahhar; His oneness is undeniable at the Reckoning.", noteBn: "ওয়া বারাযু লিল্লাহিল-ওয়াহিদিল-কাহহার — তারা আল্লাহ আল-ওয়াহিদ আল-কাহহারের সামনে হাজির হবে; হিসাবের দিন তাঁর একত্ব কেউ অস্বীকার করতে পারবে না।" },
      { ref: "39:4", noteEn: "Subhana-hu Huwa-llahu-l-Wahid-ul-Qahhar — Glory be to Him, He is Allah, the One, the Subduer; absolute oneness.", noteBn: "সুবহানাহু হুওয়াল্লাহুল-ওয়াহিদুল-কাহহার — তিনি পবিত্র; তিনিই আল্লাহ, আল-ওয়াহিদ, আল-কাহহার। তাঁর একত্ব নিরঙ্কুশ।" },
      { ref: "38:65", noteEn: "Qul innama ana nadhir wa ma min ilahin illa-llahu-l-Wahid-ul-Qahhar — there is no deity except Allah Al-Wahid.", noteBn: "কুল ইন্নামা আনা নাযির ওয়ামা মিন ইলাহিন ইল্লাল্লাহুল-ওয়াহিদুল-কাহহার — আল্লাহ আল-ওয়াহিদ ছাড়া কোনো উপাস্য নেই।" }
    ]},
  { n: 67, ar: "الْأَحَدُ", translit: "Al-Aḥad", meanings: { en: "The Indivisible One", bn: "অদ্বিতীয়", fr: "L'Un", id: "Yang Maha Tunggal", ur: "اکیلا", tr: "Bir Olan", ar: "الأحد الفرد" , zh: '不可分割者', ja: '唯一者', hi: 'यकता, अकेला', es: 'El Único', ru: 'Единственный', de: 'Der Einzige', fa: 'یگانه‌ی بی‌همتا', ms: 'Yang Maha Tunggal'},
    explain: { en: "Al-Ahad is uniquely applied only to Allah, denoting an indivisible, incomparable oneness that cannot be shared, divided, multiplied, or compared. While Al-Wahid is the number 'one' (which implies the possibility of a 'two'), Al-Ahad is the absolute, unique singularity that transcends counting altogether. It appears in Surah al-Ikhlas (112:1), which the Prophet said is worth one-third of the Quran. Ibn al-Qayyim says Al-Ahad is the name that most completely negates every form of polytheism.", bn: "আল-আহাদ নাম কেবল আল্লাহর জন্যই ব্যবহৃত হয়। এর অর্থ এমন একত্ব, যা অবিভাজ্য ও অতুলনীয়: তা কারও সঙ্গে ভাগ হয় না, টুকরো হয় না, বহু হয় না, কারও সঙ্গে তুলনাও চলে না। আল-ওয়াহিদ হলো সংখ্যার 'এক', যার পরে 'দুই' আসার সম্ভাবনা থাকে; আর আল-আহাদ এমন নিরঙ্কুশ, অনন্য একত্ব, যা গণনারই ঊর্ধ্বে। নামটি এসেছে সূরা আল-ইখলাসে (১১২:১), যে সূরাকে নবী ﷺ কুরআনের এক-তৃতীয়াংশের সমান বলেছেন। ইবনুল কাইয়িম বলেন, শিরকের প্রতিটি রূপকে সবচেয়ে পূর্ণভাবে নাকচ করে এই নাম।" } ,
    hadith: { en: "The Prophet ﷺ heard a man supplicate: 'O Allah, I ask You by my testifying that You are Allah, there is no god but You, Al-Ahad (the One), As-Samad...' and said he had asked Allah by His Greatest Name.", bn: "নবী ﷺ এক ব্যক্তিকে দু'আ করতে শুনলেন: 'হে আল্লাহ, আমি আপনার কাছে চাই এই সাক্ষ্যের উসিলায় যে, আপনিই আল্লাহ, আপনি ছাড়া কোনো ইলাহ নেই, আপনি আল-আহাদ (একক), আস-সামাদ...' তখন তিনি বললেন, লোকটি আল্লাহর কাছে তাঁর মহত্তম নামের উসিলায় চেয়েছে।", src: "Sunan Abi Dawud 1493; Jami' at-Tirmidhi 3475" },
    invoke: { en: "Recite Surah al-Ikhlas often — the Prophet ﷺ declared it equal to a third of the Quran, and love of it admits to Paradise. Call on Al-Ahad with the du'a he praised: 'O Allah, I ask You as I bear witness that You are Allah, al-Ahad, as-Samad...' — a plea made by His Greatest Name.", bn: "সূরা আল-ইখলাস বেশি বেশি পড়ুন। নবী ﷺ বলেছেন, এটি কুরআনের এক-তৃতীয়াংশের সমান, আর এই সূরার প্রতি ভালোবাসা জান্নাতে নিয়ে যায়। আল-আহাদকে ডাকুন সেই দু'আ দিয়ে, যার প্রশংসা নবী ﷺ করেছিলেন: 'হে আল্লাহ, আমি আপনার কাছে চাই, কারণ আমি সাক্ষ্য দিই যে আপনিই আল্লাহ, আল-আহাদ, আস-সামাদ...' এ দু'আ তাঁর ইসমে আজমের উসিলায় করা।" },
    quranicRefs: [
      { ref: "112:1", noteEn: "Qul Huwa-llahu Ahad — Say: He is Allah, Al-Ahad; the name's only Quranic appearance, distilling the entire doctrine of tawhid.", noteBn: "কুল হুওয়াল্লাহু আহাদ — বলো: তিনি আল্লাহ, আল-আহাদ। কুরআনে নামটি কেবল এখানেই এসেছে, আর এই এক আয়াতেই তাওহিদের পুরো শিক্ষার নির্যাস।" }
    ]},
  { n: 68, ar: "الصَّمَدُ", translit: "Aṣ-Ṣamad", meanings: { en: "The Eternal Refuge", bn: "অমুখাপেক্ষী", fr: "L'Absolu", id: "Yang Maha Dibutuhkan", ur: "بے نیاز", tr: "Her Şey O'na Muhtaç", ar: "المقصود في الحوائج" , zh: '自給自足者', ja: '永遠に続くもの', hi: 'बेनियाज़', es: 'El Refugio Eterno', ru: 'Самодостаточный', de: 'Die ewige Zuflucht', fa: 'پناهگاه همیشگی', ms: 'Tempat Bergantung Segala Sesuatu'},
    explain: { en: "As-Samad is one of the most profound names — the Eternal Refuge to whom all creation turns in need, who is Himself in need of nothing. The root samada means to head toward, to depend upon. Al-Samad is self-contained, self-sufficient, and the destination of all need. Surah al-Ikhlas gives both dimensions: 'Allah, As-Samad. He neither begets nor was begotten, nor is there to Him any equivalent' (112:2-4). Al-Ghazali writes that every creature in need is, in reality, turning to As-Samad whether they know it or not.", bn: "আস-সামাদ সবচেয়ে গভীর নামগুলোর একটি। তিনি সেই চিরন্তন আশ্রয়, প্রয়োজনে গোটা সৃষ্টি যাঁর দিকে ফেরে, অথচ তিনি নিজে কিছুরই মুখাপেক্ষী নন। মূল শব্দ সামাদা মানে কারও দিকে যাওয়া, কারও ওপর নির্ভর করা। আস-সামাদ স্বয়ংসম্পূর্ণ, কারও মুখাপেক্ষী নন, আর সব প্রয়োজনের শেষ ঠিকানা তিনিই। সূরা আল-ইখলাসে দুটি দিকই আছে: 'আল্লাহ আস-সামাদ। তিনি কাউকে জন্ম দেননি, তাঁকেও কেউ জন্ম দেয়নি, আর তাঁর সমতুল্য কেউ নেই' (১১২:২-৪)। ইমাম গাজালী লিখেছেন, অভাবে পড়া প্রতিটি সৃষ্টি আসলে আস-সামাদের দিকেই ফেরে, সে জানুক বা না জানুক।" },
    invoke: { en: "The two names Al-Ahad and As-Samad from Surah al-Ikhlas form the most complete declaration of tawhid. Recite this surah 3 times daily — the Prophet said it is equivalent to reciting one-third of the Quran (Bukhari 6643). When you feel needy, helpless, or looking for ultimate support, turn to As-Samad.", bn: "সূরা আল-ইখলাসের দুই নাম, আল-আহাদ ও আস-সামাদ, মিলে তাওহিদের সবচেয়ে পূর্ণ ঘোষণা। প্রতিদিন ৩ বার এই সূরা পড়ুন। নবী ﷺ বলেছেন, এটি পড়া কুরআনের এক-তৃতীয়াংশ পড়ার সমান (বুখারী ৬৬৪৩)। যখন নিজেকে অভাবী বা অসহায় লাগে, কিংবা শেষ ভরসা খোঁজেন, তখন আস-সামাদের দিকে ফিরুন।" } ,
    hadith: { en: "The Prophet ﷺ said of a man who supplicated 'You are Al-Ahad, As-Samad, who begets not nor is begotten...' that he had asked Allah by His Greatest Name, by which when He is asked He gives.", bn: "যে লোক দু'আয় বলেছিল, 'আপনি আল-আহাদ, আস-সামাদ, যিনি কাউকে জন্ম দেননি, কেউ তাঁকেও জন্ম দেয়নি...', তার সম্পর্কে নবী ﷺ বললেন: সে আল্লাহর কাছে তাঁর মহত্তম নামের উসিলায় চেয়েছে, যে নামে চাইলে তিনি দান করেন।", src: "Sunan Abi Dawud 1493; Jami' at-Tirmidhi 3475" },
    quranicRefs: [
      { ref: "112:2", noteEn: "Allahu-s-Samad — Allah is As-Samad; the entire surah then explains this name: uncreated, unbegotten, incomparable.", noteBn: "আল্লাহুস-সামাদ — আল্লাহ আস-সামাদ। সূরার বাকি অংশ এই নামেরই ব্যাখ্যা: কেউ তাঁকে সৃষ্টি করেনি, কেউ তাঁকে জন্ম দেয়নি, তাঁর কোনো তুলনা নেই।" }
    ]},
  { n: 69, ar: "الْقَادِرُ", translit: "Al-Qādir", meanings: { en: "The Capable", bn: "সর্বশক্তিমান", fr: "Le Puissant", id: "Yang Maha Kuasa", ur: "قدرت والا", tr: "Kudret Sahibi", ar: "القادر على كل شيء" , zh: '全能者', ja: '全能', hi: 'क़ुदरत वाला', es: 'El Capaz', ru: 'Могущий', de: 'Der Mächtige', fa: 'توانا', ms: 'Yang Maha Kuasa'},
    explain: { en: "Al-Qadir is the One who is capable of all things — not limited by physics, logic (from creation's perspective), time, space, or circumstance. The Quran repeatedly asserts: 'Indeed, Allah is over all things competent (Qadir).' While Al-Muqtadir emphasises actively exercising and demonstrating power, Al-Qadir emphasises the inherent and perfect capacity for power. The believer who trusts in Al-Qadir finds that no situation is hopeless, no obstacle is final, and no door is permanently closed.", bn: "আল-কাদির হলেন সেই সত্তা, যিনি সবকিছু করতে সক্ষম। পদার্থের নিয়ম, যুক্তি (সৃষ্টির দৃষ্টিতে), সময়, স্থান বা পরিস্থিতি, কিছুই তাঁকে সীমাবদ্ধ করে না। কুরআন বারবার বলে: 'নিশ্চয়ই আল্লাহ সবকিছুর ওপর ক্ষমতাবান (কাদির)।' আল-মুক্তাদির নামে জোর ক্ষমতার সক্রিয় প্রয়োগ ও প্রকাশে; আর আল-কাদির নামে জোর তাঁর নিজস্ব, পূর্ণ সামর্থ্যে। যে মুমিন আল-কাদিরের ওপর ভরসা রাখে, সে দেখে: কোনো অবস্থাই আশাহীন নয়, কোনো বাধাই শেষ কথা নয়, কোনো দরজাই চিরদিনের জন্য বন্ধ নয়।" },
    invoke: { en: "When you face what seems impossible — an illness, a debt, a door shut in your face — call upon Al-Qadir. Say 'Ya Qadir' and ask with certainty, for the One capable of all things can change any situation in an instant.", bn: "যখন এমন কিছুর সামনে পড়েন যা অসম্ভব মনে হয়, যেমন অসুখ, ঋণ, কিংবা মুখের ওপর বন্ধ হয়ে যাওয়া দরজা, তখন আল-কাদিরকে ডাকুন। 'ইয়া কাদির' বলে দৃঢ় বিশ্বাস নিয়ে চান। যিনি সবকিছু করতে সক্ষম, তিনি চোখের পলকে যেকোনো অবস্থা বদলে দিতে পারেন।" } ,
    hadith: { en: "The Prophet ﷺ taught the istikharah: 'O Allah, I seek Your decree by Your power (astaqdiruka bi-qudratika), for You are able and I am not able (fa-innaka taqdiru wa la aqdir), and You know and I know not.'", bn: "নবী ﷺ ইস্তিখারার দু'আ শিখিয়েছেন: 'হে আল্লাহ, আমি আপনার কুদরতের উসিলায় আপনার কাছে সামর্থ্য চাই (আসতাকদিরুকা বিকুদরাতিকা), কারণ আপনি সক্ষম, আমি সক্ষম নই (ফাইন্নাকা তাকদিরু ওয়া লা আকদির); আপনি জানেন, আমি জানি না।'", src: "Sahih al-Bukhari 1162" },
    quranicRefs: [
      { ref: "6:65", noteEn: "Qul Huwa-l-Qadiru 'ala an yab'atha 'alaykum 'adhaban — Say: He is Al-Qadir, able to send punishment upon you.", noteBn: "কুল হুওয়াল-কাদিরু আলা আন ইয়াবআসা আলাইকুম আযাবান — বলো: তিনি আল-কাদির, তোমাদের উপর শাস্তি পাঠাতে সক্ষম।" },
      { ref: "46:33", noteEn: "Qadirin 'ala an yuhyiya-l-mawta — He is Able to give life to the dead; nothing lies beyond His power.", noteBn: "কাদিরিন আলা আন ইউহইয়াল-মাওতা — তিনি মৃতকে জীবন দিতে সক্ষম; কিছুই তাঁর ক্ষমতার বাইরে নয়।" },
      { ref: "75:40", noteEn: "Alaysa dhalika bi-Qadirin 'ala an yuhyiya-l-mawta — Is not that One Able to give life to the dead?", noteBn: "আলাইসা যালিকা বি-কাদিরিন আলা আন ইউহইয়াল-মাওতা — সেই সত্তা কি মৃতকে জীবন দিতে সক্ষম নন?" },
      { ref: "2:20", noteEn: "Inna-llaha 'ala kulli shay'in Qadir — indeed Allah is over all things competent (Qadir).", noteBn: "ইন্নাল্লাহা আলা কুল্লি শাইইন কাদির — নিশ্চয় আল্লাহ সব কিছুতে সক্ষম (কাদির)।" }
    ]},
  { n: 70, ar: "الْمُقْتَدِرُ", translit: "Al-Muqtadir", meanings: { en: "The Omnipotent", bn: "মহাক্ষমতাবান", fr: "Le Tout-Puissant", id: "Yang Maha Berkuasa", ur: "بڑی قدرت والا", tr: "Mutlak Kudret Sahibi", ar: "التام القدرة" , zh: '掌控者', ja: '決定するもの', hi: 'बड़ी क़ुदरत वाला', es: 'El Omnipotente', ru: 'Всемогущий', de: 'Der Allvermögende', fa: 'توانای مطلق', ms: 'Yang Maha Berkuasa'},
    explain: { en: "Al-Muqtadir refers to power actively exercised in full measure — omnipotence displayed and demonstrated. The Quran (54:42) states in the context of destroyed civilisations: 'We seized them with the seizure of One Exalted in Power and Capable (Muqtadir).' This is power that cannot be defied; it carries out its will without let or hindrance. For the oppressed, this name is a source of hope; for the unjust, a warning.", bn: "আল-মুক্তাদির মানে এমন ক্ষমতা, যা পুরো মাত্রায় সক্রিয়ভাবে প্রয়োগ হয়; সর্বশক্তি, যা চোখের সামনে প্রকাশ পায়। ধ্বংস হয়ে যাওয়া জাতিগুলোর প্রসঙ্গে কুরআন (৫৪:৪২) বলে: 'আমরা তাদের পাকড়াও করেছি মহাপরাক্রমশালী, পূর্ণক্ষমতাবানের (মুক্তাদির) পাকড়াওয়ে।' এ ক্ষমতাকে কেউ রুখতে পারে না; কোনো বাধা ছাড়াই তা নিজের ইচ্ছা কার্যকর করে। মজলুমের জন্য এই নাম আশার উৎস, আর জালিমের জন্য সতর্কবার্তা।" } ,
    hadith: { en: "In the istikharah the Prophet ﷺ taught: 'astaqdiruka bi-qudratika' (I seek ability from Your power), 'for You have power and I have none (fa-innaka taqdiru wa la aqdir)' — affirming Allah's absolute, prevailing power.", bn: "ইস্তিখারায় নবী ﷺ শিখিয়েছেন: 'আসতাকদিরুকা বিকুদরাতিকা' (আমি আপনার কুদরতের উসিলায় সামর্থ্য চাই), 'কারণ ক্ষমতা আপনার আছে, আমার নেই (ফাইন্নাকা তাকদিরু ওয়া লা আকদির)'। এ দু'আয় বান্দা মেনে নেয়, আল্লাহর ক্ষমতাই নিরঙ্কুশ ও সবকিছুর ওপর প্রবল।", src: "Sahih al-Bukhari 1162" },
    invoke: { en: "When events spiral beyond your control, rest in Al-Muqtadir — every outcome lies within His perfect power. Work for the seat promised to the righteous 'in the presence of a Muqtadir King' (54:55), and ask Him to empower you for what He loves.", bn: "পরিস্থিতি হাতের বাইরে চলে গেলে আল-মুক্তাদিরের ওপর ভরসা করে নিশ্চিন্ত থাকুন; প্রতিটি পরিণতি তাঁর নিখুঁত ক্ষমতার অধীন। মুত্তাকিদের জন্য ওয়াদা করা সেই আসনের জন্য আমল করুন, যা 'মহাক্ষমতাবান মালিকের সান্নিধ্যে' (৫৪:৫৫)। আর তিনি যা ভালোবাসেন, তা করার সামর্থ্য তাঁর কাছে চান।" },
    quranicRefs: [
      { ref: "54:42", noteEn: "Akhadhna-hum akhdha 'Azizin Muqtadir — We seized them with the seizure of One Exalted, Perfect in Ability (Muqtadir).", noteBn: "আখাযনাহুম আখযা আজিযিন মুক্তাদির — আমরা তাদের পাকড়াও করেছি মহাপরাক্রমশালী, পূর্ণক্ষমতাবানের (মুক্তাদির) পাকড়াওয়ে।" },
      { ref: "54:55", noteEn: "'Inda Malikin Muqtadir — with a Sovereign, Perfect in Ability; the righteous are honoured before Him.", noteBn: "ইনদা মালিকিন মুক্তাদির — পূর্ণক্ষমতাবান এক অধিপতির সান্নিধ্যে; মুত্তাকিরা তাঁর কাছে সম্মানিত।" },
      { ref: "18:45", noteEn: "Wa kana-llahu 'ala kulli shay'in Muqtadira — Allah is ever, over all things, Perfectly Able.", noteBn: "ওয়া কানাল্লাহু আলা কুল্লি শাইইন মুক্তাদিরা — আল্লাহ সবসময়ই সবকিছুর ওপর পূর্ণক্ষমতাবান।" },
      { ref: "43:42", noteEn: "Fa-inna 'alayhim Muqtadirun — indeed We are fully Able to carry out Our will upon them.", noteBn: "ফা-ইন্না আলাইহিম মুক্তাদিরুন — নিশ্চয়ই তাদের ওপর আমাদের ইচ্ছা কার্যকর করতে আমরা পুরোপুরি সক্ষম।" }
    ]},
  { n: 71, ar: "الْمُقَدِّمُ", translit: "Al-Muqaddim", meanings: { en: "The Expediter", bn: "অগ্রসরকারী", fr: "Celui qui avance", id: "Yang Maha Mendahulukan", ur: "آگے کرنے والا", tr: "Öne Alan", ar: "المقدِّم لما يشاء" , zh: '促進者', ja: '前身せし者を支えし者', hi: 'आगे करने वाला', es: 'El que adelanta', ru: 'Приближающий', de: 'Der Voranbringende', fa: 'پیش‌دارنده', ms: 'Yang Maha Mendahulukan'},
    explain: { en: "Al-Muqaddim is the One who advances, promotes, and brings forward what He wills — in rank, time, priority, or position. This name always pairs with Al-Mu'akhkhir (the Delayer): together they express that Allah alone determines the timing and order of all events. Nothing happens before its appointed time, and nothing is delayed past its appointed time. Al-Ghazali notes that accepting this pairing liberates the servant from frustration at timing that seems wrong.", bn: "আল-মুকাদ্দিম হলেন সেই সত্তা, যিনি যা চান তা এগিয়ে দেন: মর্যাদায়, সময়ে, অগ্রাধিকারে বা অবস্থানে। এই নাম সবসময় আল-মুআখখিরের (যিনি পিছিয়ে দেন) সঙ্গে জোড়ায় আসে। দুটি নাম মিলে বোঝায়: সব ঘটনার সময় ও ক্রম ঠিক করেন একমাত্র আল্লাহ। নির্ধারিত সময়ের আগে কিছু ঘটে না, নির্ধারিত সময় পেরিয়েও কিছু পিছিয়ে থাকে না। ইমাম গাজালী বলেন, এই জোড়া মেনে নিলে বান্দা 'সময়টা ভুল হলো' ভেবে আক্ষেপ করার যন্ত্রণা থেকে মুক্তি পায়।" } ,
    hadith: { en: "In his night prayer the Prophet ﷺ would say: '...You are Al-Muqaddim (the One who brings forward) and You are Al-Mu'akhkhir (the One who delays); there is no god but You.'", bn: "রাতের নামাজে নবী ﷺ বলতেন: '...আপনিই আল-মুকাদ্দিম (অগ্রসরকারী) এবং আপনিই আল-মুআখখির (বিলম্বকারী); আপনি ছাড়া কোনো ইলাহ নেই।'", src: "Sahih al-Bukhari 1120; Sahih Muslim 771" },
    invoke: { en: "Say in tahajjud as the Prophet ﷺ did: 'Anta-l-Muqaddimu wa Anta-l-Mu'akhkhiru, la ilaha illa Anta.' Ask Al-Muqaddim to advance you toward every good — placing you in the front rows of prayer, knowledge, and sincere deeds.", bn: "তাহাজ্জুদে নবী ﷺ-এর মতো বলুন: 'আনতাল-মুকাদ্দিমু ওয়া আনতাল-মুআখখিরু, লা ইলাহা ইল্লা আনতা।' আল-মুকাদ্দিমের কাছে চান, তিনি যেন আপনাকে প্রতিটি কল্যাণের দিকে এগিয়ে দেন, নামাজ, ইলম ও খাঁটি আমলের সামনের কাতারে রাখেন।" },
    quranicRefs: [
      { ref: "16:61", noteEn: "La yasta'khiruna sa'atan wa la yastaqdimun — they can neither delay nor advance their term an hour; He alone brings forward.", noteBn: "লা ইয়াসতাখিরুনা সাআতান ওয়া লা ইয়াসতাকদিমুন — তারা তাদের নির্ধারিত সময় এক ঘণ্টাও এগিয়ে বা পিছিয়ে নিতে পারে না; একমাত্র তিনিই অগ্রসর করেন।" },
      { ref: "7:34", noteEn: "Idha ja'a ajaluhum la yasta'khiruna sa'atan wa la yastaqdimun — when the appointed term comes, none advances or delays it.", noteBn: "ইযা জাআ আজালুহুম লা ইয়াসতাখিরুনা সাআতান ওয়া লা ইয়াসতাকদিমুন — নির্ধারিত সময় এলে কেউ তা এগোতে বা পিছোতে পারে না।" },
      { ref: "6:2", noteEn: "Thumma qada ajalan wa ajalun musamman 'indahu — He decreed a term; the ordering and timing of all lies with Him.", noteBn: "সুম্মা কাদা আজালান ওয়া আজালুন মুসাম্মান ইনদাহু — তিনি এক মেয়াদ ঠিক করে দিয়েছেন; সবকিছুর ক্রম ও সময় তাঁরই হাতে।" }
    ]},
  { n: 72, ar: "الْمُؤَخِّرُ", translit: "Al-Mu'akhkhir", meanings: { en: "The Delayer", bn: "বিলম্বকারী", fr: "Celui qui recule", id: "Yang Maha Mengakhirkan", ur: "پیچھے کرنے والا", tr: "Geriye Bırakan", ar: "المؤخِّر لما يشاء" , zh: '延遲者', ja: '遠くへ押しやる遅延者', hi: 'पीछे करने वाला', es: 'El que retrasa', ru: 'Отдаляющий', de: 'Der Zurückstellende', fa: 'واپس‌دارنده', ms: 'Yang Maha Mengakhirkan'},
    explain: { en: "Al-Mu'akhkhir is the One who delays and postpones what He wills — in punishment (giving sinners time to repent), in reward (teaching patience), or in timing of events (arranging the perfect moment). This name paired with Al-Muqaddim teaches that there is no such thing as 'too early' or 'too late' in divine decree — only perfectly timed. The believer who has not received what they prayed for should trust in Al-Mu'akhkhir: the delay is wisdom.", bn: "আল-মুআখখির হলেন সেই সত্তা, যিনি যা চান তা পিছিয়ে দেন: শাস্তিতে (যাতে গুনাহগার তওবার সময় পায়), পুরস্কারে (যাতে ধৈর্য শেখে), কিংবা ঘটনার সময়ে (যাতে সবকিছু ঘটে ঠিক উপযুক্ত মুহূর্তে)। আল-মুকাদ্দিমের সঙ্গে মিলে এই নাম শেখায়: আল্লাহর ফয়সালায় 'বড্ড আগে' বা 'বড্ড দেরি' বলে কিছু নেই; সবই ঠিক সময়মতো। যে মুমিন দু'আ করে এখনো তা পায়নি, সে যেন আল-মুআখখিরের ওপর ভরসা রাখে: এই দেরির মধ্যেই আছে হিকমত।" } ,
    hadith: { en: "In his night prayer the Prophet ﷺ would say: '...You are Al-Muqaddim and You are Al-Mu'akhkhir (the One who delays whom and what He wills); there is no god but You.'", bn: "রাতের নামাজে নবী ﷺ বলতেন: '...আপনিই আল-মুকাদ্দিম এবং আপনিই আল-মুআখখির (যিনি যাকে ও যা চান পিছিয়ে দেন); আপনি ছাড়া কোনো ইলাহ নেই।'", src: "Sahih al-Bukhari 1120; Sahih Muslim 771" },
    invoke: { en: "When something you long for is delayed, trust Al-Mu'akhkhir — divine postponement is often protection, or the ripening of something better. Say 'Anta-l-Muqaddim wa Anta-l-Mu'akhkhir' and pray that your repentance is never the thing you delay.", bn: "মনের মতো কিছু আসতে দেরি হলে আল-মুআখখিরের ওপর ভরসা রাখুন। আল্লাহর দেওয়া দেরি অনেক সময় সুরক্ষা, নয়তো আরও ভালো কিছু পেকে ওঠার সময়। বলুন 'আনতাল-মুকাদ্দিম ওয়া আনতাল-মুআখখির', আর দু'আ করুন: আপনি যেন কখনো তওবায় দেরি না করেন।" },
    quranicRefs: [
      { ref: "14:42", noteEn: "Innama yu'akhkhiruhum li-yawmin tashkhasu fihi-l-absar — He only delays them to a Day; the deferral is by wisdom, not neglect.", noteBn: "ইন্নামা ইউআখখিরুহুম লি-ইয়াওমিন তাশখাসু ফিহিল-আবসার — তিনি তাদের অবকাশ দিচ্ছেন কেবল এক দিন পর্যন্ত; এই বিলম্ব হিকমতের কারণে, অবহেলায় নয়।" },
      { ref: "71:4", noteEn: "Yu'akhkhirkum ila ajalin musamma — He will delay you to an appointed term; the Delayer defers life itself.", noteBn: "ইউআখখিরকুম ইলা আজালিন মুসাম্মা — তিনি তোমাদের এক নির্ধারিত মেয়াদ পর্যন্ত অবকাশ দেবেন; আল-মুআখখির মানুষের আয়ুকেও পিছিয়ে দেন।" },
      { ref: "16:61", noteEn: "Yu'akhkhiruhum ila ajalin musamma — He defers them to a stated term, granting respite to repent.", noteBn: "ইউআখখিরুহুম ইলা আজালিন মুসাম্মা — তিনি তাদের এক নির্ধারিত মেয়াদ পর্যন্ত অবকাশ দেন, তওবার সুযোগ দিয়ে।" },
      { ref: "63:11", noteEn: "Wa lan yu'akhkhira-llahu nafsan idha ja'a ajaluha — Allah will delay no soul once its term has come.", noteBn: "ওয়া লান ইউআখখিরাল্লাহু নাফসান ইযা জাআ আজালুহা — কারও নির্ধারিত সময় এসে গেলে আল্লাহ তাকে আর অবকাশ দেন না।" }
    ]},
  { n: 73, ar: "الْأَوَّلُ", translit: "Al-Awwal", meanings: { en: "The First", bn: "সর্বপ্রথম", fr: "Le Premier", id: "Yang Maha Awal", ur: "سب سے پہلا", tr: "İlk", ar: "الأول بلا بداية" , zh: '至先者', ja: '最初', hi: 'सबसे पहला', es: 'El Primero', ru: 'Первый', de: 'Der Erste', fa: 'نخستین', ms: 'Yang Maha Awal'},
    explain: { en: "Al-Awwal is the First with no beginning before Him — He existed before time, before space, before the very concept of 'before.' Quran 57:3 presents four complementary names: 'He is Al-Awwal and Al-Akhir, Az-Zahir and Al-Batin' — the First, the Last, the Manifest, the Hidden. The Prophet (peace be upon him) used this verse in his bedtime supplication, saying: 'O Allah, You are Al-Awwal: there is nothing before You.'", bn: "আল-আওয়াল হলেন সেই প্রথম, যাঁর আগে কোনো শুরু নেই। সময়ের আগে, স্থানের আগে, এমনকি 'আগে' ধারণাটিরও আগে তিনি ছিলেন। কুরআন ৫৭:৩-এ একসঙ্গে চারটি নাম এসেছে, যেগুলো একটি আরেকটির পরিপূরক: 'তিনিই আল-আওয়াল ও আল-আখির, আজ-জাহির ও আল-বাতিন', অর্থাৎ প্রথম, শেষ, প্রকাশ্য ও গুপ্ত। নবী ﷺ ঘুমানোর দু'আয় এই আয়াত ধরে বলতেন: 'হে আল্লাহ, আপনিই আল-আওয়াল; আপনার আগে কিছু নেই।'" },
    hadith: { en: "O Allah, You are the First (Al-Awwal): there is nothing before You. And You are the Last (Al-Akhir): there is nothing after You. And You are the Manifest (Az-Zahir): there is nothing above You. And You are the Hidden (Al-Batin): there is nothing beyond You.", bn: "হে আল্লাহ, আপনি আল-আওয়াল: আপনার আগে কিছু নেই। আপনি আল-আখির: আপনার পরে কিছু নেই। আপনি আজ-জাহির: আপনার উপরে কিছু নেই। আপনি আল-বাতিন: আপনার ওপারে কিছু নেই।", src: "Sahih Muslim 2713" } ,
    invoke: { en: "Say before sleep as the Prophet ﷺ did: 'You are Al-Awwal — nothing is before You.' Put the First first in your day: let fajr, dhikr, and His right precede every other claim on your time.", bn: "ঘুমের আগে নবী ﷺ-এর মতো বলুন: 'আপনিই আল-আওয়াল, আপনার আগে কিছু নেই।' দিনেও প্রথম সত্তাকেই প্রথমে রাখুন: ফজর, জিকির আর তাঁর হক যেন আপনার সময়ের ওপর অন্য সব দাবির আগে আসে।" },
    quranicRefs: [
      { ref: "57:3", noteEn: "Huwa-l-Awwal wa-l-Akhir wa-z-Zahir wa-l-Batin — the four complementary names; Al-Awwal: nothing before Him.", noteBn: "হুওয়াল-আওয়ালু ওয়াল-আখিরু ওয়াজ-জাহিরু ওয়াল-বাতিনু — চারটি পরিপূরক নাম; আল-আওয়াল: তাঁর আগে কিছু নেই।" }
    ]},
  { n: 74, ar: "الْآخِرُ", translit: "Al-Ākhir", meanings: { en: "The Last", bn: "সর্বশেষ", fr: "Le Dernier", id: "Yang Maha Akhir", ur: "سب سے آخر", tr: "Son", ar: "الآخر بلا نهاية" , zh: '末後者', ja: '最後', hi: 'सबसे आख़िरी', es: 'El Último', ru: 'Последний', de: 'Der Letzte', fa: 'واپسین', ms: 'Yang Maha Akhir'},
    explain: { en: "Al-Akhir is the Last with no end after Him — He will remain when all creation has ceased. The Quran (55:26-27) declares: 'Whoever is on [the earth] will perish, and the Face of your Lord of Majesty and Honor will remain.' The pairing with Al-Awwal is perfect: what existed without beginning will persist without end. This name is a source of comfort: even after death, the soul returns to Al-Akhir, and at the end of time, only He remains.", bn: "আল-আখির হলেন সেই শেষ, যাঁর পরে আর কোনো শেষ নেই। গোটা সৃষ্টি ফুরিয়ে গেলেও তিনি থাকবেন। কুরআন (৫৫:২৬-২৭) ঘোষণা করে: '(পৃথিবীতে) যা কিছু আছে সবই ধ্বংস হবে; থেকে যাবে শুধু আপনার রবের চেহারা, যিনি মহিমা ও সম্মানের অধিকারী।' আল-আওয়ালের সঙ্গে এই জোড়া নিখুঁত: যিনি শুরু ছাড়াই ছিলেন, তিনি থাকবেন শেষ ছাড়াই। এই নামে আছে সান্ত্বনা: মৃত্যুর পরও রুহ ফিরে যায় আল-আখিরের কাছে, আর সময়ের শেষে কেবল তিনিই থাকবেন।" } ,
    hadith: { en: "The Prophet ﷺ would say at bedtime: 'You are Al-Awwal, there is nothing before You; and You are Al-Akhir (the Last), there is nothing after You.'", bn: "নবী ﷺ ঘুমানোর সময় বলতেন: 'আপনি আল-আউয়াল (প্রথম), আপনার পূর্বে কিছু নেই; আর আপনি আল-আখির (সর্বশেষ), আপনার পরে কিছু নেই।'", src: "Sahih Muslim 2713" },
    invoke: { en: "Say 'You are Al-Akhir — nothing is after You' in the night du'a, and when losses pile up, remember that everything ends except Him. Invest in the only relationship that outlasts all things — 'what is with Allah is everlasting' (16:96).", bn: "রাতের দু'আয় বলুন: 'আপনিই আল-আখির, আপনার পরে কিছু নেই।' একের পর এক ক্ষতি জমতে থাকলে মনে রাখুন, তিনি ছাড়া সবকিছুরই শেষ আছে। তাই সেই একটি সম্পর্কেই বিনিয়োগ করুন, যা সবকিছুর পরেও টিকে থাকে: 'আল্লাহর কাছে যা আছে, তা-ই স্থায়ী' (১৬:৯৬)।" },
    quranicRefs: [
      { ref: "57:3", noteEn: "Huwa-l-Awwal wa-l-Akhir — Al-Akhir: nothing after Him; when all creation ends He remains, the Last without end.", noteBn: "হুওয়াল-আওয়ালু ওয়াল-আখিরু — আল-আখির: তাঁর পরে কিছু নেই। সমস্ত সৃষ্টি শেষ হলেও তিনি থাকেন; তিনিই শেষ, যাঁর কোনো সমাপ্তি নেই।" }
    ]},
  { n: 75, ar: "الظَّاهِرُ", translit: "Aẓ-Ẓāhir", meanings: { en: "The Manifest", bn: "প্রকাশ্য", fr: "L'Apparent", id: "Yang Maha Nyata", ur: "ظاہر", tr: "Aşikâr Olan", ar: "الظاهر فوق كل شيء" , zh: '明显者', ja: 'すべてを勝利に導くもの', hi: 'ज़ाहिर', es: 'El Manifiesto', ru: 'Явный', de: 'Der Offenbare', fa: 'آشکار', ms: 'Yang Maha Nyata'},
    explain: { en: "Az-Zahir is the Manifest — He is known and evident through His signs, creation, and divine attributes manifested everywhere. The heavens, earth, the human body, and every phenomenon are signs (ayat) pointing to Az-Zahir. Yet He is also Al-Batin (the Hidden), transcending and existing beyond all that is manifest. This pair teaches that evidence of Allah is everywhere (zahir) yet His essence remains beyond our grasp (batin).", bn: "আজ-জাহির মানে প্রকাশ্য। তাঁর নিদর্শন, তাঁর সৃষ্টি আর সবখানে ফুটে থাকা তাঁর গুণাবলির মধ্য দিয়ে তিনি পরিচিত ও সুস্পষ্ট। আকাশ, পৃথিবী, মানুষের দেহ, প্রতিটি ঘটনা, সবই আয়াত (নিদর্শন), যা আজ-জাহিরের দিকে ইশারা করে। আবার তিনিই আল-বাতিন (গুপ্ত); প্রকাশ্য সবকিছুর ঊর্ধ্বে, সবকিছুর অতীত। এই জোড়া শেখায়: আল্লাহর প্রমাণ সবখানে (জাহির), অথচ তাঁর সত্তা আমাদের বোঝার নাগালের বাইরে (বাতিন)।" } ,
    hadith: { en: "The Prophet ﷺ would say: 'You are Az-Zahir (the Manifest), there is nothing above You; and You are Al-Batin, there is nothing beneath You.'", bn: "নবী ﷺ বলতেন: 'আপনি আজ-জাহির (প্রকাশ্য), আপনার ঊর্ধ্বে কিছু নেই; আর আপনি আল-বাতিন (গুপ্ত), আপনার নিচে কিছু নেই।'", src: "Sahih Muslim 2713" },
    invoke: { en: "Say 'You are Az-Zahir — nothing is above You', and read His manifest signs in the sky, the alternation of night and day, and your own body. When doubt whispers, step outside and let creation testify to the Manifest.", bn: "বলুন: 'আপনিই আজ-জাহির, আপনার উপরে কিছু নেই।' তারপর আকাশে, দিন-রাতের পালাবদলে আর নিজের দেহে তাঁর প্রকাশ্য নিদর্শনগুলো পড়ুন। মনে সন্দেহের কুমন্ত্রণা এলে একটু বাইরে গিয়ে দাঁড়ান; সৃষ্টিই সাক্ষ্য দেবে প্রকাশ্য সত্তার।" },
    quranicRefs: [
      { ref: "57:3", noteEn: "Huwa-z-Zahir — He is Az-Zahir; His signs fill creation, making Him the most manifest of the manifest.", noteBn: "হুওয়াজ-জাহিরু — তিনি আজ-জাহির। তাঁর নিদর্শনে সৃষ্টি ভরা; তাই প্রকাশ্য সবকিছুর মধ্যে তিনিই সবচেয়ে প্রকাশ্য।" }
    ]},
  { n: 76, ar: "الْبَاطِنُ", translit: "Al-Bāṭin", meanings: { en: "The Hidden", bn: "গুপ্ত", fr: "Le Caché", id: "Yang Maha Tersembunyi", ur: "پوشیدہ", tr: "Gizli Olan", ar: "العالم بالخفايا" , zh: '隱微者', ja: '隠されし者', hi: 'छुपा हुआ', es: 'El Oculto', ru: 'Скрытый', de: 'Der Verborgene', fa: 'نهان', ms: 'Yang Maha Tersembunyi'},
    explain: { en: "Al-Batin is the Hidden — His essence transcends all perception and conceptualisation. No eye has seen Him, no mind has encompassed Him, no description can adequately capture Him. Yet Al-Batin is not distant: He is closer to the servant than their jugular vein (Quran 50:16). The pairing Az-Zahir/Al-Batin captures the paradox of divine immanence and transcendence: everywhere manifest in His signs, yet transcending all comprehension in His essence.", bn: "আল-বাতিন মানে গুপ্ত। তাঁর সত্তা সব উপলব্ধি ও কল্পনার ঊর্ধ্বে। কোনো চোখ তাঁকে দেখেনি, কোনো মন তাঁকে আয়ত্ত করতে পারেনি, কোনো বর্ণনা তাঁকে পুরোপুরি ধরতে পারে না। তবু আল-বাতিন দূরে নন: তিনি বান্দার গলার শিরার চেয়েও কাছে (কুরআন ৫০:১৬)। আজ-জাহির ও আল-বাতিনের জোড়ায় ধরা পড়ে এক আপাত-বৈপরীত্য: তিনি কাছেও, আবার সবকিছুর ঊর্ধ্বেও। নিদর্শনে তিনি সবখানে প্রকাশ্য, অথচ সত্তায় সব বোঝার অতীত।" } ,
    hadith: { en: "The Prophet ﷺ would supplicate: 'You are Az-Zahir, there is nothing above You; and You are Al-Batin (the Hidden), there is nothing beneath You. Settle our debt and free us from want.'", bn: "নবী ﷺ দু'আ করতেন: 'আপনি আজ-জাহির, আপনার ঊর্ধ্বে কিছু নেই; আর আপনি আল-বাতিন (গুপ্ত), আপনার নিচে কিছু নেই। আমাদের ঋণ শোধ করে দিন, অভাব থেকে মুক্ত করুন।'", src: "Sahih Muslim 2713" },
    invoke: { en: "Say 'You are Al-Batin — nothing is beyond You', and entrust to the Hidden the secrets and pains you can tell no one. He is nearer to you than your jugular vein (50:16); whisper to Him what you cannot say aloud.", bn: "বলুন: 'আপনিই আল-বাতিন, আপনার অগোচরে কিছু নেই।' যে গোপন কথা আর কষ্ট কাউকে বলা যায় না, তা সঁপে দিন সেই গুপ্ত সত্তার কাছে। তিনি আপনার গলার শিরার চেয়েও কাছে (৫০:১৬); যা জোরে বলতে পারেন না, তা চুপিচুপি তাঁকে বলুন।" },
    quranicRefs: [
      { ref: "57:3", noteEn: "Huwa-l-Batin — He is Al-Batin; despite being Manifest, His essence remains beyond all grasp — the Hidden.", noteBn: "হুওয়াল-বাতিনু — তিনি আল-বাতিন। প্রকাশ্য হয়েও তাঁর সত্তা সবার নাগালের বাইরে; তিনিই গুপ্ত।" }
    ]},
  { n: 77, ar: "الْوَالِي", translit: "Al-Wālī", meanings: { en: "The Governor", bn: "সর্বময় কর্তা", fr: "Le Gérant", id: "Yang Maha Memerintah", ur: "حاکم و والی", tr: "İşleri Yöneten", ar: "المتولي للأمور" , zh: '保護的朋友', ja: '後援者', hi: 'हाकिम और कारसाज़', es: 'El Gobernante', ru: 'Правитель', de: 'Der Lenker', fa: 'سرپرست و فرمانروا', ms: 'Yang Maha Memerintah'},
    explain: { en: "Al-Wali (Governor) is the One who has complete authority over and governs all of creation — the universe operates according to His administration, and nothing falls outside His governance. This differs from Al-Waliyy (the Protecting Friend, name 55): Al-Wali is governance and sovereignty, while Al-Waliyy is friendship and protection. The Quran (13:11) states: 'Allah does not change a people's condition until they change what is within themselves' — showing that Al-Wali's governance is responsive to human choices.", bn: "আল-ওয়ালি (পরিচালক) হলেন সেই সত্তা, গোটা সৃষ্টির ওপর যাঁর পূর্ণ কর্তৃত্ব, যিনি সবকিছু পরিচালনা করেন। মহাবিশ্ব চলে তাঁরই ব্যবস্থাপনায়; তাঁর শাসনের বাইরে কিছুই নেই। এই নাম আল-ওয়ালিয়্য (অভিভাবক বন্ধু, ৫৫ নম্বর নাম) থেকে আলাদা: আল-ওয়ালি মানে শাসন ও সার্বভৌমত্ব, আর আল-ওয়ালিয়্য মানে বন্ধুত্ব ও সুরক্ষা। কুরআন (১৩:১১) বলে: 'আল্লাহ কোনো জাতির অবস্থা বদলান না, যতক্ষণ না তারা নিজেদের ভেতরের অবস্থা বদলায়।' অর্থাৎ আল-ওয়ালির পরিচালনা মানুষের নিজের বেছে নেওয়ার প্রতিও সাড়া দেয়।" } ,
    invoke: { en: "Hand the management of your affairs to Al-Wali, the true Governor, when those in charge fail you or your responsibilities exceed your strength. Ask Him to govern your household, work, and heart with His gentle administration.", bn: "যাদের হাতে দায়িত্ব, তারা যখন আপনাকে নিরাশ করে, কিংবা দায়িত্বের ভার আপনার সাধ্য ছাড়িয়ে যায়, তখন নিজের সব বিষয় সঁপে দিন আল-ওয়ালির হাতে; তিনিই প্রকৃত পরিচালক। দু'আ করুন, তিনি যেন তাঁর কোমল ব্যবস্থাপনায় আপনার পরিবার, কাজ ও অন্তর পরিচালনা করেন।" },
    quranicRefs: [
      { ref: "13:11", noteEn: "Wa ma lahum min dunihi min wal — they have no governor or protector besides Him; all authority is His.", noteBn: "ওয়া মা লাহুম মিন দুনিহি মিন ওয়াল — তিনি ছাড়া তাদের কোনো অভিভাবক বা রক্ষক নেই; সমস্ত কর্তৃত্ব তাঁর।" },
      { ref: "42:9", noteEn: "Fa-llahu Huwa-l-Waliyy — Allah, He alone is the Protecting Guardian who governs His creation's affairs.", noteBn: "ফাল্লাহু হুওয়াল-ওয়ালিয়্যু — আল্লাহই একমাত্র অভিভাবক, যিনি সৃষ্টির সব বিষয় পরিচালনা করেন।" },
      { ref: "42:28", noteEn: "Wa Huwa-l-Waliyy-ul-Hamid — He is the Protector, the Praiseworthy, who sends mercy and manages all.", noteBn: "ওয়া হুওয়াল-ওয়ালিয়্যুল-হামিদ — তিনি অভিভাবক, প্রশংসিত, যিনি রহমত পাঠান ও সব পরিচালনা করেন।" },
      { ref: "4:45", noteEn: "Wa kafa bi-llahi Waliyya — Allah suffices as a Protector and Governor over His servants.", noteBn: "ওয়া কাফা বিল্লাহি ওয়ালিয়্যা — অভিভাবক ও পরিচালক হিসেবে আল্লাহই যথেষ্ট।" }
    ]},
  { n: 78, ar: "الْمُتَعَالِي", translit: "Al-Mutaʿālī", meanings: { en: "The Most Exalted", bn: "সর্বোন্নত", fr: "Le Sublime", id: "Yang Maha Tinggi Derajat", ur: "سب سے برتر", tr: "Pek Yüce Olan", ar: "المتعالي عن النقائص" , zh: '至高者', ja: '自己を高揚するもの', hi: 'सबसे बरतर', es: 'El Excelso', ru: 'Всевышний', de: 'Der Hocherhabene', fa: 'برتر از همه', ms: 'Yang Maha Tinggi Darjat-Nya'},
    explain: { en: "Al-Muta'ali is the One who is Most Exalted, supremely above all limitations, defects, and comparisons — far beyond what any mind can imagine or any creation can resemble. The Quran (13:9) places Al-Muta'ali after Al-Kabir, showing escalating ascent. Al-Ghazali notes that Al-'Aliyy refers to transcendence in essence; Al-Muta'ali refers to transcendence that is continuously and actively maintained — He is always becoming 'more exalted' in relation to whatever is being described.", bn: "আল-মুতাআলি হলেন সর্বোচ্চ, সব সীমাবদ্ধতা, ত্রুটি ও তুলনার বহু ঊর্ধ্বে। কোনো মন তাঁকে কল্পনায় আনতে পারে না, কোনো সৃষ্টি তাঁর মতো হতে পারে না। কুরআন (১৩:৯) আল-মুতাআলিকে এনেছে আল-কাবিরের পরে, যেন উচ্চতা ধাপে ধাপে আরও বাড়ছে। ইমাম গাজালী বলেন, আল-আলিয়্য বোঝায় সত্তাগত উচ্চতা; আর আল-মুতাআলি বোঝায় এমন উচ্চতা, যা নিরন্তর ও সক্রিয়ভাবে বজায় থাকে। তাঁর সম্পর্কে যা-ই বলা হোক, তিনি সবসময় তার চেয়েও 'বেশি উঁচু'।" } ,
    invoke: { en: "Exalt Al-Muta'ali above every deficiency and every limited description creatures assign to Him. When the arrogant loom large, remember that the Most Exalted is above them all — and raise your ambitions in du'a accordingly, for you are asking the Highest.", bn: "সৃষ্টি তাঁর প্রতি যত ত্রুটি আর সীমিত বর্ণনা আরোপ করে, সেসবের ঊর্ধ্বে আল-মুতাআলির পবিত্রতা ঘোষণা করুন। দাম্ভিকদের যখন খুব বড় মনে হয়, মনে রাখবেন, সর্বোন্নত সত্তা তাদের সবার ঊর্ধ্বে। তাই দু'আয় আপনার চাওয়াও বড় করুন; আপনি তো চাইছেন সর্বোচ্চ সত্তার কাছে।" },
    quranicRefs: [
      { ref: "13:9", noteEn: "'Alimu-l-ghaybi wa-sh-shahadati-l-Kabiru-l-Muta'al — the Great, the Most Exalted (Al-Muta'al); the name appears directly.", noteBn: "আলিমুল-গাইবি ওয়াশ-শাহাদাতিল-কাবিরুল-মুতাআল — অদৃশ্য ও দৃশ্যের জ্ঞাতা, মহান, সর্বোন্নত (আল-মুতাআল); নামটি সরাসরি এসেছে।" },
      { ref: "20:114", noteEn: "Fa-Ta'ala-llahu-l-Maliku-l-Haqq — Exalted is Allah, the Sovereign, the Truth, above all deficiency.", noteBn: "ফা-তাআলাল্লাহুল-মালিকুল-হাক্ক — সুমহান আল্লাহ, তিনিই প্রকৃত অধিপতি; সব ত্রুটির ঊর্ধ্বে।" },
      { ref: "23:92", noteEn: "'Alimi-l-ghaybi wa-sh-shahadati fa-Ta'ala 'amma yushrikun — Exalted far above what they associate with Him.", noteBn: "আলিমিল-গাইবি ওয়াশ-শাহাদাতি ফা-তাআলা আম্মা ইউশরিকুন — তারা যা শরিক করে তার বহু ঊর্ধ্বে তিনি।" },
      { ref: "27:63", noteEn: "Ta'ala-llahu 'amma yushrikun — High is Allah above the partners they ascribe.", noteBn: "তাআলাল্লাহু আম্মা ইউশরিকুন — তারা যা শরিক করে তার ঊর্ধ্বে আল্লাহ সমুন্নত।" }
    ]},
  { n: 79, ar: "الْبَرُّ", translit: "Al-Barr", meanings: { en: "The Source of Goodness", bn: "পরম উপকারী", fr: "Le Bon", id: "Yang Maha Baik", ur: "نیکی والا", tr: "İyilik Sahibi", ar: "كثير الإحسان" , zh: '至善者', ja: '最も親切で正しい者', hi: 'भलाई करने वाला', es: 'La Fuente de todo bien', ru: 'Источник добра', de: 'Der Quell alles Guten', fa: 'سرچشمه‌ی نیکی', ms: 'Yang Maha Melimpahkan Kebaikan'},
    explain: { en: "Al-Barr is the Source of all goodness, kindness, and beneficence — His goodness is inherent to His being, not a response to external factors. The Quran (52:28) has the people of paradise say: 'We used to supplicate to Him before; He is Al-Barr, Al-Rahim.' This name encompasses both tenderness (birr) and righteousness — the goodness that flows outward to all creation. Ibn al-Qayyim notes that the righteous (abrar) take their name from this divine attribute.", bn: "আল-বার্র হলেন সব কল্যাণ, দয়া ও অনুগ্রহের উৎস। তাঁর কল্যাণ তাঁর সত্তারই গুণ, বাইরের কোনো কারণের জবাব নয়। কুরআনে (৫২:২৮) জান্নাতবাসীরা বলে: 'আমরা আগে থেকেই তাঁকে ডাকতাম; তিনিই আল-বার্র, আর-রাহিম।' এই নামে আছে কোমলতা (বিরর) আর সততা দুটোই; এমন কল্যাণ, যা গোটা সৃষ্টির দিকে বয়ে যায়। ইবনুল কাইয়িম বলেন, নেককারদের নাম 'আবরার' এসেছে আল্লাহর এই গুণ থেকেই।" } ,
    invoke: { en: "The people of Paradise will say: 'We used to call upon Him before; indeed He is Al-Barr, Ar-Rahim' (52:28) — so call on Al-Barr now for goodness in both worlds. Practise birr yourself, especially toward your parents, for Allah loves in His servants the quality His Name proclaims.", bn: "জান্নাতবাসীরা বলবে: 'আমরা আগে থেকেই তাঁকে ডাকতাম; নিশ্চয়ই তিনি আল-বার্র, আর-রাহিম' (৫২:২৮)। তাই দুনিয়া ও আখিরাতের কল্যাণের জন্য এখনই আল-বার্রকে ডাকুন। নিজেও বিরর (সদাচার) চর্চা করুন, বিশেষ করে মা-বাবার প্রতি। আল্লাহ তাঁর বান্দাদের মধ্যে সেই গুণ ভালোবাসেন, যা তাঁর নাম ঘোষণা করে।" },
    quranicRefs: [
      { ref: "52:28", noteEn: "Inna-hu Huwa-l-Barr-ur-Rahim — He is Al-Barr and Ar-Rahim; the people of Paradise acknowledge His goodness.", noteBn: "ইন্নাহু হুওয়াল-বার্রুর-রাহিম — তিনি আল-বার্র ও আর-রাহিম; জান্নাতের অধিবাসীরা তাঁর কল্যাণ স্বীকার করে।" }
    ]},
  { n: 80, ar: "التَّوَّابُ", translit: "At-Tawwāb", meanings: { en: "The Acceptor of Repentance", bn: "তাওবা কবুলকারী", fr: "L'Accueillant au repentir", id: "Yang Maha Penerima Tobat", ur: "توبہ قبول کرنے والا", tr: "Tövbeleri Kabul Eden", ar: "القابل للتوبة" , zh: '悔罪的接受者', ja: '還ること', hi: 'तौबा क़बूल करने वाला', es: 'El Aceptador del arrepentimiento', ru: 'Принимающий покаяния', de: 'Der die Reue Annehmende', fa: 'پذیرنده‌ی توبه', ms: 'Yang Maha Penerima Taubat'},
    explain: { en: "At-Tawwab is the One who perpetually, repeatedly turns in acceptance toward the repentant servant — and the servant's tawbah (repentance) is only possible because Allah first turns toward them. The Quran (49:12) says: 'Indeed, Allah is At-Tawwab, the Merciful.' Al-Ghazali notes the reciprocal nature: Allah's 'turning' (tawbah in its divine sense) towards the servant enables the servant's 'turning' (tawbah in the human sense) towards Allah. This is one of the most intimate divine-human interactions.", bn: "আত-তাওওয়াব হলেন সেই সত্তা, যিনি তওবাকারী বান্দার দিকে বারবার, অবিরাম কবুলের দৃষ্টিতে ফেরেন। বান্দা তওবা করতে পারে কেবল এই কারণে যে আল্লাহ আগে তার দিকে ফেরেন। কুরআন (৪৯:১২) বলে: 'নিশ্চয়ই আল্লাহ আত-তাওওয়াব, পরম দয়ালু।' ইমাম গাজালী এই পারস্পরিক সম্পর্কের কথা বলেন: বান্দার দিকে আল্লাহর 'ফেরা' (আল্লাহর ক্ষেত্রে তওবার অর্থ) বান্দাকে আল্লাহর দিকে 'ফেরার' (মানুষের ক্ষেত্রে তওবার অর্থ) সামর্থ্য দেয়। আল্লাহ ও বান্দার মধ্যে এটি সবচেয়ে অন্তরঙ্গ সম্পর্কগুলোর একটি।" },
    hadith: { en: "Allah rejoices more at the repentance of His servant when he repents than one of you would rejoice if he were on his riding camel in the wilderness and it strayed from him, and he despaired of finding it, then it came to him.", bn: "বান্দা যখন তওবা করে, আল্লাহ তাতে এত খুশি হন যে তোমাদের কেউও ততটা খুশি হয় না, যখন মরুভূমিতে তার সওয়ারির উট হারিয়ে যায়, সে তা ফিরে পাওয়ার আশা ছেড়ে দেয়, তারপর উটটি নিজেই তার কাছে ফিরে আসে।", src: "Sahih al-Bukhari 6309; Sahih Muslim 2747" },
    invoke: { en: "When seeking repentance, say: 'Allahumma Anta At-Tawwab Al-Rahim, fa-tub 'alayy' (O Allah, You are At-Tawwab, the Most Merciful — so turn to me in repentance). The Prophet (peace be upon him) said that Allah rejoices more at a servant's repentance than a man who finds his lost camel in the desert (Bukhari 6309).", bn: "তওবা করার সময় বলুন: 'আল্লাহুম্মা আনতাত-তাওওয়াবুর-রাহিম, ফাতুব আলাইয়্যা' (হে আল্লাহ, আপনিই আত-তাওওয়াব, পরম দয়ালু; তাই আমার তওবা কবুল করুন)। নবী ﷺ বলেছেন, মরুভূমিতে হারানো উট ফিরে পেয়ে মানুষ যতটা খুশি হয়, বান্দার তওবায় আল্লাহ তার চেয়েও বেশি খুশি হন (বুখারী ৬৩০৯)।" } ,
    quranicRefs: [
      { ref: "2:37", noteEn: "Fa-taba-llahu alayhi... Inna-hu Huwa-t-Tawwab-ur-Rahim — Allah relented toward Adam; the first instance of At-Tawwab in human history.", noteBn: "ফাতাবাল্লাহু আলায়হি... ইন্নাহু হুওয়াত-তাওওয়াবুর-রাহিম — আল্লাহ আদমের তওবা কবুল করলেন; মানব ইতিহাসে আত-তাওওয়াব নামের প্রথম প্রকাশ।" },
      { ref: "2:54", noteEn: "Moses commands his people to repent... Inna-hu Huwa-t-Tawwab-ur-Rahim — collective repentance is accepted.", noteBn: "মূসা তাঁর কওমকে তওবার আদেশ দেন... ইন্নাহু হুওয়াত-তাওওয়াবুর-রাহিম — গোটা জাতির সম্মিলিত তওবাও কবুল হয়।" },
      { ref: "2:128", noteEn: "Ibrahim and Ismail: Wa tub alayna, Inna-ka Anta-t-Tawwab-ur-Rahim — the prophet-patriarch invokes At-Tawwab.", noteBn: "ইব্রাহিম ও ইসমাইল: ওয়া তুব আলায়না, ইন্নাকা আনতাত-তাওওয়াবুর-রাহিম — নবী ও আদিপিতা ইব্রাহিম আত-তাওওয়াবকে ডাকেন।" },
      { ref: "49:12", noteEn: "Wa tubu ila-llahi jami'an... Inna-llaha Tawwab-un Rahim — repent to Allah together; a communal invitation.", noteBn: "ওয়া তুবু ইলাল্লাহি জামিআন... ইন্নাল্লাহা তাওওয়াবুন রাহিম — সবাই মিলে আল্লাহর কাছে তওবা করো; সবার প্রতি একসঙ্গে আহ্বান।" },
      { ref: "110:3", noteEn: "Wa-staghfir-hu, inna-hu kana Tawwaba — seek His forgiveness; He has been At-Tawwab; even the Prophet is commanded to seek tawbah.", noteBn: "ওয়াস্তাগফিরহু, ইন্নাহু কানা তাওওয়াবা — তাঁর কাছে ক্ষমা চাও; তিনি সবসময়ই তাওওয়াব। আল্লাহ এমনকি নবীকেও তওবার আদেশ দিয়েছেন।" }
    ]},
  { n: 81, ar: "الْمُنْتَقِمُ", translit: "Al-Muntaqim", meanings: { en: "The Avenger", bn: "প্রতিশোধগ্রহণকারী", fr: "Le Vengeur", id: "Yang Maha Pembalas", ur: "بدلہ لینے والا", tr: "Suçluları Cezalandıran", ar: "المنتقم من العصاة" , zh: '復仇者', ja: '復讐せし者', hi: 'बदला लेने वाला', es: 'El Vengador', ru: 'Карающий', de: 'Der Vergeltende', fa: 'انتقام‌گیرنده', ms: 'Yang Maha Membalas'},
    explain: { en: "Al-Muntaqim is the Avenger who exacts full retribution on those who persist in oppression and transgression. This name should not be misunderstood as vengeful in a petty sense; divine intiqam (retribution) is the just response to crimes against Allah's servants and divine rights. The Quran (32:22) says: 'And who is more unjust than one who is reminded of the signs of his Lord, then turns away? Indeed, We will take retribution from the criminals.' This name assures the oppressed that justice will prevail.", bn: "আল-মুনতাকিম সেই প্রতিশোধগ্রহণকারী, যিনি জুলুম ও সীমালঙ্ঘনে অটল লোকদের কাছ থেকে পুরো প্রতিফল আদায় করেন। এ নামকে তুচ্ছ অর্থের প্রতিহিংসা ভেবে ভুল বোঝা ঠিক নয়। আল্লাহর ইনতিকাম (প্রতিশোধ) হলো তাঁর বান্দাদের বিরুদ্ধে অপরাধ আর আল্লাহর হক নষ্ট করার ন্যায্য জবাব। কুরআন (৩২:২২) বলে: 'যাকে তার রবের আয়াত দিয়ে উপদেশ দেওয়া হলো, তারপরও সে মুখ ফিরিয়ে নিল, তার চেয়ে বড় জালিম আর কে? নিশ্চয়ই আমরা অপরাধীদের কাছ থেকে প্রতিশোধ নেব।' এই নাম মজলুমদের আশ্বাস দেয়: শেষ পর্যন্ত ন্যায়বিচারই জয়ী হবে।" } ,
    invoke: { en: "When wronged beyond any earthly remedy, hand the oppressor's file to Al-Muntaqim — 'Allah is Mighty, Owner of Retribution' (3:4) — and free your heart from consuming rage. Let this Name also warn your own soul: abandon sins before the seizure comes.", bn: "দুনিয়ায় কোনো প্রতিকার নেই, এমন জুলুমের শিকার হলে জালিমের মামলাটা আল-মুনতাকিমের হাতে তুলে দিন; 'আল্লাহ পরাক্রমশালী, প্রতিশোধ গ্রহণকারী' (৩:৪)। তারপর ভেতর পুড়িয়ে দেওয়া রাগ থেকে মনকে মুক্ত করুন। এই নাম নিজের নফসের জন্যও সতর্কবার্তা হোক: পাকড়াও আসার আগেই গুনাহ ছেড়ে দিন।" },
    quranicRefs: [
      { ref: "32:22", noteEn: "Inna mina-l-mujrimina Muntaqimun — Indeed We will take retribution from the criminals who turn away.", noteBn: "ইন্না মিনাল-মুজরিমিনা মুনতাকিমুন — যে অপরাধীরা মুখ ফিরিয়ে নেয়, নিশ্চয়ই আমরা তাদের কাছ থেকে প্রতিশোধ নেব।" },
      { ref: "43:41", noteEn: "Fa-inna minhum Muntaqimun — We will surely exact retribution from them.", noteBn: "ফা-ইন্না মিনহুম মুনতাকিমুন — অবশ্যই আমরা তাদের থেকে প্রতিশোধ নেব।" },
      { ref: "44:16", noteEn: "Yawma nabtishu-l-batshata-l-kubra inna Muntaqimun — the Day We seize with the great seizure, indeed We will avenge.", noteBn: "ইয়াওমা নাবতিশুল-বাতশাতাল-কুবরা ইন্না মুনতাকিমুন — যেদিন আমরা মহা পাকড়াওয়ে পাকড়াও করব, সেদিন নিশ্চয়ই প্রতিশোধ নেব।" },
      { ref: "39:37", noteEn: "Alaysa-llahu bi-'Azizin dhi-ntiqam — Is not Allah Exalted in Might, Owner of Retribution?", noteBn: "আলাইসাল্লাহু বি-আজিযিন যিনতিকাম — আল্লাহ কি পরাক্রমশালী, প্রতিশোধের অধিকারী নন?" }
    ]},
  { n: 82, ar: "الْعَفُوُّ", translit: "Al-ʿAfuww", meanings: { en: "The Pardoner", bn: "মহাক্ষমাকারী", fr: "L'Indulgent", id: "Yang Maha Pemaaf", ur: "بہت معاف کرنے والا", tr: "Affedici", ar: "كثير العفو" , zh: '赦宥者', ja: '許す者', hi: 'बहुत माफ़ करने वाला', es: 'El Indulgente', ru: 'Снисходительный', de: 'Der Verzeihende', fa: 'درگذرنده', ms: 'Yang Maha Pemaaf'},
    explain: { en: "Al-'Afuww goes beyond forgiveness — 'afw means to erase and obliterate entirely, so that the sin leaves no trace in the divine record. Al-Ghafur covers the sin; Al-'Afuww erases it completely. The Prophet (peace be upon him) taught the famous Laylat al-Qadr du'a: 'Allahumma innaka 'Afuwwun tuhibbu al-'afwa fa'fu 'anni' (O Allah, You are Al-'Afuww, You love to pardon, so pardon me). This is the preferred du'a of the ten nights of Laylat al-Qadr.", bn: "আল-আফুওয়্যু ক্ষমার চেয়েও বেশি। আফও মানে পুরোপুরি মুছে ফেলা, নিশ্চিহ্ন করে দেওয়া, যাতে আমলনামায় গুনাহের কোনো চিহ্নই না থাকে। আল-গাফুর গুনাহ ঢেকে দেন; আল-আফুওয়্যু তা একেবারে মুছে দেন। নবী ﷺ লায়লাতুল কদরের বিখ্যাত দু'আ শিখিয়েছেন: 'আল্লাহুম্মা ইন্নাকা আফুওয়ুন তুহিব্বুল আফওয়া ফাআফু আন্নি' (হে আল্লাহ, আপনি আল-আফুওয়্যু, ক্ষমা করতে ভালোবাসেন; তাই আমাকে ক্ষমা করুন)। লায়লাতুল কদরের খোঁজে শেষ দশ রাতে এটিই সবচেয়ে পছন্দের দু'আ।" },
    hadith: { en: "Aisha (may Allah be pleased with her) said: I asked, 'O Messenger of Allah, if I know which night is Laylat al-Qadr, what should I say?' He replied: Say: Allahumma innaka 'Afuwwun tuhibbu al-'afwa fa'fu 'anni (O Allah, You are the Pardoner, You love to pardon, so pardon me).", bn: "আয়িশা (রাঃ) বলেন: আমি জিজ্ঞেস করলাম, 'হে আল্লাহর রাসূল, কোন রাতটি লায়লাতুল কদর তা যদি জানতে পারি, তাহলে কী বলব?' তিনি বললেন: বলো: 'আল্লাহুম্মা ইন্নাকা আফুওয়ুন তুহিব্বুল আফওয়া ফাআফু আন্নি' (হে আল্লাহ, আপনি ক্ষমাশীল, ক্ষমা করতে ভালোবাসেন; তাই আমাকে ক্ষমা করুন)।", src: "Sunan al-Tirmidhi 3513 (Sahih)" },
    invoke: { en: "Especially in the last ten nights of Ramadan (seeking Laylat al-Qadr), repeat: 'Allahumma innaka 'Afuwwun tuhibbu al-'afwa fa'fu 'anni.' Al-'Afuww erases the sin entirely — not just covering it but removing it from the record forever.", bn: "বিশেষ করে রমজানের শেষ দশ রাতে (লায়লাতুল কদরের খোঁজে) বারবার বলুন: 'আল্লাহুম্মা ইন্নাকা আফুওয়ুন তুহিব্বুল আফওয়া ফাআফু আন্নি।' আল-আফুওয়্যু গুনাহ পুরোপুরি মুছে দেন; শুধু ঢেকে রাখেন না, আমলনামা থেকে চিরদিনের জন্য সরিয়ে দেন।" } ,
    quranicRefs: [
      { ref: "4:43", noteEn: "Inna-llaha kana Afuww-an Ghafura — Allah is Al-Afuww and Al-Ghafur; mercy underlies the law of purification.", noteBn: "ইন্নাল্লাহা কানা আফুওয়্যান গাফুরা — আল্লাহ আল-আফুওয়্যু ও আল-গাফুর; পবিত্রতার বিধানের মূলেও আছে রহমত।" },
      { ref: "4:99", noteEn: "Wa kana-llahu Afuww-an Ghafura — Allah is Al-Afuww and Al-Ghafur for those unable to migrate for His sake.", noteBn: "ওয়া কানাল্লাহু আফুওয়্যান গাফুরা — যারা আল্লাহর পথে হিজরত করতে অক্ষম, তাদের জন্য তিনি আল-আফুওয়্যু ও আল-গাফুর।" },
      { ref: "4:149", noteEn: "Fa-inna-llaha kana Afuww-an Qadira — Allah is Al-Afuww and Al-Qadir; He has power to punish yet pardons.", noteBn: "ফাইন্নাল্লাহা কানা আফুওয়্যান কাদিরা — আল্লাহ আল-আফুওয়্যু ও আল-কাদির; শাস্তির ক্ষমতা থাকলেও ক্ষমা করেন।" },
      { ref: "22:60", noteEn: "Inna-llaha la-Afuww-un Ghafur — in the ruling on just retaliation; divine pardon is greater than human justice.", noteBn: "ইন্নাল্লাহা লা-আফুওয়্যুন গাফুর — ন্যায্য বদলার বিধান প্রসঙ্গে; আল্লাহর ক্ষমা মানুষের ন্যায়বিচারের চেয়েও বড়।" },
      { ref: "58:2", noteEn: "Wa inna-llaha la-Afuww-un Ghafur — even grave marital oaths are subject to Al-Afuww's mercy.", noteBn: "ওয়া ইন্নাল্লাহা লা-আফুওয়্যুন গাফুর — দাম্পত্য নিয়ে করা গুরুতর কসমও আল-আফুওয়্যুর রহমতের আওতায়।" }
    ]},
  { n: 83, ar: "الرَّءُوفُ", translit: "Ar-Ra'ūf", meanings: { en: "The Most Kind", bn: "পরম স্নেহশীল", fr: "Le Compatissant", id: "Yang Maha Belas Kasih", ur: "نہایت شفیق", tr: "Çok Şefkatli", ar: "الرؤوف بعباده" , zh: '至慈者', ja: '哀れみ深き者', hi: 'निहायत शफ़ीक़', es: 'El Benévolo', ru: 'Сострадательный', de: 'Der Gütige', fa: 'بسیار دلسوز', ms: 'Yang Maha Belas Kasihan'},
    explain: { en: "Ar-Ra'uf is from ra'fah — the deepest, most tender compassion, even more intense than rahmah. While Ar-Rahman is broad mercy for all, Ar-Ra'uf is intimate, gentle compassion especially for the vulnerable. The Quran (9:128) describes the Prophet (peace be upon him) as ra'uf and rahim — qualities he was given as a reflection of divine attributes. Ar-Ra'uf is the compassion that winces at the pain of others and is moved to help.", bn: "আর-রাউফ এসেছে রা'ফাহ থেকে: সবচেয়ে গভীর, সবচেয়ে কোমল মমতা, যা রাহমাহর চেয়েও তীব্র। আর-রাহমান সবার জন্য ব্যাপক রহমত; আর আর-রাউফ অন্তরঙ্গ, কোমল মমতা, বিশেষ করে দুর্বলদের জন্য। কুরআন (৯:১২৮) নবী ﷺ-কে রাউফ ও রাহিম বলেছে; আল্লাহর গুণের প্রতিফলন হিসেবেই তাঁকে এই গুণ দেওয়া হয়েছিল। আর-রাউফ সেই মমতা, যা অন্যের কষ্ট দেখে ব্যথিত হয় এবং সাহায্যে এগিয়ে আসে।" } ,
    invoke: { en: "When you feel too unworthy to approach Allah, remember that Ar-Ra'uf's tender pity precedes your plea — He is kind even to those who forget Him. Ask 'Ya Ra'uf' for gentleness upon the weak, the ill, and your own frail heart, and imitate that kindness with people.", bn: "আল্লাহর কাছে যাওয়ার জন্য নিজেকে অযোগ্য মনে হলে মনে রাখুন, আপনি চাওয়ার আগেই আর-রাউফের কোমল মমতা আপনার কাছে পৌঁছে আছে। যারা তাঁকে ভুলে থাকে, তাদের প্রতিও তিনি স্নেহশীল। 'ইয়া রাউফ' বলে কোমলতা চান দুর্বলের জন্য, অসুস্থের জন্য, আর নিজের ভঙ্গুর অন্তরের জন্য; আর মানুষের সঙ্গেও সেই কোমলতা নিয়ে চলুন।" },
    quranicRefs: [
      { ref: "2:143", noteEn: "Inna-llaha bi-n-nasi la-Ra'uf-un Rahim — Allah is Ra'uf and Rahim toward people; affirmed in the change of qibla.", noteBn: "ইন্নাল্লাহা বিন-নাসি লা-রাউফুন রাহিম — আল্লাহ মানুষের প্রতি রাউফ ও রাহিম; কিবলা বদলের প্রসঙ্গে কথাটি এসেছে।" },
      { ref: "3:30", noteEn: "Wa-llahu Ra'uf-un bil-ibad — Allah is Ra'uf toward His servants; affirmed in the context of divine reckoning.", noteBn: "ওয়াল্লাহু রাউফুন বিল-ইবাদ — আল্লাহ তাঁর বান্দাদের প্রতি রাউফ; আল্লাহর কাছে হিসাব দেওয়ার প্রসঙ্গে কথাটি এসেছে।" },
      { ref: "9:117", noteEn: "Inna-hu bihim Ra'uf-un Rahim — Allah's tender compassion for those who followed the Prophet in his hour of hardship.", noteBn: "ইন্নাহু বিহিম রাউফুন রাহিম — কঠিন সময়ে যারা নবীর অনুসরণ করেছিল, তাদের প্রতি আল্লাহর কোমল মমতা।" },
      { ref: "9:128", noteEn: "Bi-l-mu'minina Ra'uf-un Rahim — the Prophet is described with Ra'uf and Rahim, divine qualities gifted to the mercy for mankind.", noteBn: "বিল-মুমিনিনা রাউফুন রাহিম — নবীকে বলা হয়েছে রাউফ ও রাহিম; মানবজাতির জন্য রহমত হয়ে আসা নবীকে আল্লাহ নিজের গুণের এই উপহার দিয়েছেন।" },
      { ref: "16:7", noteEn: "Inna Rabbakum la-Ra'uf-un Rahim — your Lord is indeed Ra'uf and Rahim; affirmed as He provides animals to carry burdens.", noteBn: "ইন্না রাব্বাকুম লা-রাউফুন রাহিম — তোমাদের রব নিশ্চয়ই রাউফ ও রাহিম; বোঝা বইবার জন্য তিনি পশু দিয়েছেন, সে প্রসঙ্গেই কথাটি এসেছে।" }
    ]},
  { n: 84, ar: "مَالِكُ الْمُلْكِ", translit: "Mālik-ul-Mulk", meanings: { en: "Master of the Kingdom", bn: "রাজত্বের মালিক", fr: "Maître du Royaume", id: "Pemilik Kerajaan", ur: "ملک کا مالک", tr: "Mülkün Ebedî Sahibi", ar: "مالك الملك كله" , zh: '主權擁有者', ja: '全ての主権を持つ者', hi: 'सारी बादशाही का मालिक', es: 'Dueño del Reino', ru: 'Владыка царства', de: 'Herr der Herrschaft', fa: 'دارنده‌ی فرمانروایی', ms: 'Pemilik Kerajaan'},
    explain: { en: "Malik-ul-Mulk is the Absolute Owner of all sovereignty — not just a king who rules, but the Owner who possesses the very concept of kingship itself. The Quran (3:26) quotes the invocation: 'O Allah, Master of the Kingdom, You give the kingdom to whom You will and take it from whom You will; You honor whom You will and humble whom You will.' No political power exists except by His permission, and all earthly kings are temporary trustees of what belongs to Malik-ul-Mulk.", bn: "মালিকুল-মুলক হলেন সব সার্বভৌমত্বের পরম মালিক। তিনি শুধু শাসনকারী রাজা নন; রাজত্ব জিনিসটারই মালিক তিনি। কুরআন (৩:২৬) এই দু'আ উদ্ধৃত করেছে: 'হে আল্লাহ, রাজত্বের মালিক, আপনি যাকে চান রাজত্ব দেন, যার কাছ থেকে চান ছিনিয়ে নেন; যাকে চান সম্মান দেন, যাকে চান অপদস্থ করেন।' তাঁর অনুমতি ছাড়া কোনো রাজনৈতিক ক্ষমতারই অস্তিত্ব নেই। দুনিয়ার সব রাজা মালিকুল-মুলকের জিনিসের অস্থায়ী আমানতদার মাত্র।" },
    invoke: { en: "When seeking elevation in position, honour, or influence — or when facing those who wield unjust authority over you — recite Quran 3:26-27: 'Quli-l-Lahumma Malika-l-Mulki, tu'ti-l-mulka man tasha...' (Say: O Allah, Master of the Kingdom, You give kingdom to whom You will...). This du'a recognises that all power belongs to Allah.", bn: "পদ, সম্মান বা প্রভাবে উন্নতি চাইলে, কিংবা কেউ আপনার ওপর অন্যায়ভাবে ক্ষমতা খাটালে কুরআন ৩:২৬-২৭ পড়ুন: 'কুলিল্লাহুম্মা মালিকাল-মুলকি তুতিল-মুলকা মান তাশা...' (বলো: হে আল্লাহ, রাজত্বের মালিক, আপনি যাকে চান রাজত্ব দেন...)। এই দু'আ মেনে নেয়: সব ক্ষমতা আল্লাহরই।" } ,
    quranicRefs: [
      { ref: "3:26", noteEn: "Quli-llahumma Malik-al-Mulki tu'ti-l-mulka man tasha — O Allah, Master of the Kingdom, You give kingdom to whom You will.", noteBn: "কুলিল্লাহুম্মা মালিকাল-মুলকি তুতিল-মুলকা মান তাশা — হে আল্লাহ, রাজত্বের মালিক, যাকে চান রাজত্ব দেন।" }
    ]},
  { n: 85, ar: "ذُو الْجَلَالِ وَالْإِكْرَامِ", translit: "Dhul-Jalāli wal-Ikrām", meanings: { en: "Lord of Majesty and Honor", bn: "মহিমা ও সম্মানের অধিকারী", fr: "Détenteur de Majesté et de Générosité", id: "Pemilik Kebesaran dan Kemuliaan", ur: "جلال اور اکرام والا", tr: "Azamet ve İkram Sahibi", ar: "صاحب الجلال والإكرام" , zh: '尊榮之主', ja: '偉大にして高潔なる王', hi: 'जलाल और इकराम वाला', es: 'Dueño de la Majestad y la Honra', ru: 'Обладатель величия и чести', de: 'Inhaber der Erhabenheit und Ehre', fa: 'صاحب شکوه و بزرگواری', ms: 'Yang Mempunyai Kebesaran dan Kemuliaan'},
    explain: { en: "Dhul-Jalali wal-Ikram is one of the grandest composite names — combining Majesty (Jalal: awe-inspiring greatness, transcendence, power) with Honour/Generosity (Ikram: dignity, nobility, generous treatment of guests). The Prophet (peace be upon him) said: 'Hold fast to ya Dhul-Jalali wal-Ikram' (Tirmidhi 3524) — making this a frequently recommended name to call upon. Ibn al-Qayyim writes that jalal moves the heart to reverence and awe, while ikram moves the heart to hope and love — together they produce the complete worshipper.", bn: "যুল-জালালি ওয়াল-ইকরাম সবচেয়ে মহান যৌগিক নামগুলোর একটি। এতে মিলেছে জালাল, অর্থাৎ ভয়-জাগানো মহত্ত্ব, সবকিছুর ঊর্ধ্বে থাকা ও ক্ষমতা; আর ইকরাম, অর্থাৎ মর্যাদা, মহানুভবতা ও মেহমানের প্রতি উদার আচরণ। নবী ﷺ বলেছেন: 'ইয়া যুল-জালালি ওয়াল-ইকরাম আঁকড়ে ধরো' (তিরমিযী ৩৫২৪); তাই এই নামে বারবার ডাকার তাগিদ এসেছে। ইবনুল কাইয়িম লিখেছেন, জালাল অন্তরে জাগায় সম্ভ্রম ও ভয়, আর ইকরাম জাগায় আশা ও ভালোবাসা; দুয়ে মিলে গড়ে ওঠে পরিপূর্ণ ইবাদতকারী।" },
    hadith: { en: "Hold fast to 'Ya Dhul-Jalali wal-Ikram' (O Lord of Majesty and Honor).", bn: "'ইয়া যুল-জালালি ওয়াল-ইকরাম' (হে মহিমা ও সম্মানের অধিকারী) বলাকে আঁকড়ে ধরো।", src: "Sunan al-Tirmidhi 3525 (Sahih)" } ,
    invoke: { en: "The Prophet ﷺ instructed: 'Persist in saying Ya Dhal-Jalali wal-Ikram' — make it a constant refrain in your du'as. Say it after the salam of every prayer ('...tabarakta ya Dhal-Jalali wal-Ikram'), combining awe of His Majesty with hope in His Generosity.", bn: "নবী ﷺ নির্দেশ দিয়েছেন: 'ইয়া যাল-জালালি ওয়াল-ইকরাম বেশি বেশি বলো।' তাই একে আপনার দু'আর নিয়মিত বুলি বানিয়ে নিন। প্রতিটি নামাজের সালামের পরে বলুন ('...তাবারাকতা ইয়া যাল-জালালি ওয়াল-ইকরাম'); এতে তাঁর মহিমার প্রতি সম্ভ্রম আর তাঁর দানশীলতার প্রতি আশা, দুটোই একসঙ্গে থাকে।" },
    quranicRefs: [
      { ref: "55:27", noteEn: "Wa yabqa Wajhu Rabbika Dhu-l-Jalali wal-Ikram — His Face of Majesty and Honor will remain when all else perishes.", noteBn: "ওয়া ইয়াবকা ওয়াজহু রাব্বিকা যুল-জালালি ওয়াল-ইকরাম — সবকিছু ধ্বংস হলেও থেকে যাবে মহিমা ও সম্মানের অধিকারী তোমার রবের চেহারা।" },
      { ref: "55:78", noteEn: "Tabaraka-smu Rabbika Dhi-l-Jalali wal-Ikram — the name of your Lord, Owner of Jalal and Ikram, is blessed.", noteBn: "তাবারাকাসমু রাব্বিকা যিল-জালালি ওয়াল-ইকরাম — জালাল ও ইকরামের অধিকারী তোমার রবের নাম বড়ই বরকতময়।" }
    ]},
  { n: 86, ar: "الْمُقْسِطُ", translit: "Al-Muqsiṭ", meanings: { en: "The Equitable", bn: "ন্যায়পরায়ণ", fr: "L'Équitable", id: "Yang Maha Memberi Keadilan", ur: "انصاف کرنے والا", tr: "Adaletle Hükmeden", ar: "العادل المنصف" , zh: '公正者', ja: '公平なる者', hi: 'इंसाफ़ क़ायम करने वाला', es: 'El Equitativo', ru: 'Беспристрастный', de: 'Der Gerechtigkeit Übende', fa: 'دادگستر', ms: 'Yang Maha Saksama'},
    explain: { en: "Al-Muqsit is the One who establishes and enacts perfect, balanced justice — justice that gives everyone their due without excess or deficiency. While Al-'Adl (name 29) describes the attribute of justice, Al-Muqsit describes its active exercise: Allah not only is just, He establishes justice. The Quran (3:18) affirms: 'Allah testifies that there is no deity except Him, as do the angels and those of knowledge, maintaining justice.' He is simultaneously the legislator, judge, and executor of justice.", bn: "আল-মুকসিত হলেন সেই সত্তা, যিনি নিখুঁত, ভারসাম্যপূর্ণ ন্যায়বিচার প্রতিষ্ঠা করেন ও কার্যকর করেন; এমন ন্যায়, যাতে প্রত্যেকে তার প্রাপ্য পায়, বেশিও না, কমও না। আল-আদল (২৯ নম্বর নাম) বোঝায় ন্যায়পরায়ণতার গুণ; আর আল-মুকসিত বোঝায় সেই গুণের সক্রিয় প্রয়োগ। আল্লাহ শুধু ন্যায়পরায়ণই নন, তিনি ন্যায় প্রতিষ্ঠাও করেন। কুরআন (৩:১৮) বলে: 'আল্লাহ সাক্ষ্য দেন যে তিনি ছাড়া কোনো ইলাহ নেই, ফেরেশতারা ও জ্ঞানীরাও (এ সাক্ষ্য দেন); তিনি ন্যায়ের ওপর প্রতিষ্ঠিত।' তিনি একাধারে ন্যায়ের বিধানদাতা, বিচারক ও বাস্তবায়নকারী।" } ,
    hadith: { en: "The Prophet ﷺ said: 'Allah does not sleep, and it does not befit Him to sleep. He lowers and raises the scale (al-qist); the deeds of the night are raised to Him before the deeds of the day, and the deeds of the day before the night.'", bn: "নবী ﷺ বলেছেন: 'আল্লাহ ঘুমান না, আর ঘুমানো তাঁর শানে শোভনও নয়। তিনি (ইনসাফের) দাঁড়িপাল্লা নামান ও ওঠান; রাতের আমল দিনের আমলের আগে এবং দিনের আমল রাতের আগে তাঁর কাছে উঠানো হয়।'", src: "Sahih Muslim 179" },
    invoke: { en: "Ask Al-Muqsit to make you scrupulously fair in judgment, family, and business — 'indeed Allah loves those who act justly' (49:9). When treated unfairly with no recourse, appeal to the Equitable who lowers and raises the scale and will balance every account.", bn: "আল-মুকসিতের কাছে চান, তিনি যেন আপনাকে বিচারে, পরিবারে ও ব্যবসায় পুরোপুরি ইনসাফকারী বানান; 'নিশ্চয়ই আল্লাহ ইনসাফকারীদের ভালোবাসেন' (৪৯:৯)। অন্যায়ের শিকার হয়ে কোথাও প্রতিকার না পেলে ফরিয়াদ জানান সেই ন্যায়বিচারকের কাছে, যিনি দাঁড়িপাল্লা নামান ও ওঠান, আর যিনি প্রতিটি হিসাব সমান করে দেবেন।" },
    quranicRefs: [
      { ref: "3:18", noteEn: "Shahida-llahu... qa'iman bi-l-qist — Allah bears witness, maintaining justice (qist); the root of Al-Muqsit.", noteBn: "শাহিদাল্লাহু... কাইমান বিল-কিসত — আল্লাহ সাক্ষ্য দেন, ন্যায়ের (কিসত) ওপর প্রতিষ্ঠিত থেকে; এই কিসত থেকেই আল-মুকসিত নাম।" },
      { ref: "21:47", noteEn: "Wa nada'u-l-mawazina-l-qista li-yawmi-l-qiyamah — We place the scales of justice for the Day of Resurrection.", noteBn: "ওয়া নাদাউল-মাওয়াযিনাল-কিসতা লি-ইয়াওমিল-কিয়ামাহ — কিয়ামতের দিনে আমরা ন্যায়ের দাঁড়িপাল্লা স্থাপন করব।" },
      { ref: "10:47", noteEn: "Qudiya baynahum bi-l-qist wa hum la yuzlamun — it is judged among them in justice, and they are not wronged.", noteBn: "কুদিয়া বাইনাহুম বিল-কিসত ওয়া হুম লা ইউযলামুন — তাদের মধ্যে ন্যায়ের সঙ্গে ফয়সালা করা হবে, তাদের প্রতি কোনো জুলুম হবে না।" },
      { ref: "10:54", noteEn: "Wa qudiya baynahum bi-l-qist wa hum la yuzlamun — He judges between them with equity, none is oppressed.", noteBn: "ওয়া কুদিয়া বাইনাহুম বিল-কিসত ওয়া হুম লা ইউযলামুন — তিনি তাদের মধ্যে ন্যায়ের সাথে বিচার করেন, কেউ নিপীড়িত হয় না।" }
    ]},
  { n: 87, ar: "الْجَامِعُ", translit: "Al-Jāmiʿ", meanings: { en: "The Gatherer", bn: "একত্রকারী", fr: "Le Rassembleur", id: "Yang Maha Mengumpulkan", ur: "جمع کرنے والا", tr: "Toplayan", ar: "الجامع للخلق يوم القيامة" , zh: '統合者', ja: '収集する者', hi: 'इकट्ठा करने वाला', es: 'El que reúne', ru: 'Собирающий', de: 'Der Versammelnde', fa: 'گردآورنده', ms: 'Yang Maha Menghimpunkan'},
    explain: { en: "Al-Jami' is the Gatherer who assembles all creation on the Day of Resurrection for the final reckoning — the first and last humans, all simultaneously. The Quran (4:87) says: 'Allah — there is no deity except Him. He will surely assemble you for the Day of Resurrection, about which there is no doubt.' Al-Jami' also describes how Allah gathers and holds together the cosmos, the Quran, and all attributes of perfection within Himself without contradiction.", bn: "আল-জামি হলেন সেই একত্রকারী, যিনি কিয়ামতের দিন চূড়ান্ত হিসাবের জন্য গোটা সৃষ্টিকে জড়ো করবেন; প্রথম মানুষ থেকে শেষ মানুষ পর্যন্ত, সবাইকে একসঙ্গে। কুরআন (৪:৮৭) বলে: 'আল্লাহ, তিনি ছাড়া কোনো ইলাহ নেই। তিনি অবশ্যই তোমাদের একত্র করবেন কিয়ামতের দিন, যাতে কোনো সন্দেহ নেই।' আল-জামি নাম এটাও বোঝায় যে আল্লাহ মহাবিশ্ব ও কুরআনকে একসূত্রে ধরে রাখেন, আর পূর্ণতার সব গুণ কোনো বৈপরীত্য ছাড়াই তাঁর মধ্যে একত্র।" } ,
    invoke: { en: "Ask Al-Jami' to gather your scattered affairs, mend the divided hearts in your family and ummah, and unite you with those you love in Paradise. Pray with the Quran: 'Our Lord, You are the Gatherer of mankind for a Day about which there is no doubt' (3:9) — and prepare for that gathering.", bn: "আল-জামির কাছে চান, তিনি যেন আপনার এলোমেলো বিষয়গুলো গুছিয়ে দেন, পরিবার ও উম্মাহর ভাঙা মন জোড়া লাগান, আর জান্নাতে প্রিয়জনদের সঙ্গে মিলিয়ে দেন। কুরআনের ভাষায় দু'আ করুন: 'হে আমাদের রব, নিশ্চয়ই আপনি মানুষকে একত্র করবেন এমন এক দিনে, যাতে কোনো সন্দেহ নেই' (৩:৯)। আর সেই মহাসমাবেশের জন্য প্রস্তুতি নিন।" },
    quranicRefs: [
      { ref: "3:9", noteEn: "Rabbana innaka Jami'u-n-nasi li-yawmin la rayba fih — You will gather mankind for a Day about which there is no doubt.", noteBn: "রাব্বানা ইন্নাকা জামিউন-নাসি লি-ইয়াওমিন লা রাইবা ফিহ — আপনি মানুষকে এমন এক দিনে একত্র করবেন যাতে কোনো সন্দেহ নেই।" },
      { ref: "4:140", noteEn: "Inna-llaha Jami'u-l-munafiqina wa-l-kafirina fi jahannama jami'a — Allah will gather the hypocrites and disbelievers all together.", noteBn: "ইন্নাল্লাহা জামিউল-মুনাফিকিনা ওয়াল-কাফিরিনা ফি জাহান্নামা জামিআ — আল্লাহ মুনাফিক ও কাফিরদের সবাইকে জাহান্নামে একত্র করবেন।" },
      { ref: "42:29", noteEn: "Wa Huwa 'ala jam'ihim idha yasha'u Qadir — He is Able to gather them whenever He wills.", noteBn: "ওয়া হুওয়া আলা জামইহিম ইযা ইয়াশাউ কাদির — তিনি যখন ইচ্ছা তাদের একত্র করতে সক্ষম।" },
      { ref: "64:9", noteEn: "Yawma yajma'ukum li-yawmi-l-jam' — the Day He gathers you for the Day of Assembly.", noteBn: "ইয়াওমা ইয়াজমাউকুম লি-ইয়াওমিল-জামই — যেদিন তিনি তোমাদের সমাবেশের দিনে একত্র করবেন।" }
    ]},
  { n: 88, ar: "الْغَنِيُّ", translit: "Al-Ghaniyy", meanings: { en: "The Self-Sufficient", bn: "অভাবমুক্ত", fr: "Le Riche", id: "Yang Maha Kaya", ur: "غنی", tr: "Zengin, Muhtaç Olmayan", ar: "الغني عن الخلق" , zh: '富有者', ja: '全ての裕福なる者', hi: 'बेनियाज़, ग़नी', es: 'El Rico', ru: 'Богатый', de: 'Der Unbedürftige', fa: 'بی‌نیاز', ms: 'Yang Maha Kaya'},
    explain: { en: "Al-Ghaniyy is completely self-sufficient, independent, and in need of nothing — not our worship, not our praise, not our repentance. The Quran (47:38) says: 'Allah is the Self-Sufficient, and you are the needy.' This is humbling: all our acts of worship are not for Allah's benefit but for ours. Al-Ghazali writes that understanding Al-Ghaniyy frees the servant from performing acts of worship for show (riya') or expecting gratitude from people — because Allah alone needs nothing, and only Allah's gratitude matters.", bn: "আল-গানিয়্যু পুরোপুরি স্বয়ংসম্পূর্ণ, কারও ওপর নির্ভরশীল নন, কোনো কিছুরই মুখাপেক্ষী নন। আমাদের ইবাদত, প্রশংসা, তওবা, কিছুরই তাঁর প্রয়োজন নেই। কুরআন (৪৭:৩৮) বলে: 'আল্লাহ অভাবমুক্ত, আর তোমরাই অভাবী।' কথাটি মানুষকে বিনয়ী করে: আমাদের কোনো ইবাদতই আল্লাহর উপকারের জন্য নয়, আমাদের নিজেদের উপকারের জন্য। ইমাম গাজালী লিখেছেন, আল-গানিয়্যুকে বুঝলে বান্দা লোক দেখানো (রিয়া) ইবাদত থেকে মুক্ত হয়, মানুষের কাছে কৃতজ্ঞতা পাওয়ার আশাও ছেড়ে দেয়। কারণ একমাত্র আল্লাহই কোনো কিছুর মুখাপেক্ষী নন, আর মূল্য আছে কেবল আল্লাহর কদরের।" } ,
    hadith: { en: "Allah says: 'O My servants, all of you are hungry except those whom I feed, so ask food of Me and I will feed you. All of you are naked except those whom I clothe, so ask clothing of Me and I will clothe you.'", bn: "আল্লাহ বলেন: 'হে আমার বান্দারা, আমি যাকে খাওয়াই সে ছাড়া তোমরা সবাই ক্ষুধার্ত; তাই আমার কাছে খাবার চাও, আমি তোমাদের খাওয়াব। আমি যাকে পরাই সে ছাড়া তোমরা সবাই বস্ত্রহীন; তাই আমার কাছে পোশাক চাও, আমি তোমাদের পরাব।'", src: "Sahih Muslim 2577 (Hadith Qudsi)" },
    invoke: { en: "When gripped by poverty or dependence on people, call upon Ya Ghaniyy — He alone is free of all need and every creature is utterly poor before Him. Ask Him to enrich your heart with contentment and to free you from needing anyone besides Him.", bn: "দারিদ্র্যে পড়লে, কিংবা মানুষের মুখাপেক্ষী হয়ে পড়লে 'ইয়া গানিয়্য' বলে ডাকুন। একমাত্র তিনিই সব প্রয়োজন থেকে মুক্ত, আর প্রতিটি সৃষ্টি তাঁর সামনে একেবারে নিঃস্ব। তাঁর কাছে চান, তিনি যেন অল্পে তুষ্টি দিয়ে আপনার অন্তরকে ধনী করেন, আর তিনি ছাড়া অন্য কারও মুখাপেক্ষী হওয়া থেকে মুক্ত রাখেন।" } ,
    quranicRefs: [
      { ref: "35:15", noteEn: "Ya ayyuha-n-nasu antum-ul-fuqara ila-llah wa-llahu Huwa-l-Ghani-ul-Hamid — you are needy toward Allah; He is Al-Ghaniyy.", noteBn: "ইয়া আয়্যুহান-নাসু আনতুমুল-ফুকারাউ ইলাল্লাহ ওয়াল্লাহু হুওয়াল-গানিয়্যুল-হামিদ — তোমরা আল্লাহর মুখাপেক্ষী; তিনিই আল-গানিয়্যু।" },
      { ref: "47:38", noteEn: "Antum-ul-fuqara wa-llahu Huwa-l-Ghani — you are the poor, and Allah is Al-Ghaniyy; self-sufficiency belongs to Him alone.", noteBn: "আনতুমুল-ফুকারাউ ওয়াল্লাহু হুওয়াল-গানিয়্যু — তোমরা অভাবী, আল্লাহ আল-গানিয়্যু; স্বনির্ভরতা একমাত্র তাঁর।" }
    ]},
  { n: 89, ar: "الْمُغْنِي", translit: "Al-Mughnī", meanings: { en: "The Enricher", bn: "অভাবমোচনকারী", fr: "Celui qui enrichit", id: "Yang Maha Memberi Kekayaan", ur: "غنی کرنے والا", tr: "Zenginlik Veren", ar: "المغني لعباده" , zh: '賜予財富者', ja: '豊かにする者', hi: 'ग़नी करने वाला', es: 'El que enriquece', ru: 'Обогащающий', de: 'Der reich Machende', fa: 'بی‌نیازکننده', ms: 'Yang Maha Memberi Kekayaan'},
    explain: { en: "Al-Mughni is the One who enriches — not just materially but in every dimension of life: knowledge, contentment, relationships, and spiritual wealth. The Quran (9:28) refers to Allah making people self-sufficient from His bounty. The Prophet (peace be upon him) taught: 'Richness is not having many possessions, but richness is the contentment of the soul' (Bukhari 6446) — pointing to the inner enrichment that only Al-Mughni can provide.", bn: "আল-মুগনি হলেন সেই সত্তা, যিনি ধনী করেন; শুধু টাকাপয়সায় নয়, জীবনের প্রতিটি ক্ষেত্রে: জ্ঞানে, অল্পে তুষ্টিতে, সম্পর্কে, আর আত্মিক সম্পদে। কুরআন (৯:২৮) বলে, আল্লাহ নিজ অনুগ্রহে মানুষকে অভাবমুক্ত করেন। নবী ﷺ শিখিয়েছেন: 'অনেক ধনসম্পদ থাকার নাম ধনী হওয়া নয়; আসল ধনী হলো মনের ধনী' (বুখারী ৬৪৪৬)। এ কথা সেই ভেতরের ঐশ্বর্যের দিকে ইশারা করে, যা কেবল আল-মুগনিই দিতে পারেন।" },
    invoke: { en: "In poverty or need, call upon Al-Mughni to enrich you — with provision, or better still with contentment and independence from creation. Ask Him to make you rich in heart, for the Prophet ﷺ said true wealth is the richness of the soul.", bn: "অভাবে বা প্রয়োজনে আল-মুগনিকে ডাকুন, তিনি যেন আপনাকে অভাবমুক্ত করেন: রিজিক দিয়ে, কিংবা তার চেয়েও ভালো, অল্পে তুষ্টি আর সৃষ্টির মুখাপেক্ষী না থাকার শক্তি দিয়ে। মনের দিক থেকে ধনী হওয়ার দু'আ করুন; নবী ﷺ বলেছেন, আসল ধন হলো মনের ধন।" } ,
    hadith: { en: "The Prophet ﷺ used to supplicate: 'O Allah, I ask You for guidance, piety, chastity, and self-sufficiency (al-ghina).'", bn: "নবী ﷺ দু'আ করতেন: 'হে আল্লাহ, আমি আপনার কাছে চাই হিদায়াত, তাকওয়া, চারিত্রিক পবিত্রতা ও অভাবমুক্তি (আল-গিনা)।'", src: "Sahih Muslim 2721" },
    quranicRefs: [
      { ref: "53:48", noteEn: "Wa annahu Huwa aghna wa aqna — and it is He who enriches (aghna) and grants possessions.", noteBn: "ওয়া আন্নাহু হুওয়া আগনা ওয়া আকনা — আর তিনিই অভাবমুক্ত করেন (আগনা) ও সম্পদ দান করেন।" },
      { ref: "93:8", noteEn: "Wa wajadaka 'a'ilan fa-aghna — He found you poor and enriched you; addressed to the Prophet ﷺ.", noteBn: "ওয়া ওয়াজাদাকা আইলান ফা-আগনা — তিনি তোমাকে অভাবী পেয়ে অভাবমুক্ত করেছেন; কথাটি নবী ﷺ-কে উদ্দেশ করে।" },
      { ref: "9:28", noteEn: "Fa-sawfa yughnikumu-llahu min fadlihi — Allah will enrich you from His bounty if He wills.", noteBn: "ফা-সাওফা ইউগনিকুমুল্লাহু মিন ফাদলিহি — আল্লাহ চাইলে তাঁর অনুগ্রহ থেকে তোমাদের অভাবমুক্ত করবেন।" },
      { ref: "24:32", noteEn: "In yakunu fuqara'a yughnihimu-llahu min fadlih — if they are poor, Allah will enrich them from His bounty.", noteBn: "ইন ইয়াকুনু ফুকারাআ ইউগনিহিমুল্লাহু মিন ফাদলিহ — তারা অভাবী হলে আল্লাহ তাদের তাঁর অনুগ্রহ থেকে অভাবমুক্ত করবেন।" }
    ]},
  { n: 90, ar: "الْمَانِعُ", translit: "Al-Māniʿ", meanings: { en: "The Preventer", bn: "প্রতিরোধকারী", fr: "Celui qui empêche", id: "Yang Maha Mencegah", ur: "روکنے والا", tr: "Engelleyen", ar: "المانع لما يشاء" , zh: '保護者', ja: '抑えし者', hi: 'रोकने वाला', es: 'El que impide', ru: 'Препятствующий', de: 'Der Verwehrende', fa: 'بازدارنده', ms: 'Yang Maha Menghalang'},
    explain: { en: "Al-Mani' is the One who prevents, withholds, and protects — always according to divine wisdom. Sometimes He prevents harm from reaching His servants (protective prevention); sometimes He withholds what servants desire for their own good (educative prevention). The Prophet (peace be upon him) said in his morning and evening dhikr: 'What You prevent, no one can give; and what You give, no one can prevent.' This teaches that al-Mani' and al-Mu'ti (the Giver) are two faces of the same perfect divine management.", bn: "আল-মানি হলেন সেই সত্তা, যিনি বাধা দেন, আটকে রাখেন ও রক্ষা করেন; সবসময় নিজের হিকমত অনুযায়ী। কখনো তিনি বান্দার কাছে ক্ষতি পৌঁছাতে দেন না (রক্ষার জন্য বাধা); কখনো বান্দার চাওয়া জিনিস তার নিজের ভালোর জন্যই আটকে রাখেন (শিক্ষার জন্য বাধা)। নবী ﷺ সকাল-সন্ধ্যার জিকিরে বলতেন: 'আপনি যা আটকান, কেউ তা দিতে পারে না; আর আপনি যা দেন, কেউ তা আটকাতে পারে না।' এ থেকে বোঝা যায়, আল-মানি আর আল-মুতি (দাতা) একই নিখুঁত ব্যবস্থাপনার দুই দিক।" } ,
    hadith: { en: "After every prescribed prayer the Prophet ﷺ would say: '...O Allah, none can withhold what You give, and none can give what You withhold, and the fortune of the fortunate avails nothing against You.'", bn: "প্রতিটি ফরজ নামাজের পরে নবী ﷺ বলতেন: '...হে আল্লাহ, আপনি যা দেন, কেউ তা আটকাতে পারে না; আপনি যা আটকান, কেউ তা দিতে পারে না; আর আপনার কাছে কোনো সম্পদশালীর সম্পদ কোনো কাজে আসে না।'", src: "Sahih al-Bukhari 844; Sahih Muslim 593" },
    invoke: { en: "Say after every prescribed prayer: 'None can withhold what You give, and none can give what You withhold.' When a door closes despite your efforts, trust Al-Mani' — His prevention is protection, and what He kept from you was never your provision.", bn: "প্রতিটি ফরজ নামাজের পরে বলুন: 'আপনি যা দেন তা কেউ আটকাতে পারে না, আর আপনি যা আটকান তা কেউ দিতে পারে না।' চেষ্টা সত্ত্বেও কোনো দরজা বন্ধ হয়ে গেলে আল-মানির ওপর ভরসা রাখুন। তাঁর বাধাই আসলে সুরক্ষা; যা তিনি আপনার কাছ থেকে আটকে রেখেছেন, তা কখনো আপনার রিজিক ছিলই না।" },
    quranicRefs: [
      { ref: "35:2", noteEn: "Ma yaftahi-llahu li-n-nasi min rahmatin fa-la mumsika laha wa ma yumsik fa-la mursila lahu — what He withholds none can release.", noteBn: "মা ইয়াফতাহিল্লাহু লিন-নাসি মিন রাহমাতিন ফা-লা মুমসিকা লাহা ওয়া মা ইউমসিক ফা-লা মুরসিলা লাহু — তিনি যা আটকান তা কেউ ছাড়তে পারে না।" },
      { ref: "39:38", noteEn: "In aradani bi-rahmatin hal hunna mumsikatu rahmatih — could any withhold His mercy? Only He grants and withholds.", noteBn: "ইন আরাদানি বি-রাহমাতিন হাল হুন্না মুমসিকাতু রাহমাতিহ — কেউ কি তাঁর রহমত আটকাতে পারে? একমাত্র তিনিই দেন ও আটকান।" },
      { ref: "67:21", noteEn: "Amman hadha-lladhi yarzuqukum in amsaka rizqah — who could provide for you if He withheld His provision?", noteBn: "আম্মান হাযাল-লাযি ইয়ারযুকুকুম ইন আমসাকা রিযকাহ — তিনি তাঁর রিযিক আটকে রাখলে কে তোমাদের রিযিক দেবে?" }
    ]},
  { n: 91, ar: "الضَّارُّ", translit: "Aḍ-Ḍārr", meanings: { en: "The Distresser", bn: "ক্ষতি সাধনকারী", fr: "Celui qui peut nuire", id: "Yang Maha Pemberi Mudarat", ur: "نقصان پہنچانے والا", tr: "Zarar Vermeye Kâdir", ar: "الضار بحكمته" , zh: '折磨者', ja: '苦悩するもの', hi: 'नुक़सान पहुँचाने वाला', es: 'El que causa aflicción', ru: 'Наносящий вред', de: 'Der Bedrängende', fa: 'زیان‌رسان', ms: 'Yang Maha Memberi Mudarat'},
    explain: { en: "Ad-Darr must be understood in its proper theological context: Allah can cause harm (darar) to whomever He wills, and this always appears paired with An-Nafi' (the Benefiter). This is not arbitrariness or cruelty — divine harm is always purposeful: as a test, a consequence of oppression, or a divine warning. Quran 10:107 states: 'If Allah afflicts you with harm, none can remove it except Him.' Recognising Ad-Darr teaches that harm and hardship ultimately come from a wisdom-driven divine plan.", bn: "আদ-দার্র নামটি বুঝতে হবে আকিদার সঠিক প্রেক্ষাপটে: আল্লাহ যাকে চান তার ক্ষতি (দারার) করতে পারেন, আর এই নাম সবসময় আসে আন-নাফির (যিনি উপকার করেন) সঙ্গে জোড়ায়। এটা খামখেয়ালি বা নিষ্ঠুরতা নয়। আল্লাহর দেওয়া ক্ষতির পেছনে সবসময় উদ্দেশ্য থাকে: পরীক্ষা, জুলুমের পরিণতি, কিংবা সতর্কবার্তা। কুরআন ১০:১০৭ বলে: 'আল্লাহ যদি তোমাকে কোনো কষ্টে ফেলেন, তিনি ছাড়া কেউ তা দূর করতে পারবে না।' আদ-দার্রকে চিনলে বোঝা যায়, ক্ষতি ও কষ্ট শেষ পর্যন্ত আসে আল্লাহর হিকমতভরা পরিকল্পনা থেকেই।" } ,
    hadith: { en: "The Prophet ﷺ taught the one in pain: 'Place your hand where it hurts and say Bismillah three times, then say seven times: I seek refuge in Allah and His power from the evil of what I find and fear.'", bn: "ব্যথাগ্রস্ত ব্যক্তিকে নবী ﷺ শেখালেন: 'যেখানে ব্যথা সেখানে হাত রেখে তিনবার বিসমিল্লাহ বলো, তারপর সাতবার বলো: আমি যা অনুভব করছি ও যার আশঙ্কা করছি তার অনিষ্ট থেকে আল্লাহ ও তাঁর কুদরতের আশ্রয় চাই।'", src: "Sahih Muslim 2202" },
    invoke: { en: "When harm touches you, turn to the One in whose hand both harm and cure lie — say as Ayyub did: 'Indeed adversity has touched me, and You are the Most Merciful of the merciful' (21:83). Place your hand on the site of pain and seek refuge in Allah and His power from the evil of what you find.", bn: "কষ্ট এলে ফিরে যান সেই সত্তার কাছে, যাঁর হাতে ক্ষতি আর আরোগ্য দুটোই। আইয়ুবের মতো বলুন: 'নিশ্চয়ই আমাকে কষ্ট ছুঁয়েছে, আর আপনি দয়ালুদের মধ্যে সবচেয়ে বড় দয়ালু' (২১:৮৩)। ব্যথার জায়গায় হাত রেখে, যা অনুভব করছেন তার অনিষ্ট থেকে আল্লাহ ও তাঁর কুদরতের আশ্রয় চান।" },
    quranicRefs: [
      { ref: "6:17", noteEn: "Wa in yamsaska-llahu bi-durrin fa-la kashifa lahu illa Huwa — if Allah touches you with harm, none can remove it but He.", noteBn: "ওয়া ইন ইয়ামসাসকাল্লাহু বি-দুররিন ফা-লা কাশিফা লাহু ইল্লা হুওয়া — আল্লাহ তোমাকে কোনো কষ্টে ফেললে তিনি ছাড়া কেউ তা দূর করতে পারে না।" },
      { ref: "10:107", noteEn: "Wa in yamsaska-llahu bi-durrin fa-la kashifa lahu illa Huwa — harm decreed by Him none can lift but Him.", noteBn: "ওয়া ইন ইয়ামসাসকাল্লাহু বি-দুররিন ফা-লা কাশিফা লাহু ইল্লা হুওয়া — তাঁর নির্ধারিত ক্ষতি তিনি ছাড়া কেউ দূর করতে পারে না।" },
      { ref: "48:11", noteEn: "Man yamliku lakum mina-llahi shay'an in arada bikum darran — who can avail you against Allah if He intends harm?", noteBn: "মান ইয়ামলিকু লাকুম মিনাল্লাহি শাইআন ইন আরাদা বিকুম দাররান — তিনি ক্ষতি চাইলে আল্লাহর বিরুদ্ধে কে তোমাদের রক্ষা করবে?" },
      { ref: "39:38", noteEn: "In aradani-llahu bi-durrin hal hunna kashifatu durrih — could any remove the harm He wills? None but He.", noteBn: "ইন আরাদানিয়াল্লাহু বি-দুররিন হাল হুন্না কাশিফাতু দুররিহ — তিনি যে ক্ষতি চান তা কি কেউ দূর করতে পারে? একমাত্র তিনি।" }
    ]},
  { n: 92, ar: "النَّافِعُ", translit: "An-Nāfiʿ", meanings: { en: "The Benefiter", bn: "কল্যাণকারী", fr: "Le Bienfaisant", id: "Yang Maha Pemberi Manfaat", ur: "نفع دینے والا", tr: "Fayda Veren", ar: "النافع بفضله" , zh: '創造善良者', ja: '慈悲深い者', hi: 'नफ़ा देने वाला', es: 'El que beneficia', ru: 'Приносящий пользу', de: 'Der Nutzen Bringende', fa: 'سودرسان', ms: 'Yang Maha Memberi Manfaat'},
    explain: { en: "An-Nafi' is the Benefiter — the One who alone can bring true benefit, good, and blessing. This name always pairs with Ad-Darr: together they establish that both harm and benefit are in Allah's hands alone. The Quran (10:107) states: 'If Allah wills good for you, none can repel His favor.' Al-Ghazali notes that recognising An-Nafi' as the exclusive source of benefit liberates the believer from seeking benefit through forbidden means or from those who have no power to truly benefit.", bn: "আন-নাফি হলেন উপকারকারী; একমাত্র তিনিই সত্যিকারের উপকার, কল্যাণ ও বরকত আনতে পারেন। এই নাম সবসময় আদ-দার্রের সঙ্গে জোড়ায় আসে; দুটি মিলে বুঝিয়ে দেয়, ক্ষতি ও উপকার দুটোই কেবল আল্লাহর হাতে। কুরআন (১০:১০৭) বলে: 'আর আল্লাহ যদি তোমার কল্যাণ চান, তাঁর অনুগ্রহ কেউ ফেরাতে পারবে না।' ইমাম গাজালী বলেন, আন-নাফিকে উপকারের একমাত্র উৎস বলে চিনলে মুমিন মুক্ত হয় হারাম পথে উপকার খোঁজা থেকে, আর তাদের কাছে উপকার চাওয়া থেকেও, যাদের আসলে উপকার করার কোনো ক্ষমতা নেই।" },
    invoke: { en: "Ask An-Nafi' to make beneficial for you your knowledge, wealth, health, and time, and to bring good to others through your hands. When something seems to benefit you, remember its benefit is only by His permission.", bn: "আন-নাফির কাছে চান, তিনি যেন আপনার জ্ঞান, সম্পদ, স্বাস্থ্য ও সময়কে আপনার জন্য উপকারী করেন, আর আপনার হাত দিয়ে অন্যদের কল্যাণ পৌঁছে দেন। কোনো কিছু থেকে উপকার পেলে মনে রাখুন, সেই উপকারও এসেছে কেবল তাঁরই অনুমতিতে।" } ,
    hadith: { en: "The Prophet ﷺ said to Ibn Abbas: 'Know that if the whole nation gathered to benefit you, they could not benefit you except with what Allah has already written for you; and if they gathered to harm you, they could not harm you except with what Allah has already written against you.'", bn: "নবী ﷺ ইবনে আব্বাস (রাঃ)-কে বললেন: 'জেনে রাখো, সমগ্র উম্মত যদি তোমার উপকারে একত্র হয়, আল্লাহ যা লিখে রেখেছেন তার বাইরে কোনো উপকার তারা করতে পারবে না; আর তারা যদি তোমার ক্ষতিতে একত্র হয়, আল্লাহ যা লিখে রেখেছেন তার বাইরে কোনো ক্ষতিও করতে পারবে না।'", src: "Jami' at-Tirmidhi 2516 — hasan sahih" },
    quranicRefs: [
      { ref: "48:11", noteEn: "Aw arada bikum naf'a — or if He intends benefit (naf') for you, none can prevent it.", noteBn: "আও আরাদা বিকুম নাফআ — অথবা তিনি তোমাদের কল্যাণ (নাফ) চাইলে কেউ তা রুখতে পারে না।" },
      { ref: "7:188", noteEn: "La amliku li-nafsi naf'an wa la darran illa ma sha'a-llah — I hold no benefit or harm for myself except as Allah wills.", noteBn: "লা আমলিকু লি-নাফসি নাফআন ওয়া লা দাররান ইল্লা মা শাআল্লাহ — আল্লাহ যা চান তা ছাড়া আমি নিজের কল্যাণ বা ক্ষতির মালিক নই।" },
      { ref: "10:49", noteEn: "Qul la amliku li-nafsi darran wa la naf'an illa ma sha'a-llah — benefit and harm belong to Allah alone.", noteBn: "কুল লা আমলিকু লি-নাফসি দাররান ওয়া লা নাফআন ইল্লা মা শাআল্লাহ — কল্যাণ ও ক্ষতি একমাত্র আল্লাহরই।" }
    ]},
  { n: 93, ar: "النُّورُ", translit: "An-Nūr", meanings: { en: "The Light", bn: "মহাজ্যোতি", fr: "La Lumière", id: "Yang Maha Bercahaya", ur: "نور", tr: "Nûr", ar: "نور السماوات والأرض" , zh: '光明者', ja: '光', hi: 'नूर', es: 'La Luz', ru: 'Свет', de: 'Das Licht', fa: 'نور', ms: 'Yang Maha Bercahaya'},
    explain: { en: "An-Nur is the Light of the heavens and the earth — not light in the physical sense (photons) but the Divine Reality by which all existence is illuminated, known, and guided. Quran 24:35 gives the famous metaphor of a lamp in a niche, concluding: 'Allah is the Light of the heavens and the earth.' Ibn al-Qayyim devoted an entire work (Madarij al-Salikin) to the spiritual illumination that flows from An-Nur. Hearts are illuminated by faith, guided by the Quran, and see truly only through divine light.", bn: "আন-নুর হলেন আসমান ও জমিনের আলো। এ আলো চোখে দেখা বস্তুগত আলো (আলোর কণা) নয়; বরং সেই মহাসত্য, যার আলোয় গোটা অস্তিত্ব আলোকিত হয়, চেনা যায়, পথ পায়। কুরআন ২৪:৩৫-এ এসেছে কুলুঙ্গিতে রাখা প্রদীপের বিখ্যাত উপমা, আর শেষ কথা: 'আল্লাহ আসমান ও জমিনের নুর।' ইবনুল কাইয়িম আন-নুর থেকে আসা আত্মিক আলো নিয়ে একটি পুরো গ্রন্থ (মাদারিজুস সালিকিন) লিখেছেন। অন্তর আলোকিত হয় ঈমানে, পথ পায় কুরআনে, আর সত্যিকারের দেখা দেখে কেবল আল্লাহর আলোতেই।" },
    hadith: { en: "O Allah, place light in my heart, light in my sight, light in my hearing, light on my right, light on my left, light above me, light below me, light in front of me, light behind me, and make me light.", bn: "হে আল্লাহ, আমার হৃদয়ে নুর রাখুন, দৃষ্টিতে নুর, শ্রবণে নুর, ডানে নুর, বামে নুর, উপরে নুর, নিচে নুর, সামনে নুর, পিছনে নুর, আর আমাকে নুরময় করে দিন।", src: "Sahih al-Bukhari 6316; Sahih Muslim 763" } ,
    invoke: { en: "When darkness of confusion or sadness surrounds you, call upon Ya Nur — He is the Light of the heavens and earth who illuminates hearts with guidance. Recite the Prophet's du'a 'Allahumma-j'al fi qalbi nura' (O Allah, place light in my heart) and ask Him to light your path.", bn: "বিভ্রান্তি বা দুঃখের অন্ধকার ঘিরে ধরলে 'ইয়া নূর' বলে ডাকুন। তিনিই আসমান ও জমিনের আলো, যিনি হেদায়েতের আলোয় অন্তর আলোকিত করেন। নবী ﷺ-এর দু'আ পড়ুন: 'আল্লাহুম্মাজআল ফি কালবি নূরা' (হে আল্লাহ, আমার অন্তরে আলো দিন), আর তাঁর কাছে চান, তিনি যেন আপনার পথ আলোকিত করেন।" } ,
    quranicRefs: [
      { ref: "24:35", noteEn: "Allahu Nuru-s-samawati wa-l-ard — Allah is the Light of the heavens and earth; the famous Light Verse with its profound parable.", noteBn: "আল্লাহু নুরুস-সামাওয়াতি ওয়াল-আরদ — আল্লাহ আসমান ও জমিনের নুর; এটিই নুরের বিখ্যাত আয়াত, যাতে আছে গভীর এক উপমা।" }
    ]},
  { n: 94, ar: "الْهَادِي", translit: "Al-Hādī", meanings: { en: "The Guide", bn: "পথপ্রদর্শক", fr: "Le Guide", id: "Yang Maha Pemberi Petunjuk", ur: "ہدایت دینے والا", tr: "Hidayet Veren", ar: "الهادي إلى الحق" , zh: '引導者', ja: '導く者', hi: 'हिदायत देने वाला', es: 'El Guía', ru: 'Направляющий', de: 'Der Rechtleitende', fa: 'هدایتگر', ms: 'Yang Maha Pemberi Petunjuk'},
    explain: { en: "Al-Hadi is the Guide who leads whomever He wills to truth, right action, and ultimate salvation. Guidance (hidayah) in Islamic theology has two dimensions: general guidance (showing the path to all through revelation) and specific guidance (enabling certain hearts to accept and act upon it). The Quran (22:54) says: 'And indeed, Allah is the Guide of those who have believed to a straight path.' The believer's greatest need is guidance (hidayah) — sought in every rakat of every prayer through Surah al-Fatiha.", bn: "আল-হাদি হলেন সেই পথপ্রদর্শক, যিনি যাকে চান সত্য, সঠিক আমল ও চূড়ান্ত মুক্তির পথে নিয়ে যান। ইসলামি আকিদায় হিদায়াতের দুটি দিক আছে: সাধারণ হিদায়াত, অর্থাৎ ওহির মাধ্যমে সবাইকে পথ দেখানো; আর বিশেষ হিদায়াত, অর্থাৎ কিছু অন্তরকে তা মেনে নেওয়ার ও সে অনুযায়ী চলার তাওফিক দেওয়া। কুরআন (২২:৫৪) বলে: 'নিশ্চয়ই আল্লাহ মুমিনদের সরল পথে পরিচালিত করেন।' মুমিনের সবচেয়ে বড় প্রয়োজন হিদায়াত; তাই প্রতিটি নামাজের প্রতিটি রাকাতে সূরা আল-ফাতিহায় তা চাওয়া হয়।" },
    invoke: { en: "The most important du'a for guidance is in Surah al-Fatiha itself: 'Ihdina-s-sirat al-mustaqim' (Guide us to the straight path) — said at least 17 times daily in the five prayers. Additionally, recite: 'Allahumma Anta-l-Hadi, fa-dini wa-qawwim 'iwajaji' (O Allah, You are the Guide, so guide me and straighten my crookedness).", bn: "হিদায়াতের সবচেয়ে গুরুত্বপূর্ণ দু'আ আছে সূরা আল-ফাতিহাতেই: 'ইহদিনাস-সিরাতাল-মুস্তাকিম' (আমাদের সরল পথ দেখান)। পাঁচ ওয়াক্ত নামাজে প্রতিদিন অন্তত ১৭ বার এটি পড়া হয়। এর পাশাপাশি পড়ুন: 'আল্লাহুম্মা আনতাল-হাদি, ফাহদিনি ওয়া কাওয়্যিম ইওয়াজাজি' (হে আল্লাহ, আপনিই পথপ্রদর্শক; তাই আমাকে পথ দেখান, আর আমার বক্রতা সোজা করে দিন)।" } ,
    hadith: { en: "The Prophet ﷺ taught al-Hasan the du'a of Qunut: 'Allahumma-hdini fiman hadayt' (O Allah, guide me among those You have guided).", bn: "নবী ﷺ হাসান (রাঃ)-কে কুনুতের দু'আ শেখান: 'আল্লাহুম্মাহদিনি ফিমান হাদাইত' (হে আল্লাহ, যাদের আপনি হিদায়াত দিয়েছেন তাদের সাথে আমাকেও হিদায়াত দিন)।", src: "Sunan Abi Dawud 1425; Jami' at-Tirmidhi 464" },
    quranicRefs: [
      { ref: "22:54", noteEn: "Wa inna-llaha la-Hadi-lladhina amanu ila Sirat-in Mustaqim — Allah is the Guide of those who believe to the straight path.", noteBn: "ওয়া ইন্নাল্লাহা লা-হাদিল্লাযিনা আমানু ইলা সিরাতিন মুস্তাকিম — আল্লাহই মুমিনদের সরল পথের পথপ্রদর্শক।" },
      { ref: "25:31", noteEn: "Wa kafa bi-Rabbika Hadiyan wa Nasira — your Lord suffices as Guide and Helper against those who oppose the truth.", noteBn: "ওয়া কাফা বিরাব্বিকা হাদিয়ান ওয়া নাসিরা — সত্যের বিরোধীদের মোকাবিলায় পথপ্রদর্শক ও সাহায্যকারী হিসেবে তোমার রবই যথেষ্ট।" }
    ]},
  { n: 95, ar: "الْبَدِيعُ", translit: "Al-Badīʿ", meanings: { en: "The Incomparable Originator", bn: "অভিনব স্রষ্টা", fr: "L'Inventeur", id: "Yang Maha Pencipta Tanpa Contoh", ur: "بے مثال پیدا کرنے والا", tr: "Örneksiz Yaratan", ar: "المبدع بلا مثال" , zh: '無可比擬至先者', ja: '比類なき者', hi: 'बेमिसाल पैदा करने वाला', es: 'El Creador incomparable', ru: 'Несравненный Творец', de: 'Der unvergleichliche Urheber', fa: 'پدیدآورنده‌ی بی‌همتا', ms: 'Yang Maha Pencipta Tanpa Contoh'},
    explain: { en: "Al-Badi' is the incomparable Originator — He created the universe and everything in it without any prior model, blueprint, or precedent. The Quran (2:117) states: 'Creator (Badi') of the heavens and earth; when He decrees a matter, He only says: Be! — and it is.' Every atom, every galaxy, every human, every concept that exists is an unprecedented original creation from Al-Badi'. Human artists work from references; Al-Badi' has none.", bn: "আল-বাদি হলেন অতুলনীয় স্রষ্টা, যিনি আগের কোনো নমুনা, নকশা বা দৃষ্টান্ত ছাড়াই মহাবিশ্ব ও তার সবকিছু সৃষ্টি করেছেন। কুরআন (২:১১৭) বলে: 'তিনি আসমান ও জমিনের বাদি (অভিনব স্রষ্টা); যখন কোনো কিছুর ফয়সালা করেন, শুধু বলেন: হও! আর তা হয়ে যায়।' প্রতিটি অণু, প্রতিটি ছায়াপথ, প্রতিটি মানুষ, অস্তিত্বে থাকা প্রতিটি ধারণা আল-বাদির এমন মৌলিক সৃষ্টি, যার আগে কোনো নজির ছিল না। মানুষ শিল্পী আগের কোনো নমুনা দেখে কাজ করে; আল-বাদির কোনো নমুনা লাগে না।" } ,
    hadith: { en: "The Prophet ﷺ heard a man supplicating: 'O Allah, I ask You — for to You belongs all praise; there is no god but You, al-Mannan (the Bestower), Badi' (Incomparable Originator) of the heavens and the earth, O Owner of Majesty and Honor, O Ever-Living, O Sustainer.' He ﷺ said: 'He has called upon Allah by His Greatest Name, by which, when He is asked, He gives, and when He is called upon, He answers.'", bn: "নবী ﷺ এক ব্যক্তিকে দু'আ করতে শুনলেন: 'হে আল্লাহ, আমি আপনার কাছে চাই, কারণ সব প্রশংসা আপনারই; আপনি ছাড়া কোনো ইলাহ নেই, আপনি আল-মান্নান (মহাদাতা), আসমান-জমিনের বাদি (অভিনব স্রষ্টা); হে মহিমা ও সম্মানের অধিকারী, হে চিরঞ্জীব, হে সর্বসত্তার ধারক।' তিনি ﷺ বললেন: 'সে আল্লাহকে তাঁর ইসমে আজম দিয়ে ডেকেছে, যে নামে চাওয়া হলে তিনি দেন, আর ডাকা হলে সাড়া দেন।'", src: "Sunan Abi Dawud 1495; Sunan an-Nasa'i 1300 — sahih" },
    invoke: { en: "Call on Al-Badi' with the du'a the Prophet ﷺ praised: 'Ya Badi'a-s-samawati wal-ard, ya Dhal-Jalali wal-Ikram, ya Hayyu ya Qayyum.' When you need a way out that has no precedent, ask the Originator who creates without any prior model.", bn: "নবী ﷺ যে দু'আর প্রশংসা করেছেন, তা দিয়ে আল-বাদিকে ডাকুন: 'ইয়া বাদিআস-সামাওয়াতি ওয়াল-আরদ, ইয়া যাল-জালালি ওয়াল-ইকরাম, ইয়া হাইয়ু ইয়া কাইয়ুম।' যখন এমন কোনো উপায় দরকার, যার কোনো নজির নেই, তখন সেই স্রষ্টার কাছে চান, যিনি আগের কোনো নমুনা ছাড়াই সৃষ্টি করেন।" },
    quranicRefs: [
      { ref: "2:117", noteEn: "Badi'u-s-samawati wa-l-ard — Originator of the heavens and earth without any prior model; the name appears directly.", noteBn: "বাদিউস-সামাওয়াতি ওয়াল-আরদ — আসমান ও যমীনের অভিনব স্রষ্টা, কোনো পূর্বনমুনা ছাড়াই; নামটি সরাসরি এসেছে।" },
      { ref: "6:101", noteEn: "Badi'u-s-samawati wa-l-ard, anna yakunu lahu walad — Originator of all; how could He have a son?", noteBn: "বাদিউস-সামাওয়াতি ওয়াল-আরদ, আন্না ইয়াকুনু লাহু ওয়ালাদ — সব কিছুর অভিনব স্রষ্টা; তাঁর সন্তান কীভাবে হবে?" },
      { ref: "21:104", noteEn: "Kama bada'na awwala khalqin nu'iduh — as We originated the first creation We will repeat it; unmatched creative power.", noteBn: "কামা বাদানা আওয়ালা খালকিন নুইদুহ — যেভাবে আমরা প্রথমবার সৃষ্টির সূচনা করেছি, সেভাবেই আবার তা করব; তাঁর সৃজনক্ষমতার কোনো তুলনা নেই।" },
      { ref: "35:1", noteEn: "Fatiri-s-samawati wa-l-ard — Originator of the heavens and earth, fashioning without precedent.", noteBn: "ফাতিরিস-সামাওয়াতি ওয়াল-আরদ — আসমান ও যমীনের স্রষ্টা, পূর্বনমুনা ছাড়াই গঠনকারী।" }
    ]},
  { n: 96, ar: "الْبَاقِي", translit: "Al-Bāqī", meanings: { en: "The Everlasting", bn: "চিরস্থায়ী", fr: "Le Permanent", id: "Yang Maha Kekal", ur: "ہمیشہ باقی رہنے والا", tr: "Bâki Olan", ar: "الباقي بعد فناء الخلق" , zh: '克制者、永生者', ja: '不朽にして不変なる者', hi: 'हमेशा बाक़ी रहने वाला', es: 'El Perdurable', ru: 'Вечный', de: 'Der Immerwährende', fa: 'پاینده', ms: 'Yang Maha Kekal'},
    explain: { en: "Al-Baqi is the Everlasting who remains when all else perishes. The Quran (55:26-27) says: 'All that exists will perish, but the Face of your Lord, full of Majesty and Honor, will remain.' Al-Baqi is the complement of Al-Awwal and Al-Akhir: the First has no beginning, the Last has no end, and Al-Baqi is the One who persists throughout. For the believer who has lost someone or something, Al-Baqi is the anchor: what is truly good and true returns to Al-Baqi and is preserved with Him.", bn: "আল-বাকি হলেন চিরস্থায়ী; সবকিছু ধ্বংস হয়ে গেলেও তিনি থাকেন। কুরআন (৫৫:২৬-২৭) বলে: 'যা কিছু আছে সবই ধ্বংস হবে; থেকে যাবে শুধু আপনার রবের চেহারা, যিনি মহিমা ও সম্মানের অধিকারী।' আল-বাকি নামটি আল-আওয়াল ও আল-আখিরের পরিপূরক: প্রথমের কোনো শুরু নেই, শেষের কোনো সমাপ্তি নেই, আর আল-বাকি পুরোটা জুড়ে টিকে থাকেন। যে মুমিন কাউকে বা কিছু হারিয়েছে, তার জন্য আল-বাকিই নোঙর: যা সত্যিই ভালো ও সত্য, তা আল-বাকির কাছে ফিরে যায় এবং তাঁর কাছে সংরক্ষিত থাকে।" } ,
    invoke: { en: "When you grieve something that has passed or fear losing what you love, call upon Ya Baqi — He alone remains when all else perishes. Attach your heart to the Everlasting rather than to fleeting things, and invest your deeds in what endures with Him forever.", bn: "যা চলে গেছে তার জন্য শোক হলে, কিংবা প্রিয় কিছু হারানোর ভয় হলে 'ইয়া বাকি' বলে ডাকুন। সবকিছু ধ্বংস হলেও একমাত্র তিনিই থেকে যান। ক্ষণস্থায়ী জিনিসে নয়, অন্তর বাঁধুন সেই চিরস্থায়ী সত্তার সঙ্গে; আর আমল জমা রাখুন সেখানে, যা তাঁর কাছে চিরকাল টিকে থাকে।" } ,
    quranicRefs: [
      { ref: "55:26", noteEn: "Kullu man 'alayha fan — everyone upon the earth will perish; the necessary counterpart to Al-Baqi.", noteBn: "কুল্লু মান আলাইহা ফান — পৃথিবীতে যারা আছে, সবাই বিলীন হবে; এ কথাই আল-বাকি নামের অনিবার্য পরিপূরক।" },
      { ref: "55:27", noteEn: "Wa yabqa wajhu Rabbika Dhu-l-Jalali wa-l-Ikram — the Face of your Lord, full of Majesty, will remain (yabqa).", noteBn: "ওয়া ইয়াবকা ওয়াজহু রাব্বিকা যুল-জালালি ওয়াল-ইকরাম — মহিমা ও সম্মানের অধিকারী তোমার প্রভুর চেহারা চিরস্থায়ী থাকবে (ইয়াবকা)।" },
      { ref: "20:73", noteEn: "Wa-llahu khayrun wa abqa — and Allah is better and more lasting (abqa) than all else.", noteBn: "ওয়াল্লাহু খাইরুন ওয়া আবকা — আর আল্লাহ সবকিছুর চেয়ে উত্তম ও চিরস্থায়ী (আবকা)।" },
      { ref: "28:88", noteEn: "Kullu shay'in halikun illa wajhah — everything will perish except His Face; He alone endures.", noteBn: "কুল্লু শাইইন হালিকুন ইল্লা ওয়াজহাহ — তাঁর চেহারা ছাড়া সব কিছু ধ্বংস হবে; একমাত্র তিনিই চিরস্থায়ী।" }
    ]},
  { n: 97, ar: "الْوَارِثُ", translit: "Al-Wārith", meanings: { en: "The Inheritor", bn: "চূড়ান্ত উত্তরাধিকারী", fr: "L'Héritier", id: "Yang Maha Mewarisi", ur: "سب کا وارث", tr: "Her Şeyin Vârisi", ar: "الوارث بعد فناء الخلق" , zh: '萬物繼承者', ja: '後継者、全てを受け継ぐ者', hi: 'सबका वारिस', es: 'El Heredero', ru: 'Наследующий', de: 'Der Erbe', fa: 'وارث همه چیز', ms: 'Yang Maha Mewarisi'},
    explain: { en: "Al-Warith is the Ultimate Inheritor — when all creation ends and every 'owner' has perished, everything returns to Al-Warith, who was always the true owner. The Quran (15:23) says: 'And indeed, it is We who give life and cause death, and We are the Heir (Al-Warith).' The Prophet Zakariyya (Zechariah, peace be upon him) called to Al-Warith: 'You are the best of inheritors' (Quran 21:89). This name reframes possession: we never truly own anything; we are temporary custodians for Al-Warith.", bn: "আল-ওয়ারিছ হলেন চূড়ান্ত উত্তরাধিকারী। যখন গোটা সৃষ্টি শেষ হবে আর প্রতিটি 'মালিক' বিদায় নেবে, তখন সবকিছু ফিরে যাবে আল-ওয়ারিছের কাছে, যিনি সবসময়ই ছিলেন প্রকৃত মালিক। কুরআন (১৫:২৩) বলে: 'নিশ্চয়ই আমরাই জীবন দিই ও মৃত্যু ঘটাই, আর আমরাই ওয়ারিছ (উত্তরাধিকারী)।' নবী যাকারিয়া (আঃ) আল-ওয়ারিছকে ডেকে বলেছিলেন: 'আপনিই শ্রেষ্ঠ উত্তরাধিকারী' (কুরআন ২১:৮৯)। এই নাম মালিকানার ধারণাই বদলে দেয়: আমরা আসলে কোনো কিছুরই মালিক নই; আমরা আল-ওয়ারিছের জিনিসের অস্থায়ী আমানতদার মাত্র।" } ,
    hadith: { en: "Among the Prophet's ﷺ supplications: 'and make it the inheritor from us (wa-j'alhu-l-waritha minna)' — entrusting to Allah, the ultimate Inheritor, all that survives us.", bn: "নবী ﷺ-এর একটি দু'আয় আছে: 'ওয়াজ'আলহুল-ওয়ারিসা মিন্না' (আমার শক্তি-সামর্থ্যকে আমার উত্তরাধিকারী বানিয়ে দিন)। এভাবে আমাদের পরে যা থেকে যায়, তা সঁপে দেওয়া হয় চূড়ান্ত উত্তরাধিকারী আল্লাহর হাতে।", src: "Jami' at-Tirmidhi 3502" },
    invoke: { en: "Hold wealth and position lightly — everything returns to Al-Warith, the final Inheritor of the heavens and the earth. Pray as Zakariyya did when longing for offspring: 'My Lord, leave me not alone, and You are the best of inheritors' (21:89), and ask Allah to keep your hearing and sight strong to the end of your life.", bn: "সম্পদ ও পদমর্যাদার ওপর মন বেঁধে রাখবেন না। শেষ পর্যন্ত সবকিছু ফিরে যায় আল-ওয়ারিছের কাছে; আসমান-জমিনের চূড়ান্ত উত্তরাধিকারী তিনিই। সন্তানের আশায় যাকারিয়া যেভাবে দু'আ করেছিলেন, আপনিও সেভাবে করুন: 'হে আমার রব, আমাকে একা ছেড়ে দেবেন না, আর আপনিই সর্বোত্তম উত্তরাধিকারী' (২১:৮৯)। আর আল্লাহর কাছে চান, জীবনের শেষ দিন পর্যন্ত যেন আপনার শোনার ও দেখার শক্তি সবল থাকে।" },
    quranicRefs: [
      { ref: "15:23", noteEn: "Wa Inna la-Nahnu nuhyi wa numumit wa Nahnu-l-Warithun — We give life and cause death, and We are the Inheritors.", noteBn: "ওয়া ইন্না লা-নাহনু নুহয়ি ওয়া নুমিতু ওয়া নাহনুল-ওয়ারিছুন: আমরাই জীবন দিই, আমরাই মৃত্যু ঘটাই, আর আমরাই উত্তরাধিকারী (ওয়ারিছ)।" },
      { ref: "19:40", noteEn: "Inna Nahnu narithu-l-ard wa man alayha — We will inherit the earth and all upon it; all returns to Al-Warith.", noteBn: "ইন্না নাহনু নারিছুল-আরদ ওয়ামান আলায়হা: পৃথিবী ও তার ওপরের সবকিছুর উত্তরাধিকারী হব আমরাই। সবকিছু ফিরে যায় আল-ওয়ারিছের কাছে।" },
      { ref: "21:89", noteEn: "Wa Anta khayru-l-Warithun — Zakariyya's prayer: You are the best of inheritors; Al-Warith receives all at the end.", noteBn: "ওয়া আনতা খায়রুল-ওয়ারিছিন: যাকারিয়ার দু'আ, 'আপনিই সর্বোত্তম উত্তরাধিকারী।' শেষে সবকিছু আল-ওয়ারিছের কাছেই যায়।" },
      { ref: "57:10", noteEn: "Wa lillahi miraathu-s-samawati wa-l-ard — and to Allah belongs the inheritance of the heavens and earth.", noteBn: "ওয়া লিল্লাহি মিরাছুস-সামাওয়াতি ওয়াল-আরদ — আকাশ ও পৃথিবীর উত্তরাধিকার আল্লাহরই।" }
    ]},
  { n: 98, ar: "الرَّشِيدُ", translit: "Ar-Rashīd", meanings: { en: "The Guide to the Right Path", bn: "সঠিক পথের নির্দেশক", fr: "Le Guide Parfait", id: "Yang Maha Pandai", ur: "رہنمائی کرنے والا", tr: "Doğru Yolu Gösteren", ar: "المرشد إلى الصواب" , zh: '指导者', ja: '導く者', hi: 'सीधी राह दिखाने वाला', es: 'El que guía por el buen camino', ru: 'Наставляющий на верный путь', de: 'Der zum rechten Weg Leitende', fa: 'راهنمای راه راست', ms: 'Yang Maha Membimbing ke Jalan yang Benar'},
    explain: { en: "Ar-Rashid is the One who guides all things to their proper end through the most right and correct path — His management of the universe proceeds by the most perfect wisdom and the most correct course. Al-Ghazali distinguishes this from Al-Hadi: while Al-Hadi guides the heart to faith, Ar-Rashid guides all of creation toward its destined purpose through the most righteous path. Nothing in Allah's decree is misguided; every event leads to its correct conclusion.", bn: "আর-রাশিদ তিনি, যিনি সবকিছুকে সবচেয়ে সঠিক ও নির্ভুল পথে তার যথাযথ পরিণতির দিকে নিয়ে যান। গোটা বিশ্বজগৎ তিনি চালান পরিপূর্ণ হিকমত আর সবচেয়ে সঠিক নিয়মে। আল-গাজালী এ নামটিকে আল-হাদি থেকে আলাদা করেছেন: আল-হাদি অন্তরকে ঈমানের পথ দেখান, আর আর-রাশিদ গোটা সৃষ্টিকে সবচেয়ে সরল-সঠিক পথে তার নির্ধারিত লক্ষ্যে পৌঁছে দেন। আল্লাহর তাকদিরে কিছুই ভুল পথে চলে না; প্রতিটি ঘটনা গিয়ে পৌঁছায় তার সঠিক পরিণতিতে।" },
    invoke: { en: "When confused about a decision, recite the du'a of the youths of the cave: 'Rabbana atina min ladunka rahmatan wa hayyi' lana min amrina rashada' (18:10), asking Ar-Rashid to set your affair upon right guidance.", bn: "কোনো সিদ্ধান্ত নিয়ে দ্বিধায় পড়লে গুহার যুবকদের দু'আ পড়ুন: 'রাব্বানা আতিনা মিন লাদুনকা রাহমাতান ওয়া হাইয়ি লানা মিন আমরিনা রাশাদা' (১৮:১০)। আর-রাশিদের কাছে চান, তিনি যেন আপনার কাজটি সঠিক পথে গুছিয়ে দেন।" } ,
    quranicRefs: [
      { ref: "2:256", noteEn: "Qad tabayyana-r-rushdu mina-l-ghayy — right guidance (rushd) has become clear from error; Allah's guidance distinguishes truth.", noteBn: "কাদ তাবাইয়ানার-রুশদু মিনাল-গাইয়: সঠিক পথ (রুশদ) ভ্রান্ত পথ থেকে আলাদা হয়ে স্পষ্ট হয়ে গেছে। আল্লাহর হিদায়াতই সত্যকে আলাদা করে চিনিয়ে দেয়।" },
      { ref: "72:2", noteEn: "Yahdi ila-r-rushd fa-amanna bih — it guides to right conduct (rushd), so we believed in it.", noteBn: "ইয়াহদি ইলার-রুশদ ফা-আমান্না বিহ — এটি সঠিক পথের (রুশদ) দিকে পরিচালিত করে, তাই আমরা তাতে ঈমান আনলাম।" },
      { ref: "18:10", noteEn: "Wa hayyi' lana min amrina rashada — grant us right guidance (rashad) in our affair; du'a of the cave youths.", noteBn: "ওয়া হাইয়ি লানা মিন আমরিনা রাশাদা: আমাদের কাজ সঠিক পথে (রাশাদ) গুছিয়ে দিন। এটি গুহার যুবকদের দু'আ।" },
      { ref: "40:38", noteEn: "Ittabi'uni ahdikum sabila-r-rashad — follow me; I will guide you to the way of right conduct.", noteBn: "ইত্তাবিউনি আহদিকুম সাবিলার-রাশাদ — আমাকে অনুসরণ করো; আমি তোমাদের সঠিক পথের দিকে পরিচালিত করব।" }
    ]},
  { n: 99, ar: "الصَّبُورُ", translit: "Aṣ-Ṣabūr", meanings: { en: "The Most Patient", bn: "মহাধৈর্যশীল", fr: "Le Très Patient", id: "Yang Maha Sabar", ur: "بڑا صابر", tr: "Çok Sabırlı", ar: "الذي لا يعاجل بالعقوبة" , zh: '耐心者', ja: '辛抱強き者', hi: 'बड़ा सब्र करने वाला', es: 'El Muy Paciente', ru: 'Терпеливый', de: 'Der überaus Geduldige', fa: 'بسیار شکیبا', ms: 'Yang Maha Sabar'},
    explain: { en: "As-Sabur is the Most Patient — His patience (sabr) is not passive acceptance but active, purposeful forbearance: He delays punishment for the disobedient, allows time for the heedless to return, and withholds immediate retribution in His perfect wisdom. Al-Ghazali notes that As-Sabur concludes the list of the 99 Names, echoing Al-Halim (name 32): both reflect Allah's forbearance, but As-Sabur represents the highest degree of that forbearance which encompasses all creation. The hadith 'Whoever memorises them enters Paradise' (Bukhari 2736; Muslim 2677) gives the virtue without listing the Names; the enumerated list ending with As-Sabur comes from Tirmidhi's narration.", bn: "আস-সাবুর মানে মহাধৈর্যশীল। তাঁর ধৈর্য (সবর) চুপচাপ মেনে নেওয়া নয়, বরং সক্রিয় ও উদ্দেশ্যপূর্ণ সহনশীলতা। তিনি নাফরমানদের শাস্তি পিছিয়ে দেন, গাফিলদের ফিরে আসার সময় দেন, আর নিজের পূর্ণ হিকমতে সঙ্গে সঙ্গে প্রতিশোধ নেন না। আল-গাজালী বলেছেন, আস-সাবুর দিয়েই ৯৯ নামের তালিকা শেষ হয়, আর এ নাম যেন আল-হালিমেরই (৩২ নম্বর নাম) প্রতিধ্বনি। দুটি নামেই আল্লাহর সহনশীলতা ফুটে ওঠে, তবে আস-সাবুর সেই সহনশীলতার সর্বোচ্চ স্তর, যা গোটা সৃষ্টিকে ঘিরে আছে। 'যে এগুলো মুখস্থ করবে, সে জান্নাতে যাবে' হাদিসটি (বুখারী ২৭৩৬; মুসলিম ২৬৭৭) নামগুলোর তালিকা না দিয়েই ফজিলতের কথা বলে; আস-সাবুর দিয়ে শেষ হওয়া তালিকাটি এসেছে তিরমিযীর বর্ণনায়।" },
    invoke: { en: "As-Sabur teaches us to bear trials without complaint or haste. When tested, say 'Ya Sabur' and ask Allah for patience — remembering that His own forbearance delays the punishment we deserve, granting us time to turn back.", bn: "আস-সাবুর নাম আমাদের শেখায়, অভিযোগ বা তাড়াহুড়া না করে বিপদ সয়ে যেতে। পরীক্ষায় পড়লে 'ইয়া সাবুর' বলে আল্লাহর কাছে সবর চান। মনে রাখবেন, তাঁর নিজের সহনশীলতাই আমাদের প্রাপ্য শাস্তি পিছিয়ে রাখে, যাতে আমরা ফিরে আসার সময় পাই।" } ,
    hadith: { en: "The Prophet ﷺ said: 'None is more patient (asbar) at hearing an injury than Allah: they ascribe a son to Him, yet He grants them well-being and provides for them.'", bn: "নবী ﷺ বলেছেন: 'কষ্টদায়ক কথা শুনে আল্লাহর চেয়ে বেশি ধৈর্য ধরেন (আসবার), এমন কেউ নেই। লোকেরা দাবি করে তাঁর সন্তান আছে, তবুও তিনি তাদের সুস্থ রাখেন, রিজিক দেন।'", src: "Sahih al-Bukhari 6099; Sahih Muslim 2804" },
    quranicRefs: [
      { ref: "35:45", noteEn: "Wa law yu'akhidhu-llahu-n-nasa bima kasabu ma taraka 'ala zahriha min dabbah — were He to punish at once, no creature would remain; His forbearance.", noteBn: "ওয়া লাও ইউআখিযুল্লাহুন-নাসা বিমা কাসাবু মা তারাকা আলা যাহরিহা মিন দাব্বাহ: তিনি যদি সঙ্গে সঙ্গে শাস্তি দিতেন, পৃথিবীর বুকে কোনো প্রাণী বেঁচে থাকত না। এ তাঁরই সহনশীলতা।" },
      { ref: "16:61", noteEn: "Wa law yu'akhidhu-llahu-n-nasa bi-zulmihim ma taraka 'alayha min dabbah — He does not hasten to punish wrongdoing.", noteBn: "ওয়া লাও ইউআখিযুল্লাহুন-নাসা বি-যুলমিহিম মা তারাকা আলাইহা মিন দাব্বাহ — তিনি অন্যায়ের জন্য দ্রুত শাস্তি দেন না।" },
      { ref: "22:48", noteEn: "Wa ka'ayyin min qaryatin amlaytu laha wa hiya zalimah — how many a town I gave respite though it was unjust.", noteBn: "ওয়া কাআইয়িন মিন কারয়াতিন আমলাইতু লাহা ওয়া হিয়া যালিমাহ: কত জনপদ জালিম হওয়া সত্ত্বেও আমি তাদের অবকাশ দিয়েছি।" },
      { ref: "2:153", noteEn: "Inna-llaha ma'a-s-sabirin — indeed Allah is with the patient; He loves and rewards their sabr.", noteBn: "ইন্নাল্লাহা মাআস-সাবিরিন: নিশ্চয়ই আল্লাহ সবরকারীদের সঙ্গে আছেন। তিনি তাদের সবর ভালোবাসেন এবং এর প্রতিদান দেন।" }
    ]},
];

